## 1.  The Flask application (`app.py`)

```python
#!/usr/bin/env python3
"""
Flask app that copies all *.mp4 files from a source directory
to a USB stick mounted at /media/usb and reports the progress
to a Bootstrap‑5 front‑end.
"""

import os
import shutil
import threading
import time
from pathlib import Path

from flask import (
    Flask, render_template, jsonify, request, abort
)

# ------------------------------------------------------------------
# Configuration – edit these paths to match your environment
# ------------------------------------------------------------------
SOURCE_DIR = Path("/home/your_user/videos")   # <-- change this
USB_MOUNT_POINT = Path("/media/usb")          # <-- change this

# ------------------------------------------------------------------
# Global state
# ------------------------------------------------------------------
# A simple dict to keep track of total files and how many we already
# copied.  In production you’d use a more robust persistence layer
# (Redis, database, etc.) if you need to survive restarts.
progress = {
    "total": 0,
    "copied": 0,
    "running": False,
}

# Lock to serialize access to the progress dict
progress_lock = threading.Lock()


# ------------------------------------------------------------------
# Helper – copy a single file, preserve metadata
# ------------------------------------------------------------------
def copy_file(src: Path, dst: Path):
    """Copy a single file, preserving metadata."""
    dst.parent.mkdir(parents=True, exist_ok=True)  # ensure destination folder
    shutil.copy2(src, dst)


# ------------------------------------------------------------------
# Main copy routine – runs in a background thread
# ------------------------------------------------------------------
def copy_all_mp4():
    """
    Walk SOURCE_DIR recursively, find every *.mp4 file and copy it
    to the USB, preserving relative structure.
    Updates the global `progress` dict after each file.
    """
    with progress_lock:
        progress["running"] = True
        progress["total"] = 0
        progress["copied"] = 0

    # First pass – count total number of MP4 files
    mp4_files = []
    for root, _, files in os.walk(SOURCE_DIR):
        for f in files:
            if f.lower().endswith(".mp4"):
                mp4_files.append(Path(root) / f)

    with progress_lock:
        progress["total"] = len(mp4_files)

    # Second pass – copy files one by one
    for src_path in mp4_files:
        # Destination keeps the relative path inside SOURCE_DIR
        relative_path = src_path.relative_to(SOURCE_DIR)
        dst_path = USB_MOUNT_POINT / relative_path

        try:
            copy_file(src_path, dst_path)
        except Exception as e:
            # In a real system you’d log the error; here we just skip
            print(f"[ERROR] Could not copy {src_path} → {dst_path}: {e}")

        with progress_lock:
            progress["copied"] += 1

    with progress_lock:
        progress["running"] = False


# ------------------------------------------------------------------
# Flask endpoints
# ------------------------------------------------------------------
app = Flask(__name__)


@app.route("/")
def index():
    """Render the HTML page with the copy button & progress bar."""
    return render_template("index.html")


@app.route("/start", methods=["POST"])
def start_copy():
    """Kick off the copy operation in a background thread."""
    with progress_lock:
        if progress["running"]:
            return jsonify({"status": "already_running"}), 409

        thread = threading.Thread(target=copy_all_mp4, daemon=True)
        thread.start()

    return jsonify({"status": "started"})


@app.route("/progress")
def get_progress():
    """Return JSON describing the current copy progress."""
    with progress_lock:
        if progress["total"] == 0:
            percent = 0
        else:
            percent = int(100 * progress["copied"] / progress["total"])

        data = {
            "running": progress["running"],
            "total": progress["total"],
            "copied": progress["copied"],
            "percent": percent,
        }
    return jsonify(data)


# ------------------------------------------------------------------
# Run the application
# ------------------------------------------------------------------
if __name__ == "__main__":
    # In production use a real WSGI server – this is fine for demos
    app.run(host="0.0.0.0", port=5000, debug=True)
```

