import os
from flask import (
    Flask, render_template, request, session, jsonify, send_file
)
import openai
import io
import datetime

app = Flask(__name__)
app.secret_key = os.getenv("FLASK_SECRET_KEY", "dev_secret_key")

# Make sure you set OPENAI_API_KEY in your environment
openai.api_key = os.getenv("OPENAI_API_KEY")

# --------- Helper functions ---------

def chat_completion(messages, model="gpt-4-1106-preview"):
    """Wrapper around OpenAI ChatCompletion API."""
    try:
        response = openai.ChatCompletion.create(
            model=model,
            messages=messages,
            temperature=0.7,
            max_tokens=1500,
        )
        return response.choices[0].message.content.strip()
    except Exception as e:
        # In production you would log this
        return f"[Error] {str(e)}"

def get_expansion_prompt(outline, character, plot, style):
    return f"""
You are a creative novelist.  
Given the following brief:

- Outline: {outline}
- Main character: {character}
- Plot: {plot}
- Language style: {style}

Expand each section into detailed, vivid descriptions (≈300 words each).  
Return a JSON object with keys "outline", "character", "plot".  
Do not add any extra text.
"""

def get_chapter_prompt(outline, character, plot, style, chapter_number, previous_chapters):
    # Build a context that tells ChatGPT how many chapters have already been written
    context = "\n".join(previous_chapters) if previous_chapters else ""
    return f"""
You are a seasoned writer.  
The novel so far has these chapters:
{context}

You have the following:

- Outline: {outline}
- Main character: {character}
- Current plot point: {plot}
- Language style: {style}
- You are writing chapter #{chapter_number}.

Write a full chapter (~1200 words) that follows the plot and keeps the style consistent.  
Do not repeat previous chapters.  Do not mention this instruction.  
Return only the chapter text.
"""

# --------- Routes ---------

@app.route("/")
def index():
    return render_template("index.html")

@app.route("/api/auto_expand", methods=["POST"])
def auto_expand():
    data = request.json
    outline = data.get("outline", "")
    character = data.get("character", "")
    plot = data.get("plot", "")
    style = data.get("style", "")

    # Save base data to session
    session["outline"] = outline
    session["character"] = character
    session["plot"] = plot
    session["style"] = style
    session["generated_chapters"] = []  # reset

    prompt = get_expansion_prompt(outline, character, plot, style)
    result = chat_completion(
        messages=[{"role": "user", "content": prompt}]
    )

    try:
        import json
        expanded = json.loads(result)
        # Store expanded content
        session["outline"] = expanded.get("outline", outline)
        session["character"] = expanded.get("character", character)
        session["plot"] = expanded.get("plot", plot)
        return jsonify({"status": "ok", "data": expanded})
    except Exception:
        return jsonify({"status": "error", "message": "Failed to parse JSON from GPT."})

@app.route("/api/generate_chapter", methods=["POST"])
def generate_chapter():
    data = request.json
    # The new plot fragment that the user entered for this chapter
    new_plot = data.get("new_plot", "")
    # Update the plot in session
    session["plot"] = new_plot

    outline = session.get("outline", "")
    character = session.get("character", "")
    plot = session.get("plot", "")
    style = session.get("style", "")
    prev_chapters = session.get("generated_chapters", [])
    chapter_number = len(prev_chapters) + 1

    prompt = get_chapter_prompt(outline, character, plot, style,
                                chapter_number, prev_chapters)

    chapter_text = chat_completion(
        messages=[{"role": "user", "content": prompt}]
    )

    # Store generated chapter
    session["generated_chapters"].append(chapter_text)

    return jsonify({"status": "ok", "chapter": chapter_text})

@app.route("/api/re_generate", methods=["POST"])
def re_generate():
    """Re‑generate the last chapter based on new feedback."""
    data = request.json
    new_plot = data.get("new_plot", "")

    # Replace the last plot entry
    session["plot"] = new_plot

    # Remove the last chapter
    session["generated_chapters"] = session.get("generated_chapters", [])[:-1]

    # Generate again
    return generate_chapter(data)

@app.route("/api/download_chapter", methods=["POST"])
def download_chapter():
    """Create a downloadable text file of the current chapter."""
    data = request.json
    chapter_number = data.get("chapter_number", len(session.get("generated_chapters", [])))
    try:
        chapter_text = session["generated_chapters"][chapter_number - 1]
    except IndexError:
        return jsonify({"status": "error", "message": "Invalid chapter number."})

    # Build a file in memory
    file_stream = io.BytesIO()
    file_stream.write(chapter_text.encode("utf-8"))
    file_stream.seek(0)

    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"chapter_{chapter_number}_{timestamp}.txt"

    return send_file(
        file_stream,
        as_attachment=True,
        download_name=filename,
        mimetype="text/plain",
    )

if __name__ == "__main__":
    app.run(debug=True)
```

