const uint8_t HC12_RX = 2;        // Arduino RX ← HC‑12 TX
const uint8_t DHT_PIN = 4;        // DHT‑22 data pin
const uint8_t INPUT_PIN = 5;      // Digital input pin
const uint8_t DEVICE_ID = 1;      // Unique ID for this node
const unsigned long SEND_INTERVAL_MS = 2000; // Send every 2 seconds

// ---------- GLOBAL OBJECTS ----------
SoftwareSerial hc12Serial(HC12_RX, HC12_TX);   // RX, TX
DHT dht(DHT_PIN, DHT22);                      // DHT22 type

unsigned long lastSendMillis = 0;              // Time stamp of last send

/*********************************************************************
  setup() – runs once at startup
*********************************************************************/
void setup() {
  // 1. Serial for debugging (optional, can be removed for 100% power‑saver)
  Serial.begin(9600);
  while (!Serial) ;  // Wait for serial monitor (useful during programming)

  // 2. HC‑12 serial
  hc12Serial.begin(9600);               // HC‑12 default baud rate
  Serial.println(F("HC‑12 initialized"));

  // 3. DHT sensor
  dht.begin();
  Serial.println(F("DHT sensor initialized"));

  // 4. Digital input pin
  pinMode(INPUT_PIN, INPUT_PULLUP);     // Pull‑up, adjust if you need pull‑down
  Serial.println(F("Digital input initialized"));
}

/*********************************************************************
  loop() – runs forever
*********************************************************************/
void loop() {
  // 1. Check if it's time to send a new packet
  unsigned long now = millis();
  if (now - lastSendMillis >= SEND_INTERVAL_MS) {
    lastSendMillis = now;  // reset timer

    // 2. Read temperature (°C). Returns NaN on failure.
    float temperature = dht.readTemperature();

    // 3. Read digital input (1 = HIGH, 0 = LOW)
    int digitalState = digitalRead(INPUT_PIN);

    // 4. Validate temperature reading
    if (isnan(temperature)) {
      Serial.println(F("Failed to read temperature from DHT"));
      // Optionally skip sending if reading fails
      return;
    }

    // 5. Build JSON‑style packet
    // Example: {"id":1,"temp":23.56,"input":0}
    String packet = "{";
    packet += "\"id\":";
    packet += DEVICE_ID;
    packet += ",\"temp\":";
    packet += String(temperature, 2); // 2 decimal places
    packet += ",\"input\":";
    packet += digitalState;
    packet += "}";

    // 6. Send via HC‑12
    hc12Serial.println(packet);

    // 7. Debug output
    Serial.print(F("Sent packet: "));
    Serial.println(packet);
