Below is a **starter kit** for a “BotDoggy” – a very simple web‑app that lets you “translate” a dog's bark (or a short audio clip) into a human‑readable description.  
The code is split into three parts:

1. **Backend** – A tiny Flask app that forwards the request to OpenAI’s GPT‑4 (or any GPT‑3.5‑turbo model you prefer) and returns the translated text.  
2. **Frontend** – A one‑page HTML site that lets the user record a short audio clip (or paste a text prompt), sends it to the Flask endpoint, and shows the result.  
3. **Styling** – A minimal CSS file to make the UI look decent.

> **⚠️ Security & Privacy Notice**  
> - This example sends *raw audio or text* to the OpenAI API. Make sure you **never** expose your API key to the client.  
> - In production you would add HTTPS, rate‑limiting, authentication, and proper error handling.  
> - This code is for educational purposes only. Use it responsibly and in compliance with OpenAI’s use‑case policy.

---

## 1️⃣ Backend – `app.py`

```python
# app.py
import os
import uuid
from flask import Flask, request, jsonify, send_from_directory
from flask_cors import CORS
import openai
import soundfile as sf

app = Flask(__name__, static_folder="static")
CORS(app)  # Allow cross‑origin requests from our front‑end

# --------------------------------------------------------------
# Configure OpenAI
# --------------------------------------------------------------
openai.api_key = os.getenv("OPENAI_API_KEY")  # Set in environment

MODEL_NAME = "gpt-4o-mini"  # or "gpt-3.5-turbo-1106"

# --------------------------------------------------------------
# Helpers
# --------------------------------------------------------------
def transcribe_audio(file_path: str) -> str:
    """
    Use Whisper to get the raw text transcription of a dog bark.
    """
    with open(file_path, "rb") as f:
        response = openai.audio.transcriptions.create(
            model="whisper-1",
            file=f,
        )
    return response.text

def generate_translation(prompt: str) -> str:
    """
    Ask GPT to turn the dog's sounds / transcription into a human readable message.
    """
    system_prompt = (
        "You are a helpful assistant that can translate dog barks, howls, whines, "
        "or any canine vocalization into a simple, human‑readable description. "
        "Respond concisely."
    )
    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": prompt},
    ]

    completion = openai.chat.completions.create(
        model=MODEL_NAME,
        messages=messages,
        temperature=0.7,
        max_tokens=150,
    )
    return completion.choices[0].message.content.strip()

# --------------------------------------------------------------
# Routes
# --------------------------------------------------------------
@app.route("/api/translate", methods=["POST"])
def translate():
    """
    Accepts either:
      - JSON: { "prompt": "<text>" }
      - Multipart form: file=audio
    """
    if request.is_json:
        data = request.get_json()
        prompt = data.get("prompt", "")
        if not prompt:
            return jsonify({"error": "Missing 'prompt' in JSON"}), 400
        translation = generate_translation(prompt)
        return jsonify({"translation": translation}), 200

    if "file" not in request.files:
        return jsonify({"error": "No audio file uploaded"}), 400

    audio_file = request.files["file"]
    if audio_file.filename == "":
        return jsonify({"error": "Empty file name"}), 400

    # Save temporarily
    tmp_name = f"tmp_{uuid.uuid4().hex}.wav"
    tmp_path = os.path.join("uploads", tmp_name)
    os.makedirs("uploads", exist_ok=True)
    audio_file.save(tmp_path)

    # Transcribe
    transcription = transcribe_audio(tmp_path)

    # Generate translation
    translation = generate_translation(transcription)

    # Clean up
    os.remove(tmp_path)

    return jsonify({"translation": translation, "transcription": transcription}), 200

# Serve static front‑end files
@app.route("/")
def index():
    return send_from_directory(app.static_folder, "index.html")

# --------------------------------------------------------------
# Run
# --------------------------------------------------------------
if __name__ == "__main__":
    # Make sure the uploads dir is cleaned each run
    if os.path.isdir("uploads"):
        for f in os.listdir("uploads"):
            os.remove(os.path.join("uploads", f))
    app.run(host="0.0.0.0", port=5000, debug=True)
```

