```js
// script.js
const recordBtn = document.getElementById('record-btn');
const stopBtn = document.getElementById('stop-btn');
const audioPreview = document.getElementById('audio-preview');
const textPrompt = document.getElementById('text-prompt');
const textTranslateBtn = document.getElementById('text-translate-btn');
const translationDiv = document.getElementById('translation');

let mediaRecorder;
let audioChunks = [];

recordBtn.addEventListener('click', async () => {
  // Request microphone
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  mediaRecorder = new MediaRecorder(stream);

  mediaRecorder.ondataavailable = e => audioChunks.push(e.data);
  mediaRecorder.onstop = async () => {
    const audioBlob = new Blob(audioChunks, { type: 'audio/wav' });
    audioChunks = [];

    // Show preview
    const url = URL.createObjectURL(audioBlob);
    audioPreview.src = url;
    audioPreview.load();

    // Send to server
    const form = new FormData();
    form.append('file', audioBlob, 'bark.wav');

    const response = await fetch('/api/translate', {
      method: 'POST',
      body: form,
    });

    const data = await response.json();
    if (response.ok) {
      translationDiv.textContent = `🐕 ${data.transcription}\n\n➡️ ${data.translation}`;
    } else {
      translationDiv.textContent = `Error: ${data.error}`;
    }
  };

  mediaRecorder.start();
  recordBtn.disabled = true;
  stopBtn.disabled = false;
});

stopBtn.addEventListener('click', () => {
  mediaRecorder.stop();
  recordBtn.disabled = false;
  stopBtn.disabled = true;
});

textTranslateBtn.addEventListener('click', async () => {
  const prompt = textPrompt.value.trim();
  if (!prompt) return;

  const response = await fetch('/api/translate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ prompt }),
  });

  const data = await response.json();
  if (response.ok) {
    translationDiv.textContent = `🐕 ${prompt}\n\n➡️ ${data.translation}`;
  } else {
    translationDiv.textContent = `Error: ${data.error}`;
  }
});
```

