### 3.1 初始化用户（initUser）

`cloudfunctions/initUser/index.js`

```javascript
const cloud = require('wx-server-sdk')
cloud.init()

const db = cloud.database()
const _ = db.command

// 云函数：initUser
exports.main = async (event, context) => {
  const { code } = event
  const wxContext = cloud.getWXContext()

  // 调用微信接口获取 openid 和 session_key
  const res = await cloud.openapi.wxa.getSessionKeyByCode({ code })
  const { openid } = wxContext

  // 检查是否已存在用户记录
  const userRes = await db.collection('users')
    .where({ _openid: openid })
    .limit(1)
    .get()

  if (userRes.data.length > 0) {
    // 已存在：返回现有积分
    return { openId: openid, points: userRes.data[0].points }
  }

  // 新建用户记录，初始积分 0
  await db.collection('users').add({
    data: {
      points: 0
    }
  })

  return { openId: openid, points: 0 }
}
```

> **说明**：  
> - 这里使用 `wx.getOpenIdByCode`（`wx.getSessionKeyByCode` + `wxContext.OPENID`）确保安全。  
> - 初始积分设为 0；若你想给新人赠送积分，只需修改 `points` 初始值即可。

### 3.2 积分转账（transferPoints）

`cloudfunctions/transferPoints/index.js`

```javascript
const cloud = require('wx-server-sdk')
cloud.init()

const db = cloud.database()
const _ = db.command

// 云函数：transferPoints
exports.main = async (event, context) => {
  const { toOpenId, amount } = event
  const fromOpenId = context.OPENID

  if (!toOpenId) {
    throw new Error('缺少接收者 OpenID')
  }
  if (amount <= 0) {
    throw new Error('转账金额需大于 0')
  }

  // 使用事务保证原子性
  const trx = db.command.transaction()

  // 1. 检查发起方是否有足够积分
  const from = await db.collection('users')
    .where({ _openid: fromOpenId })
    .field({ points: true })
    .get()
  if (from.data.length === 0) {
    throw new Error('未找到发起方记录')
  }
  if (from.data[0].points < amount) {
    throw new Error('积分不足')
  }

  // 2. 检查接收方是否存在
  const to = await db.collection('users')
    .where({ _openid: toOpenId })
    .field({ points: true })
    .get()
  if (to.data.length === 0) {
    throw new Error('接收方不存在')
  }

  // 3. 执行扣减和加分
  await trx
    .collection('users')
    .doc(from.data[0]._id)
    .update({ data: { points: _.inc(-amount) } })
    .collection('users')
    .doc(to.data[0]._id)
    .update({ data: { points: _.inc(+amount) } })
    .commit()

  return { msg: `已成功转账 ${amount} 积分` }
}
```

> **安全要点**  
> - 所有用户身份均通过 `context.OPENID` 确认，防止伪造。  
> - 通过 `transaction`（事务）保证扣减/加分操作是原子性的，防止并发导致积分错误。  
> - 对输入做最基本的合法性校验。

