```python
#!/usr/bin/env python3
"""
Flask app to copy all .mp4 files from a source directory to a USB drive,
and expose a simple web UI with a progress bar.
"""

import os
import shutil
import threading
import time
from pathlib import Path
from typing import List

from flask import Flask, jsonify, render_template, request

app = Flask(__name__)

# Configuration
SOURCE_DIR = Path("/home/<USER>/Videos")        # À adapter
USB_MOUNT_POINT = Path("/media/usb")            # À adapter
ALLOWED_EXTENSIONS = {".mp4"}                   # Extension autorisée

# Shared state (protected by a lock)
progress = {
    "total_files": 0,
    "copied_files": 0,
    "files": [],       # List of filenames processed
    "status": "idle"   # "idle" | "running" | "finished" | "error"
}
lock = threading.Lock()


def find_mp4_files(source: Path) -> List[Path]:
    """Return a list of all .mp4 files in the source directory."""
    return sorted(
        [f for f in source.rglob("*") if f.suffix.lower() in ALLOWED_EXTENSIONS],
        key=lambda p: p.name
    )


def copy_files():
    """Background worker that copies files and updates the global progress."""
    with lock:
        progress["status"] = "running"
        progress["total_files"] = 0
        progress["copied_files"] = 0
        progress["files"] = []

    mp4_files = find_mp4_files(SOURCE_DIR)

    with lock:
        progress["total_files"] = len(mp4_files)

    for idx, src_path in enumerate(mp4_files, start=1):
        # Target path relative to USB mount
        relative_path = src_path.relative_to(SOURCE_DIR)
        dest_path = USB_MOUNT_POINT / relative_path

        # Ensure parent directories exist
        dest_path.parent.mkdir(parents=True, exist_ok=True)

        try:
            shutil.copy2(src_path, dest_path)
        except Exception as e:
            # Log the error, keep going
            with lock:
                progress["status"] = f"error: {e}"
            break

        # Update progress
        with lock:
            progress["copied_files"] = idx
            progress["files"].append(str(relative_path))

    with lock:
        if progress["status"] != f"error":
            progress["status"] = "finished"


@app.route("/")
def index():
    """Serve the main page."""
    return render_template("index.html")


@app.route("/start", methods=["POST"])
def start_copy():
    """Endpoint invoked by the button to launch the copy."""
    with lock:
        if progress["status"] == "running":
            return jsonify({"ok": False, "msg": "Copy already in progress."}), 400

    thread = threading.Thread(target=copy_files, daemon=True)
    thread.start()

    return jsonify({"ok": True, "msg": "Copy started."})


@app.route("/progress")
def get_progress():
    """Return the current progress as JSON."""
    with lock:
        pct = (
            int(progress["copied_files"] / progress["total_files"] * 100)
            if progress["total_files"] else 0
        )
        return jsonify(
            {
                "status": progress["status"],
                "total_files": progress["total_files"],
                "copied_files": progress["copied_files"],
                "percentage": pct,
                "files": progress["files"],
            }
        )


if __name__ == "__main__":
    # Run the app on localhost:5000; change host/port as needed.
    app.run(host="0.0.0.0", port=5000, debug=False)
```

> **Remarques**  
> * `SOURCE_DIR` et `USB_MOUNT_POINT` doivent être ajustés à ta configuration.  
> * Le script utilise un thread d’arrière‑plan (`daemon=True`) pour ne pas bloquer le serveur.  
> * Le dictionnaire `progress` est protégé par un `threading.Lock()` pour éviter les race‑conditions.  

