// progress.js – Fetch progress every 1 s and update the UI
document.addEventListener("DOMContentLoaded", () => {
    const startBtn = document.getElementById("start-btn");
    const progressBar = document.getElementById("progress-bar");
    const alertArea = document.getElementById("alert-area");
    const fileList = document.getElementById("file-list");

    let polling = false;
    let pollInterval = null;

    const fetchProgress = async () => {
        try {
            const resp = await fetch("/progress");
            const data = await resp.json();

            // Update progress bar
            const pct = data.percentage;
            progressBar.style.width = pct + "%";
            progressBar.setAttribute("aria-valuenow", pct);
            progressBar.textContent = pct + "%";

            // Show status message
            if (data.status === "running") {
                showAlert("info", "Copie en cours…");
            } else if (data.status === "finished") {
                showAlert("success", "Copie terminée !");
                stopPolling();
            } else if (data.status.startsWith("error")) {
                showAlert("danger", "Erreur : " + data.status);
                stopPolling();
            } else if (data.status === "idle") {
                showAlert("secondary", "Prêt.");
            }

            // List of copied files
            fileList.innerHTML = "<strong>Fichiers copiés :</strong><ul>" +
                data.files.map(f => "<li>" + f + "</li>").join("") +
                "</ul>";

        } catch (err) {
            console.error(err);
        }
    };

    const startPolling = () => {
        if (!polling) {
            polling = true;
            pollInterval = setInterval(fetchProgress, 1000);
        }
    };

    const stopPolling = () => {
        if (polling) {
            clearInterval(pollInterval);
            polling = false;
        }
    };

    const showAlert = (type, message) => {
        alertArea.innerHTML =
            `<div class="alert alert-${type} alert-dismissible fade show" role="alert">
                ${message}
                <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>
            </div>`;
    };

    startBtn.addEventListener("click", async () => {
        startBtn.disabled = true;
        try {
            const resp = await fetch("/start", { method: "POST" });
            const data = await resp.json();

            if (data.ok) {
                showAlert("info", "Copie lancée !");
                startPolling();
            } else {
                showAlert("danger", data.msg || "Impossible de lancer la copie.");
                startBtn.disabled = false;
            }
        } catch (err) {
            showAlert("danger", "Erreur réseau.");
            startBtn.disabled = false;
        }
    });
});
```

