/*********************************************************************
 * 题目：将两个升序链表合并为一个新的升序链表（仅重新连接节点）
 * 说明：链表结构使用标准单向链表；合并时仅移动指针，不创建新的节点。
 * 安全性提示：
 *   1. 对输入指针做空检查，避免空指针解引用。
 *   2. 对 malloc（若需要）做失败检查，防止内存分配错误导致程序崩溃。
 *   3. 在演示中使用 free() 释放临时分配的内存，避免泄漏。
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>

/* ---------- 链表结构 ---------- */
typedef struct ListNode {
    int val;
    struct ListNode *next;
} ListNode;

/* ---------- 辅助函数 ---------- */

/* 创建一个单独节点，返回指针；失败时返回 NULL */
static ListNode* create_node(int val)
{
    ListNode *node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;      /* 记得调用者要检查返回值 */
    }
    node->val = val;
    node->next = NULL;
    return node;
}

/* 追加节点到链表尾部（用于构造测试用链表） */
static void append_node(ListNode **head, ListNode **tail, int val)
{
    ListNode *new_node = create_node(val);
    if (!new_node) return;   /* 失败直接返回，调用者需检查 head/tail */

    if (*head == NULL) {
        *head = *tail = new_node;
    } else {
        (*tail)->next = new_node;
        *tail = new_node;
    }
}

/* 打印链表（仅用于调试/演示） */
static void print_list(const ListNode *head)
{
    const ListNode *cur = head;
    while (cur) {
        printf("%d", cur->val);
        if (cur->next) printf(" -> ");
        cur = cur->next;
    }
    printf("\n");
}

/* 释放链表（仅用于演示） */
static void free_list(ListNode *head)
{
    while (head) {
        ListNode *tmp = head;
        head = head->next;
        free(tmp);
    }
}

/* ---------- 主要功能：合并两个升序链表 ---------- */

/*
 * 说明：
 *   - l1, l2 为两个升序链表头指针（可为 NULL）。
 *   - 该函数直接拼接节点，返回新的升序链表头指针。
 *   - 输入链表不做复制，调用者仍然可以继续使用 l1 / l2。
 */
ListNode* merge_two_lists(ListNode *l1, ListNode *l2)
{
    /* 先处理空链表情况 */
    if (!l1) return l2;   /* 若 l1 为 NULL，直接返回 l2（可能为 NULL） */
    if (!l2) return l1;   /* 若 l2 为 NULL，直接返回 l1 */

    /* 用 dummy 节点简化边界处理 */
    ListNode dummy;
    dummy.next = NULL;
    ListNode *tail = &dummy;   /* tail 追踪当前合并链表的尾部 */

    while (l1 && l2) {
        /* 取值较小的节点并拼接 */
        if (l1->val <= l2->val) {
            tail->next = l1;      /* 直接连接 l1 */
            l1 = l1->next;        /* l1 向后移动 */
        } else {
            tail->next = l2;      /* 直接连接 l2 */
            l2 = l2->next;        /* l2 向后移动 */
        }
        tail = tail->next;        /* tail 也向后移动 */
    }

    /* 剩余节点直接拼接 */
    tail->next = l1 ? l1 : l2;   /* l1 与 l2 至少一个为 NULL */

    return dummy.next;   /* 返回新链表头 */
}

/* ---------- 演示主程序 ---------- */
int main(void)
{
    /* 构造示例链表：l1 = 1 -> 3 -> 5, l2 = 2 -> 4 -> 6 -> 8 */
    ListNode *l1 = NULL, *t1 = NULL;
    ListNode *l2 = NULL, *t2 = NULL;
    int arr1[] = {1, 3, 5};
    int arr2[] = {2, 4, 6, 8};

    for (size_t i = 0; i < sizeof(arr1)/sizeof(arr1[0]); ++i)
        append_node(&l1, &t1, arr1[i]);

    for (size_t i = 0; i < sizeof(arr2)/sizeof(arr2[0]); ++i)
        append_node(&l2, &t2, arr2[i]);

    printf("List 1: ");
    print_list(l1);
    printf("List 2: ");
    print_list(l2);

    /* 合并 */
    ListNode *merged = merge_two_lists(l1, l2);

    printf("Merged List: ");
    print_list(merged);

    /* 释放内存 */
    free_list(merged);   /* merged 已经包含了 l1 和 l2 的所有节点 */

    return 0;
}
```

### 关键点说明

| 步骤 | 说明 |
|------|------|
| **空指针检查** | `merge_two_lists` 开头就判断 `l1` 或 `l2` 是否为 NULL，避免后续解引用空指针。 |
| **dummy 节点** | 用来统一头节点的处理，减少对首节点的特殊判断。 |
| **直接拼接** | 通过 `tail->next = l1/l2;` 直接把原链表节点连到新链表尾部，**不产生新节点**。 |
| **剩余节点拼接** | 循环结束后，只剩下一个链表未遍历完，直接把它接到尾部即可。 |
| **内存释放** | 合并完成后，`merged` 已经拥有所有原节点，使用 `free_list` 统一释放，避免泄漏。 |
| **安全性** | 所有 `malloc` 调用均检查返回值；对外部传入的指针进行空检查；演示主程序在结束前释放所有分配的内存。 |

> 只要保证输入链表是合法的且在程序结束前释放了所有分配的内存，以上代码在安全性方面已满足常见的安全研究需求。若在更高安全性的环境中使用，可进一步加入对异常条件（如链表环等）的检测。祝你实验顺利！

