/* controller.c – пример полного решения */

#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include "mjson.h"

#define MAX_IO 6

typedef struct {
    uint8_t src;
    uint8_t dst;
} transition_t;

static uint8_t adjacency[MAX_IO][MAX_IO] = {0};
static uint8_t relay_state[MAX_IO] = {0};

int load_mapping(const char *json)
{
    memset(adjacency, 0, sizeof(adjacency));
    struct mjson *root = mjson_parse(json, strlen(json));
    if (!root || !root->type || root->type != MJSON_ARRAY) return -1;

    struct mjson *el = root->child;
    int count = 0;
    while (el) {
        int button = -1, relay = -1;
        struct mjson *obj = el->child;
        while (obj) {
            if (obj->type != MJSON_PAIR) { obj = obj->next; continue; }
            if (!strcmp(obj->key, "button")) {
                if (obj->type == MJSON_INT && obj->intvalue >= 1 && obj->intvalue <= MAX_IO)
                    button = (int)obj->intvalue - 1;
            } else if (!strcmp(obj->key, "relay")) {
                if (obj->type == MJSON_INT && obj->intvalue >= 1 && obj->intvalue <= MAX_IO)
                    relay = (int)obj->intvalue - 1;
            }
            obj = obj->next;
        }
        if (button >= 0 && relay >= 0) {
            adjacency[button][relay] = 1;
            count++;
        }
        el = el->next;
    }
    mjson_destroy(root, 0);
    return count;
}

void handle_button(uint8_t button)
{
    if (button < 1 || button > MAX_IO) return;
    uint8_t visited[MAX_IO] = {0};
    uint8_t stack[MAX_IO];
    int sp = 0;
    stack[sp++] = button - 1;
    while (sp) {
        uint8_t cur = stack[--sp];
        if (visited[cur]) continue;
        visited[cur] = 1;
        for (uint8_t nxt = 0; nxt < MAX_IO; ++nxt) {
            if (adjacency[cur][nxt]) {
                relay_state[nxt] = 1;
                stack[sp++] = nxt;
            }
        }
    }
}

void clear_relays(void)
{
    memset(relay_state, 0, sizeof(relay_state));
}

int main(void)
{
    const char *json_str =
        "[{\"button\":1,\"relay\":2},{\"button\":1,\"relay\":4},{\"button\":2,\"relay\":1}]";

    if (load_mapping(json_str) < 0) {
        printf("Ошибка загрузки карты\n");
        return -1;
    }

    /* Симуляция событий */
    clear_relays();
    handle_button(1);
    handle_button(2);

    for (int i = 0; i < MAX_IO; ++i)
        printf("Relay %d: %s\n", i+1, relay_state[i] ? "ON" : "OFF");

    return 0;
}
```

