#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_TASK_LEN 128   /* Maximum length of a task description (excluding NUL) */
#define INPUT_BUF   256   /* Buffer for raw user input */

/* ------------------------------------------------------------------- */
/*   Data structures                                                  */
/* ------------------------------------------------------------------- */
typedef struct Task {
    char desc[MAX_TASK_LEN + 1]; /* +1 for terminating NUL */
    struct Task *next;
} Task;

/* Head of the singly linked list of tasks */
static Task *head = NULL;

/* ------------------------------------------------------------------- */
/*   Helper functions                                                 */
/* ------------------------------------------------------------------- */

/* Safely read a line of input, stripping trailing newline */
static void read_line(const char *prompt, char *buf, size_t buflen)
{
    if (prompt && *prompt) {
        printf("%s", prompt);
        fflush(stdout);
    }

    if (fgets(buf, (int)buflen, stdin) == NULL) {
        /* EOF or error – treat as empty string */
        buf[0] = '\0';
        return;
    }

    /* Remove trailing newline if present */
    size_t len = strcspn(buf, "\n");
    buf[len] = '\0';
}

/* Create a new task node with the given description */
static Task *create_task(const char *description)
{
    Task *node = malloc(sizeof(Task));
    if (!node) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    /* Ensure the description does not exceed the allowed length */
    strncpy(node->desc, description, MAX_TASK_LEN);
    node->desc[MAX_TASK_LEN] = '\0';   /* guarantee NUL termination */

    node->next = NULL;
    return node;
}

/* Append a task to the end of the list */
static void add_task(const char *desc)
{
    Task *node = create_task(desc);

    if (!head) {
        head = node;
    } else {
        Task *p = head;
        while (p->next) p = p->next;
        p->next = node;
    }
    printf("Task added.\n");
}

/* Print all tasks with zero‑based index */
static void list_tasks(void)
{
    if (!head) {
        printf("No tasks.\n");
        return;
    }

    printf("Current tasks:\n");
    Task *p = head;
    size_t idx = 0;
    while (p) {
        printf("%zu: %s\n", idx, p->desc);
        p = p->next;
        idx++;
    }
}

/* Delete a task at the given zero‑based index */
static void delete_task(size_t index)
{
    if (!head) {
        printf("No tasks to delete.\n");
        return;
    }

    Task *p = head;
    Task *prev = NULL;
    size_t idx = 0;

    while (p && idx < index) {
        prev = p;
        p = p->next;
        idx++;
    }

    if (!p) {
        printf("Invalid index.\n");
        return;
    }

    if (!prev) {          /* deleting head */
        head = p->next;
    } else {
        prev->next = p->next;
    }

    free(p);
    printf("Task deleted.\n");
}

/* Clean up all allocated memory */
static void free_all(void)
{
    Task *p = head;
    while (p) {
        Task *next = p->next;
        free(p);
        p = next;
    }
    head = NULL;
}

/* ------------------------------------------------------------------- */
/*   Menu handling                                                   */
/* ------------------------------------------------------------------- */

static void show_menu(void)
{
    puts("\nTodo List");
    puts("=========");
    puts("1) Add a new task");
    puts("2) List all tasks");
    puts("3) Delete a task");
    puts("4) Quit");
}

static int get_choice(void)
{
    char buf[INPUT_BUF];
    read_line("Select an option: ", buf, sizeof(buf));

    /* Convert to integer safely */
    char *endptr;
    errno = 0;
    long val = strtol(buf, &endptr, 10);
    if (errno != 0 || endptr == buf || *endptr != '\0' || val < 1 || val > 4) {
        return -1;   /* invalid */
    }
    return (int)val;
}

/* ------------------------------------------------------------------- */
/*   Main program                                                    */
/* ------------------------------------------------------------------- */

int main(void)
{
    printf("Secure Todo List – C Implementation\n");

    for (;;) {
        show_menu();

        int choice = get_choice();
        if (choice == -1) {
            printf("Invalid selection. Please enter a number between 1 and 4.\n");
            continue;
        }

        switch (choice) {
            case 1: { /* Add a task */
                char desc[INPUT_BUF];
                read_line("Enter task (max 128 chars): ", desc, sizeof(desc));

                /* Enforce maximum length for safety */
                if (strlen(desc) > MAX_TASK_LEN) {
                    desc[MAX_TASK_LEN] = '\0';
                    printf("Task truncated to %d characters.\n", MAX_TASK_LEN);
                }
                add_task(desc);
                break;
            }
            case 2: /* List tasks */
                list_tasks();
                break;
            case 3: { /* Delete a task */
                char buf[INPUT_BUF];
                read_line("Enter index to delete: ", buf, sizeof(buf));

                char *endptr;
                errno = 0;
                long val = strtol(buf, &endptr, 10);
                if (errno != 0 || endptr == buf || *endptr != '\0' || val < 0) {
                    printf("Invalid index.\n");
                    break;
                }
                delete_task((size_t)val);
                break;
            }
            case 4: /* Quit */
                free_all();
                printf("Bye!\n");
                return EXIT_SUCCESS;
            default:
                /* Should never hit */
                assert(0 && "Unexpected menu option");
        }
    }

    /* Unreachable, but keeps compiler happy */
    return EXIT_SUCCESS;
}
```

