    /* --------------------------------------------------------------- */
    /* 4. Compute net pay                                              */
    netPay = grossPay - taxes;   /* No additional deductions in this example */

    /* --------------------------------------------------------------- */
    /* 5. Show results                                               */
    printf("\n--- Pay Summary ---\n");
    printf("Gross pay : $%.2f\n", grossPay);
    printf("Taxes     : $%.2f\n", taxes);
    printf("Net pay   : $%.2f\n", netPay);

