            table[idx].value = val;
            table[idx].count = 1;
            table[idx].used  = 1;
            return;
        } else if (table[idx].value == val) {
            /* Value already present – increment counter */
            table[idx].count += 1;
            return;
        }
        /* Linear probing – move to next slot */
        h = (h + 1) & (TABLE_SIZE - 1);
    }
