 *  1. Classic bit‑by‑bit loop
 *  ----------------------------------
 *  Very clear, but O(32) operations.  No branches depend on data.
 * ------------------------------------------------------------------ */
static inline uint32_t popcnt_loop(uint32_t x)
{
    uint32_t count = 0;
    /* No data‑dependent branching: we only use bitwise ops. */
    for (int i = 0; i < 32; ++i) {
