#include <stdio.h>

#define MAX(a,b) ((a) > (b) ? (a) : (b))

int lengthOfLIS(int *nums, int numsSize)
{
    /* 合法性检查 */
    if (nums == NULL || numsSize <= 0)
        return 0;

    /* 为了安全，限制最大长度（如果业务允许可移除） */
    if (numsSize > 3000) {
        fprintf(stderr, "Error: numsSize exceeds safe limit (3000)\n");
        return -1;   /* 或者返回 0 并记录错误 */
    }

    /* 动态分配 dp 数组，避免栈溢出 */
    int *dp = (int *)malloc(numsSize * sizeof(int));
    if (!dp) {
        perror("malloc");
        return -1;
    }

    /* 初始化 dp 为 1（每个位置至少能自己形成子序列） */
    for (int i = 0; i < numsSize; ++i)
        dp[i] = 1;

    int maxLen = 1;   /* 记录全局最长子序列长度 */

    for (int i = 1; i < numsSize; ++i) {
        for (int j = 0; j < i; ++j) {
            if (nums[i] > nums[j])
                dp[i] = MAX(dp[i], dp[j] + 1);
        }
        maxLen = MAX(maxLen, dp[i]);
    }

    free(dp);   /* 记得释放 */
    return maxLen;
}
```

