```c
#include <stdio.h>
#include <stdint.h>

/**
 * solve_chicken_rabbit - 用指针返回鸡兔数量
 * @heads   : 头数（鸡 + 兔）
 * @feet    : 蹄数（2*鸡 + 4*兔）
 * @chickens: 指针，函数会将计算出的鸡数写入
 * @rabbits : 指针，函数会将计算出的兔数写入
 *
 * 返回值：
 *   0  : 成功，找到唯一解
 *  -1  : 参数非法（如负数、无解、多个解）
 *
 * 公式推导：
 *   heads = C + R
 *   feet  = 2*C + 4*R
 *
 *  从第一个方程得到 C = heads - R
 *  代入第二个方程得到：
 *      feet = 2*(heads - R) + 4*R
 *      feet = 2*heads + 2*R
 *      2*R = feet - 2*heads
 *      R   = (feet - 2*heads) / 2
 *
 *  由于 R 必须是整数并满足 0 <= R <= heads，才为合法解。
 */
int solve_chicken_rabbit(int heads, int feet, int *chickens, int *rabbits)
{
    /* 参数合法性检查 */
    if (heads < 0 || feet < 0 || chickens == NULL || rabbits == NULL)
        return -1;

    /* 用 64 位整数计算，防止溢出 */
    int64_t h = heads;
    int64_t f = feet;

    /* 先算兔子数量 */
    int64_t diff = f - 2 * h;          /* f - 2*h 必须是偶数 */
    if (diff < 0)                     /* 兔子数为负 */
        return -1;
    if (diff % 2 != 0)                /* 不是整数解 */
        return -1;

    int64_t R = diff / 2;             /* 兔子数 */
    if (R > h)                        /* 兔子数大于头数 */
        return -1;

    int64_t C = h - R;                /* 鸡数 */
    if (C < 0)                        /* 负数不可能 */
        return -1;

    /* 把结果写回指针 */
    *chickens = (int)C;
    *rabbits  = (int)R;

    return 0;
}

/* -------------------- 测试代码 -------------------- */
int main(void)
{
    int heads, feet;
    int chickens, rabbits;

    printf("输入头数和脚数（用空格分隔）：");
    if (scanf("%d %d", &heads, &feet) != 2) {
        fprintf(stderr, "输入格式错误\n");
        return 1;
    }

    if (solve_chicken_rabbit(heads, feet, &chickens, &rabbits) == 0) {
        printf("鸡 = %d, 兔 = %d\n", chickens, rabbits);
    } else {
        printf("无合法解\n");
    }

    return 0;
}
```

### 说明

1. **指针参数**  
   `chickens`、`rabbits` 是函数的输出参数，调用者通过传入指针获得结果，符合题目“利用指针做参数”的要求。

2. **安全性**  
   - 对负数和空指针做了检查。  
   - 使用 `int64_t` 进行中间运算，防止在大头数/脚数下发生溢出。  
   - 通过判断 `diff % 2 == 0` 确保解是整数。

3. **可复用性**  
   只需要 `solve_chicken_rabbit()`，其余逻辑（如输入/输出）可以根据需求自行编写。

4. **扩展**  
   如果你需要在逆向/安全研究环境中将此函数嵌入到二进制或脚本中，只要保持参数顺序和指针写回方式即可。

