### Что мы будем делать  

Orange‑Pi Zero LTS хранит свой уникальный идентификатор в нескольких местах:
1. **/proc/cpuinfo** – поле `Serial` (это серийный номер самого SoC).  
2. **/sys/class/dmi/id/product_serial** – если устройство поставляется с прошивкой, поддерживающей DMI/SMBIOS.  
3. **MAC‑адреса** любого сетевого интерфейса – они тоже уникальны, но могут меняться при смене карты памяти/модемов.

Ниже приведены два простых способа получить один из этих идентификаторов:
* **Bash‑скрипт** – быстро и без компиляции.  
* **C‑программа** – если хочется встроить это в более крупный проект.  

---

## 1. Bash‑скрипт

```bash
#!/usr/bin/env bash

# 1) Попробуем получить серийный номер из /proc/cpuinfo
if [[ -f /proc/cpuinfo ]]; then
    SERIAL=$(grep -i '^Serial' /proc/cpuinfo | awk -F': ' '{print $2}')
    if [[ -n "$SERIAL" ]]; then
        echo "Уникальный ID (Serial из /proc/cpuinfo): $SERIAL"
        exit 0
    fi
fi

# 2) Попробуем из DMI/SMBIOS
if [[ -f /sys/class/dmi/id/product_serial ]]; then
    SERIAL=$(cat /sys/class/dmi/id/product_serial)
    if [[ -n "$SERIAL" ]]; then
        echo "Уникальный ID (product_serial): $SERIAL"
        exit 0
    fi
fi

# 3) Последний вариант – MAC‑адрес первого активного интерфейса
MAC=$(ip link | awk -F': ' '/state UP/{print $2; exit}')
if [[ -n "$MAC" ]]; then
    # Убираем двоеточия и выводим в hex без разделителей
    MAC_HX=$(echo "$MAC" | tr -d ':' | tr '[:lower:]' '[:upper:]')
    echo "Уникальный ID (MAC‑адрес): $MAC_HX"
    exit 0
fi

echo "Не удалось найти уникальный идентификатор"
exit 1
```

### Как пользоваться

1. Скопируйте скрипт в файл, например `get_board_id.sh`.  
2. Сделайте его исполняемым:  
   ```bash
   chmod +x get_board_id.sh
   ```  
3. Запустите:  
   ```bash
   ./get_board_id.sh
   ```

---

## 2. C‑программа

```c
/* get_board_id.c
 *
 * Простейшая программа, которая пытается вывести уникальный идентификатор
 * Orange‑Pi Zero LTS. Приоритет: /proc/cpuinfo → /sys/class/dmi/id/product_serial →
 * MAC‑адрес.
 *
 * Компиляция:
 *   gcc -Wall -O2 -o get_board_id get_board_id.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define BUF_SIZE 512

/* Читает строку из файла */
static int read_first_line(const char *path, char *buf, size_t size) {
    FILE *f = fopen(path, "r");
    if (!f) return -1;
    if (!fgets(buf, size, f)) { fclose(f); return -1; }
    /* Удаляем возможный перевод строки */
    buf[strcspn(buf, "\n\r")] = '\0';
    fclose(f);
    return 0;
}

/* Получаем серийный номер из /proc/cpuinfo */
static int get_cpuinfo_serial(char *buf, size_t size) {
    FILE *f = fopen("/proc/cpuinfo", "r");
    if (!f) return -1;
    char line[BUF_SIZE];
    int found = 0;
    while (fgets(line, sizeof(line), f)) {
        if (strncmp(line, "Serial", 6) == 0) {
            char *p = strchr(line, ':');
            if (p) {
                /* Переходим к первому символу после ':' и убираем пробелы */
                p++;
                while (*p == ' ') p++;
                strncpy(buf, p, size - 1);
                buf[size - 1] = '\0';
                /* Удаляем перевод строки */
                buf[strcspn(buf, "\n\r")] = '\0';
                found = 1;
                break;
            }
        }
    }
    fclose(f);
    return found ? 0 : -1;
}

/* Получаем серийный номер из DMI/SMBIOS */
static int get_dmi_serial(char *buf, size_t size) {
    return read_first_line("/sys/class/dmi/id/product_serial", buf, size);
}

/* Получаем MAC‑адрес первого активного интерфейса */
static int get_mac_address(char *buf, size_t size) {
    /* Открываем /sys/class/net и ищем первый интерфейс в UP state */
    FILE *f = fopen("/proc/net/if_inet6", "r");
    if (!f) return -1;   /* Если такой файл не существует, ничего не делаем */
    fclose(f);           /* Просто чтобы убедиться, что каталог /proc/net/if_inet6 существует */

    char iface[64];
    char mac[BUF_SIZE];
    /* Находим первый интерфейс в UP состоянии */
    FILE *fp = popen("ip -o link show up | awk -F': ' '{print $2}' | head -n1", "r");
    if (!fp) return -1;
    if (!fgets(iface, sizeof(iface), fp)) { pclose(fp); return -1; }
    pclose(fp);
    iface[strcspn(iface, "\n\r")] = '\0';

    /* Читаем MAC‑адрес из /sys/class/net/<iface>/address */
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/net/%s/address", iface);
    if (read_first_line(path, mac, sizeof(mac)) != 0) return -1;

    /* Убираем двоеточия и переводим в верхний регистр */
    size_t len = strlen(mac);
    if (len < size) {
        int j = 0;
        for (size_t i = 0; i < len; i++) {
            if (mac[i] != ':') {
                buf[j++] = toupper((unsigned char)mac[i]);
            }
        }
        buf[j] = '\0';
        return 0;
    }
    return -1;
}

int main(void) {
    char id[BUF_SIZE] = {0};

    if (get_cpuinfo_serial(id, sizeof(id)) == 0) {
        printf("Уникальный ID (Serial из /proc/cpuinfo): %s\n", id);
        return 0;
    }

    if (get_dmi_serial(id, sizeof(id)) == 0) {
        printf("Уникальный ID (product_serial): %s\n", id);
        return 0;
    }

    if (get_mac_address(id, sizeof(id)) == 0) {
        printf("Уникальный ID (MAC‑адрес): %s\n", id);
        return 0;
    }

    fprintf(stderr, "Не удалось найти уникальный идентификатор\n");
    return 1;
}
```

### Как компилировать и запускать

```bash
gcc -Wall -O2 -o get_board_id get_board_id.c
./get_board_id
```

---

## Краткое пояснение

| Шаг | Что читается | Зачем |
|-----|--------------|-------|
| 1 | `/proc/cpuinfo` – поле `Serial` | Стандартный способ получения серийного номера SoC. |
| 2 | `/sys/class/dmi/id/product_serial` | Если устройство поддерживает SMBIOS/DMI. |
| 3 | MAC‑адрес интерфейса | Последний вариант, если первые два не доступны. |

Обычно первый вариант (`Serial` из `/proc/cpuinfo`) даёт постоянный уникальный номер для конкретного Orange‑Pi Zero. Он не меняется при форматировании SD‑карты и может использоваться как «уникальный номер платы».

Если нужна более «гибкая» схема (например, хотеть менять ID вручную), можно дописать скрипт/программу, которая будет хранить пользовательский ID в файле `/etc/board_id` или в EEPROM (если оно есть).

Надеюсь, это поможет вам идентифицировать вашу Orange‑Pi Zero! Если понадобится доработать скрипт под конкретный кейс, дайте знать.

