{
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(bases[i].basename, name) == 0)
            return i;
    }
    return (size_t)-1;
}

/* Добавляем слово в массив слов для конкретной базы */
static void add_word(Base *b, const char *w)
{
    if (b->word_cnt == b->word_cap) {
        size_t new_cap = b->word_cap ? b->word_cap * 2 : INITIAL_WORD_CAPACITY;
        char **tmp = realloc(b->words, new_cap * sizeof(char *));
        if (!tmp) { perror("realloc(words)"); exit(EXIT_FAILURE); }
        b->words = tmp;
        b->word_cap = new_cap;
    }
    b->words[b->word_cnt++] = strdup(w);
}

/* ---------------------------------  Основные функции  --------------------------------- */

/* Чтение файла с базами (file2.txt) */
static void load_bases(const char *path, Base **out_bases, size_t *out_cnt)
{
    FILE *f = fopen(path, "r");
    if (!f) { perror(path); exit(EXIT_FAILURE); }

    char line[LINE_BUF_SIZE];
    Base *bases = NULL;
    size_t cap = 0;
    size_t cnt = 0;

    while (fgets(line, sizeof(line), f)) {
        /* Ожидаемый формат: "base-a":"./a.db" */
        char tmp_b[256], tmp_p[256];
        if (sscanf(line, "\"%[^\"]\":\"%[^\"]\"", tmp_b, tmp_p) != 2)
            continue; /* пропускаем невалидные строки */

        trim(tmp_b);
        trim(tmp_p);

        /* Добавляем в массив bases */
        if (cnt == cap) {
            size_t new_cap = cap ? cap * 2 : INITIAL_BASE_CAPACITY;
            Base *tmp = realloc(bases, new_cap * sizeof(Base));
            if (!tmp) { perror("realloc(bases)"); exit(EXIT_FAILURE); }
            bases = tmp;
            cap = new_cap;
        }

        Base *b = &bases[cnt++];
        b->basename   = strdup(tmp_b);
        b->pathtobase = strdup(tmp_p);
        b->words      = NULL;
        b->word_cnt   = 0;
        b->word_cap   = 0;
    }

    fclose(f);
    *out_bases = bases;
    *out_cnt   = cnt;
}

/* Чтение файла с словами для каждой базы (например, a.db) */
static void load_words_for_bases(Base *bases, size_t count)
{
    for (size_t i = 0; i < count; ++i) {
        Base *b = &bases[i];
        FILE *f = fopen(b->pathtobase, "r");
        if (!f) {
            fprintf(stderr, "Не удалось открыть %s\n", b->pathtobase);
            continue; /* пропускаем, но оставляем пустой список слов */
        }

        /* Читаем весь файл целиком */
        fseek(f, 0, SEEK_END);
        long sz = ftell(f);
        fseek(f, 0, SEEK_SET);
        char *buf = malloc(sz + 1);
        if (!buf) { perror("malloc(buf)"); exit(EXIT_FAILURE); }
        size_t rd = fread(buf, 1, sz, f);
        buf[rd] = '\0';
        fclose(f);

        /* Токенизируем по разделителям (пробел, табуляция, \n, \r) */
        char *tok = strtok(buf, " \t\r\n");
        while (tok) {
            add_word(b, tok);
            tok = strtok(NULL, " \t\r\n");
        }
        free(buf);
    }
}

/* Чтение файла text (file1.txt) */
static char *read_text_file(const char *path)
{
    FILE *f = fopen(path, "r");
    if (!f) { perror(path); exit(EXIT_FAILURE); }

    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    if (!buf) { perror("malloc(buf)"); exit(EXIT_FAILURE); }
    size_t rd = fread(buf, 1, sz, f);
    buf[rd] = '\0';
    fclose(f);
    return buf;
}

/* Создаём строку‑результат, заменяя маркеры */
static char *expand_placeholders(const char *text, Base *bases, size_t base_cnt)
{
    size_t out_cap = strlen(text) + 1;
    char *out = malloc(out_cap);
    if (!out) { perror("malloc(out)"); exit(EXIT_FAILURE); }
    size_t out_len = 0;

    const char *p = text;
    while (*p) {
        if (*p == '%') {
            /* ищем закрывающий % */
            const char *q = strchr(p + 1, '%');
            if (!q) {
                /* нет закрывающего, просто копируем остальное */
                size_t rem = strlen(p);
                if (out_len + rem + 1 > out_cap) {
                    out_cap = out_len + rem + 1;
                    out = realloc(out, out_cap);
                    if (!out) { perror("realloc(out)"); exit(EXIT_FAILURE); }
                }
                strcpy(out + out_len, p);
                break;
            }
            /* извлекаем имя базисного маркера */
            size_t name_len = q - (p + 1);
            char name[128];
            if (name_len >= sizeof(name)) name_len = sizeof(name) - 1;
            strncpy(name, p + 1, name_len);
            name[name_len] = '\0';

            /* ищем соответствующую базу */
            size_t idx = find_base(bases, base_cnt, name);
            if (idx != (size_t)-1 && bases[idx].word_cnt > 0) {
                /* случайное слово */
                const char *word = bases[idx].words[rand() % bases[idx].word_cnt];
                size_t wlen = strlen(word);
                if (out_len + wlen + 1 > out_cap) {
                    out_cap = out_len + wlen + 1;
                    out = realloc(out, out_cap);
                    if (!out) { perror("realloc(out)"); exit(EXIT_FAILURE); }
                }
                strcpy(out + out_len, word);
                out_len += wlen;
            } else {
                /* База не найдена – оставляем маркер без изменений */
                size_t mark_len = (q - p) + 1;
                if (out_len + mark_len + 1 > out_cap) {
                    out_cap = out_len + mark_len + 1;
                    out = realloc(out, out_cap);
                    if (!out) { perror("realloc(out)"); exit(EXIT_FAILURE); }
                }
                memcpy(out + out_len, p, mark_len);
                out_len += mark_len;
            }
            p = q + 1; /* продолжаем после закрывающего % */
        } else {
            /* обычный символ */
            if (out_len + 2 > out_cap) {
                out_cap *= 2;
                out = realloc(out, out_cap);
                if (!out) { perror("realloc(out)"); exit(EXIT_FAILURE); }
            }
            out[out_len++] = *p++;
        }
    }
    out[out_len] = '\0';
    return out;
}

/* ---------------------------------  Главная функция  --------------------------------- */

int main(void)
{
    srand((unsigned)time(NULL));

    /* 1) Запросим имена файлов */
    char source_path[256];
    char out_path[256];
    read_line("Введите имя исходного файла: ", source_path, sizeof(source_path));
    read_line("Введите имя файла для записи результата: ", out_path, sizeof(out_path));

    /* 2) Читаем исходный файл (source) и ищем 'text' и 'data' */
    FILE *src = fopen(source_path, "r");
    if (!src) { perror(source_path); exit(EXIT_FAILURE); }

    char line[LINE_BUF_SIZE];
    char text_file[256] = "", data_file[256] = "";
    while (fgets(line, sizeof(line), src)) {
        if (strstr(line, "\"text\"")) {
            sscanf(line, "\"text\":\"%[^\"]\"", text_file);
            trim(text_file);
        } else if (strstr(line, "\"data\"")) {
            sscanf(line, "\"data\":\"%[^\"]\"", data_file);
            trim(data_file);
        }
    }
    fclose(src);

    if (strlen(text_file) == 0 || strlen(data_file) == 0) {
        fprintf(stderr, "В исходном файле не найдены строки \"text\" или \"data\"\n");
        return EXIT_FAILURE;
    }

    /* 3) Загружаем базы (file2.txt) */
    Base *bases = NULL;
    size_t base_cnt = 0;
    load_bases(data_file, &bases, &base_cnt);

    /* 4) Для каждой базы читаем слова из соответствующего файла */
    load_words_for_bases(bases, base_cnt);

    /* 5) Читаем файл text (file1.txt) */
    char *text_content = read_text_file(text_file);

    /* 6) Расширяем маркеры */
    char *expanded = expand_placeholders(text_content, bases, base_cnt);

    /* 7) Записываем результат в выходной файл */
    FILE *out = fopen(out_path, "w");
    if (!out) { perror(out_path); exit(EXIT_FAILURE); }
    fputs(expanded, out);
    fclose(out);

    /* Очистка памяти */
    free(text_content);
    free(expanded);
    for (size_t i = 0; i < base_cnt; ++i) {
        free(bases[i].basename);
        free(bases[i].pathtobase);
        for (size_t j = 0; j < bases[i].word_cnt; ++j)
            free(bases[i].words[j]);
        free(bases[i].words);
    }
    free(bases);

    printf("Готово! Результат записан в %s\n", out_path);
    return EXIT_SUCCESS;
}
```

---

## Как собрать и запустить

```bash
gcc -std=c99 -Wall -Wextra -O2 -o expand expand.c
./expand
```

В ходе работы программа попросит ввести:

```
Введите имя исходного файла:  source.txt
Введите имя файла для записи результата:  out.txt
```

После выполнения вы найдёте `out.txt` с заменёнными маркерами.  

---

### Что делает код

1. **Чтение входных данных** – из файла `source.txt` извлекаются имена файлов `file1.txt` и `file2.txt`.
2. **Парсинг `file2.txt`** – каждая строка вида `"base-a":"./a.db"` превращается в структуру `Base`.
3. **Загрузка слов** – из каждого указанного файла‑базы читаются все слова (разделители – пробелы, табуляции, переводы строк).
4. **Чтение `file1.txt`** – строка с маркерами `%base-a% …`.
5. **Замена маркеров** – каждый маркер заменяется случайным словом из соответствующей базы; если база не найдена, маркер остаётся без изменений.
6. **Запись результата** в файл, указанный пользователем.

Все операции сопровождаются проверкой ошибок, чтобы при любой проблеме пользователь сразу получил понятный вывод.

Если понадобится добавить новые правила парсинга или изменить формат входных файлов, достаточно изменить соответствующий кусок кода без перестройки всей программы.

