## Краткий обзор

Ниже – минимальный, но полностью безопасный (в рамках ограничений обычного «башнего» калькулятора) калькулятор на C, работающий со строковым вводом и поддерживающий четыре арифметические операции (`+`, `-`, `*`, `/`).  

После кода вы найдёте краткую **обратную связь** с точки зрения **безопасности**: что потенциально может стать уязвимостью, как избежать, какие практики применяются и какие инструменты можно использовать для проверки.

---

### 1. Исходный код

```c
/* calculator.c – простой калькулятор на C (строковый ввод, безопасная обработка) */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <ctype.h>

/* Максимальная длина строки для чтения пользовательского ввода */
#define MAX_INPUT 256

/* Операции */
typedef enum {
    OP_NONE,
    OP_ADD,
    OP_SUB,
    OP_MUL,
    OP_DIV
} OpCode;

/* Простой парсер: ищем оператор, разбиваем строку на два операнда */
static OpCode parse_expression(const char *buf, double *lhs, double *rhs) {
    const char *p = buf;
    /* Пропустить ведущие пробелы */
    while (*p && isspace((unsigned char)*p)) p++;

    /* Первая часть – левый операнд */
    char *endptr;
    errno = 0;
    *lhs = strtod(p, &endptr);
    if (p == endptr || errno != 0) return OP_NONE;   /* не число */
    p = endptr;

    /* Пропустить пробелы между операндом и оператором */
    while (*p && isspace((unsigned char)*p)) p++;

    /* Определить оператор */
    OpCode op = OP_NONE;
    switch (*p) {
        case '+': op = OP_ADD; break;
        case '-': op = OP_SUB; break;
        case '*': op = OP_MUL; break;
        case '/': op = OP_DIV; break;
        default: return OP_NONE;          /* не поддерживаемый оператор */
    }
    p++;  /* перейти за оператор */

    /* Пропустить пробелы после оператора */
    while (*p && isspace((unsigned char)*p)) p++;

    /* Вторая часть – правый операнд */
    errno = 0;
    *rhs = strtod(p, &endptr);
    if (p == endptr || errno != 0) return OP_NONE;   /* не число */
    /* Убедиться, что после правого операнда нет «дополнительно» */
    while (*endptr && isspace((unsigned char)*endptr)) endptr++;
    if (*endptr != '\0') return OP_NONE;  /* непустая строка после правого операнда */

    return op;
}

static void print_result(double result) {
    /* Чтобы избежать «0.000000000000001» – форматируем с 10 знаками после запятой */
    printf("Result: %.10g\n", result);
}

int main(void) {
    char buffer[MAX_INPUT];

    printf("Simple calculator. Supported ops: + - * /\n");
    printf("Enter expression (e.g. 3.14 * 2): ");

    if (!fgets(buffer, sizeof(buffer), stdin)) {
        fprintf(stderr, "Error reading input.\n");
        return EXIT_FAILURE;
    }

    /* Удалить символ перевода строки, если он есть */
    buffer[strcspn(buffer, "\n")] = '\0';

    double lhs = 0.0, rhs = 0.0;
    OpCode op = parse_expression(buffer, &lhs, &rhs);

    if (op == OP_NONE) {
        fprintf(stderr, "Malformed expression.\n");
        return EXIT_FAILURE;
    }

    /* Обрабатываем операции */
    double result = 0.0;
    switch (op) {
        case OP_ADD: result = lhs + rhs; break;
        case OP_SUB: result = lhs - rhs; break;
        case OP_MUL: result = lhs * rhs; break;
        case OP_DIV:
            if (rhs == 0.0) {
                fprintf(stderr, "Division by zero.\n");
                return EXIT_FAILURE;
            }
            result = lhs / rhs;
            break;
        default: /* не должно происходить */ break;
    }

    print_result(result);
    return EXIT_SUCCESS;
}
```

#### Как собрать

```bash
gcc -std=c11 -Wall -Wextra -Wshadow -O2 -s calculator.c -o calculator
```

> ⚠️ **Важно**: в командной строке стоит использовать `-s`, чтобы убрать символы отладки из бинарника и сделать его меньше и менее «видимым» для анализа, но для статического анализа лучше оставить символы отладки (`-g`).

