```c
/*
 *  broadcast_receiver.c
 *
 *  Demonstrates a parent process that broadcasts a user‑supplied string
 *  every second on 255.255.255.255:2346 and a child process that
 *  listens on the same port.  When a received message matches the
 *  argument, the child stores the sender’s IP/port in a shared table.
 *
 *  Compile:   gcc -Wall -O2 -o broadcast_receiver broadcast_receiver.c -pthread
 *  Run:       ./broadcast_receiver "hello world"
 *
 *  Author:    OpenAI ChatGPT (security‑researcher mode)
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/mman.h>
#include <semaphore.h>

#define BROADCAST_IP   "255.255.255.255"
#define BROADCAST_PORT 2346
#define BUF_SIZE       256
#define MAX_ENTRIES    10
#define PRINT_INTERVAL 30   /* seconds */

/* -------------------------------------------------------------- */
/*  Shared data structure                                         */
/* -------------------------------------------------------------- */
typedef struct {
    char ip[INET_ADDRSTRLEN];
    int  port;
} entry_t;

typedef struct {
    entry_t entries[MAX_ENTRIES];
    int     count;
    sem_t   sem;          /* process‑shared semaphore */
} shared_t;

/* Global pointer to the shared memory area (used for cleanup) */
static shared_t *shm_ptr = NULL;

/* -------------------------------------------------------------- */
/*  Signal handler for graceful termination                      */
/* -------------------------------------------------------------- */
static void cleanup(int signo)
{
    if (shm_ptr) {
        /* Destroy the semaphore and unmap the memory */
        sem_destroy(&shm_ptr->sem);
        munmap(shm_ptr, sizeof(shared_t));
    }
    printf("\n[+] Exiting (signal %d)\n", signo);
    exit(EXIT_SUCCESS);
}

/* -------------------------------------------------------------- */
/*  Helper: print the table (must be called with sem held)       */
/* -------------------------------------------------------------- */
static void print_table(void)
{
    printf("\n=== Sender table (%d entries) ===\n", shm_ptr->count);
    for (int i = 0; i < shm_ptr->count; ++i) {
        printf("  %d: %s:%d\n", i + 1,
               shm_ptr->entries[i].ip,
               shm_ptr->entries[i].port);
    }
    printf("================================\n");
}

/* -------------------------------------------------------------- */
/*  Parent process: send broadcast every second                  */
/* -------------------------------------------------------------- */
static void parent_send_loop(const char *msg)
{
    int sock;
    struct sockaddr_in dest;
    socklen_t destlen = sizeof(dest);
    int send_res;

    /* Create UDP socket */
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket (parent)");
        exit(EXIT_FAILURE);
    }

    /* Allow sending broadcast */
    int opt = 1;
    if (setsockopt(sock, SOL_SOCKET, SO_BROADCAST, &opt, sizeof(opt)) < 0) {
        perror("setsockopt SO_BROADCAST");
        close(sock);
        exit(EXIT_FAILURE);
    }

    /* Destination address */
    memset(&dest, 0, sizeof(dest));
    dest.sin_family = AF_INET;
    dest.sin_port   = htons(BROADCAST_PORT);
    if (inet_pton(AF_INET, BROADCAST_IP, &dest.sin_addr) <= 0) {
        fprintf(stderr, "Invalid broadcast IP\n");
        close(sock);
        exit(EXIT_FAILURE);
    }

    time_t last_print = time(NULL);

    while (1) {
        /* Send the string */
        send_res = sendto(sock, msg, strlen(msg), 0,
                          (struct sockaddr *)&dest, destlen);
        if (send_res < 0) {
            perror("sendto (parent)");
            /* Don't abort on transient failure */
        } else {
            printf("[+] Sent \"%s\" to %s:%d\n",
                   msg, BROADCAST_IP, BROADCAST_PORT);
        }

        /* Every PRINT_INTERVAL seconds, dump the table */
        if (difftime(time(NULL), last_print) >= PRINT_INTERVAL) {
            /* Acquire semaphore to read table safely */
            if (sem_wait(&shm_ptr->sem) == 0) {
                print_table();
                sem_post(&shm_ptr->sem);
            } else {
                perror("sem_wait (parent)");
            }
            last_print = time(NULL);
        }

        sleep(1);
    }

    /* Never reached, but keep compiler happy */
    close(sock);
}

/* -------------------------------------------------------------- */
/*  Child process: listen and record matching packets            */
/* -------------------------------------------------------------- */
static void child_receive_loop(const char *msg)
{
    int sock;
    struct sockaddr_in my_addr, src;
    socklen_t srclen = sizeof(src);
    char buf[BUF_SIZE];

    /* Create UDP socket */
    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket (child)");
        exit(EXIT_FAILURE);
    }

    /* Bind to port */
    memset(&my_addr, 0, sizeof(my_addr));
    my_addr.sin_family      = AF_INET;
    my_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    my_addr.sin_port        = htons(BROADCAST_PORT);

    if (bind(sock, (struct sockaddr *)&my_addr, sizeof(my_addr)) < 0) {
        perror("bind (child)");
        close(sock);
        exit(EXIT_FAILURE);
    }

    printf("[*] Child listening on port %d\n", BROADCAST_PORT);

    while (1) {
        ssize_t n = recvfrom(sock, buf, sizeof(buf)-1, 0,
                             (struct sockaddr *)&src, &srclen);
        if (n < 0) {
            perror("recvfrom (child)");
            continue;
        }
        buf[n] = '\0';  /* null‑terminate */

        /* Compare received message with the argument */
        if (strcmp(buf, msg) == 0) {
            /* Record source IP and port */
            if (sem_wait(&shm_ptr->sem) == 0) {
                if (shm_ptr->count < MAX_ENTRIES) {
                    inet_ntop(AF_INET, &src.sin_addr,
                              shm_ptr->entries[shm_ptr->count].ip,
                              sizeof(shm_ptr->entries[shm_ptr->count].ip));
                    shm_ptr->entries[shm_ptr->count].port =
                        ntohs(src.sin_port);
                    shm_ptr->count++;
                    printf("[+] Matched packet from %s:%d; "
                           "table now %d entries\n",
                           shm_ptr->entries[shm_ptr->count-1].ip,
                           shm_ptr->entries[shm_ptr->count-1].port,
                           shm_ptr->count);
                } else {
                    printf("[-] Table full (max %d).  Packet from %s:%d discarded.\n",
                           MAX_ENTRIES,
                           inet_ntoa(src.sin_addr), ntohs(src.sin_port));
                }
                sem_post(&shm_ptr->sem);
            } else {
                perror("sem_wait (child)");
            }
        } else {
            /* Non‑matching packet – ignore */
        }
    }

    /* Never reached, but keep compiler happy */
    close(sock);
}

/* -------------------------------------------------------------- */
/*  Main entry point                                              */
/* -------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr,
                "Usage: %s <string_to_broadcast>\n"
                "The string will be sent every second to 255.255.255.255:2346\n",
                argv[0]);
        exit(EXIT_FAILURE);
    }

    /* Install signal handler for graceful exit */
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Create shared memory */
    shm_ptr = mmap(NULL, sizeof(shared_t),
                   PROT_READ | PROT_WRITE,
                   MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (shm_ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    /* Initialise shared data */
    shm_ptr->count = 0;
    if (sem_init(&shm_ptr->sem, 1, 1) != 0) {  /* pshared=1 */
        perror("sem_init");
        munmap(shm_ptr, sizeof(shared_t));
        exit(EXIT_FAILURE);
    }

    /* Fork into parent and child */
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        cleanup(SIGTERM);
    } else if (pid == 0) {
        /* Child */
        child_receive_loop(argv[1]);
    } else {
        /* Parent */
        parent_send_loop(argv[1]);
    }

    /* Should never reach here */
    cleanup(SIGTERM);
    return 0;
}
```

---

### How the code works

| Component | What it does | Security note |
|-----------|--------------|---------------|
| **`mmap(... MAP_SHARED|MAP_ANONYMOUS)`** | Shares a small data area between parent/child | The area is **not** protected by a kernel‑level guard; if another process could map the same address space (rare), it could read/write it. |
| **`sem_init(&shm_ptr->sem, 1, 1)`** | Creates a process‑shared semaphore | The semaphore serialises access, preventing race conditions on the table. |
| **Parent** | Sends the user string every second to `255.255.255.255:2346` | Broadcast traffic may be dropped by routers/firewalls; sending to the broadcast address without `SO_BROADCAST` would fail. |
| **Child** | Binds to the same port, receives packets, compares payload, and, if equal, records the sender’s IP/port | No authentication, so any host can spoof the IP and flood the table. |
| **Printing** | Parent prints the table every 30 s | The `printf` can become a bottleneck if the child inserts many entries quickly. |

---

### Things to improve for production

1. **Authentication** – add HMAC or a shared secret so only legitimate packets are recorded.  
2. **Input validation** – ensure the broadcast string is not longer than the buffer.  
3. **Rate limiting** – avoid a malicious host filling the table or exhausting the semaphore.  
4. **Firewall rules** – restrict traffic on port 2346 to known hosts or a private subnet.  
5. **Non‑blocking I/O** – use `select()`/`poll()` or a thread pool to avoid a single blocking `recvfrom`.  

Feel free to adapt the code to your environment, but remember the security implications listed above!

