```c
/*********************************************************************
 *  Программа:  callgraph.c
 *  Задача:      Из файла test.txt построить граф вызовов функций.
 *  Функции считаются как любые слова, за которыми следует '('.
 *  Учитываются только простые вызовы в теле функций (не в макросах,
 *  строках, комментариях).  Граф выводится в виде списка смежности.
 *
 *  Ограничения:
 *    • Нет поддержки строковых литералов – '(' в строке игнорируется.
 *    • Не обрабатывает макросы и лямбда‑выражения.
 *    • Границы блоков считаются по фигурным скобкам без учёта
 *      вложенных фигурных скобок в строках/комментариях (удаляются
 *      заранее).
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* --------- Утилиты ------------------------------------------- */

#define INITIAL_CAP 10
#define MAX_KEYWORDS 30

/* Хранит список строк */
typedef struct {
    char **items;
    int count;
    int capacity;
} StrList;

void list_init(StrList *l) {
    l->capacity = INITIAL_CAP;
    l->count = 0;
    l->items = malloc(l->capacity * sizeof(char*));
}
void list_add(StrList *l, const char *s) {
    if (l->count == l->capacity) {
        l->capacity *= 2;
        l->items = realloc(l->items, l->capacity * sizeof(char*));
    }
    l->items[l->count++] = strdup(s);
}
void list_free(StrList *l) {
    for (int i = 0; i < l->count; ++i) free(l->items[i]);
    free(l->items);
}

/* Проверка, является ли слово ключевым словом C */
int is_keyword(const char *w) {
    static const char *keywords[MAX_KEYWORDS] = {
        "auto","break","case","char","const","continue","default",
        "do","double","else","enum","extern","float","for","goto",
        "if","inline","int","long","register","restrict","return",
        "short","signed","sizeof","static","struct","switch","typedef",
        "union","unsigned","void","volatile","while","_Alignas",
        "_Alignof","_Atomic","_Bool","_Complex","_Generic","_Imaginary",
        "_Noreturn","_Static_assert","_Thread_local"
    };
    for (int i = 0; i < MAX_KEYWORDS; ++i)
        if (strcmp(w, keywords[i]) == 0) return 1;
    return 0;
}

/* Удаляем C‑комментарии // и /* *\/ */
void strip_comments(char *buf) {
    char *src = buf, *dst = buf;
    while (*src) {
        if (*src == '/' && *(src+1) == '*') {          /* /*  */
            src += 2;
            while (*src && !(*src == '*' && *(src+1) == '/')) src++;
            if (*src) src += 2;                       /* */  */
        } else if (*src == '/' && *(src+1) == '/') {  /* //  */
            src += 2;
            while (*src && *src != '\n') src++;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

/*  Проверяем, что в строке встречается '(' после слова   */
int is_func_call(const char *s) {
    const char *p = s;
    /* Пропускаем ведущие пробелы */
    while (isspace((unsigned char)*p)) ++p;
    /* Слово (идентификатор) */
    if (!isalpha((unsigned char)*p) && *p != '_') return 0;
    const char *wstart = p;
    while (isalnum((unsigned char)*p) || *p == '_') ++p;
    const char *wend = p;
    if (*p != '(') return 0;          /* нет открывающей скобки */
    /* Проверяем, не ключевое слово */
    size_t len = wend - wstart;
    char word[64];
    if (len >= sizeof(word)) return 0; /* слишком длинное слово – игнорируем */
    memcpy(word, wstart, len);
    word[len] = '\0';
    if (is_keyword(word)) return 0;
    return 1;
}

/* Получаем слово (идентификатор) до '(' */
void get_word_before_parenth(const char *s, char *buf, size_t buflen) {
    const char *p = s;
    /* ищем позицию '(' */
    p = strchr(p, '(');
