typedef struct Func {
    char *name;           /* имя функции */
    char *body;           /* тело функции (строка) */
    StrList calls;        /* список вызванных функций */
} Func;

typedef struct {
    Func *funcs;
    int count;
    int capacity;
} FuncList;

void flist_init(FuncList *l) {
    l->capacity = INITIAL_CAP;
    l->count = 0;
    l->funcs = malloc(l->capacity * sizeof(Func));
}
void flist_add(FuncList *l, const char *name, const char *body) {
    if (l->count == l->capacity) {
        l->capacity *= 2;
        l->funcs = realloc(l->funcs, l->capacity * sizeof(Func));
    }
    Func *f = &l->funcs[l->count++];
    f->name = strdup(name);
    f->body = strdup(body);
    list_init(&f->calls);
}
void flist_free(FuncList *l) {
    for (int i = 0; i < l->count; ++i) {
        free(l->funcs[i].name);
        free(l->funcs[i].body);
        list_free(&l->funcs[i].calls);
    }
    free(l->funcs);
}

/* ---------- Поиск функций ----------------------------------- */

/* Ищет все функции, возвращает список */
FuncList parse_functions(const char *code) {
    FuncList flist;
    flist_init(&flist);

    const char *p = code;
    while ((p = strchr(p, '{'))) {                 /* ищем '{' */
        /* ищем закрывающую скобку ')' перед '{' */
        const char *rparen = NULL;
        const char *q = p-1;
        while (q >= code) {
            if (*q == ')') { rparen = q; break; }
            if (*q == '{') { break; }          /* вложенный '{' – значит это не начало функции */
            --q;
        }
        if (!rparen) { ++p; continue; }

        /* получаем имя функции до '(' */
        char func_name[64];
        get_word_before_parenth(rparen, func_name, sizeof(func_name));
        if (!func_name[0]) { ++p; continue; }

        /* находим конец тела функции – закрывающую фигурную скобку */
        int depth = 1;
        const char *body_start = p+1;
        const char *rbrace = body_start;
        while (*rbrace && depth > 0) {
            if (*rbrace == '{') ++depth;
            else if (*rbrace == '}') --depth;
            ++rbrace;
        }
        if (depth != 0) { ++p; continue; } /* сбой парсинга */
        size_t body_len = rbrace - body_start - 1; /* без последней '}' */
        char *body = malloc(body_len + 1);
        memcpy(body, body_start, body_len);
        body[body_len] = '\0';

        flist_add(&flist, func_name, body);
        free(body);

        p = rbrace;  /* продолжаем поиск после тела */
    }

    return flist;
}

/* ---------- Строим граф вызовов ------------------------------ */

void build_callgraph(FuncList *flist) {
    for (int i = 0; i < flist->count; ++i) {
        Func *f = &flist->funcs[i];
        const char *body = f->body;
        const char *p = body;
        while ((p = strstr(p, "("))) {               /* ищем '(' */
            /* идём назад, чтобы получить слово до '(' */
            const char *q = p;
            const char *end = q;
            while (q > body && isalnum((unsigned char)*(q-1)) || *(q-1) == '_')
                --q;
            const char *start = q;
            size_t len = end - start;
            if (len == 0) { p++; continue; }
            char word[64];
            if (len >= sizeof(word)) { p++; continue; }
            memcpy(word, start, len);
            word[len] = '\0';
            /* Игнорируем ключевые слова и саму функцию */
            if (!is_keyword(word) && strcmp(word, f->name) != 0)
                list_add(&f->calls, word);
            p = end + 1;
        }
    }
}

/* ---------- Вывод ------------------------------------------- */

void print_callgraph(const FuncList *flist) {
    for (int i = 0; i < flist->count; ++i) {
        const Func *f = &flist->funcs[i];
        printf("Function %s calls:\n", f->name);
        if (f->calls.count == 0) {
            printf("  (нет вызовов)\n");
        } else {
            for (int j = 0; j < f->calls.count; ++j)
                printf("  %s\n", f->calls.items[j]);
        }
        printf("\n");
    }
}

/* ---------- Главная ------------------------------------------ */

int main(void) {
    /* Читаем файл test.txt целиком */
    FILE *fp = fopen("test.txt", "r");
    if (!fp) { perror("fopen"); return 1; }
    fseek(fp, 0, SEEK_END);
    long sz = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char *code = malloc(sz + 1);
    if (!code) { perror("malloc"); fclose(fp); return 1; }
    fread(code, 1, sz, fp);
    fclose(fp);
    code[sz] = '\0';

    /* Удаляем комментарии */
    strip_comments(code);

    /* Парсим функции */
    FuncList flist = parse_functions(code);
    free(code);  /* код больше не нужен */

    /* Строим граф вызовов */
    build_callgraph(&flist);

    /* Выводим результат */
    print_callgraph(&flist);

    /* Очищаем память */
    flist_free(&flist);
    return 0;
}
