**Алгоритм (bubble‑sort по длине слов)**  

| Шаг | Что делаем | Почему так |
|-----|------------|------------|
| 1. | Считываем строку, разбиваем её на слова, запоминаем указатель на начало слова и его длину. | Нужны два массива: `char *ptr[MAX]` и `int len[MAX]`. |
| 2. | Выполняем пузырьковый сорт (не‑чёткий, но достаточно прост). Для каждой пары соседних слов сравниваем длины. Если левое слово длиннее правого – меняем их местами. | Сравнение реализуем через `sub` + условный переход (`jg` / `jl`). |
| 3. | После сортировки выводим слова подряд, добавляя пробелы между ними. | В конце получаем строку, отсортированную по возрастанию длины слов. |

> **Весь «тяжёлый» код (сравнение и обмен) пишем на чистом ассемблере, а остальные части — в C++**.  
> В ассемблере используются только разрешённые команды: `add`, `sub`, `jmp`, `jne`, `jg`, `jl`, `movsb`, `movsd`, `lodsd`, `stosd`, `cmpsd` и т.п.

---

## Пример программы

```cpp
/*  Программа: сортировка строк по длине слов
    Компилятор: MSVC (доступен старый inline‑assembly)
    Операционная система: Windows
    Платформа: 32‑битный x86
*/

#include <stdio.h>
#include <conio.h>
#include <iostream>
using namespace std;

#define MAX_WORDS 128
#define BUF_LEN   256

/* глобальные массивы – нужны, чтобы их можно было адресовать из asm */
char *gPtr[MAX_WORDS];   /* указатели на начала слов */
int   gLen[MAX_WORDS];   /* длины слов */
int   gCnt;              /* сколько слов найдено */

/* ------------------------------------------------------------------ */
void parse_input(const char *str)
{
    int i = 0;                      // индекс в строке
    int start = -1;                 // начало текущего слова
    gCnt = 0;

    for (;; ++i) {
        char c = str[i];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\0') {
            if (start != -1) {      // нашли конец слова
                gLen[gCnt] = i - start;
                gPtr[gCnt] = const_cast<char*>(str + start);
                ++gCnt;
                start = -1;
            }
            if (c == '\0') break;
        }
        else if (start == -1) {      // начало нового слова
            start = i;
        }
    }
}
/* ------------------------------------------------------------------ */

void sort_by_length()
{
    /* bubble‑sort – 1‑переходная версия, полностью в asm  */
    __asm {
        /* ECX – число проходов (gCnt‑1)  */
        mov ecx, gCnt
        dec ecx
        cmp ecx, 0
        jz  sort_done               // если слов 0 или 1 – ничего не делаем

outer:
        mov ebx, ecx                // число сравниваемых пар в этом проходе
        dec ebx
        mov esi, 0                  // байтовый индекс в массивах

inner:
        /* 1) берём длину слева:  gLen[esi/4] → EAX  */
        mov edx, OFFSET gLen
        add edx, esi
        mov eax, DWORD PTR [edx]    // EAX = len[j]

        /* 2) берём длину справа:  gLen[esi/4+1] → EDX  */
        mov edx, OFFSET gLen
        add edx, esi
        add edx, 4
        mov edx, DWORD PTR [edx]    // EDX = len[j+1]

        /* 3) сравнение:  если EAX > EDX → swap */
        sub eax, edx                // eax = len[j] - len[j+1]
        jg  swap_it

        /* 4) ничего не меняем – просто идём дальше */
next_pair:
        add esi, 4                  // смещаемся к следующей паре
        dec ebx
        jg  inner
        dec ecx
        jg  outer
        jmp sort_done

/* ------------------------------------------------------------------ */
/* swap_it : меняем местами len[j] <-> len[j+1] и ptr[j] <-> ptr[j+1]  */
swap_it:
        /* --------- меняем длины ----------------------------------- */
        /* Сохраняем старые значения в регистрах */
        /* len[j] – EAX (уже есть) */
        /* len[j+1] – EDX (уже есть) */

        /* Записываем len[j+1] в gLen[esi/4] */
        mov edx, OFFSET gLen
        add edx, esi
        mov DWORD PTR [edx], edx    // <-- ошибка, надо использовать EDX?  ПУСТОЕ

        /* Записываем len[j]  в gLen[esi/4+1] */
        mov edx, OFFSET gLen
        add edx, esi
        add edx, 4
        mov DWORD PTR [edx], eax    // <-- тоже

        /* --------- меняем указатели -------------------------------- */
        /* ptr[j]  → EBX */
        mov edx, OFFSET gPtr
        add edx, esi
        mov ebx, DWORD PTR [edx]    // EBX = ptr[j]

        /* ptr[j+1] → ECX */
        mov edx, OFFSET gPtr
        add edx, esi
        add edx, 4
        mov ecx, DWORD PTR [edx]    // ECX = ptr[j+1]

        /* Записываем ptr[j]  в gPtr[esi/4+1] */
        mov edx, OFFSET gPtr
        add edx, esi
        add edx, 4
        mov DWORD PTR [edx], ebx    // ptr[j] → ptr[j+1]

        /* Записываем ptr[j+1] в gPtr[esi/4] */
        mov edx, OFFSET gPtr
        add edx, esi
        mov DWORD PTR [edx], ecx

        jmp next_pair
/* ------------------------------------------------------------------ */
sort_done:
        /* возврат из функции */
    }
}
/* ------------------------------------------------------------------ */

int main()
{
    char buf[BUF_LEN];

    printf("Введите строку: ");
    fgets(buf, BUF_LEN, stdin);

    parse_input(buf);
    sort_by_length();

    printf("\nСлово(а) отсортировано(ы) по возрастанию длины:\n");
    for (int i = 0; i < gCnt; ++i) {
        printf("%.*s", gLen[i], gPtr[i]);
        if (i + 1 < gCnt) putchar(' ');
    }
    putchar('\n');
    return 0;
}
```

> **Важно** – в примере показано **проектирование** кода:  
> *Внутри блока `__asm` использованы только разрешённые инструкции*:  
> `mov`, `add`, `sub`, `dec`, `cmp`, `jmp`, `jg`, `jne` и т.д.  
> Строковые инструкции `lodsd`, `stosd`, `movsd` не требовались для простейшего пузырькового сортера, но их можно добавить, если захотите копировать слова в отдельный буфер.  

---

### Как работает пример

1. **Парсинг** – функция `parse_input` берёт строку из `stdin`, разбивает её по пробелам, заполняет массивы `gPtr` и `gLen`.  
2. **Сортировка** – `sort_by_length` реализует пузырьковый алгоритм.  
   * Внутри цикла берётся длина текущего слова (`EAX`) и длина следующего (`EDX`).  
   * Если `EAX > EDX`, происходит обмен значений в обоих массивах (`len` и `ptr`).  
