#include <sys/stat.h>   /* For mode constants */
#include <semaphore.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

/* Names of the shared semaphores */
#define SEM1_NAME "/sem1"
#define SEM2_NAME "/sem2"

static sem_t *sem1 = NULL;
static sem_t *sem2 = NULL;

/* Graceful cleanup on SIGINT/SIGTERM */
static void cleanup(int sig) {
    (void)sig;   /* unused */
    if (sem1) sem_close(sem1);
    if (sem2) sem_close(sem2);
    /* Unlink only if this process created the semaphores */
    /* (this is safe – unlinking again is no‑op) */
    sem_unlink(SEM1_NAME);
    sem_unlink(SEM2_NAME);
    printf("\n[INFO] Cleaned up semaphores. Exiting.\n");
    exit(0);
}

/* Open or create named semaphore, initialise to 1 if created */
static sem_t *open_sem(const char *name) {
    sem_t *sem;
    /* Try to create; if it already exists, just open */
    sem = sem_open(name, O_CREAT | O_EXCL, 0666, 1);
    if (sem == SEM_FAILED) {
        if (errno == EEXIST) {
            /* Already exists – open without O_EXCL */
            sem = sem_open(name, 0);
            if (sem == SEM_FAILED) {
                perror("sem_open");
                exit(EXIT_FAILURE);
            }
        } else {
            perror("sem_open");
            exit(EXIT_FAILURE);
        }
    }
    return sem;
}

/* Print current status of semaphores (for demo only) */
static void print_status(void) {
    /* We cannot read the value of a named semaphore in a portable way.
       So we just print a message each time we acquire/release. */
}

/* Simple wrapper that prints the action */
static void action(const char *msg) {
    printf("%s\n", msg);
    fflush(stdout);
}

int main(void)
{
