    printf("  d  – lock SEM1 then SEM2 (demo of blocking)\n");
    printf("  e  – lock SEM2 then SEM1 (demo of deadlock)\n");
    printf("  r  – release both semaphores (in any order)\n");
    printf("  x  – exit\n\n");
    fflush(stdout);

