            case '2': {
                action("[PID] Trying to lock SEM2...");
                if (sem_wait(sem2) == -1) {
                    perror("sem_wait(SEM2)");
                } else {
                    action("[PID] SEM2 locked.");
                }
                break;
            }
            case 'w': {
                action("[PID] Releasing SEM2...");
                if (sem_post(sem2) == -1) {
                    perror("sem_post(SEM2)");
                } else {
                    action("[PID] SEM2 released.");
                }
                break;
            }
            /* Demo of simple blocking */
            case 'd': {
                action("[PID] d: lock SEM1 → lock SEM2...");
                if (sem_wait(sem1) == -1) {
                    perror("sem_wait(SEM1)");
                    break;
                }
                action("[PID] SEM1 locked by d.");
                if (sem_wait(sem2) == -1) {
                    perror("sem_wait(SEM2)");
                    /* Release SEM1 to avoid deadlock in this path */
                    sem_post(sem1);
                    break;
                }
                action("[PID] SEM2 locked by d.");
                break;
            }
            /* Demo of deadlock */
            case 'e': {
                action("[PID] e: lock SEM2 → lock SEM1...");
                if (sem_wait(sem2) == -1) {
                    perror("sem_wait(SEM2)");
                    break;
                }
                action("[PID] SEM2 locked by e.");
                if (sem_wait(sem1) == -1) {
                    perror("sem_wait(SEM1)");
                    /* Release SEM2 to avoid deadlock in this path */
                    sem_post(sem2);
                    break;
                }
                action("[PID] SEM1 locked by e.");
                break;
            }
            case 'r': {
                /* Release both semaphores if owned */
                /* We don't know ownership; we simply try to release once */
                if (sem_post(sem1) == 0)
                    action("[PID] SEM1 released by r.");
                if (sem_post(sem2) == 0)
                    action("[PID] SEM2 released by r.");
                break;
            }
            case 'x':
                printf("[PID] Exiting.\n");
                cleanup(0);
                break;
            default:
                printf("[PID] Unknown key '%c'\n", ch);
                break;
        }
    }

    cleanup(0);
    return 0;
}
