## 3. Implementazione delle funzioni

```c
/* magazzino.c */
#include "magazzino.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

/* 1. lettura file -------------------------------------------------------- */
int leggi_file(FILE *fp, Prodotti *prod, int *n_prod) {
    char line[256];
    int cnt = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (cnt >= MAX_PRODOTTI) {
            fprintf(stderr, "Limite massimo di prodotti (%d) raggiunto.\n", MAX_PRODOTTI);
            return -1;
        }

        /* rimuovi eventuale newline */
        line[strcspn(line, "\n")] = '\0';

        /* parsing: cod, costo, quantita */
        char cod[MAX_CODLEN + 1];
        int costo, quantita;
        if (sscanf(line, "%31s %d %d", cod, &costo, &quantita) != 3) {
            fprintf(stderr, "Formato errato nella riga: %s\n", line);
            continue;  /* ignora la riga */
        }

        /* controllo validità */
        if (costo < 0 || quantita < 0 || quantita > 10000) {
            fprintf(stderr, "Valori non validi nella riga: %s\n", line);
            continue;
        }

        /* copia dati */
        strncpy(prod[cnt].cod, cod, MAX_CODLEN);
        prod[cnt].cod[MAX_CODLEN] = '\0';
        prod[cnt].costo = costo;
        prod[cnt].quantita = quantita;

        cnt++;
    }

    *n_prod = cnt;
    return 0;
}

/* 2. verifica variazione ----------------------------------------------- */
int verifica_variabile(const char *cod, int var, const Prodotti *prod, int n_prod) {
    for (int i = 0; i < n_prod; ++i) {
        if (strcmp(prod[i].cod, cod) == 0) {
            /* prodotto trovato */
            long long nuovo = (long long)prod[i].quantita + var;
            if (var < 0 && nuovo < 0)            /* decremento eccessivo */
                return -2;
            if (var > 0 && nuovo > 10000)        /* incremento oltre 10000 */
                return -2;
            return 1;                            /* valido */
        }
    }
    return -1;  /* non trovato */
}

/* 3. aggiornamento e stampa -------------------------------------------- */
void aggiorna_e_stampa(const char *cod, int var, Prodotti *prod, int n_prod) {
    long long totale_0 = 0, totale_1 = 0;
    for (int i = 0; i < n_prod; ++i) {
        totale_0 += (long long)prod[i].costo * prod[i].quantita;
    }

    /* aggiornamento */
    for (int i = 0; i < n_prod; ++i) {
        if (strcmp(prod[i].cod, cod) == 0) {
            prod[i].quantita += var;
            break;
        }
    }

    for (int i = 0; i < n_prod; ++i) {
        totale_1 += (long long)prod[i].costo * prod[i].quantita;
    }

    printf("Valore totale prima: %.2f€\n", totale_0 / 100.0);
    printf("Valore totale dopo : %.2f€\n", totale_1 / 100.0);
}

/* 4. ordinamento e scrittura su file ----------------------------------- */
int comparatore(const void *a, const void *b) {
    const Prodotti *p = a, *q = b;
    long long val_a = (long long)p->costo * p->quantita;
    long long val_b = (long long)q->costo * q->quantita;
    if (val_a < val_b) return 1;  /* decrescente */
    if (val_a > val_b) return -1;
    return 0;
}

void ordina_e_scrivi(FILE *fp_out, Prodotti *prod, int n_prod) {
    qsort(prod, n_prod, sizeof(Prodotti), comparatore);

    for (int i = 0; i < n_prod; ++i) {
        fprintf(fp_out, "%s %d %d\n",
                prod[i].cod,
                prod[i].costo,
                prod[i].quantita);
    }
}
```

