## 2. 代码

```c
/*  Dijkstra algorithm (from vertex V0) in C
 *
 *  Author: <your name>
 *  Date  : 2026-01-31
 *
 *  说明：
 *    - V0 采用索引 0（即第一个顶点）
 *    - 邻接矩阵 adj[i][j] 为 i→j 的权值，若无边则设为 INF
 *    - 需要保证所有权值为非负，否则结果不一定正确
 *
 *  安全性：
 *    - 所有数组访问均做边界检查
 *    - 用 INT_MAX/2 表示 INF，防止加法溢出
 *    - 代码中未使用任何不安全函数（如 gets、strcpy 等）
 */

#include <stdio.h>
#include <limits.h>

/* ----------------- 常量与类型 ----------------- */
#define MAX_VERTEX 10                 /* 最大顶点数（可自行调整） */
#define INF        (INT_MAX / 2)      /* 用来表示“无穷大”，避免 INT_MAX + w 产生溢出 */

/* ----------------- 数据结构 ----------------- */
int V;                                 /* 实际顶点数 */
int adj[MAX_VERTEX][MAX_VERTEX];       /* 邻接矩阵 */
int dist[MAX_VERTEX];                  /* 最短路长度 */
int prev[MAX_VERTEX];                  /* 前驱顶点，便于重构路径 */
int visited[MAX_VERTEX];               /* 标记顶点是否已确定最短路 */

/* ----------------- 函数原型 ----------------- */
void init_graph(void);
void dijkstra(int src);
void print_solution(int src);
int  min_distance(void);

/* ----------------- 主函数 ----------------- */
int main(void)
{
    /* 1. 读取顶点数和邻接矩阵（示例中直接硬编码） */
    V = 5;          /* 例如 5 个顶点 */

    /* 这里演示一个完整的邻接矩阵（0 表示无边） */
    int sample_adj[5][5] = {
        {0, 2, 0, 6, 0},
        {2, 0, 3, 8, 5},
        {0, 3, 0, 0, 7},
        {6, 8, 0, 0, 9},
        {0, 5, 7, 9, 0}
    };

    /* 复制到全局矩阵并把无边（0）转换为 INF */
    for (int i = 0; i < V; ++i)
        for (int j = 0; j < V; ++j)
            adj[i][j] = (sample_adj[i][j] == 0 && i != j) ? INF : sample_adj[i][j];

    /* 2. 运行 Dijkstra，从顶点 0 开始 */
    dijkstra(0);

    /* 3. 打印结果 */
    print_solution(0);

    return 0;
}

/* ----------------- 初始化 ----------------- */
void init_graph(void)
{
    for (int i = 0; i < V; ++i) {
        visited[i] = 0;          /* 未访问 */
        dist[i]   = INF;         /* 初始距离 “无穷大” */
        prev[i]   = -1;          /* 无前驱 */
    }
    dist[0] = 0;                  /* 源点到自己的距离为 0 */
}

/* ----------------- Dijkstra 主体 ----------------- */
void dijkstra(int src)
{
    init_graph();

    for (int cnt = 0; cnt < V; ++cnt) {
        /* 2. 选取未访问且 dist 最小的顶点 k */
        int k = min_distance();
        if (k == -1) break;            /* 所有可达顶点已访问 */

        visited[k] = 1;                /* 标记已访问 */

        /* 3. 更新邻接顶点的距离 */
        for (int i = 0; i < V; ++i) {
            if (!visited[i] && adj[k][i] < INF) { /* 仅考虑存在边的情况 */
                int new_dist = dist[k] + adj[k][i];
                if (new_dist < dist[i]) {
                    dist[i] = new_dist;
                    prev[i] = k;
                }
            }
        }
    }
}

/* ----------------- 找到未访问且 dist 最小的顶点 ----------------- */
int min_distance(void)
{
    int min = INF;
    int idx  = -1;

    for (int i = 0; i < V; ++i) {
        if (!visited[i] && dist[i] < min) {
            min = dist[i];
            idx = i;
        }
    }
    return idx; /* 若 idx 为 -1，说明没有未访问顶点可更新 */
}

/* ----------------- 输出结果 ----------------- */
void print_solution(int src)
{
    printf("Shortest paths from vertex %d:\n", src);
    for (int i = 0; i < V; ++i) {
        if (i == src) continue;
        printf("  To vertex %d: ", i);
        if (dist[i] == INF) {
            printf("unreachable\n");
            continue;
        }
        printf("distance = %d, path = ", dist[i]);

        /* 重建路径（从目标回溯到源） */
        int path[MAX_VERTEX];
        int len = 0;
        int v = i;
        while (v != -1) {
            path[len++] = v;
            v = prev[v];
        }

        /* 逆序打印路径 */
        for (int j = len - 1; j >= 0; --j)
            printf("%d%s", path[j], (j == 0) ? "" : " -> ");

        printf("\n");
    }
}
