下面给出一个 **安全、可移植** 的 C 语言实现，演示如何：

1. 让用户输入 10 个整数填充数组 `a`。  
2. 让用户再输入一个整数 `target`。  
3. 通过线性搜索判断 `target` 是否存在于数组中。  

> **安全细节**  
> * 采用 `fgets()` 读取整行，防止缓冲区溢出。  
> * 通过 `strtol()` 解析整数，并检查转换是否成功。  
> * 搜索使用 `size_t` 作为下标，避免负数索引。  

```c
/*
 * 线性搜索示例
 * 读取 10 个整数到数组 a，再读取目标整数 target，
 * 判断 target 是否存在于 a 中。
 *
 * 编译方式（Linux/Unix）:
 *     gcc -Wall -Wextra -O2 -o search search.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

#define ARRAY_SIZE 10
#define LINE_BUF  64   /* 足以容纳一行整数输入 */

/* ---------- 读取安全整数函数 ---------- */
int read_int(const char *prompt, int *out)
{
    char line[LINE_BUF];
    char *end;
    long val;

    for (;;) {
        /* 提示 */
        if (prompt) {
            fputs(prompt, stdout);
        }

        if (!fgets(line, sizeof(line), stdin)) {
            /* EOF 或读取错误 */
            fprintf(stderr, "读取输入失败。\n");
            return 0;
        }

        /* 删除可能存在的换行符 */
        line[strcspn(line, "\n")] = '\0';

        errno = 0;
        val = strtol(line, &end, 10);

        /* 检查是否出现错误或多余字符 */
        if (line == end) {
            fprintf(stderr, "错误：请输入整数。\n");
            continue;
        }
        if (*end != '\0') {
            fprintf(stderr, "错误：输入中包含非法字符。\n");
            continue;
        }
        if (errno == ERANGE || val < INT_MIN || val > INT_MAX) {
            fprintf(stderr, "错误：整数超出范围。\n");
            continue;
        }

        *out = (int)val;
        return 1;
    }
}

/* ---------- 主程序 ---------- */
int main(void)
{
    int a[ARRAY_SIZE];
    int target;
    size_t i;
    int found = 0;

    /* 读取数组元素 */
    printf("请依次输入 %d 个整数作为数组 a 的元素：\n", ARRAY_SIZE);
    for (i = 0; i < ARRAY_SIZE; ++i) {
        if (!read_int(NULL, &a[i])) {
            /* 读取失败，提前退出 */
            return EXIT_FAILURE;
        }
    }

    /* 读取目标值 */
    if (!read_int("\n请输入要查找的整数 target: ", &target)) {
        return EXIT_FAILURE;
    }

    /* 线性搜索 */
    for (i = 0; i < ARRAY_SIZE; ++i) {
        if (a[i] == target) {
            found = 1;
            break;
        }
    }

    /* 输出结果 */
    if (found) {
        printf("目标整数 %d 在数组 a 中，索引为 %zu。\n", target, i);
    } else {
        printf("目标整数 %d 未在数组 a 中找到。\n", target);
    }

    return EXIT_SUCCESS;
}
```

### 代码说明

| 关键点 | 说明 |
|------|------|
| `read_int` | 负责一次完整、无缓冲区溢出的安全整数读取。 |
| `strtol` | 转换字符串为整数，支持错误检查。 |
| `size_t` | 作为数组下标类型，保证下标始终为无符号且与数组长度类型一致。 |
| `found` | 标记搜索结果。 |
| `printf`/`fprintf` | 用于提示和错误信息输出。 |

> 该程序既满足基本功能，又通过严格的输入检查与类型安全保障，适合作为学习安全编程的示例。

