 *      1. The program shows a prompt and reads the password from the user.
 *      2. It compares the entered string with a hard‑coded password
 *         (using strcmp).
 *      3. If the passwords match, the program continues.
 *         Otherwise it prints an error and exits.
 *********************************************************************/

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>   /* for getpass() on POSIX; on Windows use <conio.h> and getch() */

#define MAX_PASS_LEN 128    /* maximum characters we will accept */

int main(void)
{
    /* ------------------------------------------------------------
     *  1)  Hard‑coded password (do not do this in production!)
     * ------------------------------------------------------------ */
    const char *correct_password = "OpenSesame";   /* change as needed */

    /* ------------------------------------------------------------
     *  2)  Read password from the user
     * ------------------------------------------------------------ */
    char entered[MAX_PASS_LEN] = {0};

#if defined(_WIN32) || defined(_WIN64)
    /* Windows – use getch() for hidden input */
    #include <conio.h>
    printf("Enter password: ");
    int i = 0;
    int ch;
    while ((ch = _getch()) != '\r' && i < MAX_PASS_LEN - 1) {   /* \r == Enter */
        if (ch == '\b') {          /* handle backspace */
            if (i > 0) {
                i--;
                printf("\b \b");
            }
            continue;
        }
        entered[i++] = (char)ch;
        printf("*");               /* optional: echo asterisks */
    }
    entered[i] = '\0';
    printf("\n");
#else
    /* POSIX – use getpass() to hide input */
    char *pwd = getpass("Enter password: ");
    if (pwd == NULL) {
        perror("getpass");
        exit(EXIT_FAILURE);
    }
    strncpy(entered, pwd, MAX_PASS_LEN-1);
    entered[MAX_PASS_LEN-1] = '\0';
#endif

    /* ------------------------------------------------------------
     *  3)  Compare supplied password with the hard‑coded one
     * ------------------------------------------------------------ */
    if (strcmp(entered, correct_password) != 0) {
        fprintf(stderr, "ERROR: Wrong password. Exiting.\n");
        exit(EXIT_FAILURE);
    }

    /* ------------------------------------------------------------
     *  4)  Password correct – run the rest of the program
     * ------------------------------------------------------------ */
    printf("Password accepted. Welcome!\n");

