    *out = BASE_ADDR_CHAR[offset_char(row, col)];
    return true;
}
static inline bool write_char(size_t row, size_t col, uint8_t val) {
    if (row >= ROWS_CHAR || col >= COLS_CHAR) return false;
    BASE_ADDR_CHAR[offset_char(row, col)] = val;
    return true;
}

