下面是一份 **C 代码**，实现了“最長嚴格遞增子數列（Longest Increasing Subsequence, LIS）” 的求解。  
程式使用 **O(n log n)** 的方法（patience sorting / 下三角）計算 LIS 的長度，並可選擇輸出具體的子序列。  

> **安全性小提示**  
> 1. 只使用了 `malloc` / `free`，不會造成緩衝區溢位。  
> 2. 讀入數值時採用 `scanf` + `if (scanf(... ) != 1)` 進行錯誤檢查。  
> 3. 若要在更複雜的環境下使用，請把 `scanf` 換成 `fgets` + `strtol`，以避免格式錯誤。  

```c
/*********************************************************************
 *  最長嚴格遞增子數列 (Longest Increasing Subsequence, LIS)
 *
 *  時間複雜度 : O(n log n)   (n = 整數個數)
 *  空間複雜度 : O(n)
 *
 *  讀入: 先輸入整數 n (1 ≤ n ≤ 10^5)，然後輸入 n 個整數 (可為正、負、0)。
 *  輸出: LIS 的長度，並可選擇輸出 LIS 本身（按原順序）。
 *
 *  這份程式已做基本的輸入檢查，避免常見的安全問題（如緩衝區溢位）。
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* 取得整型，帶有基本檢查 */
static int read_int(int *out) {
    if (scanf("%d", out) != 1) {
        return 0;   /* 讀取失敗 */
    }
    return 1;
}

/* 取得長度為 n 的整型陣列 */
static int *read_array(size_t n) {
    int *arr = malloc(n * sizeof(int));
    if (!arr) return NULL;  /* 內存不足 */
    for (size_t i = 0; i < n; ++i) {
        if (!read_int(&arr[i])) { /* 讀入錯誤 */
            free(arr);
            return NULL;
        }
    }
    return arr;
}

/* binary search: 取得第一個大於 target 的索引 */
static size_t upper_bound(const int *arr, size_t size, int target) {
    size_t lo = 0, hi = size;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (arr[mid] <= target)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

/* 計算 LIS 長度，並可選擇回傳 LIS 本身 */
static size_t LIS(const int *nums, size_t n, int **out_seq) {
    /* dp[i] = 最小尾數值，使得長度為 i+1 的 LIS 能以此值結束 */
    int *dp = malloc(n * sizeof(int));
    if (!dp) return 0;
    int *prev = malloc(n * sizeof(int));          /* 前一個索引，用於回溯 */
    int *tails = malloc(n * sizeof(int));         /* 存儲 dp 尾部對應的原始索引 */
    if (!prev || !tails) {
        free(dp);
        free(prev);
        free(tails);
        return 0;
    }

    size_t len = 0;      /* LIS 的長度 */
    for (size_t i = 0; i < n; ++i) {
        size_t pos = upper_bound(dp, len, nums[i]); /* 找到位置 */
        dp[pos] = nums[i];
        tails[pos] = i;                       /* 存儲原始索引 */
        prev[i] = (pos > 0) ? tails[pos - 1] : -1; /* 追蹤前一個元素 */

        if (pos == len)
            len++;                            /* LIS 長度擴大 */
    }

    /* 若需要回傳 LIS 本身 */
    if (out_seq) {
        int *seq = malloc(len * sizeof(int));
        if (!seq) { /* 內存不足，僅返回長度 */
            free(dp);
            free(prev);
            free(tails);
            return len;
        }
        size_t idx = len - 1;
        for (int pos = tails[len - 1]; pos != -1; pos = prev[pos]) {
            seq[idx] = nums[pos];
            if (idx == 0) break;
            idx--;
        }
        *out_seq = seq;
    }

    free(dp);
    free(prev);
    free(tails);
    return len;
}

int main(void) {
    /* ---------- 讀入數據 ---------- */
    int n;
    printf("請輸入整數個數 (n): ");
    if (!read_int(&n) || n <= 0) {
