   ------------------------------------------------------------- */

/*
 * Partition helper: places an element in its correct position
 * and returns its final index.
 */
static size_t partition(int32_t *arr, size_t low, size_t high)
{
    /* Choose the last element as pivot (simple but can degrade to O(n^2)). */
    int32_t pivot = arr[high];
    size_t i = low;

    for (size_t j = low; j < high; ++j) {
