#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <openssl/sha.h>

/* Максимальный размер буфера для чтения файлов */
#define BUFSIZE 256

/* Чтение строки из файла до первого символа '\n' */
static int read_line(const char *path, char *buf, size_t buflen)
{
    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror(path);
        return -1;
    }

    if (!fgets(buf, (int)buflen, fp)) {
        perror("fgets");
        fclose(fp);
        return -1;
    }

    /* Удаляем завершающий \n, если есть */
    buf[strcspn(buf, "\n")] = '\0';

    fclose(fp);
    return 0;
}

/* Получаем серийный номер из /proc/cpuinfo */
static int get_cpu_serial(char *serial, size_t len)
{
    char line[BUFSIZE];
    if (read_line("/proc/cpuinfo", line, sizeof(line)) < 0)
        return -1;

    /* В строке может быть: Serial\t\t: 000000004c3f9d4f */
    char *pos = strstr(line, "Serial");
    if (!pos)
        return -1;

    /* Перемещаемся к ':' */
    pos = strchr(pos, ':');
    if (!pos)
        return -1;

    /* Сдвигаемся за ':' и пропускаем пробелы */
    pos++;

    while (*pos == ' ' || *pos == '\t')
        pos++;

    /* Теперь pos указывает на серийный номер */
    strncpy(serial, pos, len - 1);
    serial[len - 1] = '\0';

    /* Удаляем возможные пробелы в конце */
    serial[strcspn(serial, " \t\r")] = '\0';

    return 0;
}

