static void print_sha256(const unsigned char *data, size_t dlen)
{
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(data, dlen, hash);

    printf("Уникальный SHA‑256 ID: ");
    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++)
        printf("%02x", hash[i]);
    printf("\n");
}

int main(void)
{
    char cpu_serial[BUFSIZE] = {0};
    char mac[BUFSIZE] = {0};
    int got_mac = 0;

    /* 1) Получаем серийный номер CPU */
    if (get_cpu_serial(cpu_serial, sizeof(cpu_serial)) != 0) {
