### 2.  Complete source code

```cpp
/********************************************************************
 *  BigInt.cpp – Minimal big‑integer for 30‑digit decimal numbers
 *  Author:   Security Researcher (anonymous)
 *  Language: C++11, no <vector>
 *  Restrictions: |value| <= 10^30
 *  Operations: + - * /
 *
 *  Compile:
 *      g++ -std=c++11 -O2 -Wall -Wextra -o bigint BigInt.cpp
 *
 *  Usage example:
 *      ./bigint
 *      123456789012345678901234567890
 *      -
 *      -98765432109876543210987654321
 *      Result: 246913456902469135690123456589
 ********************************************************************/

#include <iostream>
#include <string>
#include <cctype>
#include <cstdlib>
#include <algorithm>
#include <iomanip>
#include <stdexcept>
#include <limits>

/* ---------- BigInt class ---------- */
class BigInt {
public:
    static constexpr std::size_t MAX_DIGITS = 30;      // absolute value <= 10^30
    static constexpr std::size_t ARRAY_SIZE  = 31;      // 0…30 inclusive (max 30 digits + dummy for carry)

    BigInt() : negative(false) { digits.fill(0); }

    // Construct from string (decimal, optional leading '-')
    explicit BigInt(const std::string& s) : negative(false) {
        parse(s);
        trim();
    }

    // ----- Arithmetic operators -----
    BigInt operator+(const BigInt& other) const { return add(*this, other); }
    BigInt operator-(const BigInt& other) const { return sub(*this, other); }
    BigInt operator*(const BigInt& other) const { return mul(*this, other); }
    BigInt operator/(const BigInt& other) const { return div(*this, other); }
    BigInt operator%(const BigInt& other) const { return mod(*this, other); }

    // ----- Comparison operators -----
    bool operator==(const BigInt& other) const { return negative == other.negative && digits == other.digits; }
    bool operator!=(const BigInt& other) const { return !(*this == other); }
    bool operator<(const BigInt& other) const { return cmp(*this, other) < 0; }
    bool operator>(const BigInt& other) const { return cmp(*this, other) > 0; }
    bool operator<=(const BigInt& other) const { return cmp(*this, other) <= 0; }
    bool operator>=(const BigInt& other) const { return cmp(*this, other) >= 0; }

    // ----- I/O operators -----
    friend std::ostream& operator<<(std::ostream& os, const BigInt& bi);
    friend std::istream& operator>>(std::istream& is, BigInt& bi);

private:
    std::array<char, ARRAY_SIZE> digits;   // digits[0] = least significant
    bool negative;                         // sign flag

    /* ---------- Parsing ---------- */
    void parse(const std::string& s) {
        std::size_t pos = 0;
        negative = false;
        if (s.empty())
            throw std::invalid_argument("Empty string");

        if (s[0] == '-') {
            negative = true;
            pos = 1;
        } else if (s[0] == '+') {
            pos = 1;
        }

        // Skip leading zeros
        while (pos < s.size() && s[pos] == '0') ++pos;

        if (pos == s.size()) {        // value is zero
            negative = false;
            digits.fill(0);
            return;
        }

        std::size_t len = s.size() - pos;
        if (len > MAX_DIGITS)
            throw std::out_of_range("Number exceeds 10^30");

        // Fill digits array (little endian)
        digits.fill(0);
        std::size_t i = 0;
        for (std::size_t k = s.size(); k > pos; --k, ++i) {
            if (!std::isdigit(s[k-1]))
                throw std::invalid_argument("Invalid character in number");
            digits[i] = static_cast<char>(s[k-1] - '0');
        }
    }

    /* ---------- Normalization ---------- */
    void trim() {
        // Remove leading zeros in the big‑end part
        std::size_t i = ARRAY_SIZE - 1;
        while (i > 0 && digits[i] == 0) --i;
        if (i == 0 && digits[0] == 0) {  // value is zero
            negative = false;
        }
    }

    /* ---------- Helper arithmetic ---------- */
    static BigInt add(const BigInt& a, const BigInt& b) {
        if (a.negative == b.negative) {
            BigInt res;
            res.negative = a.negative;
            int carry = 0;
            for (std::size_t i = 0; i < ARRAY_SIZE; ++i) {
                int sum = a.digits[i] + b.digits[i] + carry;
                res.digits[i] = static_cast<char>(sum % 10);
                carry = sum / 10;
            }
            // Result will never overflow 30 digits because input bounds guarantee it
            res.trim();
            return res;
        } else {
            // a + (-b) == a - b
            return sub(a, negate(b));
        }
    }

    static BigInt sub(const BigInt& a, const BigInt& b) {
        if (a.negative != b.negative) {
            // a - (-b) == a + b
            return add(a, negate(b));
        }

        // Same sign: subtract magnitudes
        if (cmp(a, b) >= 0) {
            BigInt res;
            res.negative = a.negative;
            int borrow = 0;
            for (std::size_t i = 0; i < ARRAY_SIZE; ++i) {
                int diff = a.digits[i] - b.digits[i] - borrow;
                if (diff < 0) {
                    diff += 10;
                    borrow = 1;
                } else {
                    borrow = 0;
                }
                res.digits[i] = static_cast<char>(diff);
            }
            res.trim();
            return res;
        } else {
            // Result sign is opposite
            return negate(sub(b, a));
        }
    }

    static BigInt mul(const BigInt& a, const BigInt& b) {
        BigInt res;
        res.negative = (a.negative != b.negative);
        // Use 64-bit accumulator to avoid intermediate overflow
        std::array<int, 2*ARRAY_SIZE> temp{};
        for (std::size_t i = 0; i < ARRAY_SIZE; ++i) {
            for (std::size_t j = 0; j < ARRAY_SIZE; ++j) {
                if (i + j >= 2*ARRAY_SIZE) continue;
                temp[i + j] += a.digits[i] * b.digits[j];
            }
        }
        // Propagate carries
        int carry = 0;
        for (std::size_t k = 0; k < ARRAY_SIZE; ++k) {
            int val = temp[k] + carry;
            res.digits[k] = static_cast<char>(val % 10);
            carry = val / 10;
        }
        res.trim();
        return res;
    }

    /* ----- Division (quotient) and remainder ----- */
    static BigInt div(const BigInt& dividend, const BigInt& divisor) {
        if (divisor.isZero())
            throw std::domain_error("Division by zero");

        BigInt q, r;
        divmod(dividend, divisor, q, r);
        return q;
    }

    static BigInt mod(const BigInt& dividend, const BigInt& divisor) {
        if (divisor.isZero())
            throw std::domain_error("Division by zero");

        BigInt q, r;
        divmod(dividend, divisor, q, r);
        return r;
    }

    static void divmod(const BigInt& dividend, const BigInt& divisor,
                       BigInt& quotient, BigInt& remainder) {
        if (divisor.isZero())
            throw std::domain_error("Division by zero");

        // Handle sign
        bool qneg = (dividend.negative != divisor.negative);
        bool rneg = dividend.negative;

        BigInt a = abs(dividend);
        BigInt b = abs(divisor);

        quotient = BigInt();      // zero
        quotient.negative = qneg;
        remainder = BigInt();     // zero
        remainder.negative = rneg;

        // Long division – classic algorithm
        for (int i = ARRAY_SIZE - 1; i >= 0; --i) {
            // Shift remainder left by one decimal digit
            remainder.shiftLeft();
            remainder.digits[0] = a.digits[i];

            // Determine how many times b fits into remainder
            int cnt = 0;
            while (remainder >= b) {
                remainder = sub(remainder, b);
                ++cnt;
            }
            quotient.digits[i] = static_cast<char>(cnt);
        }
        quotient.trim();
        remainder.trim();
    }

    /* ----- Misc helpers ----- */
    static BigInt negate(const BigInt& x) {
        BigInt r = x;
        if (!r.isZero())
            r.negative = !r.negative;
        return r;
    }

    static BigInt abs(const BigInt& x) {
        BigInt r = x;
        r.negative = false;
        return r;
    }

    static int cmp(const BigInt& a, const BigInt& b) {
        // 1 if a > b, 0 if equal, -1 if a < b
        if (a.negative != b.negative)
            return a.negative ? -1 : 1;
        // Same sign – compare magnitudes
        for (int i = ARRAY_SIZE - 1; i >= 0; --i) {
            if (a.digits[i] != b.digits[i])
                return (a.digits[i] > b.digits[i]) ? (a.negative ? -1 : 1)
                                                  : (a.negative ? 1 : -1);
        }
        return 0;  // equal
    }

    bool isZero() const {
        for (char d : digits) if (d != 0) return false;
        return true;
    }

    void shiftLeft() { // multiply by 10
        for (int i = ARRAY_SIZE - 1; i > 0; --i) digits[i] = digits[i-1];
        digits[0] = 0;
    }
};

/* ---------- I/O implementation ---------- */
std::ostream& operator<<(std::ostream& os, const BigInt& bi) {
    if (bi.negative && !bi.isZero()) os << '-';
    bool leading = true;
    for (int i = BigInt::ARRAY_SIZE - 1; i >= 0; --i) {
        if (leading && bi.digits[i] == 0) continue;
        leading = false;
        os << static_cast<int>(bi.digits[i]);
    }
    if (leading) os << '0';   // the number is zero
    return os;
}

std::istream& operator>>(std::istream& is, BigInt& bi) {
    std::string s;
    is >> s;
    bi = BigInt(s);
    return is;
}

/* ---------- Simple command‑line demo ---------- */
int main() {
