 *          a·x + b·y = c
 *          x   –   y = d
 *
 *  Author:  <your name>
 *  Date:    2026‑01‑31
 *
 *  This program is written with a focus on safety:
 *      •  No unchecked scanf / gets / strcpy, etc.
 *      •  All arithmetic is done in 64‑bit integers or double.
 *      •  Division by zero is detected early.
 *      •  Integer overflows are mitigated by using int64_t and
 *          checking the result of the division before casting to int.
 *
 *  Compile with:  gcc -Wall -Wextra -O2 -o solve solve.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>
#include <limits.h>

/* ---------- helpers ---------- */

/* Read a single integer from stdin safely.
 *  Return 0 on success, non‑zero on failure. */
static int read_int(const char *prompt, int64_t *out)
{
    char line[128];
    char *end;

    printf("%s", prompt);
    if (!fgets(line, sizeof line, stdin)) {
        fprintf(stderr, "Error: failed to read input.\n");
        return -1;
    }

    errno = 0;
    long long val = strtoll(line, &end, 10);

    /* Check for parse errors */
    if (end == line || (*end != '\n' && *end != '\0')) {
        fprintf(stderr, "Error: invalid integer.\n");
        return -1;
    }
    if ((errno == ERANGE && (val == LLONG_MAX || val == LLONG_MIN)) ||
        (val > INT64_MAX || val < INT64_MIN)) {
        fprintf(stderr, "Error: integer out of range.\n");
        return -1;
    }

    *out = val;
    return 0;
}

/* ---------- solver ---------- */

/* Solve the system and return 0 on success.
 *  On success, the solution is stored in *x and *y (double). */
static int solve_system(int64_t a, int64_t b, int64_t c, int64_t d,
                        double *x, double *y)
{
    /*  From the second equation:   y = x - d
        Substitute into the first:  a·x + b·(x - d) = c
                                    (a + b)·x - b·d = c
                                    (a + b)·x = c + b·d
        Therefore:
            denom = a + b
            numer = c + b·d
    */

    /* Guard against overflow when computing numer = c + b*d */
    __int128 num128 = (__int128)c + (__int128)b * (__int128)d;
    if (num128 < INT64_MIN || num128 > INT64_MAX) {
        fprintf(stderr, "Error: intermediate result overflows 64‑bit range.\n");
        return -1;
    }
    int64_t numer = (int64_t)num128;

    int64_t denom = a + b;
    if (denom == 0) {
        fprintf(stderr, "Error: system has no unique solution (denominator is zero).\n");
        return -1;
    }

    /* Use double for division; this is safe because we already checked overflow. */
    *x = (double)numer / (double)denom;
    *y = *x - (double)d;

    return 0;
}

/* ---------- main ---------- */

int main(void)
{
    int64_t a, b, c, d;
    double x, y;
    int ok;

    /* Read input safely */
    if (read_int("Enter a: ", &a)) return EXIT_FAILURE;
    if (read_int("Enter b: ", &b)) return EXIT_FAILURE;
    if (read_int("Enter c: ", &c)) return EXIT_FAILURE;
    if (read_int("Enter d: ", &d)) return EXIT_FAILURE;

    /* Solve */
    ok = solve_system(a, b, c, d, &x, &y);
    if (ok != 0) {
        return EXIT_FAILURE;
    }

    printf("Solution: x = %.10g, y = %.10g\n", x, y);
    return EXIT_SUCCESS;
}
```

### How it works

1. **Input** – The `read_int()` routine uses `fgets()` + `strtoll()` so that the program never reads beyond the buffer and never overflows the integer type.  
2. **Overflow protection** – When computing `numer = c + b*d`, the code uses an `__int128` temporary to catch any overflow that could occur in the 64‑bit range.  
3. **Division by zero** – The program explicitly checks that `a + b != 0` before dividing.  
4. **Output** – The solution is printed as a floating‑point number with 10 significant digits; this is sufficient for most practical purposes.  
5. **Exit codes** – `0` indicates success, any non‑zero value signals an error condition that can be used by a wrapper script.

---

## 2. Security commentary

| Potential risk | Mitigation in this program |
|----------------|---------------------------|
| **Buffer overflow** (`gets`, `scanf("%d")`, etc.) | Uses `fgets()` with a fixed‑size buffer and checks the termination character. |
| **Integer overflow** (during `c + b*d`) | Uses 128‑bit arithmetic for the intermediate result and checks it against 64‑bit limits. |
| **Division by zero** (unique solution exists?) | Checks `denom == 0` before performing the division. |
| **Untrusted input leading to denial of service** | The program processes only four integers; memory usage is bounded. |
| **Format string vulnerabilities** | No uncontrolled format strings; all `printf`/`fprintf` calls have constant format specifiers. |
| **Race conditions / concurrency** | The program is single‑threaded. |
| **Use‑after‑free / dangling pointers** | No dynamic allocation; everything lives on the stack or in static storage. |
| **Information disclosure** | Only prints the solution; error messages are generic enough to avoid leaking internal state. |

> **Bottom line:** The code follows best practices for a small C program that processes user‑supplied integers. If you need to harden it further (e.g., for a security‑critical environment), you might:
>  - Compile with `-fstack-protector-strong -Wformat -Werror` to catch stack smashing or format string bugs at compile time.
>  - Run it under `valgrind` or `AddressSanitizer` during testing to guarantee no memory corruption.
>  - Wrap the arithmetic in a library that guarantees constant‑time execution if you are in a cryptographic setting (not required here).

---

## 3. Extending / auditing

1. **Fuzz testing** – Feed a fuzzing tool (e.g., AFL, libFuzzer) into the `read_int()` routine to ensure that random inputs never cause undefined behaviour.  
2. **Static analysis** – Run `clang-tidy` or `cppcheck` on the source.  
3. **Code review checklist** – Verify that every `printf`/`fprintf` has a literal format string, that no pointer arithmetic escapes bounds, and that all user data is validated before use.  
4. **Runtime sanitization** – Build with `-fsanitize=address,undefined` and run with `./solve` under test inputs to detect hidden bugs.  

---

