```c
/*********************************************************************
 *  Pull‑based cache‑invalidation simulation
 *  Inspired by G. Cao, “A Scalable Low‑Latency Cache Invalidation
 *  Strategy for Mobile Environments”, ACM MobiCom 2000.
 *
 *  Author:  ChatGPT (OpenAI)
 *  Date:    2026‑01‑31
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>
#include <string.h>

/* ------------------------ Simulation constants ------------------------ */

#define NUM_CLIENTS      5
#define DB_SIZE          500
#define ITEM_SIZE_BYTES  1024          /* 1024 bytes = 8192 bits */
#define BANDWIDTH_BPS    10000         /* 10,000 bits per second */
#define CACHE_SIZE       100
#define NUM_HOT          50            /* items 1..50 are hot */
#define HOT_ACCESS_PROB  0.8
#define HOT_UPDATE_PROB  0.33

#define CHECK_REQ_BITS   256           /* 32 bytes (check request) */
#define CONFIRM_BITS     256           /* 32 bytes (confirm reply) */
#define DATA_BITS        (ITEM_SIZE_BYTES * 8)  /* 8192 bits */

#define WARMUP_SECONDS   500.0          /* ignore first 500 seconds */
#define QUERIES_TO_COLLECT 10000       /* after warm‑up, run 10 000 queries */

/* ----------------------------- Data structures ----------------------- */

typedef struct {
    int id;
    int version;        /* monotonically increasing integer */
} DataItem;                 /* server side */

typedef struct {
    int id;
    int version;        /* cached copy */
} CachedItem;              /* client cache entry */

typedef struct {
    CachedItem cache[CACHE_SIZE];
    int cacheCount;
} Client;

typedef enum {
    EVENT_QUERY,
    EVENT_UPDATE
} EventType;

typedef struct Event {
    double time;           /* scheduled simulation time */
    EventType type;        /* type of event */
    int clientId;          /* 0..NUM_CLIENTS-1 for queries, -1 for updates */
    int itemId;            /* queried/update item id */
    struct Event *next;    /* linked list for event queue */
} Event;

/* ---------------------------- Globals ------------------------------- */

DataItem db[DB_SIZE + 1];          /* 1‑based indexing for convenience */
Client clients[NUM_CLIENTS];

Event *eventQueue = NULL;          /* sorted by time */

/* ------------------------------ RNG --------------------------------- */

static inline double rand_uniform(void) {
    /* uniform in [0,1) */
    return drand48();
}

static inline double rand_exponential(double mean) {
    /* exponential distribution with given mean */
    double u = rand_uniform();
    /* avoid log(0) */
    if (u < 1e-12) u = 1e-12;
    return -log(1.0 - u) * mean;
}

/* --------------------------- Event queue ---------------------------- */

static void enqueue_event(Event *ev) {
    /* insert in increasing time order */
    if (!eventQueue || ev->time < eventQueue->time) {
        ev->next = eventQueue;
        eventQueue = ev;
    } else {
        Event *p = eventQueue;
        while (p->next && p->next->time <= ev->time)
            p = p->next;
        ev->next = p->next;
        p->next = ev;
    }
}

static Event* dequeue_event(void) {
    if (!eventQueue) return NULL;
    Event *ev = eventQueue;
    eventQueue = eventQueue->next;
    ev->next = NULL;
    return ev;
}

/* --------------------------- Cache helpers -------------------------- */

static int cache_find(Client *c, int itemId) {
    for (int i = 0; i < c->cacheCount; ++i)
        if (c->cache[i].id == itemId) return i;
    return -1;
}

static void cache_move_to_front(Client *c, int idx) {
    if (idx <= 0) return;
    CachedItem tmp = c->cache[idx];
    memmove(&c->cache[1], &c->cache[0], idx * sizeof(CachedItem));
    c->cache[0] = tmp;
}

static void cache_insert(Client *c, int itemId, int version) {
    if (c->cacheCount < CACHE_SIZE) {
        /* shift right */
        memmove(&c->cache[1], &c->cache[0], c->cacheCount * sizeof(CachedItem));
        c->cache[0].id = itemId;
        c->cache[0].version = version;
        c->cacheCount++;
    } else {
        /* evict LRU (last) */
        memmove(&c->cache[0], &c->cache[1], (CACHE_SIZE - 1) * sizeof(CachedItem));
        c->cache[0].id = itemId;
        c->cache[0].version = version;
    }
}

/* ----------------------------- Simulation --------------------------- */

void init_server(void) {
    for (int i = 1; i <= DB_SIZE; ++i) {
        db[i].id = i;
        db[i].version = 0;
    }
}

void init_clients(void) {
    for (int i = 0; i < NUM_CLIENTS; ++i) {
        clients[i].cacheCount = 0;
    }
}

static int select_item_hot(void) {
    /* return item id according to hot/cold distribution */
    if (rand_uniform() < HOT_ACCESS_PROB)
        return 1 + (int)(rand_uniform() * NUM_HOT);  /* 1..NUM_HOT */
    else
        return NUM_HOT + 1 + (int)(rand_uniform() * (DB_SIZE - NUM_HOT));
}

static int select_item_update(void) {
    if (rand_uniform() < HOT_UPDATE_PROB)
        return 1 + (int)(rand_uniform() * NUM_HOT);
    else
        return NUM_HOT + 1 + (int)(rand_uniform() * (DB_SIZE - NUM_HOT));
}

void run_simulation(double T_query, double T_update,
                    double *out_hit_ratio, double *out_avg_delay) {
    init_server();
    init_clients();
    eventQueue = NULL;

    /* statistics */
    int totalQueries = 0;
    int hitQueries = 0;
    double sumDelay = 0.0;
    double simTime = 0.0;

    /* schedule first events */
    for (int c = 0; c < NUM_CLIENTS; ++c) {
        Event *ev = malloc(sizeof(Event));
        ev->time = rand_exponential(T_query);
        ev->type = EVENT_QUERY;
        ev->clientId = c;
        ev->itemId = select_item_hot();
        enqueue_event(ev);
    }
    Event *uEv = malloc(sizeof(Event));
    uEv->time = rand_exponential(T_update);
    uEv->type = EVENT_UPDATE;
    uEv->clientId = -1;
    uEv->itemId = select_item_update();
    enqueue_event(uEv);

    /* simulation loop */
    while (1) {
        Event *ev = dequeue_event();
        if (!ev) break;          /* no more events (should not happen) */
        simTime = ev->time;

        if (ev->type == EVENT_QUERY) {
            /* schedule next query from same client */
            Event *nextEv = malloc(sizeof(Event));
            nextEv->time = simTime + rand_exponential(T_query);
            nextEv->type = EVENT_QUERY;
            nextEv->clientId = ev->clientId;
            nextEv->itemId = select_item_hot();
            enqueue_event(nextEv);

            /* process query */
            Client *c = &clients[ev->clientId];
            int idx = cache_find(c, ev->itemId);
            double delay = 0.0;
            int hit = 0;

            if (idx >= 0) {
                /* cache hit – send check message */
                delay += CHECK_REQ_BITS / (double)BANDWIDTH_BPS;   /* to server */
                /* server checks */
                if (c->cache[idx].version == db[ev->itemId].version) {
                    /* still valid – confirm reply */
                    delay += CONFIRM_BITS / (double)BANDWIDTH_BPS;
                    hit = 1;
                } else {
                    /* stale – send data */
                    delay += DATA_BITS / (double)BANDWIDTH_BPS;
                    /* update cache entry */
                    c->cache[idx].version = db[ev->itemId].version;
                }
                /* LRU move */
                cache_move_to_front(c, idx);
            } else {
                /* cache miss – request data */
                delay += CHECK_REQ_BITS / (double)BANDWIDTH_BPS;   /* request */
                delay += DATA_BITS / (double)BANDWIDTH_BPS;       /* data reply */
                /* insert into cache */
                cache_insert(c, ev->itemId, db[ev->itemId].version);
            }

            /* collect stats after warm‑up */
            if (simTime >= WARMUP_SECONDS) {
                totalQueries++;
                if (hit) hitQueries++;
                sumDelay += delay;
                if (totalQueries >= QUERIES_TO_COLLECT) {
                    /* finished scenario */
                    *out_hit_ratio = hitQueries / (double)totalQueries;
                    *out_avg_delay = sumDelay / totalQueries;
                    free(ev);
                    /* clean up remaining events */
                    while (eventQueue) {
                        Event *tmp = eventQueue;
                        eventQueue = eventQueue->next;
                        free(tmp);
                    }
                    return;
                }
            }
        } else if (ev->type == EVENT_UPDATE) {
            /* schedule next update */
            Event *nextEv = malloc(sizeof(Event));
            nextEv->time = simTime + rand_exponential(T_update);
            nextEv->type = EVENT_UPDATE;
            nextEv->clientId = -1;
            nextEv->itemId = select_item_update();
            enqueue_event(nextEv);

            /* process update */
            db[ev->itemId].version++;   /* increment version */
        }

        free(ev);
    }
}

/* --------------------------- Main ---------------------------------- */

int main(void) {
    srand48(time(NULL));

    double T_query_values[] = {5, 10, 25, 50, 100};
    double T_update_values[] = {5, 10, 20, 100, 200};

    FILE *out = fopen("results.csv", "w");
    if (!out) {
        perror("fopen");
        return EXIT_FAILURE;
    }
    fprintf(out, "T_query,T_update,hit_ratio,avg_delay_sec\n");
    printf("T_query,T_update,hit_ratio,avg_delay_sec\n");

    for (int i = 0; i < sizeof(T_query_values)/sizeof(double); ++i) {
        for (int j = 0; j < sizeof(T_update_values)/sizeof(double); ++j) {
            double hit_ratio, avg_delay;
            run_simulation(T_query_values[i], T_update_values[j],
                           &hit_ratio, &avg_delay);
            printf("%g,%g,%.5f,%.5f\n",
                   T_query_values[i], T_update_values[j],
                   hit_ratio, avg_delay);
            fprintf(out, "%g,%g,%.5f,%.5f\n",
                    T_query_values[i], T_update_values[j],
                    hit_ratio, avg_delay);
        }
    }

    fclose(out);
    printf("\nResults written to results.csv\n");
    return EXIT_SUCCESS;
}
```

### How the simulation works

