/*********************************************************************
 * 题目：给定整数 a, b 及用户选择 1/2/3，输出：
 *      1 -> a 与 b 中较大的值
 *      2 -> a 与 b 中较小的值
 *      3 -> a 与 b 的和
 * 需求：使用指针传参
 *********************************************************************/

#include <stdio.h>
#include <limits.h>   // INT_MAX, INT_MIN

/* 通过指针返回 a 与 b 中较大的值 */
int max_of(int *pa, int *pb)
{
    if (!pa || !pb) {
        /* 指针非法，返回最小整数值，随后主程序可做错误处理 */
        return INT_MIN;
    }
    return (*pa > *pb) ? *pa : *pb;
}

/* 通过指针返回 a 与 b 中较小的值 */
int min_of(int *pa, int *pb)
{
    if (!pa || !pb) {
        return INT_MAX;
    }
    return (*pa < *pb) ? *pa : *pb;
}

/* 通过指针返回 a 与 b 的和（防止溢出） */
int sum_of(int *pa, int *pb, int *overflow)
{
    if (!pa || !pb) {
        *overflow = 1;
        return 0;
    }

    long long temp = (long long)(*pa) + (long long)(*pb);
    if (temp > INT_MAX || temp < INT_MIN) {
        *overflow = 1;
        return 0;          /* 返回值不可靠 */
    }

    *overflow = 0;
    return (int)temp;
}

int main(void)
{
    int a, b, choice;
    printf("请输入两个整数 a, b 以及操作选项（1 大，2 小，3 和）：\n");
    /* 安全读取：检查 scanf 返回值，避免无效输入导致程序异常 */
    if (scanf("%d %d %d", &a, &b, &choice) != 3) {
        fprintf(stderr, "错误：输入格式不正确。\n");
        return 1;
    }

    int result;
    int overflow_flag = 0;   /* 仅 sum_of 可能需要 */

    switch (choice) {
        case 1:
            result = max_of(&a, &b);
            if (result == INT_MIN) {   /* 说明指针传参异常 */
                fprintf(stderr, "内部错误：max_of 接收到无效指针。\n");
                return 1;
            }
            printf("较大的数是：%d\n", result);
            break;

        case 2:
            result = min_of(&a, &b);
            if (result == INT_MAX) {
                fprintf(stderr, "内部错误：min_of 接收到无效指针。\n");
                return 1;
            }
            printf("较小的数是：%d\n", result);
            break;

        case 3:
            result = sum_of(&a, &b, &overflow_flag);
            if (overflow_flag) {
                fprintf(stderr, "警告：整数溢出，无法得到可靠结果。\n");
            } else {
                printf("两数之和是：%d\n", result);
            }
            break;

        default:
            fprintf(stderr, "错误：未识别的选项 %d。请使用 1、2 或 3。\n", choice);
            return 1;
    }

    return 0;
}
```

---

## 安全性分析

| 风险点 | 说明 | 解决方案 |
|--------|------|----------|
| **空指针传递** | `max_of`, `min_of`, `sum_of` 直接解引用指针。 | 在每个函数入口处检查指针是否为 `NULL`，若是则返回错误标记（如 `INT_MIN` / `INT_MAX`）并在主程序中检测。 |
| **整数溢出** | `sum_of` 可能超出 `int` 范围，导致结果错误。 | 先用 `long long` 计算，再检查是否超出 `INT_MAX` / `INT_MIN`。 |
| **无效输入** | `scanf` 可能读不到三值。 | 检查 `scanf` 的返回值，确保读取成功。 |
| **缓冲区溢出** | 这里未使用字符串或数组读入，避免了传统缓冲区溢出。 | 若后续需要处理字符串，建议使用 `fgets` + `strtol` 或 `scanf` 的 `%n` 方式验证长度。 |
| **信息泄露** | 错误信息不泄露内部实现细节。 | 错误提示仅说明问题本身，而不包含内部指针地址等敏感信息。 |

> **建议**  
> 1. 在生产环境中，可以使用更强的类型安全（如 `int32_t`）和更严格的边界检查。  
> 2. 若需支持大整数，可使用 `int64_t` 或 `__int128`（在 GCC/Clang）并相应调整溢出检测逻辑。  
> 3. 对于多线程或外部攻击面，考虑在 `sum_of` 里加入原子操作或锁以防并发修改。

