**Скрипт «highlight_hex.c»**  
Небольшой утилитный C‑программа, которая выводит содержимое любого C‑файла и «подсвечивает» все шестнадцатеричные константы (подразумевается, что они записаны как `0x…` или `0X…`).  
Подсветка реализована при помощи ANSI‑цветов – это работает в большинстве терминалов Linux/Unix, в Windows – только в новых версиях Windows 10/11 (или при включенной ANSI‑поддержке).

> **Важно**: программа не пытается «проверять» контекст (строки, комментарии и т.д.).  
> Она просто ищет шаблон `0x[0‑9A‑Fa‑f]+`. Для более надёжного анализа контекста понадобится более сложный парсер (например, Flex/Bison или библиотека `libclang`).

```c
/*
 * highlight_hex.c
 *
 * Чтение произвольного C‑файла и вывод его содержимого,
 * при этом все шестнадцатеричные константы подсвечиваются цветом.
 *
 * Компиляция:
 *   gcc -Wall -O2 -std=c99 highlight_hex.c -o highlight_hex
 *
 * Пример использования:
 *   ./highlight_hex my_program.c
 *
 * Работает в терминалах, поддерживающих ANSI‑escape‑последовательности.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define MAX_LINE_LENGTH 8192

/* ANSI‑цвета */
#define ANSI_COLOR_RED    "\x1b[31m"
#define ANSI_COLOR_RESET  "\x1b[0m"

/*
 * highlight_line()
 *
 * Печатает строку `line` с подсветкой всех совпадений `re`.
 * Для каждого совпадения печатается: [перед совпадением] + RED + [совпадение] + RESET + [после совпадения].
 */
static void highlight_line(const char *line, regex_t *re)
{
    const char *start_ptr = line;
    regmatch_t pmatch[1];
    int offset = 0;                /* смещение в строке относительно начала */
    int line_len = strlen(line);

    /* Если нет совпадений, просто печатаем строку */
    if (regexec(re, line, 1, pmatch, 0) != 0) {
        fputs(line, stdout);
        return;
    }

    /* Перебираем все совпадения */
    while (regexec(re, start_ptr, 1, pmatch, 0) == 0) {
        /* pmatch[0].rm_so / .rm_eo – смещение внутри start_ptr */
        int match_start = offset + pmatch[0].rm_so;
        int match_end   = offset + pmatch[0].rm_eo;

        /* Печатаем часть до совпадения */
        fwrite(line + offset, 1, match_start - offset, stdout);

        /* Печатаем совпадение в красном цвете */
        fwrite(ANSI_COLOR_RED, 1, strlen(ANSI_COLOR_RED), stdout);
        fwrite(line + match_start, 1, match_end - match_start, stdout);
        fwrite(ANSI_COLOR_RESET, 1, strlen(ANSI_COLOR_RESET), stdout);

        /* Обновляем указатели и смещения */
        offset = match_end;
        start_ptr = line + match_end;

        /* Если достигли конца строки, выходим */
        if (match_end >= line_len)
            break;
    }

    /* Печатаем остаток строки */
    fputs(line + offset, stdout);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr,
                "Использование: %s <имя_файла>\n"
                "Выводит содержимое файла, подсвечивая все шестнадцатеричные константы.\n",
                argv[0]);
        return EXIT_FAILURE;
    }

    const char *filename = argv[1];
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Ошибка открытия файла");
        return EXIT_FAILURE;
    }

    /* Регулярное выражение: 0x[0-9A-Fa-f]+  */
    const char *pattern = "0x[0-9A-Fa-f]+";
    regex_t re;
    int ret = regcomp(&re, pattern, REG_EXTENDED | REG_ICASE);
    if (ret != 0) {
        char errbuf[256];
        regerror(ret, &re, errbuf, sizeof(errbuf));
        fprintf(stderr, "Ошибка компиляции регулярного выражения: %s\n", errbuf);
        fclose(fp);
        return EXIT_FAILURE;
    }

    /* Чтение построчно */
    char buf[MAX_LINE_LENGTH];
    while (fgets(buf, sizeof(buf), fp) != NULL) {
        highlight_line(buf, &re);
    }

    regfree(&re);
    fclose(fp);
    return EXIT_SUCCESS;
}
```

### Как это работает

1. **Регулярное выражение**  
   `0x[0-9A-Fa-f]+` — ищет последовательность вида `0x1A3F`, `0Xff`, `0x0` и т.д.  
   Флаг `REG_ICASE` позволяет игнорировать регистр `x`.

2. **Печать с подсветкой**  
   При обходе строки программа ищет первое совпадение, печатает часть до него, затем совпадение в красном цвете (`ANSI_COLOR_RED`), сбрасывает цвет и продолжает с конца совпадения. Это повторяется до конца строки.

3. **Удобство**  
   Программа читает файл построчно, чтобы не потреблять лишнюю память даже при больших исходниках.

### Почему это полезно для исследователя безопасности

- **Быстрый обзор** – позволяет сразу увидеть все числовые литералы, которые могут представлять маски, ключи, флаги, адреса и т.д.
- **Проверка на скрытые данные** – часто злоумышленники используют hex‑литералы для «скрытия» вредоносных строк в коде. Подсветка ускоряет их поиск.
- **Документация** – можно легко экспортировать подсвеченный вывод в HTML (заменив ANSI‑последовательности на `<span style="color:red">`) и использовать в отчётах.

> **Примечание**  
> Если вам нужно учитывать только активный код (игнорировать строки/комментарии), то потребуется более сложный парсер (например, `clang` или собственный лексер). Этот скрипт – быстрый и «плохой» инструмент, но отлично подходит для предварительного анализа.

