#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <sys/stat.h>
#include <pthread.h>

/* ----------  Configuration  ---------- */
#define SHM_KEY   0x1234        /* key for the command buffer          */
#define SEM_KEY   0x5678        /* key for the semaphore set (3 sems)  */
#define BUFFER_SIZE  4096       /* size of the command buffer          */

/* ----------  Global data  ---------- */
static int    shm_id   = -1;     /* ID of the command buffer          */
static char  *shm_buf  = NULL;   /* Pointer to the command buffer     */
static int    sem_id   = -1;     /* ID of the semaphore set           */

/* ----------  Semaphore helpers  ---------- */
static void semop_wrapper(int semid, int sem_num, int sem_op)
{
    struct sembuf sb = { sem_num, sem_op, 0 };
    if (semop(semid, &sb, 1) == -1) {
        perror("semop");
        exit(EXIT_FAILURE);
    }
}

/* ----------  Thread routine  ---------- */
static void *handle_command(void *arg)
{
    char *cmd = (char *)arg;              /* the command string (malloced)    */
    char *cmd_copy = strdup(cmd);         /* we need a modifiable copy        */

    /* -------------------  Parse ------------------- */
    char *saveptr = NULL;
    char *token  = strtok_r(cmd_copy, " \t\r\n", &saveptr); /* command name */

    if (!token) {                          /* malformed command                */
        free(cmd_copy);
        free(cmd);
        return NULL;
    }

    /* -------------------  READ ------------------- */
    if (strcmp(token, "read") == 0) {
        char *fname = strtok_r(NULL, " \t\r\n", &saveptr);
        if (!fname) {
            fprintf(stderr, "ERROR: read <filename> expected\n");
            goto cleanup;
        }

        /* open file */
        int fd = open(fname, O_RDONLY);
        if (fd == -1) {
            perror("open");
            goto cleanup;
        }

        /* determine file size */
        struct stat st;
        if (fstat(fd, &st) == -1) {
            perror("fstat");
            close(fd);
            goto cleanup;
        }
        size_t fsize = st.st_size;
        if (fsize > BUFFER_SIZE) fsize = BUFFER_SIZE;   /* truncate if too big */

        /* read file */
        char file_buf[BUFFER_SIZE];
        ssize_t r = read(fd, file_buf, fsize);
        if (r == -1) {
            perror("read");
            close(fd);
            goto cleanup;
        }
        close(fd);

        /* create a new shared memory segment for the data */
        int new_shm_id = shmget(IPC_PRIVATE, fsize, IPC_CREAT | 0666);
        if (new_shm_id == -1) {
            perror("shmget (data)");
            goto cleanup;
        }

        char *new_shm_ptr = shmat(new_shm_id, NULL, 0);
        if (new_shm_ptr == (char *)-1) {
            perror("shmat (data)");
            shmctl(new_shm_id, IPC_RMID, NULL);
            goto cleanup;
        }

        memcpy(new_shm_ptr, file_buf, fsize);
        shmdt(new_shm_ptr);

        /* ----------  Tell client the key ---------- */
        /* we need exclusive access to the command buffer */
        semop_wrapper(sem_id, 2, -1);           /* lock mutex */

        snprintf(shm_buf, BUFFER_SIZE, "%d %zu", new_shm_id, fsize);

        semop_wrapper(sem_id, 2, +1);           /* unlock mutex */

        /* Signal client that the answer is ready */
        semop_wrapper(sem_id, 1, +1);
        goto cleanup;
    }

    /* -------------------  WRITE ------------------- */
    if (strcmp(token, "write") == 0) {
        char *fname = strtok_r(NULL, " \t\r\n", &saveptr);
        if (!fname) {
            fprintf(stderr, "ERROR: write <filename> <data> expected\n");
            goto cleanup;
        }

        /* The remaining part of the original command is the data */
        char *data_start = cmd + (cmd + strlen(token) - cmd + 1) + strlen(fname) + 1;
        /* data_start now points to the first byte after the filename */

        /* write to file (create / truncate) */
        int fd = open(fname, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd == -1) {
            perror("open (write)");
            goto cleanup;
        }

        if (write(fd, data_start, strlen(data_start)) == -1) {
            perror("write");
            close(fd);
            goto cleanup;
        }
        close(fd);

        /* Signal client that the operation finished */
        semop_wrapper(sem_id, 1, +1);
        goto cleanup;
    }

    /* -------------------  Unknown command ------------------- */
    fprintf(stderr, "ERROR: unknown command '%s'\n", token);
    semop_wrapper(sem_id, 1, +1);   /* let the client continue anyway */

cleanup:
    free(cmd_copy);
    free(cmd);
    return NULL;
}

/* ----------  Main server loop  ---------- */
int main(void)
{
    /* ----  Shared memory for command buffer  ---- */
    shm_id = shmget(SHM_KEY, BUFFER_SIZE, IPC_CREAT | 0666);
    if (shm_id == -1) {
        perror("shmget");
        exit(EXIT_FAILURE);
    }
    shm_buf = shmat(shm_id, NULL, 0);
    if (shm_buf == (char *)-1) {
        perror("shmat");
        exit(EXIT_FAILURE);
    }
    memset(shm_buf, 0, BUFFER_SIZE);          /* initialise buffer */

    /* ----  Semaphores  ---- */
    sem_id = semget(SEM_KEY, 3, IPC_CREAT | 0666);
    if (sem_id == -1) {
        perror("semget");
        exit(EXIT_FAILURE);
    }
    /* initialise semaphores */
    if (semctl(sem_id, 0, SETVAL, 0) == -1)   /* command ready flag  */
        perror("semctl 0");
    if (semctl(sem_id, 1, SETVAL, 0) == -1)   /* response ready flag */
        perror("semctl 1");
    if (semctl(sem_id, 2, SETVAL, 1) == -1)   /* mutex              */
        perror("semctl 2");

    /* ----  Server loop  ---- */
    for (;;) {
        /* Wait for a command to arrive */
        semop_wrapper(sem_id, 0, -1);   /* sem[0]-- : block until client signals */

        /* Grab the mutex to read the command */
        semop_wrapper(sem_id, 2, -1);   /* lock mutex */

        /* Copy the command to a private buffer */
        char *cmd = strdup(shm_buf);

        /* Clear the buffer for the next command */
        memset(shm_buf, 0, BUFFER_SIZE);

        semop_wrapper(sem_id, 2, +1);   /* unlock mutex */

        /* Create a worker thread to handle the command */
        pthread_t tid;
        if (pthread_create(&tid, NULL, handle_command, cmd) != 0) {
            perror("pthread_create");
            free(cmd);
            continue;          /* keep the server running */
        }
        pthread_detach(tid);   /* we don't need to join */
    }

    /* ----  Cleanup (unreachable in this example)  ---- */
    shmdt(shm_buf);
    shmctl(shm_id, IPC_RMID, NULL);
    semctl(sem_id, 0, IPC_RMID);
    return 0;
}
