### `client.c`

```c
/*  client.c
 *
 *  Minimal client that talks to the server described in server.c.
 *  It accepts one command from the user, writes it to shared memory
 *  and waits for the response (if any).
 */

#define _POSIX_C_SOURCE 200112L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <sys/stat.h>

/* ----------  Configuration  ---------- */
#define SHM_KEY   0x1234        /* key for the command buffer          */
#define SEM_KEY   0x5678        /* key for the semaphore set (3 sems)  */
#define BUFFER_SIZE  4096       /* size of the command buffer          */

/* ----------  Semaphore helpers  ---------- */
static void semop_wrapper(int semid, int sem_num, int sem_op)
{
    struct sembuf sb = { sem_num, sem_op, 0 };
    if (semop(semid, &sb, 1) == -1) {
        perror("semop");
        exit(EXIT_FAILURE);
    }
}

/* ----------  Main client code  ---------- */
int main(void)
{
    /* ----  Read command from stdin  ---- */
    char line[BUFFER_SIZE];
    if (!fgets(line, sizeof line, stdin)) {
        fprintf(stderr, "ERROR: failed to read command\n");
        return EXIT_FAILURE;
    }
    /* strip trailing newline */
    line[strcspn(line, "\r\n")] = '\0';

    /* Basic format check */
    char *cmd = line;
    while (*cmd == ' ') cmd++;          /* skip leading spaces */
    if (!(strncmp(cmd, "read ", 5) == 0 || strncmp(cmd, "write ", 6) == 0)) {
        fprintf(stderr, "ERROR: command must start with 'read' or 'write'\n");
        return EXIT_FAILURE;
    }

    /* ----  Attach shared memory (command buffer)  ---- */
    int shm_id = shmget(SHM_KEY, BUFFER_SIZE, 0666);
    if (shm_id == -1) {
        perror("shmget");
        return EXIT_FAILURE;
    }
    char *shm_buf = shmat(shm_id, NULL, 0);
    if (shm_buf == (char *)-1) {
        perror("shmat");
        return EXIT_FAILURE;
    }

    /* ----  Attach semaphore set  ---- */
    int sem_id = semget(SEM_KEY, 3, 0666);
    if (sem_id == -1) {
        perror("semget");
        shmdt(shm_buf);
        return EXIT_FAILURE;
    }

    /* ----  Write command into buffer ---- */
    /* lock the buffer mutex */
    semop_wrapper(sem_id, 2, -1);   /* sem[2]-- */
    strncpy(shm_buf, line, BUFFER_SIZE - 1);
    shm_buf[BUFFER_SIZE - 1] = '\0';
    semop_wrapper(sem_id, 2, +1);   /* sem[2]++ */

    /* ----  Signal the server that a command is ready ---- */
    semop_wrapper(sem_id, 0, +1);   /* sem[0]++ */

    /* ----  Wait for the server's response ---- */
    semop_wrapper(sem_id, 1, -1);   /* sem[1]-- */

    /* ----  If this was a 'read' command, retrieve the data ---- */
    if (strncmp(line, "read ", 5) == 0) {
        /* the server wrote "<shmid> <size>" into shm_buf */
        int new_shm_id = 0;
        size_t file_size = 0;
        if (sscanf(shm_buf, "%d %zu", &new_shm_id, &file_size) != 2) {
            fprintf(stderr, "ERROR: server did not send a valid response\n");
        } else {
            /* Attach the new shared memory segment */
            char *new_shm_ptr = shmat(new_shm_id, NULL, 0);
            if (new_shm_ptr == (char *)-1) {
                perror("shmat (new data)");
            } else {
                /* print the file contents */
                fwrite(new_shm_ptr, 1, file_size, stdout);
                putchar('\n');

                /* clean up the data segment */
                shmdt(new_shm_ptr);
                shmctl(new_shm_id, IPC_RMID, NULL);
            }
        }
    }

    /* ----  Clean up ---- */
    shmdt(shm_buf);
    /* we do NOT remove the command buffer or semaphores – that is the
       server’s responsibility */
    return EXIT_SUCCESS;
}
