## 3. A secure, corrected implementation

Below is a **minimal, well‑commented** version that addresses all the issues.  
Feel free to copy‑paste and compile it with `gcc -Wall -Wextra -pedantic`.

```c
/*  shortest_job_first.c
 *
 *  A small, secure implementation of SJF (non‑preemptive).
 *
 *  Author:   Security Researcher
 *  License:  MIT
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>   /* for INT_MAX */

/*------------------------------------------------------------*/
/*  Data structures                                           */
/*------------------------------------------------------------*/
typedef struct {
    int id;             /* 1‑based process identifier */
    int burst;          /* burst time (must be > 0)     */
    int waiting;        /* computed waiting time        */
    int turnaround;     /* computed turnaround time    */
} process_t;

/*------------------------------------------------------------*/
/*  Helper: compare burst times for qsort (ascending)        */
/*------------------------------------------------------------*/
int cmp_burst(const void *a, const void *b)
{
    const process_t *pa = a;
    const process_t *pb = b;
    return (pa->burst - pb->burst);
}

/*------------------------------------------------------------*/
/*  Main                                                     */
/*------------------------------------------------------------*/
int main(void)
{
    int n;
    printf("Enter the number of processes (1‑10): ");
    if (scanf("%d", &n) != 1 || n <= 0 || n > 10) {
        fprintf(stderr, "Invalid number of processes.\n");
        return EXIT_FAILURE;
    }

    /* Allocate an array big enough for the maximum 10 processes */
    process_t proc[10];

    for (int i = 0; i < n; ++i) {
        printf("Enter burst time for process %d: ", i + 1);
        if (scanf("%d", &proc[i].burst) != 1 ||
            proc[i].burst <= 0) {
            fprintf(stderr, "Burst time must be a positive integer.\n");
            return EXIT_FAILURE;
        }
        proc[i].id = i + 1;      /* preserve original order */
    }

    /* Sort the processes by burst time (SJF) */
    qsort(proc, n, sizeof(process_t), cmp_burst);

    /* Compute waiting & turnaround times */
    int cumulative_wait = 0;
    int total_waiting = 0;

    for (int i = 0; i < n; ++i) {
        proc[i].waiting   = cumulative_wait;
        proc[i].turnaround = proc[i].waiting + proc[i].burst;

        cumulative_wait += proc[i].burst;
        total_waiting   += proc[i].waiting;

        printf("Process %2d (burst %3d): waiting %3d, turnaround %3d\n",
               proc[i].id,
               proc[i].burst,
               proc[i].waiting,
               proc[i].turnaround);
    }

    /* Compute average waiting time */
    double avg_wait = (double)total_waiting / n;
    printf("Average waiting time: %.2f\n", avg_wait);

    return EXIT_SUCCESS;
}
```

### What changed?

| Change | Why it fixes the issue |
|--------|------------------------|
| `int main(void)` | Meets the C standard. |
| Input validation (`scanf` return value, bounds on `n`, burst > 0) | Stops buffer overrun and bad data. |
| `process_t` struct with `id` | Keeps original process numbering after sorting. |
| `qsort` instead of hand‑rolled bubble sort | Correct, stable, and less error‑prone. |
| Separate `cumulative_wait` & `total_waiting` variables | Accurate sums. |
| `double avg_wait` | Uses floating‑point division. |
| Fixed array size (10) but validated `n <= 10` | No out‑of‑bounds write. |
| Clear, descriptive output | Easier to debug / verify results. |

