## 1. 代码

```c
/*
 * Disk Scheduling Simulator
 * Implements FCFS, SSTF, and SCAN algorithms.
 * Author: <Your Name>
 * Date  : <Date>
 *
 * Compile:  gcc -Wall -Wextra -O2 disk_sched.c -o disk_sched
 *
 * Usage:   ./disk_sched
 *          Follow the prompts to enter the request sequence,
 *          initial head direction and other parameters.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_CYL 199          /* 最大磁道编号，0 ~ 199 */
#define MIN_CYL 0
#define MAX_REQUESTS 200     /* 允许的最大请求数 */

/* ----------------- 工具函数 ----------------- */

/* 计算绝对值 (C99 提供了 labs) */
static inline int abs_val(int x) { return x < 0 ? -x : x; }

/* 交换两个整型 */
static inline void swap(int *a, int *b) {
    int tmp = *a; *a = *b; *b = tmp;
}

/* ----------------- 算法实现 ----------------- */

/* 1. FCFS */
void fcfs(const int *req, int n, int start_head,
          int *order, int *total_seek)
{
    int head = start_head;
    int seek = 0;

    for (int i = 0; i < n; ++i) {
        order[i] = req[i];
        seek += abs_val(order[i] - head);
        head = order[i];
    }
    *total_seek = seek;
}

/* 2. SSTF */
void sstf(const int *req, int n, int start_head,
          int *order, int *total_seek)
{
    int *unserv = (int *)malloc(n * sizeof(int));
    memcpy(unserv, req, n * sizeof(int));

    int head = start_head;
    int seek = 0;
    int served = 0;

    while (served < n) {
        /* 找到离 head 最近的请求 */
        int idx = -1;
        int min_dist = INT_MAX;
        for (int i = 0; i < n; ++i) {
            if (unserv[i] < 0) continue;          /* 已服务 */
            int d = abs_val(unserv[i] - head);
            if (d < min_dist) {
                min_dist = d;
                idx = i;
            }
        }

        if (idx == -1) break; /* 这应该不会发生 */

        order[served] = unserv[idx];
        seek += min_dist;
        head = order[served];

        unserv[idx] = -1;  /* 标记已服务 */
        served++;
    }

    *total_seek = seek;
    free(unserv);
}

/* 3. SCAN */
void scan(const int *req, int n, int start_head,
          int direction, /* 0: 低号磁道方向, 1: 高号磁道方向 */
          int *order, int *total_seek)
{
    /* 先把请求按磁道号排序 */
    int *sorted = (int *)malloc(n * sizeof(int));
    memcpy(sorted, req, n * sizeof(int));
    qsort(sorted, n, sizeof(int), [](const void *a, const void *b) {
        return (*(int *)a - *(int *)b);
    });

    int head = start_head;
    int seek = 0;
    int idx = 0;   /* 指向 sorted 中当前请求 */

    /* 根据方向找到第一个需要访问的请求 */
    if (direction == 1) {   /* 向高号磁道移动 */
        /* 找到第一个 >= head 的索引 */
        while (idx < n && sorted[idx] < head) idx++;
        /* 先向 199 移动，处理所有 >= head 的请求 */
        for (int i = idx; i < n; ++i) {
            order[seek == 0 ? 0 : (int)strlen(order) ? 0 : 0] = sorted[i];
        }
    } else {               /* 向低号磁道移动 */
        /* 找到第一个 > head 的索引 */
        idx = n - 1;
        while (idx >= 0 && sorted[idx] > head) idx--;
        /* 先向 0 移动，处理所有 <= head 的请求（从高到低） */
    }

    /* 为了简化，下面用两段循环实现：先往一个方向走，再往另一方向走 */
    int cur = start_head;
    if (direction == 1) {
        /* 1) 先向高端 199 */
        while (idx < n) {
            order[seek] = sorted[idx];
            seek += abs_val(order[seek] - cur);
            cur = order[seek];
            idx++;
        }
        /* 2) 到 199，反向到 0 */
        seek += abs_val(MAX_CYL - cur);
        cur = MAX_CYL;
        idx = n - 1;
        while (idx >= 0) {
            order[seek] = sorted[idx];
            seek += abs_val(order[seek] - cur);
            cur = order[seek];
            idx--;
        }
    } else {
        /* 1) 先向低端 0 */
        while (idx >= 0) {
            order[seek] = sorted[idx];
            seek += abs_val(order[seek] - cur);
            cur = order[seek];
            idx--;
        }
        /* 2) 到 0，反向到 199 */
        seek += abs_val(cur - MIN_CYL);
        cur = MIN_CYL;
        idx = 0;
        while (idx < n) {
            order[seek] = sorted[idx];
            seek += abs_val(order[seek] - cur);
            cur = order[seek];
            idx++;
        }
    }

    *total_seek = seek;
    free(sorted);
}

/* ----------------- 主程序 ----------------- */

int main(void)
{
    printf("磁盘调度实验程序\n");
    printf("请输入磁道请求序列长度（不超过 %d）：", MAX_REQUESTS);
