    printf("\n=== FCFS ===\n");
    printf("调度顺序: ");
    for (int i = 0; i < n; ++i) printf("%d ", order[i]);
    printf("\n平均寻道长度: %.2f\n", (double)total_seek / n);

    /* SSTF */
    sstf(req, n, start_head, order, &total_seek);
    printf("\n=== SSTF ===\n");
    printf("调度顺序: ");
    for (int i = 0; i < n; ++i) printf("%d ", order[i]);
    printf("\n平均寻道长度: %.2f\n", (double)total_seek / n);

    /* SCAN */
    scan(req, n, start_head, dir, order, &total_seek);
    printf("\n=== SCAN ===\n");
    printf("调度顺序: ");
    for (int i = 0; i < n; ++i) printf("%d ", order[i]);
    printf("\n平均寻道长度: %.2f\n", (double)total_seek / n);

    free(req);
    free(order);
    return EXIT_SUCCESS;
}
