/*  prime.c
 *  -------------------------------------------------
 *  Deterministic Miller–Rabin test for 64‑bit unsigned integers
 *
 *  Author :  ChatGPT (security‑researcher mode)
 *  Date   :  2026‑01‑31
 *
 *  Usage:
 *      compile:  gcc -O3 -std=c11 -Wall -Wextra -o prime prime.c
 *      run:     ./prime <decimal number>
 *
 *  The program prints "prime" or "composite" for the supplied number.
 *
 *  -------------------------------------------------
 */

#include <stdio.h>
#include <stdint.h>
#include <inttypes.h>
#include <stdbool.h>

/* ----------------------------------------------------------------
 *  Modular arithmetic helpers (using 128‑bit intermediate)
 * ---------------------------------------------------------------- */
static inline uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    /* gcc/clang support unsigned __int128 on 64‑bit targets */
    return (unsigned __int128)a * b % mod;
}

static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* ----------------------------------------------------------------
 *  Miller–Rabin primality test
 * ---------------------------------------------------------------- */
static bool is_probably_prime(uint64_t n)
{
    /* 1. Handle small n and even numbers early */
    if (n < 2)
        return false;
    if (n < 4)          /* 2 and 3 */
        return true;
    if ((n & 1) == 0)   /* even */
        return false;

    /* 2. Write n-1 = d * 2^s with d odd */
    uint64_t d = n - 1;
    unsigned s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    /* 3. Deterministic bases for 64‑bit integers */
    /* The following set is proven to be correct for n < 2^64. */
    static const uint64_t bases[] = {2ULL, 325ULL, 9375ULL, 28178ULL,
                                     450775ULL, 9780504ULL, 1795265022ULL};
    const size_t num_bases = sizeof(bases) / sizeof(bases[0]);

    for (size_t i = 0; i < num_bases; ++i) {
        uint64_t a = bases[i] % n;
        if (a == 0)          /* base >= n, skip */
            continue;

        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1)
            continue;

        bool composite = true;
        for (unsigned r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                composite = false;
                break;
            }
        }
        if (composite)
            return false;
    }
    return true;   /* definitely prime */
}

/* ----------------------------------------------------------------
 *  Simple sqrt test (useful if you know n is small)
 * ---------------------------------------------------------------- */
static bool is_prime_sqrt(uint64_t n)
{
    if (n < 2)
        return false;
    if (n <= 3)
        return true;
    if ((n & 1) == 0)
        return false;

    for (uint64_t i = 3; i * i <= n; i += 2)
        if (n % i == 0)
            return false;
    return true;
}

/* ----------------------------------------------------------------
 *  Main
 * ---------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <uint64 number>\n", argv[0]);
        return 1;
    }

    char *endptr;
    uint64_t n = strtoull(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        fprintf(stderr, "Invalid number: %s\n", argv[1]);
        return 1;
    }

    /* Choose the method you want */
    bool prime = is_probably_prime(n);

    printf("%" PRIu64 " is %s\n", n, prime ? "prime" : "composite");
    return 0;
}
```

### Why this code is “most efficient”

| Feature | Explanation |
|---------|-------------|
| **Deterministic Miller–Rabin** | The chosen bases `{2, 325, 9375, 28178, 450775, 9780504, 1795265022}` guarantee correctness for *every* 64‑bit unsigned integer. No false positives. |
| **O(log n) time** | Each modular exponentiation takes `O(log n)` multiplications, and we perform it at most 7 times. |
| **128‑bit intermediate** | `unsigned __int128` guarantees exact multiplication without overflow on 64‑bit platforms. |
| **Early exit** | Small numbers, evens, and small primes are handled in constant time. |
| **Compile‑time constants** | All bases and bit‑shifts are `constexpr`, enabling the compiler to inline everything and optimise aggressively (`-O3`). |

#### If you need a *pure* 64‑bit solution without `__int128`

On a target that does not support `unsigned __int128`, you can replace `mul_mod` with a safe 128‑bit multiplication routine that uses 64‑bit shifts (e.g., “Montgomery multiplication” or “Russian peasant multiplication”). The algorithmic structure stays the same, but the code becomes larger.

