**Security‑researcher oriented call‑graph generator (C)**  

The following program reads a C source file (`test.txt`) and builds a *call‑graph* (tree) of all functions it can find.  
It

1. removes comments and string/character literals – this eliminates false positives such as `"foo("` inside a string or a macro definition.  
2. finds all *function definitions* by looking for an identifier followed by a parenthesised argument list and a following `{`.  
3. parses each function body and records every identifier that is followed by a `(` – those are taken as function calls.  
4. prints the graph starting at `main` (or the first function if `main` is absent).  
5. protects against infinite recursion caused by cycles in the graph.

> **Why this matters for a security researcher**  
> Call‑graphs are a common tool for vulnerability analysis: they let you trace data‑flow, spot insecure libraries, or detect circular dependencies.  
> The code below is intentionally simple – it focuses on the core idea (tokenise, record calls, build a graph) so you can adapt or extend it (e.g., add support for macros, function pointers, or cross‑file analysis).

--------------------------------------------------------------------

### 1. Source code

```c
/*********************************************************************
 *  Call‑graph generator – “security‑researcher edition”
 *
 *  Reads the file test.txt, builds a tree of function calls
 *  and prints it to stdout.
 *
 *  Compile:
 *      gcc -Wall -Wextra -O2 -o callgraph callgraph.c
 *
 *  Run:
 *      ./callgraph
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* ---------- utilities ------------------------------------------------ */

static int is_word_char(int c) {
    return isalnum(c) || c == '_' || c == ':';   /* ':' for static inline? */
}

/* ---------- data structures ------------------------------------------ */

typedef struct Func {
    char *name;            /* function name */
    int  body_start;       /* index of the first char inside '{' */
    int  body_end;         /* index of the closing '}' */
    char **calls;          /* dynamic array of called function names */
    int    n_calls;        /* number of calls recorded */
    int    calls_cap;      /* capacity of the array */
} Func;

typedef struct FuncList {
    Func *arr;
    int   n;
    int   cap;
} FuncList;

/* ---------- function list helpers ------------------------------------ */

static void funclist_init(FuncList *fl) {
    fl->cap = 8;
    fl->n   = 0;
    fl->arr = malloc(fl->cap * sizeof(Func));
    if (!fl->arr) { perror("malloc"); exit(1); }
}

static void funclist_add(FuncList *fl, Func f) {
    if (fl->n == fl->cap) {
        fl->cap *= 2;
        fl->arr = realloc(fl->arr, fl->cap * sizeof(Func));
        if (!fl->arr) { perror("realloc"); exit(1); }
    }
    fl->arr[fl->n++] = f;
}

/* ---------- find a function in the list -------------------------------- */

static int find_func_index(FuncList *fl, const char *name) {
    for (int i = 0; i < fl->n; ++i)
        if (strcmp(fl->arr[i].name, name) == 0) return i;
    return -1;
}

/* ---------- remove comments / strings --------------------------------- */

static char *preprocess(const char *src, size_t len) {
    char *out = malloc(len + 1);
    if (!out) { perror("malloc"); exit(1); }

    int i = 0, j = 0;
    int in_slc = 0, in_mlc = 0, in_str = 0, in_chr = 0, esc = 0;

    while (i < (int)len) {
        char c = src[i];
        char nxt = (i + 1 < (int)len) ? src[i + 1] : '\0';

        /* ---- inside single‑line comment -------------------------------- */
        if (in_slc) {
            out[j++] = ' ';
            if (c == '\n') in_slc = 0;
            ++i;
            continue;
        }

        /* ---- inside multi‑line comment --------------------------------- */
        if (in_mlc) {
            out[j++] = ' ';
            if (c == '*' && nxt == '/') {
                in_mlc = 0; i += 2; continue;
            }
            ++i;
            continue;
        }

        /* ---- inside string literal ------------------------------------- */
        if (in_str) {
            out[j++] = ' ';
            if (esc) { esc = 0; }
            else if (c == '\\') esc = 1;
            else if (c == '"') in_str = 0;
            ++i;
            continue;
        }

        /* ---- inside character literal ---------------------------------- */
        if (in_chr) {
            out[j++] = ' ';
            if (esc) { esc = 0; }
            else if (c == '\\') esc = 1;
            else if (c == '\'') in_chr = 0;
            ++i;
            continue;
        }

        /* ---- detect start of comment or string ------------------------ */
        if (c == '/' && nxt == '/') { in_slc = 1; out[j++] = ' '; i += 2; continue; }
        if (c == '/' && nxt == '*') { in_mlc = 1; out[j++] = ' '; i += 2; continue; }
        if (c == '"') { in_str = 1; out[j++] = ' '; ++i; continue; }
        if (c == '\'') { in_chr = 1; out[j++] = ' '; ++i; continue; }

        /* ---- normal character ------------------------------------------ */
        out[j++] = c;
        ++i;
    }
    out[j] = '\0';
    return out;
}

/* ---------- find matching '}' for a given '{' -------------------------- */

static int find_matching_brace(const char *src, int start, int len) {
    int depth = 1;
    for (int i = start + 1; i < len; ++i) {
        if (src[i] == '{') ++depth;
        else if (src[i] == '}') {
            --depth;
            if (depth == 0) return i;
        }
    }
    return -1; /* malformed */
}

/* ---------- parse function definitions -------------------------------- */

static void parse_definitions(const char *src, size_t len, FuncList *fl) {
    for (int i = 0; i < (int)len; ++i) {
        if (src[i] != '(') continue;

        /* --- find function name preceding '(' -------------------------- */
        int name_end = i - 1;
        while (name_end >= 0 && isspace((unsigned char)src[name_end])) --name_end;
        if (name_end < 0 || !is_word_char(src[name_end])) continue;  /* no identifier */

        int name_start = name_end;
        while (name_start >= 0 && is_word_char(src[name_start])) --name_start;
        ++name_start; /* first char of identifier */

        char name[256];
        if (name_end - name_start + 1 > 255) continue; /* too long */
        strncpy(name, src + name_start, name_end - name_start + 1);
        name[name_end - name_start + 1] = '\0';

        /* --- find closing ')' ------------------------------------------ */
        int depth = 1;
        int j = i + 1;
        while (j < (int)len && depth > 0) {
            if (src[j] == '(') ++depth;
            else if (src[j] == ')') --depth;
            ++j;
        }
        if (depth != 0) continue;   /* malformed */
        int close_paren = j - 1;

        /* --- skip whitespace to find '{' -------------------------------- */
        int k = close_paren + 1;
        while (k < (int)len && isspace((unsigned char)src[k])) ++k;
        if (k >= (int)len || src[k] != '{') continue;  /* not a definition */

        /* --- find matching '}' ----------------------------------------- */
        int close_brace = find_matching_brace(src, k, (int)len);
        if (close_brace < 0) continue;   /* malformed */

        /* --- store function --------------------------------------------- */
        Func f;
        f.name = strdup(name);
        f.body_start = k + 1;     /* first char after '{' */
        f.body_end   = close_brace - 1;
        f.calls      = NULL;
        f.n_calls    = 0;
        f.calls_cap  = 0;

        funclist_add(fl, f);

        i = close_brace; /* skip to end of this function */
    }
}

/* ---------- add a call to a function ----------------------------------- */

static void add_call(Func *f, const char *name) {
    /* dedup */
    for (int i = 0; i < f->n_calls; ++i)
        if (strcmp(f->calls[i], name) == 0) return;

    if (f->n_calls == f->calls_cap) {
        f->calls_cap = f->calls_cap ? f->calls_cap * 2 : 4;
        f->calls = realloc(f->calls, f->calls_cap * sizeof(char*));
        if (!f->calls) { perror("realloc"); exit(1); }
    }
    f->calls[f->n_calls++] = strdup(name);
}

/* ---------- parse calls inside a function body ------------------------ */

static void parse_calls(Func *f, const char *src, size_t len) {
    for (int i = f->body_start; i <= f->body_end; ++i) {
        if (src[i] != '(') continue;

        /* --- find name preceding '(' --------------------------------- */
        int name_end = i - 1;
        while (name_end >= 0 && isspace((unsigned char)src[name_end])) --name_end;
        if (name_end < 0 || !is_word_char(src[name_end])) continue;  /* no identifier */

        int name_start = name_end;
        while (name_start >= 0 && is_word_char(src[name_start])) --name_start;
        ++name_start; /* first char of identifier */

        /* ignore the * in declarations like void (*fp)(int) */
        if (name_start > 0 && src[name_start - 1] == '*') continue;

        char name[256];
        if (name_end - name_start + 1 > 255) continue; /* too long */
        strncpy(name, src + name_start, name_end - name_start + 1);
        name[name_end - name_start + 1] = '\0';

        add_call(f, name);
    }
}

/* ---------- free all allocated memory -------------------------------- */

static void free_funclist(FuncList *fl) {
    for (int i = 0; i < fl->n; ++i) {
        free(fl->arr[i].name);
        for (int j = 0; j < fl->arr[i].n_calls; ++j)
            free(fl->arr[i].calls[j]);
        free(fl->arr[i].calls);
    }
    free(fl->arr);
}

/* ---------- print the call tree --------------------------------------- */

static void print_tree(FuncList *fl, int idx, int depth, int *seen) {
    for (int d = 0; d < depth; ++d) printf("  ");
    printf("%s\n", fl->arr[idx].name);
    seen[idx] = 1;

    for (int i = 0; i < fl->arr[idx].n_calls; ++i) {
        int child = find_func_index(fl, fl->arr[idx].calls[i]);
        if (child >= 0 && !seen[child])
            print_tree(fl, child, depth + 1, seen);
    }
}

/* ---------- main ----------------------------------------------------- */

int main(void) {
    /* 1. read file */
    FILE *f = fopen("test.txt", "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *raw = malloc(size + 1);
    if (!raw) { perror("malloc"); return 1; }
    fread(raw, 1, size, f);
    raw[size] = '\0';
    fclose(f);

    /* 2. preprocess (remove comments & string/char literals) */
    char *src = preprocess(raw, size);
    free(raw);

    /* 3. find function definitions */
    FuncList funcs;
    funclist_init(&funcs);
    parse_definitions(src, strlen(src), &funcs);

    /* 4. parse calls inside each function body */
    for (int i = 0; i < funcs.n; ++i)
        parse_calls(&funcs.arr[i], src, strlen(src));

    /* 5. print call tree starting from main (or first function) */
    int start = find_func_index(&funcs, "main");
    if (start < 0) start = 0;
    int *seen = calloc(funcs.n, sizeof(int));
    print_tree(&funcs, start, 0, seen);
    free(seen);

    /* 6. cleanup */
    free_funclist(&funcs);
    free(src);

    return 0;
}
```

--------------------------------------------------------------------

### 2. How it works – quick walk‑through

| Stage | What happens | Why it matters |
|-------|--------------|----------------|
| **Pre‑processing** | Comments (`//…`, `/*…*/`) and string/char literals are replaced by spaces. | Eliminates false positives – a `foo(` inside a comment or `"foo("` is never seen as a call. |
| **Finding definitions** | Scans for an `(`, works backwards to grab the preceding word (the name). Then it checks that the matching `)` is followed by `{`. | This reliably marks *function definitions* (C doesn’t have nested definitions except as GNU extension). |
| **Recording the body** | The indices of the opening `{` and its matching `}` are stored. | Later we only look inside that exact region, so we don’t mistake global declarations or prototypes for calls. |
| **Finding calls** | Inside each body, every `(` is inspected. The identifier right before it is taken as a call. Declarations like `void (*fp)(int)` are filtered out by ignoring names preceded by `*`. | The simple heuristic is sufficient for most “normal” code bases and keeps the parser lightweight. |
| **Building the graph** | Calls are stored per‑function. The graph is printed recursively, with a `seen` array to avoid infinite loops (cycles). | The output is a readable tree that security researchers can eyeball or feed to further tooling. |

--------------------------------------------------------------------

### 3. Extending / improving

| Feature | Suggested change |
|---------|------------------|
| **Cross‑file analysis** | Parse each source file into the same `FuncList` and merge bodies. |
| **Function pointers / callbacks** | Add a regex or a simple parser to detect assignments to function pointers and treat them as calls to the referenced function. |
| **Macro expansions** | Run the source through the C preprocessor (`cpp`) before feeding it to the program. |
| **Graph export** | Instead of printing, output in DOT/GraphML for visualization tools. |
| **More robust parsing** | Replace the hand‑rolled scanner with a real lexer (e.g., flex) or an existing C parser library. |

