下面给出一个 **完整、可直接编译运行的 C 版“万年历实验”程序**。  
程序实现了：

1. **键盘输入初始时间**（年、月、日）。  
2. 通过菜单可 **增加/减少年份、月份、日期**，并且会自动处理闰年、月份天数、跨月跨年等情况。  
3. 一个 **“重置到初始时间”** 的功能。  
4. 简单的输入合法性检查与错误提示。  

> **编译**  
> ```bash
> gcc -Wall -Wextra -std=c11 perpetual_calendar.c -o perpetual_calendar
> ./perpetual_calendar
> ```

```c
/*********************************************************************
 *  万年历实验（C 版） 
 *  功能：
 *  1) 通过键盘输入初始时间
 *  2) 增加/减少 年、月、日
 *  3) 重置到初始时间
 *  4) 自动处理闰年、月份天数、跨月跨年
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/* ------------------- 日期结构 ------------------- */
typedef struct {
    int year;   /* 年份 例如 2024 */
    int month;  /* 月份 1~12 */
    int day;    /* 日期 1~31（根据月份动态判断） */
} Date;

/* ------------------- 工具函数 ------------------- */

/* 判断闰年 */
bool is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

/* 返回某月天数（考虑闰年） */
int days_in_month(int year, int month) {
    static const int days[12] = { 31, 28, 31, 30, 31, 30,
                                 31, 31, 30, 31, 30, 31 };
    if (month == 2 && is_leap_year(year))
        return 29;
    return days[month - 1];
}

/* 让日期保持合法：日不超出该月天数，若超出则取该月最大值 */
void clamp_day(Date *d) {
    int max_day = days_in_month(d->year, d->month);
    if (d->day > max_day) d->day = max_day;
    if (d->day < 1)       d->day = 1;
}

/* 处理跨月跨年（正向） */
void add_month(Date *d, int n) {
    d->month += n;
    while (d->month > 12) {
        d->month -= 12;
        d->year++;
    }
    while (d->month < 1) {
        d->month += 12;
        d->year--;
    }
    clamp_day(d);
}

/* 处理跨年（正向） */
void add_year(Date *d, int n) {
    d->year += n;
    /* 若原来是闰年 2/29，目标年非闰年则改为 2/28 */
    if (d->month == 2 && d->day == 29 && !is_leap_year(d->year))
        d->day = 28;
    clamp_day(d);
}

/* 处理日的增减（可能跨月跨年） */
void add_day(Date *d, int n) {
    d->day += n;
    while (d->day > days_in_month(d->year, d->month)) {
        d->day -= days_in_month(d->year, d->month);
        d->month++;
        if (d->month > 12) {
            d->month = 1;
            d->year++;
        }
    }
    while (d->day < 1) {
        d->month--;
        if (d->month < 1) {
            d->month = 12;
            d->year--;
        }
        d->day += days_in_month(d->year, d->month);
    }
}

/* ------------------- 输入与打印 ------------------- */

/* 安全读取整数，提示错误后返回 false */
bool read_int(const char *prompt, int *out) {
    char buf[64];
    while (1) {
        printf("%s", prompt);
        if (!fgets(buf, sizeof(buf), stdin))
            return false;          // EOF / 错误
        char *end;
        long val = strtol(buf, &end, 10);
        if (end != buf && (*end == '\n' || *end == '\0')) {
            *out = (int)val;
            return true;
        }
        printf("输入无效，请重新输入。\n");
    }
}

/* 打印日期 */
void print_date(const Date *d) {
    printf("\n当前日期：%04d-%02d-%02d\n", d->year, d->month, d->day);
}

/* ------------------- 主程序 ------------------- */
int main(void) {
    Date original = {0}, current = {0};

    /* ---------- 读取初始日期 ---------- */
    printf("=== 万年历实验 ===\n");
    while (1) {
        if (!read_int("请输入年份（例如 2024）：", &original.year)) return 1;
        if (!read_int("请输入月份（1~12）：", &original.month)) return 1;
        if (!read_int("请输入日期（1~31）：", &original.day)) return 1;

        if (original.month < 1 || original.month > 12) {
            printf("月份必须在 1~12 之间。\n");
            continue;
        }
        int max_day = days_in_month(original.year, original.month);
        if (original.day < 1 || original.day > max_day) {
            printf("该月最多 %d 天。\n", max_day);
            continue;
        }
        break;
    }
    current = original;  // 记录当前时间
    printf("\n初始化完成，初始时间已保存。\n");

    /* ---------- 主循环 ---------- */
    while (1) {
        print_date(&current);
        printf("\n请选择操作：\n");
        printf("1. 增加年份\n");
        printf("2. 减少年份\n");
        printf("3. 增加月份\n");
        printf("4. 减少月份\n");
        printf("5. 增加日期\n");
        printf("6. 减少日期\n");
        printf("7. 重置到初始时间\n");
        printf("8. 退出\n");
        printf("输入您的选择（1~8）：");

        int choice;
        if (!fgets(buf, sizeof(buf), stdin)) break;
        choice = atoi(buf);

        int amount;
        switch (choice) {
            case 1:
                if (!read_int("请输入增加的年份数（正整数）：", &amount)) continue;
                add_year(&current, amount);
                break;
            case 2:
                if (!read_int("请输入减少的年份数（正整数）：", &amount)) continue;
                add_year(&current, -amount);
                break;
            case 3:
                if (!read_int("请输入增加的月份数（正整数）：", &amount)) continue;
                add_month(&current, amount);
                break;
            case 4:
                if (!read_int("请输入减少的月份数（正整数）：", &amount)) continue;
                add_month(&current, -amount);
                break;
            case 5:
                if (!read_int("请输入增加的日期数（正整数）：", &amount)) continue;
                add_day(&current, amount);
                break;
            case 6:
                if (!read_int("请输入减少的日期数（正整数）：", &amount)) continue;
                add_day(&current, -amount);
                break;
            case 7:
                current = original;
                printf("已重置到初始时间。\n");
                break;
            case 8:
                printf("退出程序。\n");
                return 0;
            default:
                printf("无效选择，请重新输入。\n");
                break;
        }
    }

    return 0;
}
```

### 说明

| 功能 | 说明 |
|------|------|
| `is_leap_year` | 判断是否闰年。 |
| `days_in_month` | 返回指定年月的天数。 |
| `add_month`, `add_year`, `add_day` | 分别处理月份、年份、日期的增减，自动跨月/跨年。 |
| `clamp_day` | 保证日期在合法范围内。 |
| `read_int` | 读取整数，若输入错误提示重新输入。 |
| `print_date` | 打印当前日期。 |
| `original` | 保存用户最初输入的日期，用于“重置”。 |

