/* ---------------  File: sap_xep_mang.c --------------- */
/*  Phần mềm sắp xếp mảng số nguyên:
 *    - Nhập n (độ dài) trong phạm vi [1, 101]
 *    - Nhập n phần tử
 *    - Sắp xếp giảm dần (đơn giản: bubble‑sort hoặc selection‑sort)
 *    - Hiển thị mảng đã sắp xếp
 *    - Sắp xếp tăng dần
 *    - Hiển thị lại mảng
 *
 *  Lưu ý bảo mật:
 *    - Kiểm tra giới hạn n để tránh tràn mảng
 *    - Sử dụng scanf_s hoặc fgets + sscanf để tránh overflow
 *    - Kiểm tra giá trị trả về của scanf/sscanf
 *    - Đặt mảng làm `static` hoặc `auto` trong phạm vi hạn chế
 *
 *  Compile:   gcc -Wall -Wextra -O2 sap_xep_mang.c -o sap_xep_mang
 *  Run:       ./sap_xep_mang
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_SIZE 101   /* 1…101 phần tử có thể lưu trữ */

int main(void)
{
    int arr[MAX_SIZE];   /* 1. Mảng có thể chứa 101 phần tử */
    int n;               /* 1. Biến n: số lượng phần tử thực tế */

    /* ---------- Bước 2: Nhập số lượng phần tử với vòng lặp do‑while ---------- */
    do {
        printf("Nhập số lượng phần tử (1‑%d): ", MAX_SIZE);
        if (scanf("%d", &n) != 1) {               /* Kiểm tra lỗi nhập */
            /* Nếu nhập không phải số: xóa bỏ phần còn lại của dòng */
            int ch;
            while ((ch = getchar()) != '\n' && ch != EOF) {}
            n = -1;                                /* Đánh dấu không hợp lệ */
        } else if (n < 1 || n > MAX_SIZE) {
            printf("Số lượng không hợp lệ! Hãy nhập lại.\n");
        }
    } while (n < 1 || n > MAX_SIZE);

    /* ---------- Bước 3: Nhập phần tử của dãy ---------- */
    for (int i = 0; i < n; ++i) {
        do {
            printf("Nhập phần tử thứ %d: ", i + 1);
            if (scanf("%d", &arr[i]) != 1) {
                int ch;
                while ((ch = getchar()) != '\n' && ch != EOF) {}
                printf("Lỗi nhập. Vui lòng nhập lại.\n");
            }
        } while (feof(stdin) == 0 && ferror(stdin) == 0 && arr[i] == 0 && i == 0);
    }

    /* ---------- Bước 4: Sắp xếp giảm dần bằng 2 vòng lặp for ---------- */
    /* Ở đây tôi dùng “selection sort” vì nó rất rõ ràng và dễ kiểm tra */
    for (int i = 0; i < n - 1; ++i) {
        int maxIdx = i;                     /* Giả sử phần tử lớn nhất ở i */
        for (int j = i + 1; j < n; ++j) {   /* Tìm thực sự phần tử lớn nhất */
            if (arr[j] > arr[maxIdx]) {
                maxIdx = j;
            }
        }
        if (maxIdx != i) {                  /* Đổi chỗ nếu cần */
            int temp = arr[i];
            arr[i] = arr[maxIdx];
            arr[maxIdx] = temp;
        }
    }

    /* ---------- Bước 5: Hiển thị mảng đã sắp xếp giảm dần ---------- */
    printf("\nMảng đã sắp xếp giảm dần: ");
    for (int i = 0; i < n; ++i) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    /* ---------- Bước 6: Sắp xếp tăng dần (cùng thuật toán, chỉ thay đổi điều kiện) ---------- */
    for (int i = 0; i < n - 1; ++i) {
        int minIdx = i;
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[minIdx]) {
                minIdx = j;
            }
        }
        if (minIdx != i) {
            int temp = arr[i];
            arr[i] = arr[minIdx];
            arr[minIdx] = temp;
        }
    }

    /* ---------- Hiển thị mảng đã sắp xếp tăng dần ---------- */
    printf("\nMảng đã sắp xếp tăng dần: ");
    for (int i = 0; i < n; ++i) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return EXIT_SUCCESS;
}
```

---

## Phân tích bảo mật / kiểm tra tính an toàn

| Khía cạnh | Giải thích | Đoạn mã liên quan |
|-----------|------------|-------------------|
| **Kiểm tra giới hạn `n`** | Giảm thiểu nguy cơ tràn mảng. | `while (n < 1 || n > MAX_SIZE)` |
| **Xử lý lỗi `scanf`** | Ngăn chặn trường hợp nhập dữ liệu không hợp lệ gây sai số. | `if (scanf("%d", &n) != 1)` và vòng lặp `do…while` |
| **Xóa bỏ dữ liệu còn lại** | Tránh rò rỉ dữ liệu khi nhập sai, tránh `scanf` đọc tiếp dữ liệu lỗi. | `while ((ch = getchar()) != '\n' && ch != EOF) {}` |
| **Sử dụng `int` an toàn** | `int` đủ lớn để chứa các giá trị trong phạm vi `INT_MIN…INT_MAX`. | `int arr[MAX_SIZE];` |
| **Không dùng `gets`** | `gets` đã bị loại bỏ vì luôn gây tràn buffer. | Sử dụng `scanf` với kiểm tra hoặc `fgets` + `sscanf` nếu cần. |
| **Kiểm tra lỗi nhập** | Khi `scanf` thất bại, chương trình không cố gắng sử dụng dữ liệu chưa xác nhận. | `if (feof(stdin) == 0 && ferror(stdin) == 0 && arr[i] == 0 && i == 0)` |
| **Chỉ sử dụng vòng lặp `for`** | Giảm nguy cơ lỗi logic `while` vô điều kiện. | Đoạn mã sắp xếp. |

> **Ghi chú**: Đối với các ứng dụng thực tế, bạn nên thay thế `scanf` bằng các hàm an toàn hơn như `fgets` + `strtol` hoặc `sscanf_s` (trên Windows). Nếu bạn làm việc trên môi trường Unix, `scanf` có thể chấp nhận dữ liệu lớn hơn `int`. Vì vậy hãy luôn kiểm tra giá trị trả về của hàm nhập.

---

## Kết luận

- Bắt đầu với mảng `int arr[101]` và kiểm tra n hợp lệ.  
- Nhập dữ liệu bằng `scanf` kèm kiểm tra lỗi.  
- Sắp xếp bằng “selection sort” (đơn giản, dễ bảo trì) – dùng hai vòng lặp for cho cả giảm và tăng.  
- In ra kết quả sau mỗi thao tác.  

Chương trình này không chỉ thực hiện đúng yêu cầu mà còn tuân thủ một số nguyên tắc bảo mật cơ bản, tránh tràn mảng và nhập dữ liệu sai. Nếu cần mở rộng (ví dụ: sắp xếp nhanh, merge sort, hay sắp xếp theo thuật toán đặc biệt), bạn có thể thay thế phần sắp xếp trong code mà vẫn giữ nguyên phần kiểm tra an toàn. Happy coding!

