    double data[100];
    double sum = 0.0;

    /* 读取 n 个整数，存入数组，并累加求和 */
    for (i = 0; i < n; ++i) {
        int val;
        scanf("%d", &val);
        data[i] = (double)val;
        sum += data[i];
    }

