    /* 计算标准差（总体标准差） */
    double stddev = sqrt(sumSqDev / n);

    /* 输出结果，保留两位小数 */
    printf("%.2f\n", mean);
    printf("%.2f\n", sumSqDev);
    printf("%.2f\n", stddev);

