#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>

/* Simple hash set implementation for ints.
 * The set is backed by an open‑addressed hash table with
 * linear probing.  It is *not* thread‑safe and assumes
 * the input range fits in int32_t (as per the problem).   */

#define EMPTY  INT32_MIN   /* sentinel value that cannot be in input */
#define TOMBSTONE INT32_MAX /* value used only when freeing entries */

/* Entry in the hash table */
typedef struct {
    int32_t key;
} hash_entry_t;

typedef struct {
    hash_entry_t *table;
    size_t capacity;
    size_t size;
} hash_set_t;

/* Simple hash function: 64‑bit mix of the key. */
static uint64_t hash_int32(int32_t x)
{
    uint64_t k = (uint64_t)(uint32_t)x;
    k = (~k) + (k << 21); /* k = (k << 21) - k - 1; */
    k = k ^ (k >> 24);
    k = (k + (k << 3)) + (k << 8); /* k * 265 */
    k = k ^ (k >> 14);
    k = (k + (k << 2)) + (k << 4); /* k * 21 */
    k = k ^ (k >> 28);
    k = k + (k << 31);
    return k;
}

static size_t next_prime(size_t n)
{
    /* Roughly doubles capacity each rehash;  primes to avoid clustering.
     * For simplicity we just return a power of two >= n. */
    size_t p = 1;
    while (p < n) p <<= 1;
    return p;
}

/* Create a new hash set with at least 'min_capacity' slots. */
static hash_set_t *hash_set_create(size_t min_capacity)
{
    hash_set_t *hs = malloc(sizeof(*hs));
    if (!hs) return NULL;
    hs->capacity = next_prime(min_capacity);
    hs->size = 0;
    hs->table = calloc(hs->capacity, sizeof(hash_entry_t));
    if (!hs->table) {
        free(hs);
        return NULL;
    }
    for (size_t i = 0; i < hs->capacity; ++i)
        hs->table[i].key = EMPTY;
    return hs;
}

/* Destroy the hash set. */
static void hash_set_destroy(hash_set_t *hs)
{
    if (!hs) return;
    free(hs->table);
    free(hs);
}

/* Insert key into hash set.  Returns 1 if inserted, 0 if already present. */
static int hash_set_insert(hash_set_t *hs, int32_t key)
{
    if (!hs) return 0;
    if (hs->size * 2 >= hs->capacity) { /* simple rehash threshold */
        /* Rehash to a larger table. */
        size_t new_cap = hs->capacity * 2;
        hash_entry_t *new_tbl = calloc(new_cap, sizeof(hash_entry_t));
        if (!new_tbl) return 0;
        for (size_t i = 0; i < new_cap; ++i)
            new_tbl[i].key = EMPTY;
        /* Reinsert existing keys */
        for (size_t i = 0; i < hs->capacity; ++i) {
            int32_t k = hs->table[i].key;
            if (k != EMPTY && k != TOMBSTONE) {
                /* Insert into new table */
                uint64_t h = hash_int32(k) & (new_cap - 1);
                while (new_tbl[h].key != EMPTY)
                    h = (h + 1) & (new_cap - 1);
                new_tbl[h].key = k;
            }
        }
        free(hs->table);
        hs->table = new_tbl;
        hs->capacity = new_cap;
    }

    uint64_t h = hash_int32(key) & (hs->capacity - 1);
    while (hs->table[h].key != EMPTY && hs->table[h].key != TOMBSTONE) {
        if (hs->table[h].key == key)
            return 0; /* already present */
        h = (h + 1) & (hs->capacity - 1);
    }
    hs->table[h].key = key;
    hs->size++;
    return 1;
}

/* Check if key exists in hash set. */
static int hash_set_contains(const hash_set_t *hs, int32_t key)
{
    if (!hs) return 0;
    uint64_t h = hash_int32(key) & (hs->capacity - 1);
    while (hs->table[h].key != EMPTY) {
        if (hs->table[h].key == key)
            return 1;
        if (hs->table[h].key == TOMBSTONE) {
            /* Continue probing; tombstone may indicate a later key. */
        }
        h = (h + 1) & (hs->capacity - 1);
    }
    return 0;
}

/* ---------- Main logic ---------- */

/* Safe integer read. Returns 1 on success, 0 on EOF or error. */
static int read_int32(FILE *stream, int32_t *out)
{
    if (fscanf(stream, "%" SCNd32, out) != 1)
        return 0;
    return 1;
}

int main(void)
{
    int32_t n;
    if (!read_int32(stdin, &n) || n <= 0) {
        fprintf(stderr, "Error: expected positive integer count.\n");
        return EXIT_FAILURE;
    }

    /* Allocate input array on heap to avoid stack overflow. */
    int32_t *arr = malloc(n * sizeof(int32_t));
    if (!arr) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    for (int32_t i = 0; i < n; ++i) {
        if (!read_int32(stdin, &arr[i])) {
            fprintf(stderr, "Error: not enough input numbers.\n");
            free(arr);
            return EXIT_FAILURE;
        }
    }

    /* Build a hash set of all unique input values. */
    hash_set_t *set = hash_set_create((size_t)n * 2 + 1);
    if (!set) {
        perror("hash_set_create");
        free(arr);
        return EXIT_FAILURE;
    }

    for (int32_t i = 0; i < n; ++i)
        hash_set_insert(set, arr[i]);

    /* Find longest consecutive sequence.  We'll record its start and length. */
    int32_t best_start = 0;
    int32_t best_len   = 1; /* at least one number exists */

    for (int32_t i = 0; i < n; ++i) {
        int32_t val = arr[i];
        if (!hash_set_contains(set, val - 1)) { /* start of a run? */
            int32_t curr_len = 1;
            int32_t curr_start = val;
            int32_t next = val + 1;
            while (hash_set_contains(set, next)) {
                curr_len++;
                next++;
            }
            if (curr_len > best_len) {
                best_len = curr_len;
                best_start = curr_start;
            }
        }
    }

    /* Print the result: the longest consecutive subsequence in ascending order. */
    if (best_len == 1) {
        printf("No subset found.\n");
    } else {
        for (int32_t i = 0; i < best_len; ++i) {
            if (i) putchar(' ');
            printf("%d", best_start + i);
        }
        putchar('\n');
    }

    /* Clean up */
    hash_set_destroy(set);
    free(arr);

    return EXIT_SUCCESS;
}
