## 1.  Server – `udp_server.c`

```c
/*********************************************************************
 * udp_server.c
 * -------------
 * A minimal UDP echo‑uppercase server.
 * Listens on port 5000 and runs forever (until killed).
 * 
 * Build:
 *   gcc -Wall -Wextra -O2 -o udp_server udp_server.c
 *********************************************************************/

#define _POSIX_C_SOURCE 200112L   // for getaddrinfo, getifaddrs
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>

#include <unistd.h>
#include <signal.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <ifaddrs.h>

/* -------------------------------------------------------------- */

#define LISTEN_PORT  "5000"           // <‑‑ choose any >4000
#define MAXDATAGRAM 512              // max bytes we accept per message

static volatile sig_atomic_t keep_running = 1;

static void sigint_handler(int signo) {
    (void)signo;                      // silence unused warning
    keep_running = 0;
}

/* -------------------------------------------------------------- */
/*  Convert a C string in-place to upper‑case.
 *  Input buffer must be null‑terminated and length <= MAXDATAGRAM.
 */
static void to_upper(char *buf, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        buf[i] = (char)toupper((unsigned char)buf[i]);
    }
}

/* -------------------------------------------------------------- */
/*  Print the local IP addresses on all interfaces.  Useful
 *  when the board is on a network where you don't know its
 *  address.
 */
static void dump_local_ip(void) {
    struct ifaddrs *ifaddr, *ifa;
    char addr[INET6_ADDRSTRLEN];

    if (getifaddrs(&ifaddr) == -1) {
        perror("getifaddrs");
        return;
    }

    printf("Local IP addresses:\n");
    for (ifa = ifaddr; ifa != NULL; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == NULL)
            continue;
        if (ifa->ifa_addr->sa_family == AF_INET) {         /* IPv4 */
            struct sockaddr_in *sa = (struct sockaddr_in *)ifa->ifa_addr;
            if (inet_ntop(AF_INET, &sa->sin_addr, addr, sizeof(addr))) {
                printf("  %-15s %s\n", ifa->ifa_name, addr);
            }
        }
#ifdef AF_INET6
        else if (ifa->ifa_addr->sa_family == AF_INET6) {    /* IPv6 */
            struct sockaddr_in6 *sa = (struct sockaddr_in6 *)ifa->ifa_addr;
            if (inet_ntop(AF_INET6, &sa->sin6_addr, addr, sizeof(addr))) {
                printf("  %-15s %s\n", ifa->ifa_name, addr);
            }
        }
#endif
    }
    freeifaddrs(ifaddr);
}

/* -------------------------------------------------------------- */
int main(void) {
    int sockfd;
    struct addrinfo hints, *servinfo, *p;
    struct sockaddr_storage client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    char buf[MAXDATAGRAM + 1];          // +1 for safety null‑terminator
    ssize_t numbytes;

    /* Install Ctrl‑C handler */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* ----------------------------------  bind socket  --------- */

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;        // allow IPv4 or IPv6
    hints.ai_socktype = SOCK_DGRAM;     // UDP
    hints.ai_flags = AI_PASSIVE;        // use local IP

    int rv = getaddrinfo(NULL, LISTEN_PORT, &hints, &servinfo);
    if (rv != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rv));
        return EXIT_FAILURE;
    }

    for (p = servinfo; p != NULL; p = p->ai_next) {
        sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (sockfd == -1) {
            perror("socket");
            continue;
        }

        if (bind(sockfd, p->ai_addr, p->ai_addrlen) == -1) {
            close(sockfd);
            perror("bind");
            continue;
        }
        break;                          // success
    }

    if (p == NULL) {
        fprintf(stderr, "Failed to bind to port %s\n", LISTEN_PORT);
        freeaddrinfo(servinfo);
        return EXIT_FAILURE;
    }

    freeaddrinfo(servinfo);

    printf("UDP server listening on port %s\n", LISTEN_PORT);
    dump_local_ip();

    /* ----------------------------------  main loop  --------- */
    while (keep_running) {
        /* receive a datagram */
        numbytes = recvfrom(sockfd, buf, MAXDATAGRAM, 0,
                            (struct sockaddr *)&client_addr, &client_addr_len);

        if (numbytes == -1) {
            if (errno == EINTR)          // interrupted by signal
                continue;
            perror("recvfrom");
            break;
        }

        /* Safety: ensure the buffer is null‑terminated for string ops */
        if (numbytes > MAXDATAGRAM)
            numbytes = MAXDATAGRAM;
        buf[numbytes] = '\0';

        printf("Received %zd bytes from %s:%d\n",
               numbytes,
               inet_ntop(client_addr.ss_family,
                         (client_addr.ss_family == AF_INET)
                             ? &((struct sockaddr_in *)&client_addr)->sin_addr
                             : &((struct sockaddr_in6 *)&client_addr)->sin6_addr,
                         buf, sizeof(buf)),
               (client_addr.ss_family == AF_INET)
                   ? ntohs(((struct sockaddr_in *)&client_addr)->sin_port)
                   : ntohs(((struct sockaddr_in6 *)&client_addr)->sin6_port));

        /* convert to uppercase */
        to_upper(buf, (size_t)numbytes);

        /* send back */
        ssize_t sent = sendto(sockfd, buf, numbytes, 0,
                              (struct sockaddr *)&client_addr, client_addr_len);

        if (sent == -1) {
            perror("sendto");
            break;
        }
    }

    printf("\nShutting down gracefully.\n");
    close(sockfd);
    return EXIT_SUCCESS;
}
