 *********************************************************************/

#define _POSIX_C_SOURCE 200112L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define SERVER_PORT "5000"
#define MAXDATAGRAM 512

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <server-ip>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    const char *message = "Jan Kowalski";     // hard‑coded name

    /* ---- Resolve server address --------------------------------- */
    struct addrinfo hints, *servinfo, *p;
    int rv, sockfd;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;          // IPv4 or IPv6
    hints.ai_socktype = SOCK_DGRAM;       // UDP

    rv = getaddrinfo(server_ip, SERVER_PORT, &hints, &servinfo);
    if (rv != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rv));
        return EXIT_FAILURE;
    }

    /* Pick the first suitable address */
    for (p = servinfo; p != NULL; p = p->ai_next) {
        sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (sockfd == -1) {
            perror("socket");
            continue;
        }
        break;
    }

    if (p == NULL) {
        fprintf(stderr, "Could not create socket\n");
        freeaddrinfo(servinfo);
        return EXIT_FAILURE;
    }

    /* ---- Send message ------------------------------------------- */
    ssize_t sent = sendto(sockfd, message, strlen(message), 0,
                          p->ai_addr, p->ai_addrlen);

    if (sent == -1) {
        perror("sendto");
        close(sockfd);
        freeaddrinfo(servinfo);
        return EXIT_FAILURE;
    }

    /* ---- Receive reply ------------------------------------------- */
    char buf[MAXDATAGRAM + 1];
    socklen_t addrlen = p->ai_addrlen;
    ssize_t recvd = recvfrom(sockfd, buf, MAXDATAGRAM, 0,
                             p->ai_addr, &addrlen);

    if (recvd == -1) {
        perror("recvfrom");
        close(sockfd);
        freeaddrinfo(servinfo);
        return EXIT_FAILURE;
    }

    buf[recvd] = '\0';            // null‑terminate safely

    printf("Sent:     \"%s\"\n", message);
    printf("Received: \"%s\"\n", buf);

    close(sockfd);
    freeaddrinfo(servinfo);
    return EXIT_SUCCESS;
}
