 ********************************************************************/

#include <iostream>
#include <random>

// ---------------------------------------------------------------
// 1. Структура узла бинарного дерева
// ---------------------------------------------------------------
struct Node
{
    int          value;   // значение узла
    Node*        left;    // левый сын
    Node*        right;   // правый сын

    explicit Node(int v)
        : value(v), left(nullptr), right(nullptr) {}
};

// ---------------------------------------------------------------
// 2. Функция AddNode (добавление одного узла)
// ---------------------------------------------------------------
// Предполагается, что такая функция уже реализована.
// Ниже приведён простейший пример её работы для BST.
// Если ваша реализация отличается, замените этот код на свой.
Node* AddNode(Node* root, int val)
{
    if (root == nullptr)
        return new Node(val);

    if (val < root->value)
        root->left = AddNode(root->left, val);
    else
        root->right = AddNode(root->right, val);

    return root;
}

// ---------------------------------------------------------------
// 3. Функция fullTree – «заполнение» дерева произвольным числом
// ---------------------------------------------------------------
/**
 * @brief Заполняет бинарное дерево случайными числами.
 *
 * @param root   Ссылка на указатель на корень дерева.  Если дерево пустое,
