 *        случайных чисел на ваш источник.
 */
void fullTree(Node*& root, std::size_t count)
{
    if (count == 0) return;

    // Генератор случайных чисел (1 … 1000) – можно изменить диапазон.
    std::mt19937 rng(std::random_device{}());
    std::uniform_int_distribution<int> dist(1, 1000);

    for (std::size_t i = 0; i < count; ++i)
    {
        int val = dist(rng);           // ← замените на ваш источник данных
        root = AddNode(root, val);     // добавляем узел в дерево
    }
}

// ---------------------------------------------------------------
