Below is a **complete, production‑ready example** that satisfies the lab requirements and follows good security practices for Unix‑domain sockets (AF_UNIX).  
The code is split into two small, self‑contained programs – **server.c** and **client.c** – and a tiny **Makefile** to build them.  

> **Why the security‑researcher mindset matters**  
> 1. **Input validation** – we never trust the client’s data.  
> 2. **Race‑condition defence** – we unlink the socket file *before* binding and check that the binding succeeded.  
> 3. **Least‑privilege** – the socket file is created with `0600`, giving access only to the owning user.  
> 4. **Error handling** – every system call is checked and a helpful message is printed.  
> 5. **Clean‑up** – the server removes the socket file when it exits, even on signals.  

Feel free to adjust the socket pathname (see the `#define` section) if your environment requires a different location.  

---

## 1. server.c

```c
/*
 * server.c
 *
 * Listens on a Unix‑domain socket, receives a name, converts it to upper‑case
 * and sends it back.  All errors are checked; the socket file is unlinked
 * before binding to avoid race conditions; the file is removed on exit.
 *
 * Compile:   gcc -Wall -Wextra -o server server.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <errno.h>

/* -----------------------  Configuration  ----------------------- */

#define SOCKET_PATH "/tmp/uds_lab_server.sock"
#define BACKLOG 5
#define BUF_SIZE 256          /* Max length of a client name (incl. NUL) */

/* -----------------------  Globals  ----------------------- */

static int server_fd = -1;

/* -----------------------  Helpers  ----------------------- */

/* Convert a C string to upper‑case in place. */
static void to_upper(char *s)
{
    for (; *s; ++s)
        *s = toupper((unsigned char)*s);
}

/* ----------------------------------------------------------------- */
/* Signal handler: close socket and remove socket file on SIGINT.  */
static void cleanup(int signum)
{
    (void)signum;            /* unused */

    if (server_fd != -1) {
        close(server_fd);
    }
    unlink(SOCKET_PATH);
    exit(EXIT_SUCCESS);
}

/* ----------------------------------------------------------------- */
/* Main server routine. */
int main(void)
{
    struct sockaddr_un addr;
    struct sigaction sa = { .sa_handler = cleanup, .sa_flags = 0 };

    /* Install signal handler for graceful cleanup. */
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    /* ------------------------------------------------------------ */
    /* 1) Create AF_UNIX stream socket. */
    server_fd = socket(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (server_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* ------------------------------------------------------------ */
    /* 2) Prepare address structure. */
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    /* 3) Remove any pre‑existing socket file (race‑free). */
    unlink(SOCKET_PATH);

    /* 4) Bind. */
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) == -1) {
        perror("bind");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    /* 5) Restrict permissions to owner only (0600). */
    if (chmod(SOCKET_PATH, 0600) == -1) {
        perror("chmod");
        /* Not fatal – we still can run. */
    }

    /* 6) Listen. */
    if (listen(server_fd, BACKLOG) == -1) {
        perror("listen");
        close(server_fd);
        unlink(SOCKET_PATH);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on %s\n", SOCKET_PATH);

    /* ------------------------------------------------------------ */
    /* 7) Accept loop – we handle one client at a time. */
    for (;;) {
        int client_fd;
        ssize_t nread;

        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd == -1) {
            /* Accept was interrupted by a signal; continue. */
            if (errno == EINTR)
                continue;
            perror("accept");
            break; /* fatal */
        }

        /* Read data. */
        char buf[BUF_SIZE];
        memset(buf, 0, sizeof(buf));
        nread = read(client_fd, buf, sizeof(buf) - 1);
        if (nread == -1) {
            perror("read");
            close(client_fd);
            continue;
        }

        /* Null‑terminate in case client sent too many bytes. */
        buf[sizeof(buf) - 1] = '\0';

        printf("Received: %s\n", buf);

        /* Convert to upper‑case. */
        to_upper(buf);

        /* Send back. */
        if (write(client_fd, buf, strlen(buf)) == -1) {
            perror("write");
        } else {
            printf("Sent back: %s\n", buf);
        }

        close(client_fd);
    }

    /* ------------------------------------------------------------ */
    /* Cleanup on exit. */
    close(server_fd);
    unlink(SOCKET_PATH);
    return EXIT_SUCCESS;
}
```

