## 2. client.c

```c
/*
 * client.c
 *
 * Connects to the Unix‑domain socket created by server.c, sends a name
 * (first + last), receives the upper‑case reply and prints it.
 *
 * Compile:   gcc -Wall -Wextra -o client client.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <errno.h>

/* -----------------------  Configuration  ----------------------- */

#define SOCKET_PATH "/tmp/uds_lab_server.sock"
#define BUF_SIZE 256

/* ----------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    struct sockaddr_un addr;
    int sock_fd;
    ssize_t nwrite, nread;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <FirstName> <LastName>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    /* Build a single string with a space separator. */
    char message[BUF_SIZE];
    if (snprintf(message, sizeof(message), "%s %s", argv[1], argv[2]) >= (int)sizeof(message)) {
        fprintf(stderr, "Input too long (max %zu bytes).\n", sizeof(message) - 1);
        exit(EXIT_FAILURE);
    }

    /* Create socket. */
    sock_fd = socket(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (sock_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* Set up address. */
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    /* Connect. */
    if (connect(sock_fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) == -1) {
        perror("connect");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    /* Send the message. */
    nwrite = write(sock_fd, message, strlen(message));
    if (nwrite == -1) {
        perror("write");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    /* Read reply. */
    char reply[BUF_SIZE];
    memset(reply, 0, sizeof(reply));
    nread = read(sock_fd, reply, sizeof(reply) - 1);
    if (nread == -1) {
        perror("read");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    /* Null‑terminate. */
    reply[sizeof(reply) - 1] = '\0';

    printf("Server replied: %s\n", reply);

    close(sock_fd);
    return EXIT_SUCCESS;
}
```

