/*********************************************************************
 *  diary.c  - 简单日记管理系统（带密码保护）
 *
 *  依赖库: OpenSSL (libssl, libcrypto)
 *********************************************************************/
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>

#define DATE_SZ 11      /* "YYYY-MM-DD" + '\0' */
#define KEY_SZ  51
#define TEXT_SZ 2001
#define MAX_ENTRIES 1000

#define DIARY_FILE   "diary.bin"
#define PASS_FILE    "password.txt"

typedef struct {
    char date[DATE_SZ];
    char keyword[KEY_SZ];
    char content[TEXT_SZ];
} DiaryEntry;

/* ---------- 密码相关 ---------- */
static int get_random_bytes(unsigned char *buf, int len)
{
    if (!RAND_bytes(buf, len))
        return -1;
    return 0;
}

static int compute_hash(const unsigned char *salt, const char *pw,
                        unsigned char *out_hash)
{
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (!ctx) return -1;
    const EVP_MD *md = EVP_sha256();

    EVP_DigestInit_ex(ctx, md, NULL);
    EVP_DigestUpdate(ctx, salt, 16);            /* salt first */
    EVP_DigestUpdate(ctx, pw, strlen(pw));
    EVP_DigestFinal_ex(ctx, out_hash, NULL);
    EVP_MD_CTX_free(ctx);
    return 0;
}

static int load_password(unsigned char *salt, unsigned char *hash)
{
    FILE *f = fopen(PASS_FILE, "rb");
    if (!f) return -1;
    if (fread(salt, 1, 16, f) != 16) { fclose(f); return -1; }
    if (fread(hash, 1, 32, f) != 32) { fclose(f); return -1; }
    fclose(f);
    return 0;
}

static int save_password(const unsigned char *salt, const unsigned char *hash)
{
    FILE *f = fopen(PASS_FILE, "wb");
    if (!f) return -1;
    fwrite(salt, 1, 16, f);
    fwrite(hash, 1, 32, f);
    fclose(f);
    return 0;
}

static int prompt_password(char *buf, size_t size)
{
    printf("Password: ");
    if (!fgets(buf, (int)size, stdin)) return -1;
    buf[strcspn(buf, "\n")] = 0;   /* strip newline */
    return 0;
}

/* 初始化密码（第一次运行时） */
static int init_password()
{
    unsigned char salt[16], hash[32];
    char pw[128], pw2[128];

    printf("=== 设置初始密码 ===\n");
    while (1) {
        printf("请输入密码: ");
        if (!fgets(pw, sizeof(pw), stdin)) return -1;
        pw[strcspn(pw, "\n")] = 0;

        printf("请再次输入密码: ");
        if (!fgets(pw2, sizeof(pw2), stdin)) return -1;
        pw2[strcspn(pw2, "\n")] = 0;

        if (strcmp(pw, pw2) != 0) {
            printf("两次输入不一致，请重试。\n");
            continue;
        }
        if (strlen(pw) < 6) {
            printf("密码至少 6 位，重试。\n");
            continue;
        }

        /* 生成盐 */
        if (get_random_bytes(salt, 16) < 0) {
            fprintf(stderr, "随机数生成失败\n");
            return -1;
        }
        compute_hash(salt, pw, hash);
        save_password(salt, hash);
        printf("初始密码已设置。\n");
        return 0;
    }
}

/* 认证用户 */
static int authenticate()
{
    unsigned char salt[16], hash[32], try_hash[32];
    char pw[128];

    if (load_password(salt, hash) < 0) {
        /* 没有密码文件，先初始化 */
        if (init_password() < 0) return -1;
        /* 重新加载 */
        if (load_password(salt, hash) < 0) return -1;
    }

    for (int tries = 0; tries < 3; ++tries) {
        if (prompt_password(pw, sizeof(pw)) < 0) return -1;
        compute_hash(salt, pw, try_hash);
        if (CRYPTO_memcmp(hash, try_hash, 32) == 0) {
            printf("认证成功！\n");
