}

/* ---------- 日记相关 ---------- */
static int load_entries(DiaryEntry **out, int *cnt)
{
    FILE *f = fopen(DIARY_FILE, "rb");
    if (!f) { *out = NULL; *cnt = 0; return 0; }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    *cnt = size / sizeof(DiaryEntry);
    *out = malloc(*cnt * sizeof(DiaryEntry));
    if (!*out) { fclose(f); return -1; }
    fread(*out, sizeof(DiaryEntry), *cnt, f);
    fclose(f);
    return 0;
}

static int save_entries(DiaryEntry *entries, int cnt)
{
    FILE *f = fopen(DIARY_FILE, "wb");
