    if (cnt == 0) { printf("无记录。\n"); free(entries); return; }

    qsort(entries, cnt, sizeof(DiaryEntry), cmp_date);
    for (i = 0; i < cnt; ++i) {
        printf("=== [%d] %s ===\n", i+1, entries[i].date);
        printf("关键字: %s\n", entries[i].keyword);
