    entries[idx].content[0] = '\0';
    while (1) {
        if (!fgets(line, sizeof(line), stdin)) break;
        if (strncmp(line, "<END>", 5) == 0) break;
        strncat(entries[idx].content, line, TEXT_SZ - strlen(entries[idx].content) - 1);
    }
    if (entries[idx].content[0] == '\0') {
        /* 用户未输入，恢复原内容 */
        load_entries(&entries, &cnt); /* reload original */
    }

    save_entries(entries, cnt);
    free(entries);
    printf("记录已更新。\n");
}

static void delete_entry()
{
    char date[DATE_SZ];
    printf("请输入要删除的日期 (YYYY-MM-DD): ");
    fgets(date, DATE_SZ, stdin);
    date[strcspn(date, "\n")] = 0;

    DiaryEntry *entries; int cnt;
    if (load_entries(&entries, &cnt) < 0) { printf("读取错误\n"); return; }
    int idx = find_by_date(entries, cnt, date);
    if (idx < 0) { printf("未找到该记录。\n"); free(entries); return; }

    /* 删除 */
    for (int i = idx; i < cnt-1; ++i) entries[i] = entries[i+1];
    cnt--;
    save_entries(entries, cnt);
    free(entries);
    printf("记录已删除。\n");
}

static void search_entries()
{
    int choice;
    printf("按 (1) 关键字 还是 (2) 日期查询？ ");
    scanf("%d", &choice);
    getchar(); /* consume newline */

    if (choice == 1) {
        char kw[KEY_SZ];
        printf("关键字: ");
        fgets(kw, KEY_SZ, stdin);
        kw[strcspn(kw, "\n")] = 0;

        DiaryEntry *entries; int cnt;
        if (load_entries(&entries, &cnt) < 0) { printf("读取错误\n"); return; }
        int found = 0;
        for (int i = 0; i < cnt; ++i) {
            if (strstr(entries[i].keyword, kw)) {
                if (!found) printf("=== 搜索结果 ===\n");
                found = 1;
                printf("[%s] %s\n", entries[i].date, entries[i].keyword);
            }
        }
        if (!found) printf("未找到匹配记录。\n");
        free(entries);
    } else if (choice == 2) {
        char start[DATE_SZ], end[DATE_SZ];
        printf("起始日期 (YYYY-MM-DD): ");
        fgets(start, DATE_SZ, stdin);
        start[strcspn(start, "\n")] = 0;
        printf("结束日期 (YYYY-MM-DD): ");
        fgets(end, DATE_SZ, stdin);
        end[strcspn(end, "\n")] = 0;

        DiaryEntry *entries; int cnt;
        if (load_entries(&entries, &cnt) < 0) { printf("读取错误\n"); return; }
        int found = 0;
        for (int i = 0; i < cnt; ++i) {
            if (strcmp(entries[i].date, start) >= 0 &&
                strcmp(entries[i].date, end) <= 0) {
                if (!found) printf("=== 搜索结果 ===\n");
                found = 1;
                printf("[%s] %s\n", entries[i].date, entries[i].keyword);
            }
        }
        if (!found) printf("未找到匹配记录。\n");
        free(entries);
    } else {
        printf("无效选项。\n");
    }
}

