static void delete_item(void) {
    Category cat = read_category();
    if (cat == CATEGORY_INVALID) { printf("无效的类别！\n"); return; }
    char name[NAME_LEN];
    printf("请输入要删除的商品名称：");
    fgets(name, NAME_LEN, stdin);
    name[strcspn(name, "\n")] = '\0';

    Item **pp = &head;
    while (*pp) {
        if ((*pp)->cat == cat && strcmp((*pp)->name, name) == 0) {
            Item *tmp = *pp;
            *pp = tmp->next;
            free(tmp);
            printf("商品已删除。\n");
            return;
        }
        pp = &((*pp)->next);
    }
    printf("该商品不存在！\n");
}

static void sell_item(void) {
    Category cat = read_category();
    if (cat == CATEGORY_INVALID) { printf("无效的类别！\n"); return; }
    char name[NAME_LEN];
    printf("请输入要购买的商品名称：");
    fgets(name, NAME_LEN, stdin);
    name[strcspn(name, "\n")] = '\0';

