/* ---------- 排序与统计 ---------- */
typedef struct { int count; int sum; } StatInt;
typedef struct { int count; double sum; } StatDbl;

static int cmp_price_desc(const void *a, const void *b) {
    const Item *ia = *(const Item **)a;
    const Item *ib = *(const Item **)b;
    if (ia->price < ib->price) return 1;
    if (ia->price > ib->price) return -1;
    return 0;
}

static int cmp_stock_desc(const void *a, const void *b) {
    const Item *ia = *(const Item **)a;
    const Item *ib = *(const Item **)b;
    return (ia->stock < ib->stock) ? 1 : ((ia->stock > ib->stock) ? -1 : 0);
}

static int cmp_manuf_desc(const void *a, const void *b) {
    const Item *ia = *(const Item **)a;
    const Item *ib = *(const Item **)b;
    int cmp = strcmp(ib->manufacturer, ia->manufacturer);
    return cmp;
}

static void list_by_compare(int (*cmp)(const void*, const void*)) {
    /* 先把链表转成数组，方便排序 */
    int n = 0;
    Item *p = head;
    while (p) { n++; p = p->next; }
    if (n == 0) { printf("没有任何商品！\n"); return; }

    Item **arr = malloc(sizeof(Item*) * n);
    p = head;
    for (int i = 0; i < n; ++i) { arr[i] = p; p = p->next; }

    qsort(arr, n, sizeof(Item*), cmp);
    for (int i = 0; i < n; ++i) print_item(arr[i]);

    free(arr);
}

static void stats_by_price(void) { list_by_compare(cmp_price_desc); }
static void stats_by_stock(void) { list_by_compare(cmp_stock_desc); }
static void stats_by_manufacturer(void) { list_by_compare(cmp_manuf_desc); }

static void statistics_menu(void) {
