           "4. 按生产厂家倒序统计\n"
           "请选择（1/2/3/4）：");
    int opt;
    if (scanf("%d", &opt) != 1) { clear_input(); return; }
    clear_input();

    switch (opt) {
        case 1: stats_all(); break;
        case 2: stats_by_price(); break;
        case 3: stats_by_stock(); break;
        case 4: stats_by_manufacturer(); break;
        default: printf("无效选项！\n");
    }
}

