## 1. 安全实现（C99 标准）

```c
/*
 *  safe_string_sort.c
 *
 *  功能：读取两个字符串 → 分别排序 → 合并 → 重新排序 → 去重
 *  安全性：使用 fgets、qsort、动态分配、长度检查、错误处理
 *  备注：为了演示安全原则，限制单个字符串最大长度为 1024。
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_STR_LEN 1024   /* 每个字符串允许的最大长度（不含 '\0'） */

/* 读取一行字符串，去掉结尾的换行符，返回 0 成功，否则返回 -1 */
static int read_line(char *buf, size_t size) {
    if (fgets(buf, (int)size, stdin) == NULL) {
        return -1;                    /* EOF / 错误 */
    }

    /* 删除尾部换行符，如果存在 */
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') {
        buf[len - 1] = '\0';
    }

    /* 检查是否被截断（即输入长度 >= size-1） */
    if (len == size - 1 && buf[len - 1] != '\0') {
        /* 缓冲区已满，但仍有未读取的字符，清空剩余输入 */
        int ch;
        while ((ch = getchar()) != '\n' && ch != EOF)
            /* 读走并丢弃 */;
        return -1;   /* 视为错误，或者可返回一个特殊值提示 “输入过长” */
    }
    return 0;
}

/* 用于 qsort 的字符比较函数（按 ASCII） */
static int cmp_char(const void *a, const void *b) {
    return (*(const unsigned char *)a - *(const unsigned char *)b);
}

/* 对字符串进行原地排序 */
static void sort_string(char *s) {
    size_t len = strlen(s);
    qsort(s, len, sizeof(char), cmp_char);
}

/* 合并两个已排序的字符串，生成新的字符串（动态分配） */
static char *merge_sorted(const char *a, const char *b) {
    size_t len_a = strlen(a);
    size_t len_b = strlen(b);
    size_t total_len = len_a + len_b;

    char *merged = malloc(total_len + 1);   /* +1 为终止符 */
    if (!merged) {
        return NULL;   /* 内存分配失败 */
    }

    memcpy(merged, a, len_a);
    memcpy(merged + len_a, b, len_b);
    merged[total_len] = '\0';

    return merged;
}

/* 去重：输入字符串已按 ASCII 排序，直接遍历即可 */
static void unique_in_place(char *s) {
    if (!s) return;
    size_t write = 0, read = 0;
    size_t len = strlen(s);

    while (read < len) {
        /* 复制当前字符，跳过后续相同字符 */
        s[write++] = s[read];
        while (read < len && s[read] == s[write - 1]) {
            ++read;
        }
        ++read;
    }
    s[write] = '\0';
}

int main(void) {
    char str1[MAX_STR_LEN + 1];
    char str2[MAX_STR_LEN + 1];

    printf("请输入第一个字符串（长度不超过 %d）: ", MAX_STR_LEN);
    if (read_line(str1, sizeof(str1)) < 0) {
        fprintf(stderr, "读取第一个字符串失败或长度过长。\n");
        return EXIT_FAILURE;
    }

    printf("请输入第二个字符串（长度不超过 %d）: ", MAX_STR_LEN);
    if (read_line(str2, sizeof(str2)) < 0) {
        fprintf(stderr, "读取第二个字符串失败或长度过长。\n");
        return EXIT_FAILURE;
    }

    /* 步骤 1：分别排序 */
    sort_string(str1);
    sort_string(str2);

    /* 步骤 2：合并 */
    char *merged = merge_sorted(str1, str2);
    if (!merged) {
        fprintf(stderr, "内存分配失败。\n");
        return EXIT_FAILURE;
    }

    /* 步骤 3：再次排序 */
    sort_string(merged);

    /* 步骤 4：去重（原地） */
    unique_in_place(merged);

    printf("最终结果: \"%s\"\n", merged);

    free(merged);
    return EXIT_SUCCESS;
}
```

### 代码要点

| 目标 | 实现细节 |
|------|----------|
| **缓冲区溢出** | 使用 `fgets()` 限定读取长度，手动去掉换行符，并检测输入是否被截断。 |
| **动态内存管理** | `merge_sorted()` 使用 `malloc()`，随后 `free()`，避免堆泄漏。 |
| **排序** | `qsort()` 是标准库安全实现；比较函数使用无符号 char 防止负值溢出。 |
| **去重** | 先对字符串排序，再遍历一次即可；原地处理，空间复杂度 O(1)。 |
| **错误处理** | 所有失败情况均返回 `EXIT_FAILURE` 并输出错误信息，避免程序继续运行在异常状态。 |
| **编码** | 使用 `unsigned char` 进行 ASCII 比较，防止字符符号扩展导致的错误。 |

