```c
/*
 * triangle_area.c
 *
 * Reads three lines, each containing a point in the exact format
 * "(fx, fy)" where fx and fy are floating point numbers.
 * Computes the area of the triangle formed by the three points
 * and prints the area to two decimal places.
 *
 * Compile:
 *   gcc -std=c11 -Wall -Wextra -O2 -o triangle_area triangle_area.c -lm
 *
 * Example usage:
 *   echo -e "(0,0)\n(1,0)\n(0,1)" | ./triangle_area
 *   0.50
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>

#define MAX_LINE 256

/*
 * Parses a line that must be exactly of the form "(fx, fy)".
 *   s    : input string (terminated by '\0' or '\n')
 *   x    : pointer to store the first coordinate
 *   y    : pointer to store the second coordinate
 *
 * Returns true if parsing succeeded and the whole line was consumed
 * (apart from an optional trailing newline). Otherwise returns false.
 */
static bool parse_point(const char *s, double *x, double *y)
{
    const char *p = s;

    /* Must start with '(' */
    if (*p != '(') return false;
    ++p;

    /* Parse first number. strtod skips leading whitespace, so we must
     * ensure there is no whitespace before the number. */
    char *end;
    *x = strtod(p, &end);
    if (p == end) return false;            /* no conversion */
    if (*end != ',') return false;        /* comma missing */
    ++end;                                 /* skip comma */

    /* After the comma there must be exactly one space */
    if (*end != ' ') return false;
    ++end;

    *y = strtod(end, &end);
    if (end == NULL) return false;
    if (*end != ')') return false;
    ++end;

    /* After the closing parenthesis we can only have a newline or null terminator */
    if (*end != '\0' && *end != '\n') return false;

    return true;
}

int main(void)
{
    double ax, ay, bx, by, cx, cy;
    char line[MAX_LINE];

    /* Read and parse first point */
    if (!fgets(line, sizeof(line), stdin)) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }
    if (!parse_point(line, &ax, &ay)) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }

    /* Read and parse second point */
    if (!fgets(line, sizeof(line), stdin)) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }
    if (!parse_point(line, &bx, &by)) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }

    /* Read and parse third point */
    if (!fgets(line, sizeof(line), stdin)) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }
    if (!parse_point(line, &cx, &cy)) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }

    /* Compute area using the shoelace formula */
    double area = 0.5 * fabs((bx - ax) * (cy - ay) - (cx - ax) * (by - ay));

    printf("%.2f\n", area);
    return EXIT_SUCCESS;
}
```

### How It Works

1. **Reading Lines**  
   `fgets` reads a line of input into a buffer of size `MAX_LINE`.  
   If fewer than three lines are provided, the program reports an error.

2. **Exact Format Checking**  
   The `parse_point` function walks through the string character by character, ensuring:
   * It starts with `'('`
   * The first coordinate is a valid floating‑point number (checked by `strtod`)
   * Followed by a single comma `','`
   * Followed by exactly one space `' '`
   * The second coordinate is a valid floating‑point number
   * Followed by a closing parenthesis `')'`
   * Nothing else may follow except a newline or string terminator.

3. **Area Calculation**  
   The triangle area is computed with the shoelace formula:
   \[
   A = \frac12 \left| (x_2 - x_1)(y_3 - y_1) - (x_3 - x_1)(y_2 - y_1) \right|
   \]

4. **Output**  
   The area is printed with `printf("%.2f\n", area);` which formats the number
   to two decimal places.

