/*********************************************************************
 *  Josephus problem (minimal time/space) – C implementation
 *
 *  Problem statement:
 *      n people stand in a circle, numbered 1 … n.
 *      Starting from person 1, count k people clockwise and eliminate
 *      the k‑th person.  Continue counting from the next person
 *      and eliminate every k‑th person until only one remains.
 *      Return the surviving person’s original number.
 *
 *  Algorithm:
 *      Use the iterative recurrence
 *          J(1) = 0
 *          J(i) = (J(i-1) + k) mod i     for i > 1
 *      J(i) is 0‑based; add 1 before printing.
 *
 *  Complexity:
 *      Time   : O(n) – one pass over the numbers 1 … n
 *      Space  : O(1) – only a few integer variables
 *
 *  Security / Robustness notes:
 *      •  All arithmetic is done in unsigned 64‑bit integers
 *        (uint64_t) to avoid overflow for very large n/k.
 *      •  Input is read with scanf but the return value is checked.
 *      •  Zero or negative values are rejected with a clear error.
 *      •  The program uses only the C standard library and
 *        has no buffer overflows or undefined behaviour.
 *********************************************************************/

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

int main(void)
{
    uint64_t n, k;

    printf("Enter the number of people (n) and the step (k): ");

    /* 读取输入并检查成功率，避免未定义行为 */
    if (scanf("%" SCNu64 " %" SCNu64, &n, &k) != 2) {
        fprintf(stderr, "Error: Invalid input format.\n");
        return EXIT_FAILURE;
    }

    /* 业务校验：n >= 1 且 k >= 1 才有意义 */
    if (n == 0 || k == 0) {
        fprintf(stderr, "Error: Both n and k must be positive integers.\n");
        return EXIT_FAILURE;
    }

    /* 迭代求解 Josephus 问题 */
    uint64_t survivor = 0;   /* 0‑based index of the survivor */
    for (uint64_t i = 1; i <= n; ++i) {
        survivor = (survivor + k) % i;
