/*
 * Prime Checker
 * --------------
 * This program reads an integer and tells you whether it is a prime number.
 *
 * Compilation:
 *     gcc -std=c11 -O2 -Wall prime.c -o prime
 *
 * Usage (via stdin):
 *     ./prime
 *     29
 *     Output: 29 is a prime number.
 *
 * Usage (via command line argument):
 *     ./prime 42
 *     Output: 42 is NOT a prime number.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <math.h>

/* ------------------------------------------------------------
   Returns true if n is a prime number.
   ------------------------------------------------------------ */
static bool is_prime(long long n)
{
    if (n <= 1)           return false;   // 0, 1 and negatives are not prime
    if (n <= 3)           return true;    // 2 and 3 are prime

    /* Eliminate even numbers and multiples of 3 early */
    if (n % 2 == 0 || n % 3 == 0) return false;

    /* Check odd divisors from 5 up to sqrt(n) */
    /* Using the 6k ± 1 optimization reduces iterations */
    long long i = 5;
    long long limit = (long long) sqrt((double) n);

    while (i <= limit)
    {
        if (n % i == 0 || n % (i + 2) == 0)
            return false;

        i += 6;   // next pair of candidates: 6k-1 and 6k+1
    }

    return true;
}

/* ------------------------------------------------------------
   Main: read number, call is_prime, print result.
   ------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    long long number;
    if (argc == 2) {                     // command‑line argument supplied
        char *endptr;
        number = strtoll(argv[1], &endptr, 10);
        if (*endptr != '\0') {
            fprintf(stderr, "Error: '%s' is not a valid integer.\n", argv[1]);
            return EXIT_FAILURE;
