        printf("Enter an integer: ");
        if (scanf("%lld", &number) != 1) {
            fprintf(stderr, "Error: could not read an integer.\n");
            return EXIT_FAILURE;
        }
    }

    if (is_prime(number))
        printf("%lld is a prime number.\n", number);
    else
        printf("%lld is NOT a prime number.\n", number);

    return EXIT_SUCCESS;
}
```

