## 1.  Integer Square‑Root (exact integer part)

```c
/*  int_sqrt.c
 *  --------------------------
 *  Computes the floor of the square root of a 64‑bit unsigned integer.
 *  Uses the Newton–Raphson method on integers (Babylonian algorithm).
 *
 *  This version is safe against overflow because all intermediate values
 *  are confined to 128‑bit arithmetic when using the GCC/Clang __int128
 *  extension.  On compilers without __int128, you can replace it with a
 *  checked‑overflow routine or use the floating‑point version below.
 *
 *  Compile with:   gcc -std=c11 -Wall -Wextra -O2 -o int_sqrt int_sqrt.c
 */

#include <stdio.h>
#include <stdint.h>

/* Helper: perform multiplication using 128‑bit type if available */
static inline uint64_t mul_u64(uint64_t a, uint64_t b)
{
#if defined(__SIZEOF_INT128__)
    return (uint64_t)((__int128)a * b);
#else
    /* Fallback: multiply in two 32‑bit halves (slow, but portable) */
    uint64_t ah = a >> 32, al = a & 0xffffffffULL;
    uint64_t bh = b >> 32, bl = b & 0xffffffffULL;

    uint64_t high = ah * bh;
    uint64_t mid1 = ah * bl;
    uint64_t mid2 = al * bh;
    uint64_t low  = al * bl;

    /* Propagate carries */
    uint64_t carry = ((mid1 & 0xffffffffULL) + (mid2 & 0xffffffffULL) + (low >> 32)) >> 32;
    high += (mid1 >> 32) + (mid2 >> 32) + carry;
    return (high << 32) | (low & 0xffffffffULL);
#endif
}

/* Integer square root: floor(sqrt(n)) */
static uint64_t isqrt_u64(uint64_t n)
{
    if (n == 0 || n == 1)
        return n;

    /* Initial guess: most significant 1‑bit << 1 (or n >> 1 if you prefer) */
    uint64_t x = n;
    uint64_t y = (x >> 1) + 1;          /* initial guess */

    while (y < x) {
        x = y;
        y = (x + mul_u64(n, 1ULL) / x) >> 1;
    }
    return x;
}

int main(void)
{
    uint64_t val;
    printf("Enter a non‑negative 64‑bit integer: ");
    if (scanf("%" SCNu64, &val) != 1) {
        fprintf(stderr, "Invalid input.\n");
        return 1;
    }

    uint64_t root = isqrt_u64(val);
    printf("floor(sqrt(%ju)) = %ju\n", val, root);
    return 0;
}
```

**Explanation & Security Notes**

| Issue | Mitigation |
|-------|------------|
| **Integer overflow** | The algorithm uses 128‑bit intermediate multiplication (`__int128`) when available; otherwise a safe 32‑bit split multiplication is employed. |
| **Unchecked input** | The program uses `scanf("%" SCNu64, …)` with `<inttypes.h>` to strictly read an unsigned 64‑bit value. |
| **Denominator zero** | The loop condition `y < x` guarantees that `x` never becomes 0, so `n / x` is safe. |
| **Timing attacks** | The loop runs a constant number of iterations (bounded by the bit‑width of the input), which is acceptable for offline computation. |
| **Side‑channel leakage** | The arithmetic is deterministic; no branching on secret data, so no obvious side‑channel risk. |

