**Fonction : `ajoutMOT` – insertion d’un mot dans une liste doublement chaînée tout en gardant l’ordre alphabétique**

> *Contexte :*  
> Dans un dictionnaire implémenté sous forme de liste doublement chaînée, chaque nœud contient un mot (`char *`) ainsi que des pointeurs vers le nœud précédent et suivant.  
> Pour rester sécurisé, on évite les dépassements de tampon, la duplication de mots, et on vérifie que l’allocation mémoire réussit.

```c
/*********************************************************************
 *  Ajout d’un mot dans un dictionnaire doublement chaîné
 *
 *  - La liste est triée par ordre alphabétique croissant
 *  - La fonction renvoie le pointeur vers le (possible) nouveau
 *    début de la liste
 *
 *  Paramètres
 *  ----------
 *      Node **head     : pointeur sur le pointeur vers le premier
 *                        nœud de la liste (pour pouvoir modifier le
 *                        début si nécessaire)
 *      const char *mot : mot à insérer (doit être null‑terminated)
 *
 *  Retour
 *  ------
 *      0  : réussite
 *     -1  : erreur mémoire (malloc a échoué)
 *     -2  : mot déjà présent dans la liste
 *
 *  Sécurité
 *  --------
 *      • Utilisation de `strdup` ou `malloc + strcpy` avec contrôle de
 *        longueur maximale
 *      • Comparaison de mots via `strcmp` (alphabetique, case‑sensitive)
 *      • Vérification d’inclusion avant insertion
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ----------------------------------------------------------------- */
/* Structure d’un nœud de la liste doublement chaînée                 */
typedef struct Node
{
    char  *mot;          /* mot stocké (string terminée par '\0')      */
    struct Node *prev;   /* pointeur vers le nœud précédent           */
    struct Node *next;   /* pointeur vers le nœud suivant             */
} Node;

/* ----------------------------------------------------------------- */
/* Fonction utilitaire : copie sécurisée d’un mot                     */
static char *safe_strdup(const char *s)
{
    size_t len = strlen(s);
    /* Vous pouvez fixer une taille maximale autorisée (ex : 255)    */
    if (len > 255) return NULL;            /* mot trop long */
    char *copy = malloc(len + 1);          /* +1 pour le terminator */
    if (!copy) return NULL;
    strcpy(copy, s);                        /* pas de dépassement ici */
    return copy;
}

/* ----------------------------------------------------------------- */
/* Fonction principale : ajout d’un mot                             */
int ajoutMOT(Node **head, const char *mot)
{
    if (!head || !mot) return -2;          /* paramètres invalides */

    /* Vérification de duplication avant insertion */
    for (Node *curr = *head; curr; curr = curr->next)
        if (strcmp(curr->mot, mot) == 0)
            return -2;                    /* mot déjà présent */

    /* Allocation du nouveau nœud */
    Node *newNode = malloc(sizeof(Node));
    if (!newNode) return -1;

    newNode->mot = safe_strdup(mot);
    if (!newNode->mot) {                    /* échec de strdup */
        free(newNode);
        return -1;
    }
    newNode->prev = newNode->next = NULL;

    /* Cas 1 : liste vide */
    if (!*head)
    {
        *head = newNode;
        return 0;
    }

    /* Cas 2 : insertion avant le premier nœud */
    if (strcmp(mot, (*head)->mot) < 0)
    {
        newNode->next = *head;
        (*head)->prev = newNode;
        *head = newNode;
        return 0;
    }

    /* Cas 3 : insertion dans la liste (ou à la fin) */
    Node *curr = *head;
    while (curr->next && strcmp(curr->next->mot, mot) < 0)
        curr = curr->next;

    /* Insérer après curr */
    newNode->next = curr->next;
    newNode->prev = curr;

    if (curr->next)                   /* nœud suivant existe */
        curr->next->prev = newNode;
    curr->next = newNode;

    return 0;
}

/* ----------------------------------------------------------------- */
/* Exemple d’utilisation (pour tester la fonction)                     */
#ifdef TEST_AJOUT_MOT
int main(void)
{
    Node *dict = NULL;
    ajoutMOT(&dict, "banana");
    ajoutMOT(&dict, "apple");
    ajoutMOT(&dict, "cherry");
    ajoutMOT(&dict, "date");

    /* Affichage */
    for (Node *p = dict; p; p = p->next)
        printf("%s\n", p->mot);

    /* Libération mémoire (non présentée ici) */
    return 0;
}
#endif
```

### Points de sécurité à garder en tête

| Risque | Mitigation |
|--------|------------|
| **Débordement de tampon** | `safe_strdup` impose une taille maximale (exemple 255). |
| **Injection de mot vide / NULL** | Vérification `if (!mot)` dans `ajoutMOT`. |
| **Mots duplicata** | Boucle de vérification avant l’insertion. |
| **Échec d’allocation** | Vérification de `malloc` et `strdup`. |
| **Utilisation de `strcmp`** | Sépare la comparaison des mots de l’allocation. |
| **Gestion de la mémoire** | Chaque mot est alloué séparément, et chaque nœud doit être libéré à la fin. |

> **Remarque** :  
> Si vous utilisez un langage à gestion mémoire automatique (Java, C#, etc.) vous pouvez omettre les appels explicites à `malloc`/`free` et utiliser les structures de collection natives (par ex. `TreeSet` en Java). Le principe reste le même : insérer en préservant l’ordre alphabétique.

