#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

/* ---------- Utility: Safe integer parsing ---------- */
static int read_nonnegative_long_long(long long *out)
{
    char buf[64];
    if (!fgets(buf, sizeof(buf), stdin))
        return 0;                     /* EOF or read error */

    char *endptr;
    errno = 0;
    long long val = strtoll(buf, &endptr, 10);

    /* Check that the entire line was a valid number */
    if (errno != 0 || endptr == buf || (*endptr != '\n' && *endptr != '\0'))
        return 0;

    if (val < 0) /* we only accept non‑negative */
        return 0;

    *out = val;
    return 1;
}

/* ---------- Primitive primality test ---------- */
static int is_prime(long long num)
{
    if (num < 2)
        return 0;
    if (num == 2 || num == 3)
        return 1;
    if (num % 2 == 0)
        return 0;
    /* test odd divisors up to sqrt(num) */
    for (long long d = 3; d * d <= num; d += 2) {
        if (num % d == 0)
            return 0;
    }
    return 1;
}

/* ---------- Main logic ---------- */
int main(void)
{
    printf("Enter a non‑negative integer n: ");
    fflush(stdout);

    long long n;
    if (!read_nonnegative_long_long(&n)) {
        fprintf(stderr, "Invalid input. Please enter a non‑negative integer.\n");
        return EXIT_FAILURE;
    }

    /* Edge case: n < 2 → no primes */
    if (n < 2) {
        printf("No prime numbers ≤ %lld.\n", n);
        return EXIT_SUCCESS;
    }

    /* Print primes.  We keep the output on a single line for readability. */
    int first = 1;  /* flag for space formatting */
    for (long long i = 2; i <= n; ++i) {
        if (is_prime(i)) {
            if (!first)
                putchar(' ');
            printf("%lld", i);
            first = 0;
        }
    }
    putchar('\n');

    return EXIT_SUCCESS;
}
```

