#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_HASH 1000001          /* Must be > largest possible |value| */

static int hashtable[MAX_HASH];   /* map value → latest index (or -1) */

/* -----------------------------------------------------------------
 *  Hash helpers
 * -----------------------------------------------------------------*/
static void clearHashtable(void)
{
    /* Initialise all entries to -1 (meaning “not seen”). */
    for (int i = 0; i < MAX_HASH; ++i) {
        hashtable[i] = -1;
    }
}

/* Map a possibly negative number to the hash table index.
 *  If the number is outside the supported range, we return -1
 *  which is treated as “not found”.
 */
static int getHash(int number)
{
    if (number < 0 || number >= MAX_HASH)
        return -1;          /* out of range */
    return hashtable[number];
}

static void setHash(int number, int index)
{
    if (number < 0 || number >= MAX_HASH)
        return;              /* silently ignore out‑of‑range values */
    hashtable[number] = index;
}

/* -----------------------------------------------------------------
 *  Core routine: find and print one longest consecutive subsequence
 * -----------------------------------------------------------------*/
static void findLongestConsecutiveSequence(const int *book, int n)
