            {
                std::cerr << "Employee not found\n";
                continue;
            }

            // Отправляем запись клиенту
            WriteFile(hPipe, p, sizeof(*p), &bytesRead, nullptr);

            // После отправки уменьшаем счётчик
            lk.lock();
            readers[id]--;
            lk.unlock();

            std::cout << "Client READ employee " << id << "\n";
        }
        else if (op == OP_WRITE)
        {
            // --------------------- Запись --------------------
            Employee newData;
            // Читаем новые данные из канала
            if (!ReadFile(hPipe, &newData, sizeof(newData), &bytesRead, nullptr) ||
                bytesRead != sizeof(newData))
            {
                std::cerr << "Read new data failed\n";
                break;
            }

            // Блокируем запись (отключаем всех читателей/записей)
            std::unique_lock<std::mutex> lk(rwLock);
            Employee* p = nullptr;
            for (auto &e : db)
                if (e.num == newData.num) { p = &e; break; }

            if (!p)
            {
                std::cerr << "Employee not found\n";
                continue;
            }

            *p = newData;   // обновляем
            lk.unlock();

            // Подтверждение (можно отправить 0/1)
            DWORD resp = 1;
            WriteFile(hPipe, &resp, sizeof(resp), &bytesRead, nullptr);

            std::cout << "Client WRITE employee " << newData.num << "\n";
        }
        else
        {
            std::cerr << "Unknown op\n";
            break;
        }
    }
    CloseHandle(hPipe);
}

