int main()
{
    std::string filename;
    std::cout << "Enter binary file name: ";
    std::getline(std::cin, filename);

    // --------------------------------- 1. Создать файл
    {
        std::ofstream out(filename, std::ios::binary);
        if (!out) { std::cerr << "Cannot create file\n"; return 1; }
        // Пример заполнения 5 строк, можно заменить вводом с консоли
        for (int i = 0; i < 5; ++i)
        {
            Employee e{ i + 1, {}, 0.0 };
            std::stringstream ss;
            ss << "Emp" << i;
            strncpy(e.name, ss.str().c_str(), 9);
            e.hours = double(i) * 1.5;
            out.write(reinterpret_cast<const char*>(&e), sizeof(e));
        }
    }

    // --------------------------------- 2. Загрузить данные в память
    {
        std::ifstream in(filename, std::ios::binary);
        Employee e;
        while (in.read(reinterpret_cast<char*>(&e), sizeof(e)))
            db.push_back(e);
    }

    printDb();

    // --------------------------------- 3. Запустить клиентский процесс
    std::cout << "Launching Client.exe ...\n";
    STARTUPINFOW si{};
    PROCESS_INFORMATION pi{};
    si.cb = sizeof(si);
    std::wstring clientExe = L"Client.exe";
    if (!CreateProcessW(clientExe.c_str(), nullptr, nullptr, nullptr, FALSE,
                        0, nullptr, nullptr, &si, &pi))
    {
        std::cerr << "CreateProcess failed: " << GetLastError() << "\n";
        return 1;
    }

    // --------------------------------- 4. Создать NamedPipe
    HANDLE hPipe = CreateNamedPipeW(
        PIPE_NAME.c_str(),
        PIPE_ACCESS_DUPLEX,
        PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
        PIPE_UNLIMITED_INSTANCES,
        65536, 65536, 0, nullptr);

    if (hPipe == INVALID_HANDLE_VALUE)
    {
        std::cerr << "CreateNamedPipe failed: " << GetLastError() << "\n";
        return 1;
    }

    std::cout << "Waiting for client connection...\n";
    if (!ConnectNamedPipe(hPipe, nullptr))
    {
        std::cerr << "ConnectNamedPipe failed: " << GetLastError() << "\n";
        CloseHandle(hPipe);
        return 1;
    }
    std::cout << "Client connected.\n";

    // --------------------------------- 5. Обработать клиента (можно в отдельном потоке)
    std::thread clientThread(handleClient, hPipe);
    clientThread.join();

    // --------------------------------- 6. Пере‑сохраняем файл
    std::ofstream out(filename, std::ios::binary | std::ios::trunc);
    for (auto const& e : db)
        out.write(reinterpret_cast<const char*>(&e), sizeof(e));

    std::cout << "\n--- Modified database ---\n";
    printDb();

    // --------------------------------- 7. Ожидание команды завершения (для удобства)
    std::cout << "\nPress Enter to exit...";
    std::cin.get();
    return 0;
}
```

### Ключевые моменты

1. **Параметры NamedPipe**  
   * `PIPE_TYPE_MESSAGE` + `PIPE_READMODE_MESSAGE` → гарантирует, что чтение/запись будет атомарным.  
   * `PIPE_UNLIMITED_INSTANCES` – позволяет открыть несколько копий канала (если захотите расширить).  

2. **Синхронизация**  
   * `rwLock` – глобальная `std::mutex`.  
   * `readers` – счётчик читателей по ID. Для простоты используется один mutex.  
   * При записи `unique_lock` блокирует как читателей, так и других писателей.  

3. **Проверка ошибок**  
   * В реальном коде следует обрабатывать все ошибки и писать логи.

