Below is a minimal but complete, **educational** example of how a Linux kernel module can expose a memory buffer to user space via `mmap()`.  
It demonstrates:

1. **Kernel‑side** – allocation of a page of kernel memory, creation of a character device (`/dev/mmapdemo`) and implementation of the `mmap` file‑operation that remaps the kernel page into user space.  
2. **User‑space** – opening the device, mapping the buffer, and writing/reading from it.

> **⚠️ Security Note**  
> This code is intentionally simple. In a real product you must:
> - Restrict access to the device (`chmod`/`chown` or `capability` checks).  
> - Ensure the buffer size is checked and not larger than expected.  
> - Use proper locking when accessing the buffer.  
> - Consider `KERNEL` vs `USER` page protections (e.g. `pgprot_writecombine`).  

---

## 1. Kernel Module (`mmap_demo.c`)

```c
/*
 * mmap_demo.c – Minimal kernel module that exposes a kernel buffer via mmap().
 * Compile with:
 *   make -C /lib/modules/$(uname -r)/build M=$PWD modules
 *
 * Load with:
 *   sudo insmod mmap_demo.ko
 *   sudo mknod /dev/mmapdemo c 240 0     # 240 = a dummy major number
 *   sudo chmod 666 /dev/mmapdemo
 *
 * Remove with:
 *   sudo rmmod mmap_demo
 *   sudo rm /dev/mmapdemo
 */

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/fs.h>
#include <linux/mm.h>        /* vmalloc, remap_pfn_range */
#include <linux/vmalloc.h>   /* vmalloc */
#include <linux/uaccess.h>   /* copy_* */

#define DEVICE_NAME "mmapdemo"
#define BUF_SIZE PAGE_SIZE   /* one page */

/* The buffer we will expose to userspace */
static void *kmem_buf;

/* File operations prototypes */
static int mmap_open(struct inode *inode, struct file *filp);
static int mmap_release(struct inode *inode, struct file *filp);
static int mmap_mmap(struct file *filp, struct vm_area_struct *vma);

/* File operations struct */
static const struct file_operations mmap_fops = {
    .owner   = THIS_MODULE,
    .open    = mmap_open,
    .release = mmap_release,
    .mmap    = mmap_mmap,
};

static int __init mmap_init(void)
{
    int ret;

    /* Allocate one page of kernel memory */
    kmem_buf = vmalloc(BUF_SIZE);
    if (!kmem_buf) {
        pr_err(DRIVER_NAME ": failed to allocate memory\n");
        return -ENOMEM;
    }
    memset(kmem_buf, 0, BUF_SIZE);

    /* Register a character device */
    ret = register_chrdev(240, DEVICE_NAME, &mmap_fops);
    if (ret < 0) {
        pr_err(DRIVER_NAME ": failed to register chrdev\n");
        vfree(kmem_buf);
        return ret;
    }

    pr_info(DRIVER_NAME ": loaded. /dev/%s ready.\n", DEVICE_NAME);
    return 0;
}

static void __exit mmap_exit(void)
{
    /* Unregister character device and free memory */
    unregister_chrdev(240, DEVICE_NAME);
    if (kmem_buf)
        vfree(kmem_buf);

    pr_info(DRIVER_NAME ": unloaded.\n");
}

/* File open: no special handling */
static int mmap_open(struct inode *inode, struct file *filp)
{
    return 0;
}

/* File release: no special handling */
static int mmap_release(struct inode *inode, struct file *filp)
{
    return 0;
}

/*
 * mmap() implementation
 * vma->vm_pgoff gives the offset into the buffer (in pages)
 */
static int mmap_mmap(struct file *filp, struct vm_area_struct *vma)
{
    unsigned long offset = vma->vm_pgoff * PAGE_SIZE;
    unsigned long pages  = vma->vm_end - vma->vm_start;

    /* Bounds check: we only expose one page */
    if (offset + pages > BUF_SIZE)
        return -EINVAL;

    /* Map the kernel buffer into user space */
    if (remap_pfn_range(vma,
                        vma->vm_start,
                        vmalloc_to_pfn(kmem_buf),
                        pages,
                        vma->vm_page_prot))
        return -EAGAIN;

    return 0;
}

module_init(mmap_init);
module_exit(mmap_exit);

