## 2. User‑Space Test Program (`mmap_test.c`)

```c
/*
 * mmap_test.c – Test program that maps /dev/mmapdemo into userspace
 * Compile with: gcc -o mmap_test mmap_test.c
 *
 * Run:
 *   ./mmap_test
 */
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>
#include <string.h>

#define DEVICE "/dev/mmapdemo"

int main(void)
{
    int fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    /* Map one page */
    void *ptr = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    printf("Mapped kernel buffer at %p\n", ptr);

    /* Write a test string */
    const char *msg = "Hello from userspace via mmap!";
    strcpy(ptr, msg);
    printf("Written to buffer: \"%s\"\n", (char *)ptr);

    /* Read back */
    printf("Read back: \"%s\"\n", (char *)ptr);

    /* Cleanup */
    if (munmap(ptr, PAGE_SIZE) < 0)
        perror("munmap");
    close(fd);

    return 0;
}
```

### Compile & Run

```bash
