            if (--n_ready == 0) continue;     // нет других событий
        }

        /* Проверяем все открытые клиентские соединения */
        for (i = 0; i <= max_fd; ++i) {
            if (i == listen_fd) continue;          // уже обработали
            if (!FD_ISSET(i, &read_fds)) continue; // без событий

