#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <errno.h>
#include <ctype.h>

#define MAX_PID 65536   /* enough for virtually all systems */
#define CHILD_INIT_CAP 4

typedef struct {
    int pid;                /* own PID  (0 if unused) */
    int ppid;               /* parent PID */
    char state;             /* 'R','S','D','T','Z',... */
    int *children;          /* dynamic array of child PIDs */
    int child_cnt;          /* number of children */
    int child_cap;          /* allocated capacity of children array */
} ProcInfo;

/* global array indexed by PID */
static ProcInfo proc[MAX_PID];

static inline void add_child(int parent, int child)
{
    if (parent < 0 || parent >= MAX_PID) return;
    ProcInfo *p = &proc[parent];
    if (p->child_cap == 0) {
        p->child_cap = CHILD_INIT_CAP;
        p->children = malloc(p->child_cap * sizeof(int));
        if (!p->children) { perror("malloc"); exit(EXIT_FAILURE); }
    }
    if (p->child_cnt == p->child_cap) {
        p->child_cap *= 2;
        int *tmp = realloc(p->children, p->child_cap * sizeof(int));
