        "Usage: prcinfo <root_pid> <pid1> [<pid2> … <pid5>] <option>\n"
        "Options:\n"
        "  -nd   Non‑direct descendants of pid1 (only)\n"
        "  -dd   Direct descendants of pid1 (only)\n"
        "  -sb   Siblings of pid1\n"
        "  -sz   Defunct siblings of pid1\n"
        "  -gc   Grandchildren of pid1\n"
        "  -zz   Status of pid1 (Defunct / Not Defunct)\n"
        "  -zc   Defunct direct descendants of pid1\n");
}

static int read_proc_info(void)
{
    DIR *d = opendir("/proc");
    if (!d) {
        perror("opendir(/proc)");
        return -1;
    }
    struct dirent *e;
    while ((e = readdir(d)) != NULL) {
        if (!isdigit(e->d_name[0])) continue;
        int pid = atoi(e->d_name);
        if (pid <= 0 || pid >= MAX_PID) continue;

        /* open /proc/<pid>/stat */
        char stat_path[256];
        snprintf(stat_path, sizeof(stat_path), "/proc/%d/stat", pid);
        FILE *fp = fopen(stat_path, "r");
        if (!fp) continue;  /* may not exist any more */

        /* parse fields: pid (1) comm (2) state (3) ppid (4) */
        int ppid;
        char state;
        if (fscanf(fp, "%*d %*s %c %d", &state, &ppid) != 2) {
            fclose(fp);
            continue;
        }
        fclose(fp);

        ProcInfo *p = &proc[pid];
        p->pid = pid;
        p->ppid = ppid;
        p->state = state;
        p->children = NULL;
        p->child_cnt = 0;
        p->child_cap = 0;
    }
    closedir(d);
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc < 4) {
        usage();
        return EXIT_FAILURE;
    }

    int opt_index = argc - 1;                 /* last argument is option */
    char *option = argv[opt_index];

    /* first argument is root_process */
    int root_pid = atoi(argv[1]);

    /* remaining arguments (except last) are target PIDs */
    int target_cnt = opt_index - 2 + 1;   /* number of target PIDs */
    if (target_cnt < 1 || target_cnt > 5) {
        fprintf(stderr, "You must specify 1 to 5 target PIDs.\n");
        return EXIT_FAILURE;
    }
    int *targets = malloc(target_cnt * sizeof(int));
    if (!targets) { perror("malloc"); return EXIT_FAILURE; }
    for (int i = 0; i < target_cnt; i++) {
        targets[i] = atoi(argv[2 + i]);
        if (targets[i] <= 0 || targets[i] >= MAX_PID) {
            fprintf(stderr, "Invalid PID: %s\n", argv[2 + i]);
            free(targets);
            return EXIT_FAILURE;
        }
    }

    /* Build process information */
    memset(proc, 0, sizeof(proc));
    if (read_proc_info() < 0) {
        free(targets);
        return EXIT_FAILURE;
    }

    /* Build children lists */
    for (int pid = 1; pid < MAX_PID; pid++) {
        if (proc[pid].pid == pid) {
            add_child(proc[pid].ppid, pid);
        }
    }

    /* Verify that root_pid exists */
    if (proc[root_pid].pid != root_pid) {
        fprintf(stderr, "Root PID %d does not exist.\n", root_pid);
        free(targets);
