    }

    /* For each target PID, print PID & PPID if descendant of root */
    for (int i = 0; i < target_cnt; i++) {
        int t = targets[i];
        if (proc[t].pid != t) {
            fprintf(stderr, "Target PID %d does not exist.\n", t);
            continue;
        }
        if (is_descendant(t, root_pid)) {
            printf("PID: %d, PPID: %d\n", t, proc[t].ppid);
        } else {
