    }

    if (strcmp(option, "-nd") == 0) {
        print_descendants_non_direct(pid1, 0);
    } else if (strcmp(option, "-dd") == 0) {
        print_immediate_children(pid1);
    } else if (strcmp(option, "-sb") == 0) {
