    } else if (strcmp(option, "-zz") == 0) {
        print_status(pid1);
    } else if (strcmp(option, "-zc") == 0) {
        print_defunct_descendants(pid1);
    } else {
        fprintf(stderr, "Unknown option: %s\n", option);
        usage();
        free(targets);
        return EXIT_FAILURE;
    }

    /* Clean up */
    for (int pid = 1; pid < MAX_PID; pid++) {
        if (proc[pid].children)
            free(proc[pid].children);
