#include <stdio.h>
#include <time.h>

/* ----------  辅助函数 ---------- */

/* 计算是否闰年 */
int isLeapYear(int year) {
    return ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0));
}

/* 返回某年某月的天数 */
int daysInMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7:
        case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return isLeapYear(year) ? 29 : 28;
        default:
            return 30; /* 不可能出现的情况 */
    }
}

/* 通过 struct tm 正规化日期（处理闰年、跨月、跨年等） */
void normalizeDate(int *year, int *month, int *day) {
    struct tm t;
    t.tm_year = *year - 1900;     /* struct tm 的年是从 1900 开始 */
