> **Security notes**  
> - The program uses `fgets` to read the student name (to avoid buffer over‑runs).  
> - The `%Ns` format specifier in `scanf` (where *N* is the buffer size minus one) limits the number of characters read for numeric fields.  
> - All user inputs are checked; the program terminates with an error message if an unexpected value is entered.  

```c
/*********************************************************************
 *  Vietnamese: "Xây dựng cấu trúc Sinh viên gồm: Masv, Hoten,
 *               Diemtoan, Diemly, Diemhoa. Viết chương trình nhập
 *               vào danh sách gồm n sinh viên. Tính tổng điểm của
 *               mỗi sinh viên = Diemtoan + Diemly + Diemhoa.
 *               In ra thông tin sinh viên tổng điểm cao nhất và không
 *               có môn nào dưới 5."
 *
 *  Security‑friendly implementation in standard C (C99 compliant).
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define NAME_MAX 100      /* maximum number of characters in a name */

/* --------------------------------------------------------------- */
/*  Structure definition                                           */
/* --------------------------------------------------------------- */
typedef struct {
    long   Masv;                      /* student ID            */
    char   Hoten[NAME_MAX + 1];       /* student name (UTF‑8)  */
    float  Diemtoan;                  /* Mathematics score     */
    float  Diemly;                    /* Physics score         */
    float  Diemhoa;                   /* Chemistry score       */
} SinhVien;

/* --------------------------------------------------------------- */
/*  Helper functions                                               */
/* --------------------------------------------------------------- */

/* Trim the newline character that fgets may leave at the end of a string */
static void trim_newline(char *str) {
    char *pos = strchr(str, '\n');
    if (pos) *pos = '\0';
}

/* Read a positive integer from stdin with validation */
static int read_positive_int(const char *prompt, int *out) {
    char buf[32];
    int val;
    while (1) {
        printf("%s", prompt);
        if (!fgets(buf, sizeof(buf), stdin)) return 0;          /* EOF */
        if (sscanf(buf, "%d", &val) != 1 || val <= 0) {
            printf("Lỗi: nhập một số nguyên dương hợp lệ.\n");
            continue;
        }
        *out = val;
        return 1;
    }
}

/* Read a long integer (student ID) */
static int read_long(const char *prompt, long *out) {
    char buf[64];
    long val;
    while (1) {
        printf("%s", prompt);
        if (!fgets(buf, sizeof(buf), stdin)) return 0;
        if (sscanf(buf, "%ld", &val) != 1) {
            printf("Lỗi: nhập một số nguyên lớn hợp lệ.\n");
            continue;
        }
        *out = val;
        return 1;
    }
}

/* Read a floating‑point score in the range [0, 10] */
static int read_score(const char *prompt, float *out) {
    char buf[64];
    float val;
    while (1) {
        printf("%s", prompt);
        if (!fgets(buf, sizeof(buf), stdin)) return 0;
        if (sscanf(buf, "%f", &val) != 1 || val < 0.0f || val > 10.0f) {
            printf("Lỗi: nhập một điểm hợp lệ trong khoảng [0, 10].\n");
            continue;
        }
        *out = val;
        return 1;
    }
}

/* --------------------------------------------------------------- */
/*  Main program                                                   */
/* --------------------------------------------------------------- */
int main(void) {
    int n;
    if (!read_positive_int("Nhập số sinh viên (n): ", &n)) {
        fprintf(stderr, "Không thể đọc số sinh viên. Thoát.\n");
        return EXIT_FAILURE;
    }

    /* Allocate dynamic array of students */
    SinhVien *students = calloc(n, sizeof(SinhVien));
    if (!students) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    /* Input loop */
    for (int i = 0; i < n; ++i) {
        printf("\n--- Nhập thông tin sinh viên %d/%d ---\n", i + 1, n);

        if (!read_long("Mã số sinh viên (Masv): ", &students[i].Masv)) {
            fprintf(stderr, "Lỗi đọc mã số. Thoát.\n");
            free(students);
            return EXIT_FAILURE;
        }

        printf("Họ tên (Hoten): ");
        if (!fgets(students[i].Hoten, sizeof(students[i].Hoten), stdin)) {
            fprintf(stderr, "Lỗi đọc tên. Thoát.\n");
            free(students);
            return EXIT_FAILURE;
        }
        trim_newline(students[i].Hoten);

        if (!read_score("Điểm Toán (0–10): ", &students[i].Diemtoan) ||
            !read_score("Điểm Lý (0–10): ", &students[i].Diemly) ||
            !read_score("Điểm Hóa (0–10): ", &students[i].Diemhoa)) {
            fprintf(stderr, "Lỗi đọc điểm. Thoát.\n");
            free(students);
            return EXIT_FAILURE;
        }
    }

    /* Find the best student with no subject score below 5 */
    int best_idx = -1;
    float best_total = -1.0f;

    for (int i = 0; i < n; ++i) {
        if (students[i].Diemtoan < 5.0f ||
            students[i].Diemly   < 5.0f ||
            students[i].Diemhoa  < 5.0f) {
            /* Skip students who have a score below 5 */
            continue;
        }
        float total = students[i].Diemtoan + students[i].Diemly + students[i].Diemhoa;
        if (total > best_total) {
            best_total = total;
            best_idx = i;
        }
    }

    /* Output result */
    if (best_idx == -1) {
        printf("\nKhông có sinh viên nào thỏa mãn điều kiện (không có môn dưới 5).\n");
    } else {
        printf("\n=== Sinh viên có tổng điểm cao nhất (không có môn dưới 5) ===\n");
        printf("Mã số: %ld\n", students[best_idx].Masv);
        printf("Họ tên: %s\n", students[best_idx].Hoten);
        printf("Điểm Toán: %.2f\n", students[best_idx].Diemtoan);
        printf("Điểm Lý: %.2f\n", students[best_idx].Diemly);
        printf("Điểm Hóa: %.2f\n", students[best_idx].Diemhoa);
        printf("Tổng điểm: %.2f\n", best_total);
    }

    free(students);
    return EXIT_SUCCESS;
}
