/*  F(n) = 3 * (n-1)!  */
/*  Secure and well‑documented implementation.  */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

/* 64‑bit unsigned integer is enough for n ≤ 20:
   3*(19)! = 3*121645100408832000 = 364935301226496000 < 2^64-1.   */
#define MAX_N 20

/*  Helper: detect overflow of a * b for unsigned long long  */
static int mul_overflow(unsigned long long a,
                        unsigned long long b,
                        unsigned long long *result)
{
    /*  For 0 or 1 no overflow possible.  */
    if (a == 0 || b == 0) {
        *result = 0;
        return 0;
    }
    if (a > ULLONG_MAX / b) {
        return 1;          /* overflow would happen */
    }
    *result = a * b;
    return 0;
}

int main(void)
{
    char line[256];
    long long n;
    unsigned long long f = 3;   /* F(1) = 3 */
    int scanned;
    int overflow = 0;

    printf("Enter n (natural number, 1 ≤ n ≤ %d): ", MAX_N);
    if (!fgets(line, sizeof line, stdin)) {
        fprintf(stderr, "Error reading input.\n");
        return EXIT_FAILURE;
    }

    /*  sscanf must read exactly one integer and nothing else.  */
    scanned = sscanf(line, "%lld %n", &n, &overflow);
    if (scanned != 1) {
        fprintf(stderr, "Invalid input: expected a single integer.\n");
        return EXIT_FAILURE;
    }

    if (n < 1) {
        fprintf(stderr, "Invalid input: n must be at least 1.\n");
        return EXIT_FAILURE;
    }

    if (n > MAX_N) {
        fprintf(stderr, "Input too large: n > %d would overflow 64‑bit integer.\n", MAX_N);
        return EXIT_FAILURE;
    }

    /*  Compute F(n) iteratively, checking for overflow.  */
    for (long long i = 2; i <= n; ++i) {
        unsigned long long tmp;
        if (mul_overflow(f, i - 1, &tmp)) {
            fprintf(stderr, "Overflow detected during computation.\n");
            return EXIT_FAILURE;
        }
        f = tmp;
    }

    printf("F(%lld) = %llu\n", n, f);
    return EXIT_SUCCESS;
}
