## 1.  Two‑semaphore controller  
The first program is the “keyboard‑driven” controller you asked for.  
It opens **two POSIX named semaphores** (`/sem1` and `/sem2`), each with an initial
value of **1** (binary semaphore).  
The user can press

| key | action |
|-----|--------|
| `1` | `sem_wait(&sem1)` – *acquire* semaphore 1 |
| `q` | `sem_post(&sem1)` – *release* semaphore 1 |
| `2` | `sem_wait(&sem2)` – *acquire* semaphore 2 |
| `w` | `sem_post(&sem2)` – *release* semaphore 2 |
| `x` | exit the program |

Run **two instances** in two terminals.  
When the first instance acquires a semaphore the second instance will block
until it is released – that is the classic *blocking* effect.

```c
/* semaphore_controller.c */
#define _POSIX_C_SOURCE 200809L   /* for sem_open, sem_wait, etc. */
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>      /* O_* constants */
#include <semaphore.h>
#include <unistd.h>
#include <signal.h>

static sem_t *sem1 = SEM_FAILED;
static sem_t *sem2 = SEM_FAILED;
static const char *SEM1_NAME = "/sem1";
static const char *SEM2_NAME = "/sem2";

/* clean‑up on SIGINT or normal exit */
static void cleanup(void)
{
    if (sem1 != SEM_FAILED) sem_close(sem1);
    if (sem2 != SEM_FAILED) sem_close(sem2);
    /* Don't unlink – we want both instances to keep using the same semaphores
       until *both* exit.  The first instance that does sem_unlink will
       permanently delete the names. */
}

static void signal_handler(int sig)
{
    (void)sig;
    cleanup();
    exit(0);
}

int main(void)
{
    /* open or create the semaphores, initial value 1 (binary) */
    sem1 = sem_open(SEM1_NAME, O_CREAT, 0666, 1);
    if (sem1 == SEM_FAILED) { perror("sem_open /sem1"); return 1; }

    sem2 = sem_open(SEM2_NAME, O_CREAT, 0666, 1);
    if (sem2 == SEM_FAILED) { perror("sem_open /sem2"); return 1; }

    /* handle CTRL‑C nicely */
    signal(SIGINT, signal_handler);
    atexit(cleanup);

    printf("Semaphore controller started.\n");
    printf("Press 1/q to acquire/release sem1, 2/w for sem2, x to exit.\n");

    int ch;
    while ((ch = getchar()) != EOF) {
        if (ch == '1') {
            printf("[PID %d] trying to acquire sem1 … ", (int)getpid());
            fflush(stdout);
            if (sem_wait(sem1) == -1) { perror("\nsem_wait sem1"); continue; }
            printf("acquired!\n");
        } else if (ch == 'q') {
            if (sem_post(sem1) == -1) perror("sem_post sem1");
            else printf("[PID %d] released sem1\n", (int)getpid());
        } else if (ch == '2') {
            printf("[PID %d] trying to acquire sem2 … ", (int)getpid());
            fflush(stdout);
            if (sem_wait(sem2) == -1) { perror("\nsem_wait sem2"); continue; }
            printf("acquired!\n");
        } else if (ch == 'w') {
            if (sem_post(sem2) == -1) perror("sem_post sem2");
            else printf("[PID %d] released sem2\n", (int)getpid());
        } else if (ch == 'x') {
            break;
        }
    }

    cleanup();
    return 0;
}
```

