/*  swap_strings.c   */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* ------------------------------------------------------------------ */
/* 1️⃣  Classic copy‑and‑swap using a temporary buffer                */
/* ------------------------------------------------------------------ */
void swap_using_temp(char *a, char *b, size_t max_len)
{
    /* max_len = maximum length of the two strings, INCLUDING the NUL terminator */
    char *tmp = malloc(max_len);          /* allocate on the heap – no stack overflow risk   */
    if (!tmp) { perror("malloc"); exit(EXIT_FAILURE); }

    /* copy a → tmp, b → a, tmp → b */
    memcpy(tmp, a, max_len);              /* tmp gets a's original data                    */
    memcpy(a,   b, max_len);              /* a gets b's data                              */
    memcpy(b,   tmp, max_len);            /* b gets tmp (original a)                      */

    free(tmp);
}

/* ------------------------------------------------------------------ */
/* 2️⃣  Swap using the standard library helper                       */
/* ------------------------------------------------------------------ */
void swap_using_std(char *a, char *b, size_t max_len)
{
    /* The standard library offers a tiny helper that does exactly what we need. */
    /* It copies the source into the destination until it hits the NUL byte.   */
    /* Because we know the destination buffer is big enough, the copy is safe. */

    /* Copy a → tmp (on the stack – size is guaranteed) */
    char tmp[256];                      /* choose a size that covers your max length */
    if (max_len > sizeof(tmp)) {
        fprintf(stderr, "max_len exceeds tmp buffer size\n");
        exit(EXIT_FAILURE);
    }
    memcpy(tmp, a, max_len);

    memcpy(a, b, max_len);
    memcpy(b, tmp, max_len);
