    /* 2️⃣ Using a stack buffer (safe for known max size) */
    swap_using_std(S1, S2, sizeof(S1));
    printf("After swap_using_std  : S1='%s', S2='%s'\n", S1, S2);

    /* 3️⃣ Swapping pointers – only works if you really own the data */
    char *p1 = S1;
    char *p2 = S2;
    swap_pointers(&p1, &p2);
