/* ws_uv_client.c */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <uv.h>
#include <libwebsockets.h>
#include <openssl/x509.h>

#define EXAMPLE_PROTOCOL "example-protocol"

/* ------------------ 1. 连接回调 ------------------ */
static int
callback_example(struct lws *wsi,
                 enum lws_callback_reasons reason,
                 void *user, void *in, size_t len)
{
    switch (reason) {
    case LWS_CALLBACK_CLIENT_ESTABLISHED:
        lwsl_info(">>> 连接已建立\n");
        /* 发送一条文本帧 */
        {
            const char *msg = "Hello, libwebsockets + libuv!";
            unsigned char buf[LWS_PRE + 128];
            unsigned char *p = &buf[LWS_PRE];
            memcpy(p, msg, strlen(msg));
            lws_write(wsi, p, strlen(msg), LWS_WRITE_TEXT);
        }
        break;

    case LWS_CALLBACK_CLIENT_RECEIVE:
        lwsl_info(">>> 收到数据: %.*s\n", (int)len, (char *)in);
        break;

    case LWS_CALLBACK_CLIENT_CLOSED:
        lwsl_info(">>> 连接已关闭\n");
        break;

    case LWS_CALLBACK_CLIENT_CONNECTION_ERROR:
        lwsl_err(">>> 连接错误: %s\n", (char *)in);
        break;

    case LWS_CALLBACK_CLIENT_APPEND_HANDSHAKE_HEADER:
        /* 这里可以插入自定义 Header，例如鉴权 token */
        break;

    case LWS_CALLBACK_CLIENT_RECEIVE_PONG:
        lwsl_info(">>> 收到 PONG\n");
        break;

    case LWS_CALLBACK_CLIENT_WRITEABLE:
        /* 可写事件，可以继续发送 */
        break;

    default:
        break;
    }
    return 0;
}

/* ------------------ 2. 协议表 ------------------ */
static const struct lws_protocols protocols[] = {
    {
        .name = EXAMPLE_PROTOCOL,
        .callback = callback_example,
        .per_session_data_size = 0,
        .rx_buffer_size = 0,
    },
    { NULL, NULL, 0, 0 } /* terminator */
};

/* ------------------ 3. 安全相关工具 ------------------ */
static int
verify_server_certificate(const char *url)
{
    /* 这里的实现仅供演示。实际项目请使用 libwebsockets 提供的
