    return 1; /* 通过验证 */
}

/* ------------------ 4. 主体 ------------------ */
int main(int argc, char **argv)
{
    const char *url = "wss://echo.websocket.org";
    const char *host = "echo.websocket.org";
    const char *path = "/";
    int port = 443;

    /* ① libwebsockets 上下文创建 */
    struct lws_context_creation_info ctx_info;
    memset(&ctx_info, 0, sizeof ctx_info);
    ctx_info.port = CONTEXT_PORT_NO_LISTEN;          /* 只做客户端 */
    ctx_info.protocols = protocols;
    ctx_info.options = LWS_SERVER_OPTION_EXPLICIT_VHOSTS |
                       LWS_SERVER_OPTION_VALIDATE_UTF8; /* 额外安全检查 */
    ctx_info.vhost_name = host;
    ctx_info.gid = -1;
    ctx_info.uid = -1;

    /* TLS 选项：只使用 TLSv1.2/1.3，禁止自签证书 */
    ctx_info.ssl_connection = LCCSCF_USE_SSL;
    ctx_info.client_ssl_ca_cert_path = NULL;  /* 由 libwebsockets 读取系统 CA */
    ctx_info.client_ssl_ca_cert_file = NULL;

    struct lws_context *context = lws_create_context(&ctx_info);
    if (!context) {
        lwsl_err("创建 libwebsockets 上下文失败\n");
        return EXIT_FAILURE;
    }

    /* ② libuv 事件循环 */
    uv_loop_t *loop = uv_default_loop();

    /* ③ 建立 websocket 连接 */
    struct lws_client_connect_info i;
    memset(&i, 0, sizeof i);
    i.context = context;
    i.address = host;
    i.port = port;
    i.path = path;
    i.host = host;
    i.origin = host;
    i.protocol = EXAMPLE_PROTOCOL;
    i.ssl_connection = LCCSCF_USE_SSL; /* TLS */
    i.iface = NULL; /* 默认网络接口 */
    i.userdata = loop; /* 方便回调里取 loop */

    /* 需要先把 libuv 的 poll 句柄与 libwebsockets 关联 */
    struct uv_poll_t poll;
    uv_poll_init(loop, &poll, lws_get_socket_fd(lws_client_connect_via_info(&i)));

    /* ④ 在 libuv 的 idle 里驱动 libwebsockets */
    uv_idle_t idle;
    uv_idle_init(loop, &idle);
    uv_idle_start(&idle, [](uv_idle_t *handle) {
        int rc = lws_service(lws_get_context(handle->loop), 0);
        if (rc < 0) {
            lwsl_err("lws_service 出错，退出\n");
            uv_stop(handle->loop);
        }
    });

    /* ⑤ 进入事件循环 */
    lwsl_info(">>> 开始 libuv 事件循环\n");
    uv_run(loop, UV_RUN_DEFAULT);

    /* ⑥ 清理 */
    lws_context_destroy(context);
    lwsl_info(">>> 程序退出\n");
    return EXIT_SUCCESS;
}
