**24点游戏 – C 版（树算法实现，算法复杂度低）**

下面给出的代码采用 **递归树** 的思想：  
- **节点** 代表当前可用的数字列表（长度从 4 递减到 1）。  
- **分支** 代表选取两数并用 4 种运算产生的新数。  
- **终端节点**：当只剩一个数时，如果与 24 差距 < 10⁻⁶，说明可以得到 24。  

整个搜索树的大小大约是  
`4! × 4³ ≈ 5760` 次运算，完全可以在毫秒级完成。

```c
/*********************************************************************
 *  24 点游戏 – 递归树实现 (C99)
 *  输入 4 个整数（1~13），判断是否能用 +, -, *, / 和括号得到 24
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <stdbool.h>

#define EPS 1e-6
#define TARGET 24.0

/*---------------------------------------------------------------*/
/*  递归求解函数:  numbers  当前可用数字列表
 *  len      当前列表长度
 *  path     当前已使用的表达式（可选，便于调试）
 *---------------------------------------------------------------*/
bool solve(double *numbers, int len, char *path) {
    if (len == 1) {                      /* 终止条件 */
        if (fabs(numbers[0] - TARGET) < EPS)
            return true;
        else
            return false;
    }

    /* 取所有不同的 (i,j) 对，i < j */
    for (int i = 0; i < len; ++i) {
        for (int j = i + 1; j < len; ++j) {
            double a = numbers[i];
            double b = numbers[j];
            double results[4];
            int rcnt = 0;

            /* 加 */
            results[rcnt++] = a + b;
            /* 乘 */
            results[rcnt++] = a * b;
            /* 减 (a - b) */
            results[rcnt++] = a - b;
            /* 减 (b - a) */
            results[rcnt++] = b - a;
            /* 除 (a / b) */
            if (fabs(b) > EPS) results[rcnt++] = a / b;
            /* 除 (b / a) */
            if (fabs(a) > EPS) results[rcnt++] = b / a;

            /* 构造新的数字列表，长度减 1 */
            double *next = (double *)malloc((len - 1) * sizeof(double));
            int idx = 0;
            for (int k = 0; k < len; ++k) {
                if (k != i && k != j) next[idx++] = numbers[k];
            }

            /* 递归尝试每一种运算结果 */
            for (int r = 0; r < rcnt; ++r) {
                next[idx] = results[r];      /* 把新结果放到最后 */

                /* 这里可以把表达式拼接到 path，方便调试 */
                /* 例如: sprintf(tmp, "(%s) + (%s)", path_i, path_j); */

                if (solve(next, len - 1, path))
                    return true;           /* 找到合法解，立即返回 */
            }
            free(next);
        }
    }
    return false; /* 所有路径都不通 */
}

/*---------------------------------------------------------------*/
int main(void) {
    int nums[4];
    printf("请输入 4 个整数（1~13）: ");
    for (int i = 0; i < 4; ++i) {
        if (scanf("%d", &nums[i]) != 1) {
            fprintf(stderr, "输入错误！\n");
            return EXIT_FAILURE;
        }
        if (nums[i] < 1 || nums[i] > 13) {
