/* ------------------------------------------------------------------------- */
/* Helper: Read a line and convert it to a long. Return 0 on success,
 * -1 on EOF, -2 on error (invalid number).                           */
/* ------------------------------------------------------------------------- */
static int read_long(long *out)
{
    char buf[1024];          /* big enough for any 64‑bit integer + newline */
    char *endptr;

    if (fgets(buf, sizeof buf, stdin) == NULL) {
        /* EOF or read error */
        return feof(stdin) ? -1 : -2;
    }

    errno = 0;                     /* reset errno before strtol */
    *out = strtol(buf, &endptr, 10);

    /* Check for conversion errors */
    if (errno == ERANGE || *out < INT_MIN || *out > INT_MAX) {
        /* out of range for int */
        return -2;
    }

    /* Skip leading whitespace */
    while (*endptr && (*endptr == ' ' || *endptr == '\t')) endptr++;

    /* If there's anything other than a newline or string terminator, reject */
    if (*endptr != '\n' && *endptr != '\0') {
        return -2;
    }

    return 0;
}

/* ------------------------------------------------------------------------- */
/* Dynamic integer array implementation                                   */
/* ------------------------------------------------------------------------- */
typedef struct {
    int  *data;          /* pointer to the array */
    size_t size;         /* number of elements stored */
    size_t capacity;     /* allocated capacity */
} IntArray;

static IntArray *array_create(void)
{
    IntArray *a = malloc(sizeof(*a));
    if (!a) return NULL;
    a->data     = NULL;
    a->size     = 0;
    a->capacity = 0;
    return a;
}

static int array_push(IntArray *a, int val)
{
    if (a->size == a->capacity) {
        size_t new_cap = a->capacity ? a->capacity * 2 : 16;
        int *tmp = realloc(a->data, new_cap * sizeof(int));
        if (!tmp) return -1;           /* allocation failure */
        a->data = tmp;
        a->capacity = new_cap;
    }
    a->data[a->size++] = val;
    return 0;
}

static void array_destroy(IntArray *a)
{
    if (!a) return;
    free(a->data);
    free(a);
}

/* ------------------------------------------------------------------------- */
/* Compare function for qsort, used to sort ints                           */
/* ------------------------------------------------------------------------- */
static int cmp_int(const void *p1, const void *p2)
{
    int a = *(const int *)p1;
    int b = *(const int *)p2;
    return (a > b) - (a < b);   /* portable comparison */
}

/* ------------------------------------------------------------------------- */
/* Main logic                                                              */
/* ------------------------------------------------------------------------- */
int main(void)
{
    IntArray *numbers = array_create();
    if (!numbers) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    printf("Enter integers (one per line). Press Ctrl+D (EOF) to finish.\n");

    /* Read until EOF */
    while (1) {
        long val;
        int rc = read_long(&val);
        if (rc == -1) break;           /* EOF */
        if (rc == -2) {
            fprintf(stderr, "Invalid input. Skipping line.\n");
            continue;
        }

        /* Optional sentinel: stop on -1 (but allow -1 as data) */
        /* if (val == -1) break; */

        if (array_push(numbers, (int)val) == -1) {
            fprintf(stderr, "Memory allocation failed.\n");
            array_destroy(numbers);
            return EXIT_FAILURE;
        }
    }

    if (numbers->size == 0) {
        printf("No numbers entered.\n");
        array_destroy(numbers);
        return EXIT_SUCCESS;
    }

    /* Sort the array to bring equal values together */
    qsort(numbers->data, numbers->size, sizeof(int), cmp_int);

    /* Scan for repetitions */
    printf("\nRepeated numbers:\n");
    size_t i = 0;
