* If the input contains no integers the program prints `NULL` and exits.  
* The list is reversed *node‑by‑node* (the nodes themselves are moved, not only
  the values they store).  
  For this we temporarily store all node pointers in a dynamic array,
  swap the pointers and rebuild the list from that array.  
* Finally the list is printed on one line, numbers separated by a single
  space.

The program uses only safe I/O (`fgets`), checks the return value of
`malloc`/`realloc`, and validates every token with `strtol`.  
No buffer over‑flows or unchecked casts occur – it is a small example of
secure coding in C.

```c
/*
 *  Secure singly linked list manipulation
 *  Author: Security Researcher
 *  Date: 2026‑01‑31
 *
 *  Compile:   gcc -std=c11 -Wall -Wextra -O2 -o swap_list swap_list.c
 *  Run:       ./swap_list < input.txt
 *
 *  The program reads integers terminated by a dot (.).
 *  It builds a singly linked list, swaps the nodes pairwise
 *  (first<->last, second<->second‑last, …) and prints the result.
 *  If no numbers are read, it prints "NULL".
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <ctype.h>

#define INITIAL_ARRAY_CAP 8
#define MAX_LINE_LEN 1024

/* Node of a singly linked list */
typedef struct Node {
    int data;
    struct Node *next;
} Node;

/* Append a node to the end of the list */
static void append_node(Node **head, Node **tail, int value) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = value;
    new_node->next = NULL;
    if (*tail) {
        (*tail)->next = new_node;
    } else {                 /* first element */
        *head = new_node;
    }
    *tail = new_node;
}

/* Free the entire list */
static void free_list(Node *head) {
    while (head) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }
}

/* Print the list (numbers separated by spaces) */
static void print_list(Node *head) {
    if (!head) {
        puts("NULL");
        return;
    }
    for (Node *p = head; p; p = p->next) {
        printf("%d", p->data);
        if (p->next) putchar(' ');
    }
    putchar('\n');
}

/* Main logic */
int main(void) {
    char buffer[MAX_LINE_LEN];
    Node *head = NULL, *tail = NULL;
    size_t array_cap = INITIAL_ARRAY_CAP;
    size_t array_len = 0;
    Node **nodes = malloc(array_cap * sizeof(Node *));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    /* Read input line(s) until a dot is encountered */
    while (fgets(buffer, sizeof(buffer), stdin)) {
        char *p = buffer;
        while (*p) {
            /* Skip leading spaces */
            while (isspace((unsigned char)*p)) p++;

            if (*p == '.') {          /* end of sequence */
                goto input_done;
            }
            if (*p == '\0') break;    /* end of line */

            /* Try to parse an integer */
            char *endptr;
            errno = 0;
            long val = strtol(p, &endptr, 10);

            if (p == endptr) {
                /* No integer found – skip this token */
                /* Move to next space or dot */
                while (*p && !isspace((unsigned char)*p) && *p != '.') p++;
                continue;
            }
            if (errno == ERANGE || val < INT_MIN || val > INT_MAX) {
                /* Value out of int range – skip it */
                p = endptr;
                continue;
            }

            /* Valid integer, insert into list */
            append_node(&head, &tail, (int)val);

            /* Store node pointer for later swapping */
            if (array_len == array_cap) {
                array_cap *= 2;
                Node **tmp = realloc(nodes, array_cap * sizeof(Node *));
                if (!tmp) {
                    fprintf(stderr, "Memory allocation failed\n");
                    free_list(head);
                    free(nodes);
                    return EXIT_FAILURE;
                }
                nodes = tmp;
            }
            nodes[array_len++] = tail;

            /* Advance pointer to the next token */
            p = endptr;
        }
    }

input_done:
    /* If no integers were read */
    if (head == NULL) {
        puts("NULL");
        free(nodes);
        return EXIT_SUCCESS;
    }

    /* Swap nodes pairwise */
    size_t i = 0, j = array_len - 1;
    while (i < j) {
        Node *tmp = nodes[i];
        nodes[i] = nodes[j];
        nodes[j] = tmp;
        i++;
        j--;
    }

    /* Rebuild the linked list from the reordered array */
    head = nodes[0];
    for (size_t k = 1; k < array_len; k++) {
        nodes[k - 1]->next = nodes[k];
    }
    nodes[array_len - 1]->next = NULL;

    /* Output */
    print_list(head);

    /* Clean‑up */
    free_list(head);
    free(nodes);
    return EXIT_SUCCESS;
}
```

**Explanation of security‑related precautions**

