    /* Enable broadcast option */
    int opt = 1;
    if (setsockopt(sockfd, SOL_SOCKET, SO_BROADCAST, &opt, sizeof(opt)) < 0) {
        perror("setsockopt SO_BROADCAST");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* Prepare destination address */
    memset(&dst, 0, sizeof(dst));
    dst.sin_family = AF_INET;
    dst.sin_port   = htons(LISTEN_PORT);
    if (inet_aton(BROADCAST_IP, &dst.sin_addr) == 0) {
        fprintf(stderr, "Invalid broadcast address\n");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* Send loop */
    while (1) {
        sent = sendto(sockfd, msg, strlen(msg), 0,
                      (struct sockaddr *)&dst, sizeof(dst));
        if (sent < 0) {
            perror("sendto");
        } else {
            printf("[Sender] Sent %zd bytes to %s:%d\n", sent, BROADCAST_IP, LISTEN_PORT);
        }
        sleep(1);
    }

    /* unreachable */
    close(sockfd);
    return 0;
}

static void receiver_process(const char *msg)
{
    int sockfd;
    struct sockaddr_in local, from;
    socklen_t fromlen;
    ssize_t recvd;
    char buf[BUF_SIZE];
    struct sender_entry table[MAX_TABLE];
    int table_count = 0;

    /* Create a UDP socket */
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket (receiver)");
        exit(EXIT_FAILURE);
    }

    /* Allow multiple bindings to the same port (in case of multiple runs) */
    int opt = 1;
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt SO_REUSEADDR");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* Bind to all local interfaces on LISTEN_PORT */
    memset(&local, 0, sizeof(local));
    local.sin_family = AF_INET;
    local.sin_addr.s_addr = htonl(INADDR_ANY);
    local.sin_port = htons(LISTEN_PORT);

    if (bind(sockfd, (struct sockaddr *)&local, sizeof(local)) < 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("[Receiver] Listening on port %d\n", LISTEN_PORT);

    /* Timing for periodic printing */
    time_t last_print = time(NULL);

    /* Main loop using select() so we can periodically print */
    fd_set rfds;
    struct timeval tv;
    int retval;

    while (1) {
        FD_ZERO(&rfds);
        FD_SET(sockfd, &rfds);

        /* Wait maximum 1 second to allow periodic printing */
        tv.tv_sec  = 1;
        tv.tv_usec = 0;

        retval = select(sockfd + 1, &rfds, NULL, NULL, &tv);
        if (retval < 0) {
            if (errno == EINTR) continue;   /* interrupted by signal */
            perror("select");
            break;
        } else if (retval == 0) {
            /* timeout – just fall through to printing check */
        } else {
            /* Data available */
            if (FD_ISSET(sockfd, &rfds)) {
                fromlen = sizeof(from);
                recvd = recvfrom(sockfd, buf, sizeof(buf) - 1, 0,
                                 (struct sockaddr *)&from, &fromlen);
                if (recvd < 0) {
                    perror("recvfrom");
                    continue;
                }
                buf[recvd] = '\0';   /* Null‑terminate for comparison */

                printf("[Receiver] Received %zd bytes from %s:%d: \"%s\"\n",
                       recvd,
                       inet_ntoa(from.sin_addr),
                       ntohs(from.sin_port),
                       buf);

                /* Check if the string matches the one passed on the command line */
                if (strcmp(buf, msg) == 0) {
                    /* Record sender if we have space */
                    if (table_count < MAX_TABLE) {
                        inet_ntop(AF_INET, &(from.sin_addr), table[table_count].ip,
                                  sizeof(table[table_count].ip));
                        table[table_count].port = ntohs(from.sin_port);
                        table_count++;
                        printf("[Receiver] Recorded sender %s:%d (total %d)\n",
                               table[table_count-1].ip,
                               table[table_count-1].port,
                               table_count);
                    } else {
                        printf("[Receiver] Table full – cannot record more senders\n");
                    }
                }
            }
        }

        /* Periodic printing every 30 seconds */
        time_t now = time(NULL);
        if (now - last_print >= 30) {
            printf("\n--- Sender Table (last 30s) ---\n");
            if (table_count == 0) {
                printf("No senders recorded yet.\n");
            } else {
                for (int i = 0; i < table_count; ++i) {
                    printf("%2d: %s:%u\n", i + 1, table[i].ip, table[i].port);
                }
            }
            printf("------------------------------\n\n");
            last_print = now;
        }
    }

    close(sockfd);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <string-to-broadcast>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *message = argv[1];

    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        /* Child 1 – sender */
        sender_process(message);
    } else {
        /* Child 2 – receiver */
        receiver_process(message);
    }

    /* Should never reach here */
    return 0;
}
```

---------------------------------------------------------------------

## How it works

### 1. `main()`

* Expects exactly one command‑line argument – the string that will be broadcast and that the receiver will match.
* Calls `fork()` to create two processes.
* Child 1 executes `sender_process()`, child 2 executes `receiver_process()`.

### 2. `sender_process()`

* Creates a UDP socket (`socket()`).
* Enables the `SO_BROADCAST` option so that the socket may send to `255.255.255.255`.
* Sets up the destination address (`struct sockaddr_in`) to the broadcast address on port 2346.
* Enters an infinite loop: every second it calls `sendto()` with the provided message.

### 3. `receiver_process()`

* Creates a UDP socket and binds it to `INADDR_ANY:2346`.  
  `SO_REUSEADDR` is set in case the program is restarted quickly.
* Maintains a local table (array of `sender_entry` structs) with a maximum capacity of `MAX_TABLE` entries.
* Uses a `select()` loop with a 1‑second timeout:
  * When data is available, `recvfrom()` reads the packet, prints its content and source.
  * If the packet’s payload matches the original message, the sender’s IP and port are stored in the table (if space permits).
* Every 30 seconds (checked by a `time_t` counter) the table is printed to stdout.

### 4. Timing & Periodic Printing

The receiver does **not** block indefinitely on `recvfrom()`; instead `select()` waits for either:

* incoming data (which triggers `recvfrom()`) **or**
* a timeout (1 s) that allows the program to check whether 30 s have elapsed and, if so, to print the table.

This approach keeps the program responsive while still meeting the “every 30 s” requirement.

---------------------------------------------------------------------

## Compile & Run

```bash
# compile
gcc -Wall -Wextra -std=c99 -O2 -o udp_broadcast_listener udp_broadcast_listener.c

# run
./udp_broadcast_listener "my secret string"
```

*The program will now fork into two processes.  
The sender will broadcast “my secret string” once per second.  
The receiver will print any matching senders every 30 s.*

---------------------------------------------------------------------

## Security / Research Notes

* **UDP broadcast**: On many systems broadcasting to `255.255.255.255` is disabled by default for security.  
  You might need to enable the `net.ipv4.ip_nonlocal_bind` sysctl or run the program as root.

* **IP spoofing**: A malicious user could send packets with forged source addresses that match the string, causing the receiver to log false senders.  This is a common property of UDP broadcast; filtering or authentication would be required for a secure implementation.

* **Scalability**: The table is limited to `MAX_TABLE` entries.  In a real environment you would probably want dynamic allocation, deduplication, aging of old entries, or a database.

* **Signal handling**: The program does not trap signals (e.g., SIGINT).  Adding cleanup (close sockets, remove any temporary files, etc.) is advised for production use.

---------------------------------------------------------------------

Enjoy experimenting with it – and feel free to adapt it to your specific research needs!

