### 1.  Code (Windows, C99)

```c
/*
 * resistor_lookup.c
 *
 * A minimal Windows console program that, given a target resistance in ohms,
 * prints the closest standard resistor or a 2‑resistor combination.
 *
 * Compile (MSVC):
 *     cl /W4 /O2 resistor_lookup.c
 *
 * Compile (MinGW):
 *     gcc -std=c99 -Wall -O2 resistor_lookup.c -o resistor_lookup.exe
 *
 * Usage:
 *     resistor_lookup.exe
 *     > 10.2
 *     2*5.1Ω
 *
 * Security notes: safe I/O, no buffer overrun, checked conversions.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE    64       /* Max input line length */
#define TOLERANCE   0.05     /* 5% tolerance for two‑resistor combos */

/* ----------  Standard E‑12 series (per decade) ------------- */
static const double E12_VALUES[] = {
    1.0, 1.2, 1.5, 1.8, 2.2,
    2.7, 3.3, 3.9, 4.7, 5.6,
    6.8, 8.2
};
static const size_t E12_COUNT = sizeof(E12_VALUES) / sizeof(E12_VALUES[0]);

/* Helper: trim trailing newline and spaces */
static void trim_newline(char *s)
{
    char *p = strchr(s, '\n');
    if (p) *p = '\0';
    /* also strip trailing carriage return (Windows) */
    p = strchr(s, '\r');
    if (p) *p = '\0';
}

/* Build a single resistor string: "5.1Ω" */
static void format_single_resistor(char *buf, size_t sz, double value)
{
    snprintf(buf, sz, "%.1fΩ", value);
}

/* Build a double‑resistor string: "2*5.1Ω" or "5.6+4.7Ω" */
static void format_double_resistor(char *buf, size_t sz,
                                   double v1, double v2)
{
    if (fabs(v1 - v2) < 1e-6)
        snprintf(buf, sz, "%.1f*%.1fΩ", round(v1*10)/10.0, round(v2*10)/10.0);
    else
        snprintf(buf, sz, "%.1f+%.1fΩ", v1, v2);
}

/* Generate a list of all standard resistors up to a maximum */
static double *generate_series(double max, size_t *out_count)
{
    /* Rough upper bound: 10^10 is far beyond any typical target */
    double *list = malloc(sizeof(double) * 2000);
    if (!list) return NULL;

    size_t idx = 0;
    for (int exp = -12; exp <= 12; ++exp) {
        double mult = pow(10.0, exp);
        for (size_t i = 0; i < E12_COUNT; ++i) {
            double val = E12_VALUES[i] * mult;
            if (val > max) continue;
            list[idx++] = val;
        }
    }
    *out_count = idx;
    return list;
}

/* Find the best single resistor (closest to target) */
static double best_single(double target, const double *list, size_t count)
{
    double best = list[0];
    double best_diff = fabs(target - best);
    for (size_t i = 1; i < count; ++i) {
        double diff = fabs(target - list[i]);
        if (diff < best_diff) {
            best_diff = diff;
            best = list[i];
        }
    }
    return best;
}

/* Try all 2‑resistor combinations that sum within tolerance */
static int try_double(double target, const double *list, size_t count,
                      double *out_v1, double *out_v2)
{
    for (size_t i = 0; i < count; ++i) {
        for (size_t j = i; j < count; ++j) {
            double sum = list[i] + list[j];
            if (fabs(sum - target) <= TOLERANCE * target) {
                *out_v1 = list[i];
                *out_v2 = list[j];
                return 1;   /* success */
            }
        }
    }
    return 0;           /* no pair found */
}

int main(void)
{
    char line[MAX_LINE];

    printf("Enter target resistance (ohms): ");
    if (!fgets(line, sizeof(line), stdin)) {
        fprintf(stderr, "Error: failed to read input.\n");
        return EXIT_FAILURE;
    }
    trim_newline(line);

    /* Convert string to double */
    char *endptr;
    double target = strtod(line, &endptr);
    if (endptr == line || *endptr != '\0' || target <= 0.0) {
        fprintf(stderr, "Error: invalid resistance value.\n");
        return EXIT_FAILURE;
    }

    /* Generate a list of resistors up to, say, 10× target */
    size_t series_count;
    double *series = generate_series(target * 10.0, &series_count);
    if (!series) {
        fprintf(stderr, "Error: memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    /* First, look for a single resistor within 5% */
    double best = best_single(target, series, series_count);
    if (fabs(best - target) <= TOLERANCE * target) {
        char out[32];
        format_single_resistor(out, sizeof(out), best);
        printf("%s\n", out);
        free(series);
        return EXIT_SUCCESS;
    }

    /* Else try a 2‑resistor combo */
    double v1, v2;
    if (try_double(target, series, series_count, &v1, &v2)) {
        char out[64];
        format_double_resistor(out, sizeof(out), v1, v2);
        printf("%s\n", out);
    } else {
        /* Fallback: just print the closest single resistor */
        char out[32];
        format_single_resistor(out, sizeof(out), best);
        printf("%s\n", out);
        fprintf(stderr, "Warning: exact match not found.\n");
    }

    free(series);
    return EXIT_SUCCESS;
}
```

### 2.  How it works (brief walkthrough)

1. **Input** – `fgets()` reads a line safely.  
2. **Conversion** – `strtod()` parses the string, and we check that the entire string was consumed.  
3. **Resistor list** – `generate_series()` builds all E‑12 resistors up to a chosen upper bound (`target*10`).  
4. **Single match** – `best_single()` picks the closest resistor. If it is within the 5 % tolerance, we print it.  
5. **Two‑resistor search** – `try_double()` brute‑forces all pairs (O(n²), but `n` is tiny – a few hundred).  
6. **Output** – The result is formatted with `snprintf()` to avoid overflow.

### 3.  Security‑specific notes

| Issue | Why it matters | How we handled it |
|-------|----------------|-------------------|
| **Buffer overflow** | Unchecked `strcpy`/`sprintf` could corrupt the stack. | Use `snprintf()`; size‑checked `fgets()`; no unbounded concatenation. |
| **Format string attacks** | `printf("%s")` with user‑supplied format string. | Use constant format strings. |
| **Memory leaks** | Unfreed allocations could lead to exhaustion. | All `malloc` allocations are paired with `free`. |
| **Unexpected termination** | `strtod` can produce NaN/INF silently. | Validate output (`>0`). |
| **Denial of Service** | An attacker could send a huge list; our program limits the series size. | Upper bound of `target*10`. |

