```c
/*
 *  Binary search over a sorted array of student records.
 *
 *  Security notes
 *  ----------------
 *  1.  All I/O is checked for errors.
 *  2.  fscanf is used with a width modifier to guard against
 *      overflow of the 10‑character name field.
 *  3.  The array index is always checked against the size of the
 *      array (10) before it is used.
 *  4.  The loop that reads the file uses the return value of fscanf,
 *      not feof(), which is the correct idiom.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STUDENTS 10
#define MAX_NAME_LEN 9   /* 9 chars + terminating null */

struct studinfo
{
    int    stnr;          /* student number (key) */
    char   name[MAX_NAME_LEN + 1];
    int    grade;
};

/* --------------------------------------------------------------- */
/*  Binary search: returns the index of the record with the given
 *  student number or -1 if it does not exist.                       */
static int binary_search(const struct studinfo *s, int n, int target)
{
    int low  = 0;
    int high = n - 1;

    while (low <= high)
    {
        int mid = low + (high - low) / 2;

        if (s[mid].stnr == target) return mid;

        if (s[mid].stnr < target)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return -1;      /* not found */
}

/* --------------------------------------------------------------- */
int main(void)
{
    struct studinfo students[MAX_STUDENTS];
    int          count = 0;
    FILE        *fp;

    /* ----- 1. Open the file ------------------------------------------------ */
    fp = fopen("C:\\cmpe231\\2009Spring\\student.txt", "r");
    if (!fp)
    {
        perror("Error opening student file");
        return EXIT_FAILURE;
    }

    /* ----- 2. Read the file (safe, checked) ------------------------------ */
    while (count < MAX_STUDENTS)
    {
        int rc = fscanf(fp, "%d %9s %d",
                        &students[count].stnr,
                        students[count].name,
                        &students[count].grade);

        if (rc == 3)          /* all three items read successfully */
            ++count;
        else if (rc == EOF)   /* normal end of file */
            break;
        else                  /* malformed line or I/O error */
        {
            fprintf(stderr, "Malformed entry on line %d\n", count + 1);
            fclose(fp);
            return EXIT_FAILURE;
        }
    }
    fclose(fp);

    if (count == 0)
    {
        fprintf(stderr, "No student records found.\n");
        return EXIT_FAILURE;
    }

    /* ----- 3. Ask the user for a student number ------------------------- */
    int target;
    printf("Enter a student number to search: ");
    if (scanf("%d", &target) != 1)
    {
        fprintf(stderr, "Invalid input.\n");
        return EXIT_FAILURE;
    }

    /* ----- 4. Binary search ---------------------------------------------- */
    int idx = binary_search(students, count, target);

    /* ----- 5. Output ------------------------------------------------------ */
    if (idx >= 0)
    {
        printf("\nStudent found at array index %d:\n", idx);
        printf("  Name : %s\n", students[idx].name);
        printf("  Grade: %d\n", students[idx].grade);
    }
    else
    {
        printf("\nStudent number %d not found.\n", target);
    }

    return EXIT_SUCCESS;
}
```

### How it works

1. **File Reading**  
   * `fscanf` is called with a width modifier (`%9s`) so that a name longer than 9 characters does not overflow the 10‑byte buffer.  
   * The loop terminates either when the file ends (`EOF`) or when 10 records are read.

2. **Binary Search**  
   * The helper function `binary_search` performs a classic binary search on the sorted array `students`.  
   * It returns the index of the matching record or `-1` if the key is not present.

3. **User Interaction & Output**  
   * The program prompts the user for a student number, then prints the name, grade and array index if the record is found.

### Security‑related best practices used

| Issue | Mitigation |
|-------|------------|
| **Buffer over‑run** | Field width in `fscanf` (`%9s`) + null terminator. |
| **Unchecked file open** | `fopen` return value checked; `perror` for diagnostic. |
| **Unchecked fscanf** | Return value inspected; malformed lines are reported. |
| **Array index safety** | Loop limits and bounds checks in `binary_search`. |
| **Return codes** | `EXIT_FAILURE` used for error paths, `EXIT_SUCCESS` otherwise. |

Feel free to replace the hard‑coded file path or to adjust the buffer sizes as required by your environment.

