import com.alibaba.nacos.api.NacosFactory;
import com.alibaba.nacos.api.config.ConfigService;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;

import java.util.Map;
import java.util.Properties;

public class NacosYamlDemo {

    private static final String DATA_ID = "crawler-config.yaml";
    private static final String GROUP   = "DEFAULT_GROUP";

    public static void main(String[] args) throws Exception {
        Properties props = new Properties();
        props.put("serverAddr", "127.0.0.1:8848");   // Nacos 服务器地址
        props.put("namespace", "public");           // 如果你使用命名空间
        props.put("auth.username", "nacos");        // 若开启鉴权
        props.put("auth.password", "nacos123");

        ConfigService configService = NacosFactory.createConfigService(props);

        // 1. 读取配置
        String yamlString = configService.getConfig(DATA_ID, GROUP, 5000);
        if (yamlString == null) {
            throw new RuntimeException("配置为空！请先在 Nacos 上创建 " + DATA_ID);
        }

        // 2. 解析 YAML
        Yaml yaml = new Yaml(new SafeConstructor()); // SafeConstructor 避免潜在的代码执行
        Map<String, Object> data = yaml.load(yamlString);
        if (data == null) {
            data = new HashMap<>();
        }

        // 3. 做你想做的改动
        // 例如：把 `crawler.threadPool.size` 改成 8
        // 如果层级多，可以先把 Map 递归拿出来
        Map<String, Object> crawlerMap = (Map<String, Object>) data.get("crawler");
        if (crawlerMap == null) {
            crawlerMap = new HashMap<>();
            data.put("crawler", crawlerMap);
        }
        crawlerMap.put("threadPool.size", 8);

        // 4. 重新序列化成字符串
        String newYamlString = yaml.dump(data);

        // 5. 发布新配置
        boolean published = configService.publishConfig(DATA_ID, GROUP, newYamlString);
        System.out.println("发布是否成功：" + published);
    }
}
```

