### 2.6 Service 层

```java
@Service
@RequiredArgsConstructor
public class AuthService {

    private final UserRepository userRepo;
    private final RoleRepository roleRepo;
    private final CompanyRepository companyRepo;
    private final PasswordEncoder passwordEncoder;
    private final JwtUtil jwtUtil;

    public String register(RegisterRequest req) {
        if (userRepo.findByUsername(req.getUsername()).isPresent())
            throw new RuntimeException("Username already taken");

        User user = new User();
        user.setUsername(req.getUsername());
        user.setPassword(passwordEncoder.encode(req.getPassword()));

        Role role = roleRepo.findByName(req.getRole())
                .orElseThrow(() -> new RuntimeException("Role not found"));
        user.getRoles().add(role);

        if (req.getRole() == RoleEnum.COMPANY) {
            Company c = companyRepo.findById(req.getCompanyId())
                    .orElseThrow(() -> new RuntimeException("Company not found"));
            user.setCompany(c);
        }

        userRepo.save(user);
        return jwtUtil.generateToken(user);
    }

    public String login(LoginRequest req) {
        User user = userRepo.findByUsername(req.getUsername())
                .orElseThrow(() -> new RuntimeException("Invalid credentials"));
        if (!passwordEncoder.matches(req.getPassword(), user.getPassword()))
            throw new RuntimeException("Invalid credentials");
        return jwtUtil.generateToken(user);
    }
}
```

### 2.7 JWT 工具类

```java
@Component
@RequiredArgsConstructor
public class JwtUtil {

    @Value("${spring.security.jwt.secret}")
    private String secret;

    @Value("${spring.security.jwt.expiration-ms}")
    private long expirationMs;

    public String generateToken(User user) {
        Date now = new Date();
        Date exp = new Date(now.getTime() + expirationMs);

        List<String> roles = user.getRoles()
                .stream().map(r -> r.getName().name()).collect(Collectors.toList());

        return Jwts.builder()
                .setSubject(user.getUsername())
                .claim("roles", roles)
                .setIssuedAt(now)
                .setExpiration(exp)
                .signWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)))
                .compact();
    }

    public Claims parseToken(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)))
                .build()
                .parseClaimsJws(token)
                .getBody();
    }
}
```

### 2.8 Security 配置

```java
@Configuration
@EnableWebSecurity
@RequiredArgsConstructor
public class SecurityConfig {

    private final JwtUtil jwtUtil;
    private final UserRepository userRepository;

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            // 1. 禁用 CSRF（SPA 使用 JWT + HttpOnly cookie）
            .csrf(csrf -> csrf.disable())
            .sessionManagement(session -> 
                session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .cors(Customizer.withDefaults())
            .authorizeHttpRequests(auth -> auth
                // 公开接口
                .requestMatchers("/api/auth/**").permitAll()
                // 其余需鉴权
                .anyRequest().authenticated()
            )
            // 2. JWT 过滤器
            .addFilterBefore(new JwtAuthFilter(jwtUtil, userRepository), 
                             UsernamePasswordAuthenticationFilter.class);

        // 3. 保护 XSS / CSP (可在前端设置)
        http.headers(headers -> headers
                .contentSecurityPolicy("script-src 'self'")
                .xssProtection(Customizer.withDefaults()));

        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
