### 5.1 服务器端

```java
import javax.net.ssl.*;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;

public class SecureChatServer {

    // 配置
    private static final int PORT = 8443;
    private static final String KEYSTORE = "serverkeystore.jks";
    private static final String KEYSTORE_PASS = "changeit";
    private static final int MAX_CLIENTS = 10;

    // 线程池
    private final ExecutorService pool = Executors.newFixedThreadPool(MAX_CLIENTS);

    // 记录文件（加密后）
    private final Path logDir = Paths.get("chat_logs");

    public static void main(String[] args) throws Exception {
        new SecureChatServer().start();
    }

    private void start() throws Exception {
        // 1. 初始化 TLS
        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream(KEYSTORE), KEYSTORE_PASS.toCharArray());
        kmf.init(ks, KEYSTORE_PASS.toCharArray());
        ctx.init(kmf.getKeyManagers(), null, new SecureRandom());

        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        try (SSLServerSocket ss = (SSLServerSocket) ssf.createServerSocket(PORT)) {
            System.out.println("SecureChatServer listening on port " + PORT);

            // 2. 接受连接
            while (true) {
                SSLSocket client = (SSLSocket) ss.accept();
                pool.execute(new ClientHandler(client));
            }
        }
    }

    /** 简单 token 鉴权：client 先发 token，服务器校验 */
    private boolean authenticate(BufferedReader in) throws IOException {
        String token = in.readLine();
        return "TOKEN1234".equals(token); // 在真实系统中使用更复杂的 token + DB
    }

    private class ClientHandler implements Runnable {
        private final SSLSocket socket;
        ClientHandler(SSLSocket s) { this.socket = s; }

        public void run() {
            try (socket;
                 BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                 BufferedWriter out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()))) {

                // 1. 鉴权
                if (!authenticate(in)) {
                    out.write("AUTH_FAIL\n");
                    out.flush();
                    return;
                }
                out.write("AUTH_OK\n");
                out.flush();

                // 2. 处理消息循环
                String line;
                while ((line = in.readLine()) != null) {
                    // 简单协议：TYPE|PAYLOAD
                    String[] parts = line.split("\\|", 2);
                    if (parts.length != 2) continue;
                    String type = parts[0], payload = parts[1];

                    if ("MSG".equals(type)) {          // 普通文字
                        System.out.println("Client says: " + payload);
                        writeLog("MSG", payload);
                    } else if ("IMG".equals(type)) {    // 图片（base64）
                        byte[] data = Base64.getDecoder().decode(payload);
                        Path imgPath = logDir.resolve("client_" + System.currentTimeMillis() + ".png");
                        Files.write(imgPath, data);
                        System.out.println("Received image, saved to " + imgPath);
                        writeLog("IMG", imgPath.toString());
                    } else {
                        // 其它类型可自行扩展
                    }
                }

            } catch (IOException e) {
                e.printStackTrace(); // 生产环境请使用日志框架
            }
        }
    }

    /** 记录日志（AES + HMAC） */
    private void writeLog(String type, String content) throws IOException {
        // 1. 生成日志条目
        String entry = String.format("%s|%s|%s%n", 
            java.time.Instant.now().toString(), type, content);

        // 2. 写入文件（简化：不做加密，实际可加密）
        Files.write(logDir.resolve("chat.log"), entry.getBytes(), 
            StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }
}
```

> **说明**  
> 1. **TLS** 通过 `SSLServerSocketFactory` 实现，默认使用系统 keystore。  
> 2. 这里的鉴权仅是示例，实际要实现 **OAuth2 / JWT / Kerberos** 或者 **双向证书**。  
> 3. 日志写入部分省略了 AES‑256 加密，实际请使用 Java Cryptography Architecture (JCA) 进行加密。  

### 5.2 客户端（Swing + SSLSocket）

```java
import javax.net.ssl.*;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.nio.file.*;
import java.util.Base64;

public class SecureChatClient extends JFrame {

    private JTextArea chatArea;
    private JTextField inputField;
    private JButton sendBtn, imgBtn;
    private SSLSocket socket;
    private BufferedReader in;
    private BufferedWriter out;

    public SecureChatClient() {
        setTitle("SecureChat Client");
        setSize(500, 400);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();
        connect();  // 连接服务器
    }

    private void initUI() {
        chatArea = new JTextArea();
        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        JPanel panel = new JPanel(new BorderLayout());
        inputField = new JTextField();
        sendBtn = new JButton("Send");
        imgBtn = new JButton("Send Image");

        panel.add(inputField, BorderLayout.CENTER);
        panel.add(sendBtn, BorderLayout.EAST);
        panel.add(imgBtn, BorderLayout.WEST);
        add(panel, BorderLayout.SOUTH);

        sendBtn.addActionListener(e -> sendText());
        imgBtn.addActionListener(e -> sendImage());
    }

    private void connect() {
        try {
            SSLContext ctx = SSLContext.getInstance("TLSv1.3");
            ctx.init(null, new TrustManager[] { new X509TrustManager() {
                public java.security.cert.X509Certificate[] getAcceptedIssuers() {return null;}
                public void checkClientTrusted(java.security.cert.X509Certificate[] certs, String authType){}
                public void checkServerTrusted(java.security.cert.X509Certificate[] certs, String authType){}
            } }, new java.security.SecureRandom());

            SSLSocketFactory sf = ctx.getSocketFactory();
            socket = (SSLSocket) sf.createSocket("localhost", 8443);

            in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));

            // 发送 token
            out.write("TOKEN1234\n");
            out.flush();

            String resp = in.readLine();
            if (!"AUTH_OK".equals(resp)) {
                JOptionPane.showMessageDialog(this, "Authentication failed");
                return;
            }

            // 监听服务器消息
            new Thread(() -> {
                try {
                    String line;
                    while ((line = in.readLine()) != null) {
                        chatArea.append("Server: " + line + "\n");
                    }
                } catch (IOException ex) {
                    ex.printStackTrace();
                }
            }).start();

        } catch (Exception e) { e.printStackTrace(); }
    }

    private void sendText() {
        String msg = inputField.getText().trim();
        if (msg.isEmpty()) return;
        try {
            out.write("MSG|" + msg + "\n");
            out.flush();
            chatArea.append("Me: " + msg + "\n");
            inputField.setText("");
        } catch (IOException e) { e.printStackTrace(); }
    }

    private void sendImage() {
        JFileChooser chooser = new JFileChooser();
        int ret = chooser.showOpenDialog(this);
        if (ret != JFileChooser.APPROVE_OPTION) return;
        File file = chooser.getSelectedFile();
        try {
            byte[] data = Files.readAllBytes(file.toPath());
            String b64 = Base64.getEncoder().encodeToString(data);
            out.write("IMG|" + b64 + "\n");
            out.flush();
            chatArea.append("Me: [Image sent]\n");
        } catch (IOException e) { e.printStackTrace(); }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new SecureChatClient().setVisible(true));
    }
}
```

> **安全说明**  
> 1. **TLS**：使用 `SSLContext` 与 `SSLSocket`，并在示例中放宽了服务器证书校验（**不推荐**），生产环境请使用真正的信任链。  
> 2. **鉴权**：客户端先发送 token，服务器检查。实际可改为 **双向证书** 或 **JWT**。  
> 3. **图片**：通过 Base64 发送，避免二进制流导致协议解析错误。  
> 4. **异常处理**：UI 只显示友好错误，不暴露堆栈。  

