    }

    /* 4. Set allowed cipher suite */
    if (!SSL_CTX_set_cipher_list(ctx, "DHE-RSA-AES256-SHA256")) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    /* 5. Create socket and connect */
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct hostent *he = gethostbyname(host);
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(atoi(port));
    memcpy(&addr.sin_addr, he->h_addr_list[0], he->h_length);

    if (connect(sockfd, (struct sockaddr*)&addr, sizeof(addr)) != 0) {
        perror("connect");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* 6. Create SSL object and perform handshake */
    SSL *ssl = SSL_new(ctx);
    SSL_set_fd(ssl, sockfd);
    if (SSL_connect(ssl) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("SSL/TLS connection established.\n");
    printf("Cipher: %s\n", SSL_get_cipher(ssl));

    /* 7. Send a simple message */
    const char *msg = "Hello, server!\n";
    SSL_write(ssl, msg, strlen(msg));

    /* 8. Read response */
    char buf[256];
    int n = SSL_read(ssl, buf, sizeof(buf)-1);
    if (n > 0) {
        buf[n] = '\0';
        printf("Server replied: %s", buf);
    }

    /* 9. Clean up */
    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(sockfd);
    SSL_CTX_free(ctx);
    EVP_cleanup();

    return 0;
}
```

### Server (`server.c`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <netinet/in.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

/* Path to DH parameters */
#define DH_PARAM_FILE "dh2048.pem"

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <listen-port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *port = argv[1];

    /* 1. Initialise OpenSSL */
    SSL_library_init();
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();

    /* 2. Create TLS server context */
    SSL_CTX *ctx = SSL_CTX_new(TLS_server_method());
    if (!ctx) { perror("SSL_CTX_new"); exit(EXIT_FAILURE); }

    /* 3. Load DH parameters (Diffie–Hellman key exchange) */
    if (!SSL_CTX_set_dh_auto(ctx, 1)) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }
    if (SSL_CTX_set_dh_param_file(ctx, DH_PARAM_FILE, SSL_FILETYPE_PEM) <= 0) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    /* 4. No server authentication – skip certificate/key load */

    /* 5. Set allowed cipher suite */
    /*   There is no built‑in 3DES+SHA512; we fall back to 3DES+SHA1 */
    if (!SSL_CTX_set_cipher_list(ctx, "DHE-NULL-3DES-CBC-SHA")) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    /* 6. Create listening socket */
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(atoi(port));
    addr.sin_addr.s_addr = INADDR_ANY;

    int opt = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    if (bind(sockfd, (struct sockaddr*)&addr, sizeof(addr)) != 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    listen(sockfd, 1);

    printf("Listening on port %s\n", port);

    /* 7. Accept a connection */
    struct sockaddr_in peer;
    socklen_t peer_len = sizeof(peer);
    int clientfd = accept(sockfd, (struct sockaddr*)&peer, &peer_len);
    if (clientfd < 0) {
        perror("accept");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /* 8. SSL handshake */
    SSL *ssl = SSL_new(ctx);
    SSL_set_fd(ssl, clientfd);
    if (SSL_accept(ssl) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        close(clientfd);
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("SSL/TLS connection established.\n");
    printf("Cipher: %s\n", SSL_get_cipher(ssl));

    /* 9. Read request */
    char buf[256];
    int n = SSL_read(ssl, buf, sizeof(buf)-1);
    if (n > 0) {
        buf[n] = '\0';
        printf("Client said: %s", buf);
    }

    /* 10. Send response */
    const char *reply = "Hello, client!\n";
    SSL_write(ssl, reply, strlen(reply));

    /* 11. Clean up */
    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(clientfd);
    close(sockfd);
    SSL_CTX_free(ctx);
    EVP_cleanup();

    return 0;
}
```

### One‑liner with `openssl s_client / s_server`

```bash
# Start the server
openssl s_server -accept 4433 -dhparam dh2048.pem -cipher "DHE-NULL-3DES-CBC-SHA" -verify 0

# In another terminal, run the client
openssl s_client -connect localhost:4433 -cert client-cert.pem -key client-key.pem -cipher "DHE-RSA-AES256-SHA256"
```

The `-verify 0` flag tells the server to *not* verify any client cert (i.e. no client authentication).  
The client’s `-cert` / `-key` flags provide the RSA authentication required by the spec.

