## 5. Python (PyOpenSSL + `ssl`) – Quick Demo

```python
import ssl, socket

# ---------- CLIENT ----------
ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE   # No server cert verification (for demo)
ctx.load_cert_chain('client-cert.pem', 'client-key.pem')
ctx.set_ciphers('DHE-RSA-AES256-SHA256')

with socket.create_connection(('localhost', 4433)) as sock:
    with ctx.wrap_socket(sock, server_hostname='localhost') as ssock:
        print('Cipher:', ssock.cipher())
        ssock.sendall(b'Hello, server!\n')
        print('Response:', ssock.recv(4096).decode())

# ---------- SERVER ----------
ctx = ssl.create_default_context(ssl.Purpose.CLIENT_AUTH)
ctx.load_dh_params('dh2048.pem')
ctx.set_ciphers('DHE-NULL-3DES-CBC-SHA')
ctx.verify_mode = ssl.CERT_NONE      # No client auth

with socket.create_server(('0.0.0.0', 4433)) as srv_sock:
    with ctx.wrap_socket(srv_sock, server_side=True) as ssock:
        client, addr = ssock.accept()
        with client:
            data = client.recv(4096)
            print('Client:', data.decode())
            client.sendall(b'Hello, client!\n')
```

