```java
package com.example.jwt.security;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.stereotype.Component;
import java.security.Key;
import java.time.Instant;
import java.util.Date;
import java.util.UUID;

@Component
public class JwtUtil {
    // 256‑bit secret key – replace with a secure value in production
    private final Key key = Keys.secretKeyFor(SignatureAlgorithm.HS256);
    private final long accessTokenValidity = 15 * 60 * 1000L; // 15 minutes
    private final long refreshTokenValidity = 7 * 24 * 60 * 60 * 1000L; // 7 days

    // Create access token with custom claims
    public String generateAccessToken(String username, String jti, String device) {
        return Jwts.builder()
                .setSubject(username)
                .setId(jti)
                .claim("device", device)
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + accessTokenValidity))
                .signWith(key)
                .compact();
    }

    // Create refresh token (no device claim, only jti)
    public String generateRefreshToken(String username, String jti) {
        return Jwts.builder()
                .setSubject(username)
                .setId(jti)
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + refreshTokenValidity))
                .signWith(key)
                .compact();
    }

    public Jws<Claims> parseToken(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(key)
                .build()
                .parseClaimsJws(token);
    }

    public boolean isTokenExpired(String token) {
        try {
            return parseToken(token).getBody().getExpiration().before(new Date());
        } catch (JwtException ex) {
            return true;
        }
    }

    public String getJti(String token) {
        return parseToken(token).getBody().getId();
    }

    public String getUsername(String token) {
        return parseToken(token).getBody().getSubject();
    }

    public String generateJti() {
        return UUID.randomUUID().toString();
    }
}
