package com.example.jwt.service;

import com.example.jwt.model.Session;
import com.example.jwt.model.User;
import com.example.jwt.repository.SessionRepository;
import com.example.jwt.repository.UserRepository;
import com.example.jwt.security.JwtUtil;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import java.time.Instant;
import java.util.Optional;

@Service
@RequiredArgsConstructor
public class AuthService {
    private final UserRepository userRepo;
    private final SessionRepository sessionRepo;
    private final JwtUtil jwtUtil;
    private final PasswordEncoder encoder;

    public Optional<User> register(String username, String rawPassword) {
        if (userRepo.findByUsername(username).isPresent()) return Optional.empty();
        User user = User.builder()
                .username(username)
                .password(encoder.encode(rawPassword))
                .build();
        userRepo.save(user);
        return Optional.of(user);
    }

    @Transactional
    public Optional<AuthResponse> login(String username, String rawPassword, String device) {
        var userOpt = userRepo.findByUsername(username);
        if (userOpt.isEmpty()) return Optional.empty();

        User user = userOpt.get();
        if (!encoder.matches(rawPassword, user.getPassword())) return Optional.empty();

        // Create a unique session
        String jti = jwtUtil.generateJti();
        Instant now = Instant.now();
        Instant accessExp = now.plusMillis(15 * 60 * 1000L); // 15 min
        Instant refreshExp = now.plusMillis(7 * 24 * 60 * 60 * 1000L); // 7 days

        Session session = Session.builder()
                .jti(jti)
                .user(user)
                .device(device)
                .createdAt(now)
                .expiresAt(refreshExp) // store longest expiry
                .build();
        sessionRepo.save(session);

        String accessToken = jwtUtil.generateAccessToken(username, jti, device);
        String refreshToken = jwtUtil.generateRefreshToken(username, jti);

        return Optional.of(new AuthResponse(accessToken, refreshToken, session.getId()));
    }

    @Transactional
    public Optional<AuthResponse> refresh(String refreshToken, String device) {
        try {
            var claims = jwtUtil.parseToken(refreshToken).getBody();
            if (claims.getExpiration().before(java.util.Date.from(Instant.now()))) return Optional.empty();

            String username = claims.getSubject();
            String jti = claims.getId();

            var sessionOpt = sessionRepo.findByJti(jti);
            if (sessionOpt.isEmpty()) return Optional.empty();
            Session session = sessionOpt.get();

            if (!session.getUser().getUsername().equals(username)) return Optional.empty();

            // Extend session expiry
            session.setExpiresAt(Instant.now().plusMillis(7 * 24 * 60 * 60 * 1000L));
            sessionRepo.save(session);

            // Generate new tokens
            String accessToken = jwtUtil.generateAccessToken(username, jti, device);
            String newRefreshToken = jwtUtil.generateRefreshToken(username, jti);

            return Optional.of(new AuthResponse(accessToken, newRefreshToken, session.getId()));
        } catch (Exception ex) {
            return Optional.empty();
        }
    }

    @Transactional
    public boolean logout(Long sessionId) {
        return sessionRepo.findById(sessionId)
                .map(s -> {
                    sessionRepo.deleteByJti(s.getJti());
                    return true;
                })
                .orElse(false);
    }

    @Transactional
    public void logoutAllExcept(Long sessionId, String username) {
        userRepo.findByUsername(username).ifPresent(user -> {
            sessionRepo.findAllByUserId(user.getId()).forEach(session -> {
                if (!session.getId().equals(sessionId)) {
                    sessionRepo.deleteByJti(session.getJti());
                }
            });
        });
    }

    public static class AuthResponse {
        private final String accessToken;
        private final String refreshToken;
        private final Long sessionId;
        public AuthResponse(String accessToken, String refreshToken, Long sessionId) {
            this.accessToken = accessToken;
            this.refreshToken = refreshToken;
            this.sessionId = sessionId;
        }
        // getters
        public String getAccessToken() { return accessToken; }
        public String getRefreshToken() { return refreshToken; }
        public Long getSessionId() { return sessionId; }
    }
}
