    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest req) {
        var respOpt = authService.login(req.getUsername(), req.getPassword(), req.getDevice());
        return respOpt.map(ResponseEntity::ok)
                .orElseGet(() -> ResponseEntity.status(401).body("Invalid credentials"));
    }

    @PostMapping("/refresh")
    public ResponseEntity<?> refresh(@RequestBody RefreshRequest req) {
        var respOpt = authService.refresh(req.getRefreshToken(), req.getDevice());
        return respOpt.map(ResponseEntity::ok)
                .orElseGet(() -> ResponseEntity.status(401).body("Invalid refresh token"));
    }

    @PostMapping("/logout")
    public ResponseEntity<?> logout(@RequestBody LogoutRequest req) {
        boolean success = authService.logout(req.getSessionId());
        return success ? ResponseEntity.ok("Logged out")
                       : ResponseEntity.status(400).body("Session not found");
    }

    @PostMapping("/logoutAll")
    public ResponseEntity<?> logoutAll(@RequestBody LogoutAllRequest req) {
        authService.logoutAllExcept(req.getSessionId(), req.getUsername());
        return ResponseEntity.ok("All other sessions terminated");
    }

    // DTOs
    @Data
    static class RegisterRequest { private String username; private String password; }
    @Data
    static class LoginRequest { private String username; private String password; private String device; }
    @Data
    static class RefreshRequest { private String refreshToken; private String device; }
    @Data
    static class LogoutRequest { private Long sessionId; }
    @Data
    static class LogoutAllRequest { private Long sessionId; private String username; }
}
