package com.example.jwt.controller;

import com.example.jwt.model.Session;
import com.example.jwt.repository.SessionRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/sessions")
@RequiredArgsConstructor
public class SessionController {
    private final SessionRepository sessionRepo;

    @GetMapping
    public ResponseEntity<List<Session>> list(@AuthenticationPrincipal UserPrincipal principal) {
        List<Session> sessions = sessionRepo.findAllByUserId(principal.getId());
        return ResponseEntity.ok(sessions);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<?> delete(@PathVariable Long id,
                                    @AuthenticationPrincipal UserPrincipal principal) {
        if (sessionRepo.findById(id)
                .filter(s -> s.getUser().getId().equals(principal.getId()))
                .isPresent()) {
            sessionRepo.deleteByJti(sessionRepo.findById(id).get().getJti());
            return ResponseEntity.ok("Session terminated");
        }
        return ResponseEntity.status(403).body("Forbidden");
    }

    // Custom UserPrincipal for easy access to user id
    public static class UserPrincipal {
        private final Long id;
        private final String username;
        public UserPrincipal(Long id, String username) {
            this.id = id;
            this.username = username;
        }
        public Long getId() { return id; }
        public String getUsername() { return username; }
    }
}
