```java
package com.ecom.chat.client;

import com.ecom.chat.model.Message;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.Socket;
import java.util.Base64;

public class ClientUI {
    private final String host;
    private final int port;
    private final String userId;
    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;

    // Swing components
    private JFrame frame;
    private JTextArea chatArea;
    private JTextField inputField;
    private JButton sendBtn;
    private JButton imgBtn;

    public ClientUI(String host, int port, String userId) {
        this.host = host;
        this.port = port;
        this.userId = userId;
    }

    public void start() {
        try {
            socket = new Socket(host, port);
            out = new ObjectOutputStream(socket.getOutputStream());
            in  = new ObjectInputStream(socket.getInputStream());

            // 发送连接请求
            Message connectMsg = new Message("connect", "client", userId, userId);
            out.writeObject(connectMsg);
            out.flush();

            // 监听后台线程
            new Thread(this::listen).start();

            // 构建 UI
            initUI();

        } catch (IOException e) {
            showError("无法连接到服务器: " + e.getMessage());
        }
    }

    private void initUI() {
        frame = new JFrame("电商客服 - " + userId);
        chatArea = new JTextArea();
        chatArea.setEditable(false);
        JScrollPane scroll = new JScrollPane(chatArea);

        inputField = new JTextField();
        sendBtn = new JButton("发送");
        imgBtn   = new JButton("发送图片");

        JPanel panel = new JPanel(new BorderLayout());
        panel.add(inputField, BorderLayout.CENTER);
        panel.add(sendBtn, BorderLayout.EAST);

        JPanel bottom = new JPanel(new BorderLayout());
        bottom.add(panel, BorderLayout.CENTER);
        bottom.add(imgBtn, BorderLayout.WEST);

        frame.setLayout(new BorderLayout());
        frame.add(scroll, BorderLayout.CENTER);
        frame.add(bottom, BorderLayout.SOUTH);
        frame.setSize(500, 400);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);

        sendBtn.addActionListener(e -> sendText());
        imgBtn.addActionListener(e -> sendImage());

        inputField.addActionListener(e -> sendText());
    }

    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            Message msg = new Message("text", "client", userId, txt);
            out.writeObject(msg);
            out.flush();
            appendChat("我: " + txt);
            inputField.setText("");
        } catch (IOException e) {
            showError("发送失败: " + e.getMessage());
        }
    }

    private void sendImage() {
        JFileChooser chooser = new JFileChooser();
        if (chooser.showOpenDialog(frame) != JFileChooser.APPROVE_OPTION) return;
        File img = chooser.getSelectedFile();
        try (FileInputStream fis = new FileInputStream(img)) {
            byte[] data = fis.readAllBytes();
            String base64 = Base64.getEncoder().encodeToString(data);
            Message msg = new Message("image", "client", userId,
                    base64, img.getName());
            out.writeObject(msg);
            out.flush();
            appendChat("[图片已发送]");
        } catch (IOException e) {
            showError("发送图片失败: " + e.getMessage());
        }
    }

    private void listen() {
        try {
            while (true) {
                Message msg = (Message) in.readObject();
                if ("busy".equals(msg.getType())) {
                    showError("客服忙，请稍后再来");
                    break;
                }
                if ("prompt".equals(msg.getType())) {
                    // 自动同意（你可以弹窗让用户决定）
                    out.writeObject(new Message("yes", "client", userId, "yes"));
                    out.flush();
                    continue;
                }
                // 处理收到的消息
                if ("image".equals(msg.getType())) {
                    byte[] data = Base64.getDecoder().decode(msg.getContent());
                    // 这里可以把图片写到临时文件并在 chatArea 中显示缩略图
                    appendChat("[客服发送图片: " + msg.getFilename() + "]");
                } else {
                    appendChat("客服: " + msg.getContent());
                }
            }
        } catch (Exception e) {
            showError("连接中断: " + e.getMessage());
        }
    }

    private void appendChat(String txt) {
        SwingUtilities.invokeLater(() ->
                chatArea.append(txt + "\n"));
    }

    private void showError(String msg) {
        SwingUtilities.invokeLater(() ->
                JOptionPane.showMessageDialog(frame, msg));
    }
}
```

> **安全细节**  
> 1. **加密**：上述示例使用明文 socket，可替换为 `SSLSocket`。  
> 2. **输入校验**：对上传图片做 MIME、大小检查。  
> 3. **路径安全**：不允许用户直接控制服务器文件路径。  
> 4. **日志**：不要将敏感信息写到客户端日志。

