import java.time.Instant;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.stream.Stream;

public class LatestEventFetcher {
    /** 线程安全的最新事件引用 */
    private final AtomicReference<Event> latest = new AtomicReference<>();

    public void addEvent(Event e) {
        // 先校验时间合法性
        Instant now = Instant.now();
        if (e.getTimestamp().isBefore(now.minusSeconds(300))
                || e.getTimestamp().isAfter(now.plusSeconds(300))) {
            throw new IllegalArgumentException("Timestamp out of allowed window");
        }

        // 原子性更新
        latest.updateAndGet(prev -> {
            if (prev == null || e.getTimestamp().isAfter(prev.getTimestamp())) {
                return e;
            } else {
                return prev;
            }
        });
    }

    public Optional<Event> getLatest() {
        return Optional.ofNullable(latest.get());
    }

    public static class Event {
        private final Instant timestamp;
        private final String payload;
        private final String signature; // 可选，用于完整性校验

        public Event(Instant ts, String pl, String sig) {
            this.timestamp = ts;
            this.payload   = pl;
            this.signature = sig;
        }

        public Instant getTimestamp() { return timestamp; }
        public String getPayload()   { return payload;   }
        public String getSignature(){ return signature; }
    }
}
```

> 该实现已覆盖 **并发安全**、**时间合法性校验** 与 **不可变对象**，在大多数业务场景下已经足够安全且高效。

