### 5.2 服务器代码（Java 17+）

```java
import javax.net.ssl.*;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.security.cert.CertificateException;
import java.util.concurrent.*;

public class ImageServer {
    private static final int PORT = 8443;
    private static final int MAX_RATE_PER_IP = 5; // 每秒 5 张
    private static final int MAX_IMG_SIZE = 5 * 1024 * 1024; // 5 MB

    // 简单的 per-IP rate limiter
    private final ConcurrentHashMap<String, SimpleRateLimiter> limiters = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        new ImageServer().start();
    }

    public void start() throws Exception {
        SSLContext ctx = SSLContext.getInstance("TLS");
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        KeyStore ks = KeyStore.getInstance("JKS");
        try (FileInputStream fis = new FileInputStream("server.jks")) {
            ks.load(fis, "changeit".toCharArray());
        }
        kmf.init(ks, "changeit".toCharArray());
        ctx.init(kmf.getKeyManagers(), null, null);
        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        SSLServerSocket ss = (SSLServerSocket) ssf.createServerSocket(PORT);
        System.out.println("Server listening on port " + PORT);

        while (true) {
            SSLSocket s = (SSLSocket) ss.accept();
            new Thread(() -> handleConnection(s)).start();
        }
    }

    private void handleConnection(SSLSocket socket) {
        String clientIp = socket.getInetAddress().getHostAddress();
        SimpleRateLimiter limiter = limiters.computeIfAbsent(clientIp,
                k -> new SimpleRateLimiter(MAX_RATE_PER_IP));
        try (DataInputStream dis = new DataInputStream(socket.getInputStream());
             DataOutputStream dos = new DataOutputStream(socket.getOutputStream())) {

            while (true) {
                // 速率限制
                if (!limiter.tryAcquire()) {
                    dos.writeUTF("Rate limit exceeded");
                    break;
                }

                // 读取图片长度
                int len = dis.readInt();
                if (len <= 0 || len > MAX_IMG_SIZE) {
                    dos.writeUTF("Invalid image size");
                    break;
                }
                byte[] data = new byte[len];
                dis.readFully(data);

                // MIME 验证（简化：只检查前缀）
                if (!isValidImage(data)) {
                    dos.writeUTF("Invalid image format");
                    break;
                }

                // 写文件（或转发）
                Path out = Paths.get("uploads", UUID.randomUUID() + ".png");
                Files.createDirectories(out.getParent());
                Files.write(out, data);

                dos.writeUTF("OK");
            }
        } catch (EOFException e) {
            // client closed
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try { socket.close(); } catch (IOException ignored) {}
        }
    }

    private boolean isValidImage(byte[] data) {
        // 简单检查 JPEG / PNG 头
        return (data[0] == (byte) 0xFF && data[1] == (byte) 0xD8) || // JPEG
                (data[0] == (byte) 0x89 && data[1] == (byte) 0x50 && data[2] == (byte) 0x4E &&
                 data[3] == (byte) 0x47); // PNG
    }

    // 线程安全的漏桶计数器
    private static class SimpleRateLimiter {
        private final int permitsPerSecond;
        private int permits;
        private long lastRefill;

        SimpleRateLimiter(int permitsPerSecond) {
            this.permitsPerSecond = permitsPerSecond;
            this.permits = permitsPerSecond;
            this.lastRefill = System.nanoTime();
        }

        synchronized boolean tryAcquire() {
            refill();
            if (permits > 0) {
                permits--;
                return true;
            }
            return false;
        }

        private void refill() {
            long now = System.nanoTime();
            long elapsed = now - lastRefill;
            long newPermits = elapsed * permitsPerSecond / 1_000_000_000L;
            if (newPermits > 0) {
                permits = (int) Math.min(permits + newPermits, permitsPerSecond);
                lastRefill = now;
            }
        }
    }
}
```

> **注意**：上述示例仅演示安全思路。生产环境需要考虑：
> - 证书链完整性、CRL/OCSP
> - 连接超时、心跳机制
> - 并发写文件的同步/分区
> - 监控 & 日志
> - 代码审计 & 动态渗透

