    /* UI for the operator */
    private void initUI() {
        frame = new JFrame("Customer‑Service Operator");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(300, 400);

        pendingList = new JList<>(pendingListModel);
        JScrollPane sp = new JScrollPane(pendingList);
        frame.add(sp, BorderLayout.CENTER);

        JButton acceptBtn = new JButton("Accept");
        JButton rejectBtn = new JButton("Reject");

        acceptBtn.addActionListener(e -> {
            String user = pendingList.getSelectedValue();
            if (user != null) acceptUser(user);
        });

        rejectBtn.addActionListener(e -> {
            String user = pendingList.getSelectedValue();
            if (user != null) rejectUser(user);
        });

        JPanel p = new JPanel();
        p.add(acceptBtn);
        p.add(rejectBtn);
        frame.add(p, BorderLayout.SOUTH);

        frame.setVisible(true);
    }

    private void acceptUser(String user) {
        ClientHandler handler = activeUsers.get(user);
        if (handler != null) {
            handler.sendCommand("ACCEPT");
            pendingListModel.removeElement(user);
        }
    }

    private void rejectUser(String user) {
        ClientHandler handler = activeUsers.get(user);
        if (handler != null) {
            handler.sendCommand("REJECT");
            pendingListModel.removeElement(user);
        }
    }

    /* Main loop that accepts new connections */
    private void acceptLoop() {
        while (!ss.isClosed()) {
            try {
                Socket s = ss.accept();
                new Thread(new ClientHandler(s, this), "Handler‑" + s.getRemoteSocketAddress()).start();
            } catch (IOException e) {
                // log and keep running
                e.printStackTrace();
            }
        }
    }

    /* Called by a ClientHandler when a new user connects */
    protected void registerUser(String user, ClientHandler handler) {
        activeUsers.put(user, handler);
        SwingUtilities.invokeLater(() -> pendingListModel.addElement(user));
    }

    /* Called by a ClientHandler when it is done (e.g. client disconnected) */
    protected void deregisterUser(String user) {
        activeUsers.remove(user);
        SwingUtilities.invokeLater(() -> pendingListModel.removeElement(user));
