package server;

import common.*;

import java.io.*;
import java.net.Socket;
import java.nio.file.*;
import java.util.List;
import java.util.concurrent.*;

public class ClientHandler implements Runnable {
    private final Socket socket;
    private final Server server;
    private ObjectInputStream ois;
    private ObjectOutputStream oos;

    private String user;          // will be set after receiving first message
    private volatile boolean running = true;
    private final ScheduledExecutorService heartbeat = Executors.newSingleThreadScheduledExecutor();

    public ClientHandler(Socket socket, Server server) {
        this.socket = socket;
        this.server = server;
    }

    @Override
    public void run() {
        try {
            oos = new ObjectOutputStream(socket.getOutputStream());
            oos.flush();
            ois = new ObjectInputStream(socket.getInputStream());

            // First message from client must contain username
            Message first = (Message) ois.readObject();
            if (first.getType() != MsgType.TEXT || !first.getSender().startsWith("User:")) {
                sendCommand("ERROR: Invalid initial packet");
                close();
                return;
            }
            user = first.getSender().substring("User:".length());

            server.registerUser(user, this);
            // Load history and send to client
            List<String> history = ChatLog.load(user);
            for (String line : history) {
                sendMessage(MsgType.LOG, line);
            }

            // Start heartbeat checker
            heartbeat.scheduleAtFixedRate(this::checkHeartbeat, 0, 10, TimeUnit.SECONDS);

            // Main message loop
            while (running) {
                Message msg = (Message) ois.readObject();
                process(msg);
            }
        } catch (EOFException | SocketException e) {
            // client disconnected
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            close();
        }
    }

    private void process(Message msg) throws IOException {
        switch (msg.getType()) {
            case TEXT:
                handleText(msg);
                break;
            case IMAGE:
            case FILE:
                handleFile(msg);
                break;
            case HEARTBEAT:
