        Path tmp = Files.createTempFile("client_" + user + "_", ext);
        Files.write(tmp, msg.getPayload());
        System.out.printf("[%s] %s received %s (%d bytes)%n",
                user, msg.getSender(), (msg.getType() == MsgType.IMAGE ? "image" : "file"), msg.getPayload().length);

        // Save the file locally (optional) and send a confirmation
        sendMessage(MsgType.TEXT, "Received your " + (msg.getType() == MsgType.IMAGE ? "image" : "file"));
    }

    /* Sends a simple textual command (e.g. ACCEPT, REJECT, BUSY) */
    public void sendCommand(String cmd) {
