    /* Sends a message of arbitrary type */
    public void sendMessage(MsgType type, String txt) throws IOException {
        sendMessage(type, txt.getBytes("UTF‑8"));
    }

    public void sendMessage(MsgType type, byte[] payload) throws IOException {
        Message m = new Message(type, "Server", user, payload);
        oos.writeObject(m);
        oos.flush();
    }

    /* If the client hasn't sent a heartbeat for 30 seconds, declare “busy” */
    private void checkHeartbeat() {
        // In a real system you'd keep a timestamp of last heartbeat
        // For demo we just send a BUSY hint every 30s
        try {
            sendCommand("BUSY: No response for 30s");
        } catch (Exception e) {
            close();
        }
    }

    private void close() {
        running = false;
        heartbeat.shutdownNow();
        server.deregisterUser(user);
        try { ois.close(); } catch (Exception ignored) {}
        try { oos.close(); } catch (Exception ignored) {}
        try { socket.close(); } catch (Exception ignored) {}
    }
}
