Create a package `client`.

```java
// src/client/ClientUI.java
package client;

import common.*;

import javax.imageio.ImageIO;
import javax.swing.*;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.net.Socket;
import java.nio.file.*;
import java.util.List;

public class ClientUI extends JFrame {
    private static final String SERVER = "localhost";
    private static final int PORT = 5555;

    private Socket socket;
    private ObjectInputStream ois;
    private ObjectOutputStream oos;

    private final JTextArea chatArea = new JTextArea();
    private final JTextField inputField = new JTextField();
    private final JButton sendBtn = new JButton("Send");
    private final JButton imgBtn = new JButton("Image");
    private final JButton fileBtn = new JButton("File");

    private final String userId = "User:" + UUID.randomUUID().toString().substring(0, 6);

    public ClientUI() {
        setTitle("E‑Commerce Customer Service – " + userId);
        setSize(600, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        bottom.add(inputField, BorderLayout.CENTER);
        bottom.add(sendBtn, BorderLayout.EAST);
        add(bottom, BorderLayout.SOUTH);

        JPanel top = new JPanel();
        top.add(imgBtn);
        top.add(fileBtn);
        add(top, BorderLayout.NORTH);

        sendBtn.addActionListener(e -> sendText());
        inputField.addActionListener(e -> sendText());

        imgBtn.addActionListener(e -> sendImage());
        fileBtn.addActionListener(e -> sendFile());

        addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                try { oos.close(); } catch (Exception ignored) {}
                try { ois.close(); } catch (Exception ignored) {}
                try { socket.close(); } catch (Exception ignored) {}
                System.exit(0);
            }
        });

        connect();
        new Thread(this::listenLoop, "Client‑Listener").start();
    }

    private void connect() {
        try {
            socket = new Socket(SERVER, PORT);
            oos = new ObjectOutputStream(socket.getOutputStream());
            oos.flush();
            ois = new ObjectInputStream(socket.getInputStream());

            // Send initial packet containing our id
            Message init = new Message(MsgType.TEXT, userId, null, "Hello, I'm " + userId.getBytes("UTF‑8"));
            oos.writeObject(init);
            oos.flush();

            chatArea.append("[Connected to server]\n");
        } catch (IOException e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(this, "Cannot connect to server", "Error", JOptionPane.ERROR_MESSAGE);
            System.exit(1);
        }
    }

    /* Main loop that receives messages from the server */
    private void listenLoop() {
        try {
            while (true) {
                Message msg = (Message) ois.readObject();
                handleServerMessage(msg);
            }
        } catch (EOFException | SocketException e) {
            chatArea.append("[Disconnected]\n");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /* Dispatch messages based on type */
    private void handleServerMessage(Message msg) {
        switch (msg.getType()) {
            case TEXT:
                chatArea.append("[Server] " + new String(msg.getPayload()) + "\n");
                break;
            case LOG:
                chatArea.append(msg.getPayload() + "\n");
                break;
            case COMMAND:
                handleCommand(new String(msg.getPayload()));
                break;
            case IMAGE:
                showImage(msg.getPayload());
                break;
            case FILE:
                downloadFile(msg.getPayload());
                break;
            default:
                chatArea.append("[Unknown server message]\n");
        }
    }

    /* Show a busy notification */
    private void handleCommand(String cmd) {
        if (cmd.startsWith("BUSY")) {
            SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(this,
                    "Operator is busy. Please wait a moment.", "Busy", JOptionPane.WARNING_MESSAGE));
        } else if (cmd.startsWith("REJECT")) {
            JOptionPane.showMessageDialog(this, "Your request was rejected.", "Rejected", JOptionPane.ERROR_MESSAGE);
        } else if (cmd.startsWith("ACCEPT")) {
            // nothing to do
        } else {
            chatArea.append("[Command] " + cmd + "\n");
        }
    }

    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            Message m = new Message(MsgType.TEXT, userId, null, txt.getBytes("UTF‑8"));
            oos.writeObject(m);
            oos.flush();
            chatArea.append("[Me] " + txt + "\n");
            inputField.setText("");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /* Send an image selected by the user */
    private void sendImage() {
        JFileChooser chooser = new JFileChooser();
        chooser.setFileFilter(new FileNameExtensionFilter("Images", "png", "jpg", "jpeg", "bmp"));
        if (chooser.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File f = chooser.getSelectedFile();
            try {
                byte[] data = Files.readAllBytes(f.toPath());
                Message m = new Message(MsgType.IMAGE, userId, null, data);
                oos.writeObject(m);
                oos.flush();
                chatArea.append("[Me] Sent image: " + f.getName() + "\n");
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /* Send an arbitrary file */
    private void sendFile() {
        JFileChooser chooser = new JFileChooser();
        if (chooser.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File f = chooser.getSelectedFile();
            try {
                byte[] data = Files.readAllBytes(f.toPath());
                Message m = new Message(MsgType.FILE, userId, null, data);
                oos.writeObject(m);
                oos.flush();
                chatArea.append("[Me] Sent file: " + f.getName() + "\n");
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /* Display an image received from the server */
    private void showImage(byte[] payload) {
        try {
            ByteArrayInputStream bis = new ByteArrayInputStream(payload);
            BufferedImage img = ImageIO.read(bis);
            if (img == null) return;
            ImageIcon icon = new ImageIcon(img);
            JLabel label = new JLabel(icon);
            JOptionPane.showMessageDialog(this, label, "Image from server", JOptionPane.PLAIN_MESSAGE);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /* Save a file received from the server */
    private void downloadFile(byte[] payload) {
        JFileChooser chooser = new JFileChooser();
        chooser.setSelectedFile(new File("download_" + System.currentTimeMillis()));
        if (chooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
            File dest = chooser.getSelectedFile();
            try {
                Files.write(dest.toPath(), payload);
                chatArea.append("[Server] Sent file saved to " + dest.getAbsolutePath() + "\n");
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(ClientUI::new);
    }
}
```

---

## 4. How it works

1. **Server starts** – opens a `ServerSocket`, builds a Swing UI with a list of pending users.  
2. **Client starts** – connects, sends a first text packet that contains `User:xxxxx`.  
3. **Server receives** – registers the client, loads its chat log, sends all previous lines.  
4. **Both sides** exchange `Message` objects.  The `MsgType` enum tells the receiver how to interpret the `payload`.  
5. **Images / files** are sent as raw bytes.  The client shows images in a dialog, the server saves them to a temporary file and replies with a text confirmation.  
6. **Busy logic** – every 10 s the server sends a `BUSY` command if no heartbeat (or no activity) is seen; the client shows a dialog.  
7. **Operator interaction** – the server UI lists pending users.  Press **Accept** to send an `ACCEPT` command, **Reject** to send a `REJECT` command.  
8. **Chat history** – each client message is appended to `logs/<user>.log`.  On reconnect the server reads that file and streams the content back.  
9. **Threading & exception safety** –  
   * Every client runs in its own thread (`ClientHandler`).  
   * The main listener on the client runs on a separate thread.  
   * Swing UI updates are performed on the EDT (`SwingUtilities.invokeLater`).  
   * `try‑with‑resources` / `finally` blocks close sockets and streams.  
   * `ConcurrentHashMap` and `DefaultListModel` keep UI and user data consistent.  

---

## 5. Running the demo

```bash
# Compile all Java files
javac -d out $(find . -name '*.java')

# Start the server (runs on localhost:5555)
java -cp out server.Server

# In a separate terminal start one or more clients
java -cp out client.ClientUI
```

You should see:

* The server window list every new client as a row.
* The client window can type messages, send images/files, and receives the server’s echo.
* The server window can accept or reject the pending client; the client gets the corresponding command.
* If the server does not respond for 30 s, a “busy” dialog pops up on the client.

---

## 6. Extending / Production notes

| Feature | How to add |
|---------|------------|
| **Authentication** | Add a login screen; send credentials in the initial packet; server verifies before accepting. |
| **Secure transport** | Wrap the socket in an `SSLSocket` (Java SSL/TLS) or use an existing VPN. |
| **Message framing** | Currently Java serialization is used; for a more language‑agnostic solution use a binary format (e.g. Protocol Buffers). |
| **File size limits** | Add a `maxSize` check on the server; drop or truncate oversized files. |
| **Graceful shutdown** | Add a shutdown hook on the server to close all sockets and flush logs. |
| **Persistence** | Store chat logs in a database instead of files if you need advanced queries. |

Feel free to copy, adapt or expand the code for your own projects. Happy hacking!

