/**
 * RandomWordSelector
 *
 * Reads a text file, counts words separated by whitespace, then selects 10 random
 * words (without replacement). Uses SecureRandom for cryptographic strength.
 *
 * Usage: java RandomWordSelector <path-to-file>
 */
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.SecureRandom;
import java.util.*;

public class RandomWordSelector {

    /** Number of words to sample */
    private static final int SAMPLE_SIZE = 10;

    public static void main(String[] args) {

        // ------------------------------------------------------------------
        // 1. Validate input arguments
        // ------------------------------------------------------------------
        if (args.length != 1) {
            System.err.println("Usage: java RandomWordSelector <path-to-file>");
            System.exit(1);
        }

        Path filePath = Paths.get(args[0]);

        // Basic security: ensure the path is a regular file, not a symlink to
        // something dangerous.
        if (!Files.isRegularFile(filePath, LinkOption.NOFOLLOW_LINKS)) {
            System.err.println("Error: " + filePath + " is not a regular file.");
            System.exit(1);
        }

        // ------------------------------------------------------------------
        // 2. Read the file line‑by‑line (streaming to avoid OOM on huge files)
        // ------------------------------------------------------------------
        List<String> wordList = new ArrayList<>();

        try (BufferedReader reader = Files.newBufferedReader(filePath,
                                                             StandardCharsets.UTF_8)) {

            String line;
            while ((line = reader.readLine()) != null) {
                // Split on one or more whitespace characters
                String[] words = line.trim().split("\\s+");
                for (String w : words) {
                    if (!w.isEmpty()) {          // defensive, though split won't return empty
                        wordList.add(w);
                    }
                }
            }

        } catch (IOException e) {
            System.err.println("Failed to read file: " + e.getMessage());
            System.exit(1);
        }

        // ------------------------------------------------------------------
        // 3. Count words and sanity‑check
        // ------------------------------------------------------------------
        int totalWords = wordList.size();

        if (totalWords == 0) {
            System.err.println("The file contains no words.");
            System.exit(1);
        }

        if (totalWords < SAMPLE_SIZE) {
            System.err.printf(
                    "The file contains only %d word(s), fewer than the requested %d.%n",
                    totalWords, SAMPLE_SIZE);
            System.exit(1);
        }

        // ------------------------------------------------------------------
        // 4. Randomly select 10 words without replacement
        // ------------------------------------------------------------------
        SecureRandom random = new SecureRandom();

        // Shuffle the list (faster than picking unique indices when SAMPLE_SIZE << total)
        Collections.shuffle(wordList, random);

        List<String> selectedWords = wordList.subList(0, SAMPLE_SIZE);

        // ------------------------------------------------------------------
        // 5. Output the result
        // ------------------------------------------------------------------
        System.out.println("Total words in file: " + totalWords);
        System.out.println("Randomly selected " + SAMPLE_SIZE + " words:");
        for (String w : selectedWords) {
            System.out.println("- " + w);
        }
    }
}
```

