package com.example.tcpclient;

import android.util.Log;

import java.io.IOException;
import java.net.Socket;
import java.net.SocketException;

/**
 * A simple background worker that opens a TCP socket to a specified host/port.
 * The socket is kept open for the lifetime of the thread.  Closing the
 * thread will close the socket automatically.
 */
public class NetworkConnection implements Runnable {

    private static final String TAG = "NetworkConnection";

    private final String host;
    private final int port;
    private volatile boolean running = true;

    /**
     * @param host the remote host to connect to
     * @param port the remote port
     */
    public NetworkConnection(String host, int port) {
        this.host = host;
        this.port = port;
    }

    /**
     * Signal the thread to stop and close the socket.
     */
    public void stop() {
        running = false;
    }

    @Override
    public void run() {
        // Use try-with-resources so the socket closes automatically when
        // we exit the loop or an exception is thrown.
        try (Socket socket = new Socket(host, port)) {
            Log.i(TAG, "Connected to " + host + ":" + port);

            // Example: just keep the connection alive for a while.
            // In a real app you would probably read/write to the socket.
            while (running && !Thread.currentThread().isInterrupted()) {
                // Sleep so we don't busy‑loop. Adjust as needed.
                Thread.sleep(1000);
            }

            Log.i(TAG, "Closing connection to " + host + ":" + port);

        } catch (SocketException se) {
            Log.e(TAG, "Socket error: " + se.getMessage(), se);
        } catch (IOException ioe) {
            Log.e(TAG, "IO error: " + ioe.getMessage(), ioe);
        } catch (InterruptedException ie) {
            // Thread was interrupted – exit gracefully
            Thread.currentThread().interrupt();
            Log.i(TAG, "Thread interrupted, shutting down.");
        } catch (Exception e) {
            Log.e(TAG, "Unexpected error: " + e.getMessage(), e);
        }
    }
}
```

