import java.io.Serializable;

/**
 * Packet – header (serial number) + data string.
 * Implements Serializable so that it can be sent over an ObjectOutputStream.
 */
public class Packet implements Serializable {

    private static final long serialVersionUID = 1L;   // good practice

    private final int serialNo;
    private final String data;

    public Packet(int serialNo, String data) {
        this.serialNo = serialNo;
        this.data     = data;
    }

    public int getSerialNo()  { return serialNo; }
    public String getData()   { return data;     }
}
```

--------------------------------------------------------------------
### 2.  `TCPPacketServer.java`

```java
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

/**
 *  mtserver – listens on port 1024.
 *  For each client:
 *    1) receive a Packet (ObjectInputStream)
 *    2) send back an ACK packet (ObjectOutputStream)
 *    3) then read plain text lines from the client,
 *       convert each line to upper‑case and echo it back.
 *    4) if the client sends "CLOSE" the connection closes.
 */
public class TCPPacketServer {

    private static final int PORT = 1024;            // listening port
    private static final int THREADS = 10;           // thread pool size

    public static void main(String[] args) {
        ExecutorService pool = Executors.newFixedThreadPool(THREADS);

        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("Server listening on port " + PORT);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                pool.execute(new ClientHandler(clientSocket));
            }
        } catch (IOException e) {
            System.err.println("Server error: " + e.getMessage());
        }
    }

    /* --------------------------------------------------- */
    /** Per‑client handler – runs in its own thread. */
    private static class ClientHandler implements Runnable {

        private final Socket client;

        ClientHandler(Socket s) { this.client = s; }

        @Override
        public void run() {
            try (
                // ---------- 1) receive Packet ----------
                ObjectInputStream ois  = new ObjectInputStream(client.getInputStream());
                ObjectOutputStream oos = new ObjectOutputStream(client.getOutputStream());

                // ---------- 2) send ACK ----------
                PrintStream ps = new PrintStream(client.getOutputStream(), true); // auto‑flush
                BufferedReader br = new BufferedReader(new InputStreamReader(client.getInputStream()));
            ) {
                // 2a) read the packet sent by the client
                Packet pkt = (Packet) ois.readObject();
                System.out.println("Received packet from "
                        + client.getRemoteSocketAddress()
                        + " – serialNo#" + pkt.getSerialNo()
                        + ", data=\"" + pkt.getData() + "\"");

                // 2b) send ACK packet
                Packet ack = new Packet(pkt.getSerialNo(), "ACK");
                oos.writeObject(ack);
                oos.flush();   // be sure the client gets it
                System.out.println("Sent ACK to " + client.getRemoteSocketAddress());

                // 3) read text lines, echo upper‑case
                String line;
                while ((line = br.readLine()) != null) {
                    if ("CLOSE".equalsIgnoreCase(line.trim())) {
                        System.out.println("Client requested CLOSE. Shutting down connection.");
                        break;   // leave loop → close socket
                    }
                    String upper = line.toUpperCase();
                    ps.println(upper);   // send back
                    System.out.println("Echoed back: " + upper);
                }

            } catch (IOException | ClassNotFoundException e) {
                System.err.println("Client error: " + e.getMessage());
            } finally {
                try { client.close(); } catch (IOException ignored) {}
            }
        }
    }
}
```

--------------------------------------------------------------------
### 3.  `TCPPacketClient.java`

```java
import java.io.*;
import java.net.*;

/**
 * Client – connects to localhost:1024, sends a Packet,
 * receives ACK, then lets the user type lines which are
 * forwarded to the server. The server replies with an
 * upper‑case echo. Typing "CLOSE" terminates both sides.
 */
public class TCPPacketClient {

    private static final String HOST = "localhost";
    private static final int PORT = 1024;

    public static void main(String[] args) {
        try (
            Socket socket = new Socket(HOST, PORT);

            // 1) For packet serialization
            ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());
            ObjectInputStream  ois = new ObjectInputStream(socket.getInputStream());

            // 2) For plain text exchange
            PrintStream ps   = new PrintStream(socket.getOutputStream(), true);
            BufferedReader br = new BufferedReader(new InputStreamReader(socket.getInputStream()));

            // 3) For reading user input
            BufferedReader user = new BufferedReader(new InputStreamReader(System.in));
        ) {

            System.out.println("Connected to server at " + HOST + ":" + PORT);

            /* ---- 1) Send Packet ---- */
            int serialNo = 1;                // hard‑coded for this demo
            System.out.print("Enter data for the packet: ");
            String packetData = user.readLine();

            Packet pkt = new Packet(serialNo, packetData);
            oos.writeObject(pkt);
            oos.flush();

            /* ---- 2) Receive ACK ---- */
            Packet ack = (Packet) ois.readObject();
            System.out.println("Server ACK – serialNo#" + ack.getSerialNo()
                    + ", data=\"" + ack.getData() + "\"");

            /* ---- 3) Text loop ---- */
            String line;
            while (true) {
                System.out.print("Enter text (or CLOSE to quit): ");
                line = user.readLine();

                ps.println(line);            // send to server

                if ("CLOSE".equalsIgnoreCase(line.trim())) {
                    System.out.println("Sent CLOSE. Terminating.");
                    break;
                }

                String response = br.readLine();   // server reply
                if (response == null) {
                    System.out.println("Server closed connection.");
                    break;
                }
                System.out.println("FROM SERVER: " + response);
            }

        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Client error: " + e.getMessage());
        }
    }
}
```

--------------------------------------------------------------------
## How to compile & run

```bash
# Compile all three files
javac Packet.java TCPPacketServer.java TCPPacketClient.java

# Start the server (first terminal)
java TCPPacketServer

# Start a client (second terminal)
