import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * 简单的 MD5 生成工具。
 * 用法示例请参见 main() 方法。
 */
public class Md5Util {

    /**
     * 计算 (wmPoiId + noticeId) 与 content 拼接后的 MD5。
     *
     * @param wmPoiId   第一个 long 参数
     * @param noticeId  第二个 long 参数
     * @param content   任意字符串
     * @return 32 位十六进制 MD5 字符串（小写）
     */
    public static String generateMd5(long wmPoiId, long noticeId, String content) {
        long sum = wmPoiId + noticeId;          // 两个 long 的和
        String text = sum + content;            // 拼接成字符串

        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(text.getBytes()); // 默认 UTF-8
            return bytesToHex(digest).toLowerCase();
        } catch (NoSuchAlgorithmException e) {
            // MD5 在 JDK 中总是存在，理论上不会抛异常
            throw new RuntimeException("MD5 algorithm not available", e);
        }
    }

    /**
     * 将字节数组转换为十六进制字符串。
     *
     * @param bytes 待转换字节数组
     * @return 十六进制字符串
     */
    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    /* ================== Demo ================== */
    public static void main(String[] args) {
        long wmPoiId   = 123456789L;
        long noticeId  = 987654321L;
        String content = "Hello, Security!";

        String md5 = generateMd5(wmPoiId, noticeId, content);
        System.out.println("MD5: " + md5);
    }
}
