/* parallel_matrix.cpp
 *
 * Compile:   g++ -O3 -std=c++17 -fopenmp parallel_matrix.cpp -o parallel_matrix
 * Run:       ./parallel_matrix <rowsA> <colsA> <colsB> <num_threads>
