#include <iostream>
#include <vector>
#include <cstdlib>
#include <sys/time.h>
#include <omp.h>

/* ----------------------------------------------------------------------
 * Helper: get current time in microseconds
 * ---------------------------------------------------------------------- */
static inline long long now_us() {
    struct timeval tv;
    gettimeofday(&tv, nullptr);
    return tv.tv_sec * 1000000LL + tv.tv_usec;
}

/* ----------------------------------------------------------------------
 * Main routine
 * ---------------------------------------------------------------------- */
int main(int argc, char* argv[]) {
    if (argc != 5) {
        std::cerr << "Usage: " << argv[0] << " rowsA colsA colsB nthreads\n";
        return 1;
    }
    const int rowsA = std::atoi(argv[1]);
    const int colsA = std::atoi(argv[2]);
    const int colsB = std::atoi(argv[3]);
    const int nthreads = std::atoi(argv[4]);

    /* Allocate & initialise A, B */
    std::vector<std::vector<double>> A(rowsA, std::vector<double>(colsA));
    std::vector<std::vector<double>> B(colsA, std::vector<double>(colsB));
    std::vector<std::vector<double>> C(rowsA, std::vector<double>(colsB, 0.0));

    for (int i=0;i<rowsA;i++)
        for (int j=0;j<colsA;j++)
            A[i][j] = static_cast<double>((i+j)%1000)/1000.0;

    for (int i=0;i<colsA;i++)
        for (int j=0;j<colsB;j++)
            B[i][j] = static_cast<double>((i-j)%1000)/1000.0;

    /* ------------------------------------------------------------------
     * Parallel block‑matrix multiply
     * ------------------------------------------------------------------ */
    long long start = now_us();

    omp_set_num_threads(nthreads);
    #pragma omp parallel for collapse(2) schedule(static)
    for (int i=0;i<rowsA;i++)
        for (int j=0;j<colsB;j++) {
            double sum = 0.0;
            for (int k=0;k<colsA;k++)
                sum += A[i][k] * B[k][j];
            C[i][j] = sum;
        }

    long long end = now_us();
    double elapsed_sec = (end - start) / 1e6;

    std::cout << "Threads=" << nthreads
              << "  Time=" << elapsed_sec << " s\n";

    /* (Optional) sanity check – print a checksum */
    double checksum = 0.0;
    for (auto& row : C)
        for (auto v : row)
            checksum += v;
    std::cout << "Checksum=" << checksum << "\n";

    return 0;
}
```

