import net.crud.springbootcrud.model.User;
import net.crud.springbootcrud.repository.UserRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Optional;

@Service
public class UserService {

    private final UserRepository repo;

    public UserService(UserRepository repo) {
        this.repo = repo;
    }

    public Optional<User> findById(Long id) {
        return repo.findById(id);
    }

    public List<User> findAll() {
        return repo.findAll();
    }

    @Transactional
    public User save(User user) {
        // JPA will enforce @NotBlank via validation in controller
        return repo.save(user);
    }

    @Transactional
    public void delete(Long id) {
        if (!repo.existsById(id)) {
            throw new IllegalArgumentException("User id " + id + " does not exist");
        }
        repo.deleteById(id);
    }
}
