import java.util.concurrent.*;

public class SecureSocketServer {

    private final int port;
    private final ExecutorService pool = Executors.newFixedThreadPool(4);

    public SecureSocketServer(int port) {
        this.port = port;
    }

    public void start() throws IOException, GeneralSecurityException {
        SSLServerSocket server = createSSLServerSocket(port);
        System.out.println("TLS Server listening on port " + port);

        while (!Thread.currentThread().isInterrupted()) {
            Socket client = server.accept();
            pool.submit(new ClientHandler(client));
        }
    }

    private SSLServerSocket createSSLServerSocket(int port)
            throws IOException, GeneralSecurityException {

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        // Load keystore (JKS or PKCS12)
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream("keystore.jks"), "changeit".toCharArray());
        kmf.init(ks, "changeit".toCharArray());
        ctx.init(kmf.getKeyManagers(), null, new SecureRandom());

        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        return (SSLServerSocket) ssf.createServerSocket(port);
    }

    private static class ClientHandler implements Runnable {
        private final Socket socket;
        private final InputStream in;

        ClientHandler(Socket socket) throws IOException {
            this.socket = socket;
            this.in = socket.getInputStream();
        }

        @Override
        public void run() {
            try {
                // 这里直接将 socket 交给解码器
                H264Decoder.decodeStream(in, new VideoPanel());
            } catch (Exception e) {
                System.err.println("Decoding failed: " + e);
            } finally {
                try { socket.close(); } catch (IOException ignored) {}
            }
        }
    }
}
```

**安全要点**：

1. 仅使用 TLSv1.3，禁用弱密码套件。  
2. 服务器使用自签名或受信任 CA 颁发的证书。  
3. 仅接受已认证客户端（可在 `ClientHandler` 中进一步校验 `SSLSession.getPeerCertificates()`）。  

### 5.3 H264Decoder.java

```java
import org.bytedeco.javacv.*;
import org.bytedeco.ffmpeg.avcodec.AVPacket;
import org.bytedeco.ffmpeg.avcodec.AVCodecContext;
import org.bytedeco.ffmpeg.avcodec.AVCodecID;
import org.bytedeco.ffmpeg.avformat.AVFormatContext;
import org.bytedeco.ffmpeg.avutil.AVFrame;

import javax.swing.*;
import java.awt.*;
import java.io.*;

public class H264Decoder {

    public static void decodeStream(InputStream is, VideoPanel panel)
            throws IOException {
        // Wrap InputStream in a PushDataSource
        PushDataSource push = new PushDataSource(is);
        // Create a frame grabber
        try (FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(push)) {
            grabber.setFormat("h264");  // hint FFmpeg that it's H.264
            grabber.start();

            Frame frame;
            while ((frame = grabber.grabImage()) != null) {
                // Render frame
                panel.updateFrame(frame);
            }

            grabber.stop();
        }
    }

    // Helper: Feed raw H.264 stream to FFmpeg
    private static class PushDataSource extends FFmpegFrameGrabber {
        private final InputStream is;
        private final ByteArrayOutputStream buffer = new ByteArrayOutputStream();

        PushDataSource(InputStream is) {
            super(null);
            this.is = is;
        }

        @Override
        public void start() throws FrameGrabber.Exception {
            super.start();
            // Launch a thread that reads from InputStream into FFmpeg
            new Thread(() -> {
                byte[] tmp = new byte[4096];
                int read;
                try {
                    while ((read = is.read(tmp)) != -1) {
                        buffer.write(tmp, 0, read);
                        // Feed to FFmpeg
                        try (AVPacket pkt = av_packet_alloc()) {
                            pkt.data().put(tmp, 0, read);
                            pkt.size(read);
                            pkt.stream_index(0);
                            // FFmpeg will internally queue it
                        }
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }).start();
        }
    }
}
```

> **简化说明**  
> - `FFmpegFrameGrabber` 能够自动识别 H.264 NAL 结构。  
> - 我们通过自定义 `PushDataSource` 把 socket 数据推送给 FFmpeg。  
> - 真实环境下，建议使用 `AVPacket` 的更细粒度 API，以实现更安全的 NAL 解析和流校验。

### 5.4 VideoPanel.java

```java
import org.bytedeco.javacv.Frame;
