// ClientHandler.java
import java.io.*;
import java.net.Socket;
import java.nio.file.*;
import java.util.*;

public class ClientHandler implements Runnable {
    private Socket socket;
    private String clientName;
    private ObjectInputStream ois;
    private ObjectOutputStream oos;
    private Path logDir = Paths.get("logs");          // 日志目录
    private Path logFile;                            // 对应用户的日志文件

    public ClientHandler(Socket socket, String clientName,
                         ObjectInputStream ois, ObjectOutputStream oos) {
        this.socket = socket;
        this.clientName = clientName;
        this.ois = ois;
        this.oos = oos;
        logDir.toFile().mkdirs();
        logFile = logDir.resolve(clientName + ".txt");
    }

    @Override
    public void run() {
        try {
            // 先把历史日志发送给客户端
            if (Files.exists(logFile)) {
                List<String> history = Files.readAllLines(logFile);
                for (String line : history) {
                    oos.writeObject(line);
                }
                oos.flush();
            }

            // 开始双向通信
            while (true) {
                Message msg = (Message) ois.readObject();
                // 1. 写入日志
                logMessage(msg);
                // 2. 直接转发给客服端（这里我们假设客服端即为服务器）
                // 服务器本身展示在 UI，示例中仅打印
                System.out.println("[" + clientName + "] " + msg.getFrom() + ": " + 
                                   (msg.getType() == Message.Type.TEXT ? new String(msg.getPayload()) : "附件: " + msg.getFileName()));
            }
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("用户 [" + clientName + "] 已断开连接");
            // 关闭资源
            try { socket.close(); } catch (IOException ex) {}
        }
    }

    private void logMessage(Message msg) throws IOException {
        String entry = String.format("%s|%s|%s|%s|%s",
                msg.getTimestamp(), msg.getFrom(), msg.getTo(),
                msg.getType().name(), new String(msg.getPayload(), "UTF-8"));
        Files.write(logFile, (entry + System.lineSeparator()).getBytes(),
                StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }
}
```

> **说明**  
> *日志文件使用简单的 `|` 分隔符，方便后期解析。*  
> *如果需要更严谨的结构，可改用 JSON 或数据库。*

