        chatArea.setWrapStyleWord(true);

        JScrollPane scroll = new JScrollPane(chatArea);
        add(scroll, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        inputField = new JTextField();
        sendBtn = new JButton("发送");
        attachBtn = new JButton("附件");

        bottom.add(inputField, BorderLayout.CENTER);
        bottom.add(attachBtn, BorderLayout.WEST);
        bottom.add(sendBtn, BorderLayout.EAST);
        add(bottom, BorderLayout.SOUTH);

        // 事件
        sendBtn.addActionListener(e -> sendText());
        inputField.addActionListener(e -> sendText());
        attachBtn.addActionListener(e -> attachFile());

        setVisible(true);
    }

    private void connectToServer() {
        try {
            socket = new Socket("127.0.0.1", 5000);
            oos = new ObjectOutputStream(socket.getOutputStream());
            ois = new ObjectInputStream(socket.getInputStream());

            // 发送用户名
            oos.writeObject(username);
            oos.flush();

            // 等待服务器同意
            Boolean accepted = (Boolean) ois.readObject();
            if (!accepted) {
                JOptionPane.showMessageDialog(this, "客服忙，请稍后再试！", "提示", JOptionPane.WARNING_MESSAGE);
                System.exit(0);
            }

            // 读取历史聊天
            new Thread(() -> {
                try {
                    while (true) {
                        Object obj = ois.readObject();
                        if (obj instanceof String) {
                            SwingUtilities.invokeLater(() ->
                                    chatArea.append((String) obj + "\n"));
                        } else if (obj instanceof Message) {
                            displayMessage((Message) obj);
                        }
                    }
                } catch (Exception ignored) {}
            }).start();

        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "连接失败：" + e.getMessage(),
                    "错误", JOptionPane.ERROR_MESSAGE);
            System.exit(0);
        }
    }

    private void startListener() {
        // 监听服务器响应（文本/图片/文件）
        // 这里已在 connectToServer() 中实现
    }

    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            Message msg = Message.text(username, "客服", txt);
            oos.writeObject(msg);
            oos.flush();
            chatArea.append("我: " + txt + "\n");
            inputField.setText("");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void attachFile() {
        JFileChooser fc = new JFileChooser();
        int ret = fc.showOpenDialog(this);
        if (ret != JFileChooser.APPROVE_OPTION) return;

        File file = fc.getSelectedFile();
        try {
            byte[] data = Files.readAllBytes(file.toPath());
            Message msg = Message.file(username, "客服", data, file.getName());
            oos.writeObject(msg);
            oos.flush();
            chatArea.append("我 (文件): " + file.getName() + "\n");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void displayMessage(Message msg) {
        String prefix = msg.getFrom() + ": ";
        switch (msg.getType()) {
            case TEXT:
                chatArea.append(prefix + new String(msg.getPayload()) + "\n");
                break;
            case FILE:
                // 保存文件到本地
                File out = new File("downloads", msg.getFileName());
                out.getParentFile().mkdirs();
                try (FileOutputStream fos = new FileOutputStream(out)) {
                    fos.write(msg.getPayload());
                } catch (IOException e) {
                    e.printStackTrace();
                }
                chatArea.append(prefix + "[文件已保存: " + out.getPath() + "]\n");
                break;
            default:
                break;
        }
    }

    public static void main(String[] args) {
        String name = JOptionPane.showInputDialog(null, "请输入昵称：", "登录", JOptionPane.PLAIN_MESSAGE);
        if (name == null || name.trim().isEmpty()) System.exit(0);
        SwingUtilities.invokeLater(() -> new ClientGUI(name.trim()));
    }
}
```

> **要点**  
> *`ObjectInputStream/ObjectOutputStream` 用来传递 `Message` 对象。*  
> *历史聊天记录通过 `String` 发送，若是文件或图片则直接发送 `Message`。*  
> *`attachFile()` 读取文件并通过 `Message.file()` 发送。*  
> *接收端在 `displayMessage()` 根据类型保存文件或直接在文本框显示。*

### 4.2 连接超时处理

```java
