    public static class Article {
        public String title;
        public String publishDate;
        public String contentHtml;   // full body HTML
        public List<String> imageUrls = new ArrayList<>();

        @Override
        public String toString() {
            return String.format("Title: %s\nDate: %s\nImages: %s\nContent preview: %.200s\n",
                    title, publishDate, imageUrls, contentHtml.replaceAll("\\s+", " "));
        }
    }

    public static void main(String[] args) {
        try {
            List<Article> articles = scrapeAllArticles();
            // Print or process the scraped articles
            articles.forEach(System.out::println);
        } catch (IOException e) {
            System.err.println("An error occurred while scraping: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * Scrapes all articles that are currently listed on the page.
     * @return List of Article objects
     * @throws IOException If network / parsing errors occur
     */
    public static List<Article> scrapeAllArticles() throws IOException {
        List<Article> result = new ArrayList<>();

        // 1. Download the list page
        Document listDoc = Jsoup.connect(LIST_URL)
                .userAgent("Mozilla/5.0 (compatible; Jsoup Scraper)")
                .timeout(TIMEOUT_MS)
                .get();

        // 2. Find all article links in the list
        Elements articleLinks = listDoc.select("div#newsList div.item a"); // Adjust selector to actual markup
        for (Element link : articleLinks) {
            String articleUrl = link.absUrl("href");
            if (articleUrl.isEmpty()) {
                // Sometimes the href may be relative; use baseUri
                articleUrl = BASE_URL + link.attr("href");
            }
            try {
                Article article = scrapeArticle(articleUrl);
                result.add(article);
            } catch (Exception e) {
                System.err.println("Failed to scrape article at " + articleUrl + ": " + e.getMessage());
            }
        }

        return result;
    }

    /**
     * Scrapes a single article page.
     * @param url The full URL to the article
     * @return Article object with all fields populated
     * @throws IOException If network / parsing errors occur
     */
    public static Article scrapeArticle(String url) throws IOException {
        // Fetch article page
        Document articleDoc = Jsoup.connect(url)
                .userAgent("Mozilla/5.0 (compatible; Jsoup Scraper)")
                .timeout(TIMEOUT_MS)
                .get();

        Article article = new Article();

        // 1. Title – usually the <h1> or <title> tag
        article.title = articleDoc.selectFirst("h1.article-title") != null
                ? articleDoc.selectFirst("h1.article-title").text()
                : articleDoc.title();

        // 2. Publish date – adjust selector based on actual markup
        Element dateElem = articleDoc.selectFirst("div.article-meta span.publish-date");
        article.publishDate = dateElem != null ? dateElem.text() : "Unknown";

        // 3. Body content – usually a <div> with a known class
        Element contentElem = articleDoc.selectFirst("div.article-content");
        if (contentElem == null) {
            throw new IOException("Could not find article content element");
        }
        article.contentHtml = contentElem.html();

        // 4. Image URLs – convert relative paths to absolute
        Elements images = contentElem.select("img");
        for (Element img : images) {
            String src = img.absUrl("src");
            if (src.isEmpty()) {
                // If absUrl failed, prepend the base URL
                src = BASE_URL + img.attr("src");
            }
            article.imageUrls.add(src);
        }

        return article;
    }
}
```

