```java
// AuthController.java
@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authManager;
    private final JwtTokenProvider tokenProvider;
    private final UserRepository userRepo;

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginDto dto) {
        UsernamePasswordAuthenticationToken authToken =
                new UsernamePasswordAuthenticationToken(dto.getUsername(), dto.getPassword());

        Authentication auth = authManager.authenticate(authToken);
        SecurityContextHolder.getContext().setAuthentication(auth);

        String accessToken = tokenProvider.createAccessToken(auth);
        String refreshToken = tokenProvider.createRefreshToken(dto.getUsername());

        return ResponseEntity.ok(new TokenDto(accessToken, refreshToken));
    }

    @PostMapping("/refresh")
    public ResponseEntity<?> refresh(@RequestBody RefreshDto dto) {
        if (!tokenProvider.validateToken(dto.getRefreshToken())) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }
        String username = tokenProvider.getUsername(dto.getRefreshToken());
        UserDetails user = userRepo.findByUsername(username)
                .map(u -> org.springframework.security.core.userdetails.User.builder()
                        .username(u.getUsername())
                        .password(u.getPassword())
                        .authorities(u.getRole())
                        .build())
                .orElseThrow(() -> new UsernameNotFoundException("User not found"));

        Authentication newAuth = new UsernamePasswordAuthenticationToken(
                user.getUsername(), null, user.getAuthorities());

        String newAccess = tokenProvider.createAccessToken(newAuth);
        return ResponseEntity.ok(new TokenDto(newAccess, dto.getRefreshToken()));
    }
}
