```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class Md5Base64Demo {

    /**
     * 先 MD5 计算，再 Base64 编码
     *
     * @param data 待处理的原始数据（字符串）
     * @return MD5 + Base64 结果
     */
    public static String md5ThenBase64(String data) {
        // 1️⃣ 先 MD5
        byte[] md5Bytes = md5Digest(data.getBytes(StandardCharsets.UTF_8));

        // 2️⃣ 再 Base64 编码
        return Base64.getEncoder().encodeToString(md5Bytes);
    }

    private static byte[] md5Digest(byte[] input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            return md.digest(input);
        } catch (NoSuchAlgorithmException e) {
            // 这在 Java 标准库里几乎不会发生
            throw new RuntimeException("MD5 算法不可用", e);
        }
    }

    public static void main(String[] args) {
        String original = "Hello, World!";

        String result = md5ThenBase64(original);
        System.out.println("原文:      " + original);
        System.out.println("MD5+Base64: " + result);
        // 预期输出:  "bXktc2FtcGxl" 等（取决于原文）
    }
}
```

### 关键点说明

| 步骤 | 说明 | 备注 |
|------|------|------|
| `MessageDigest.getInstance("MD5")` | 取 MD5 实例 | 该算法在 JDK 中是预置的 |
| `md.digest(...)` | 计算散列值 | 返回 16 字节（128 位） |
| `Base64.getEncoder().encodeToString(...)` | Base64 编码 | 默认使用标准 `RFC 4648` Base64，不含行分隔符 |

