### 2.2 `FileIndex`

```java
package com.example.fileindexer;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.File;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class FileIndex {
    private final Map<String, FileInfo> index = new ConcurrentHashMap<>();
    private final ObjectMapper mapper = new ObjectMapper();
    private final Path indexPath;

    public FileIndex(Path indexPath) {
        this.indexPath = indexPath;
        load();          // attempt to restore a previous run
    }

    /* ------------- Basic API ------------- */

    public void add(FileInfo fi) {
        index.put(fi.path, fi);
    }

    public void remove(String path) {
        index.remove(path);
    }

    public FileInfo get(String path) {
        return index.get(path);
    }

    public Collection<FileInfo> search(String query) {
        List<FileInfo> matches = new ArrayList<>();
        String lower = query.toLowerCase();
        for (FileInfo fi : index.values()) {
            if (fi.path.toLowerCase().contains(lower)) {
                matches.add(fi);
            }
        }
        return matches;
    }

    /* ------------- Persistence ------------- */

    public void save() {
        try {
            mapper.writerWithDefaultPrettyPrinter()
                  .writeValue(indexPath.toFile(), index);
        } catch (Exception e) {
            System.err.println("Failed to save index: " + e.getMessage());
        }
    }

    public void load() {
        if (!Files.exists(indexPath)) return;
        try {
            TypeReference<Map<String, FileInfo>> ref = new TypeReference<>() {};
            Map<String, FileInfo> loaded = mapper.readValue(indexPath.toFile(), ref);
            index.clear();
            index.putAll(loaded);
            System.out.println("[+] Restored index with " + index.size() + " entries.");
        } catch (Exception e) {
            System.err.println("Failed to load index: " + e.getMessage());
        }
    }

    /* ------------- Utility ------------- */

    public static String sha256(Path file) {
        try (var in = Files.newInputStream(file)) {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) > 0) {
                md.update(buf, 0, n);
            }
            return bytesToHex(md.digest());
        } catch (Exception e) {
            return null;   // ignore errors (e.g., permission denied)
        }
    }

    private static String bytesToHex(byte[] b) {
        StringBuilder sb = new StringBuilder();
        for (byte v : b) sb.append(String.format("%02x", v));
        return sb.toString();
    }
}
```

