### 2.3 `Indexer`

The `Indexer` walks a drive and populates the `FileIndex`.

```java
package com.example.fileindexer;

import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;

public class Indexer {
    private final FileIndex index;

    public Indexer(FileIndex index) {
        this.index = index;
    }

    public void indexRoot(Path root) {
        try {
            Files.walkFileTree(root, new SimpleFileVisitor<>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                    try {
                        index.add(new FileInfo(
                                file.toAbsolutePath().toString(),
                                attrs.size(),
                                attrs.lastModifiedTime().toMillis(),
                                FileIndex.sha256(file)));
                    } catch (Exception ignored) {}
                    return FileVisitResult.CONTINUE;
                }

                @Override
                public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                    // Nothing special – just walk into it
                    return FileVisitResult.CONTINUE;
                }
            });
            System.out.println("[+] Indexed root: " + root);
        } catch (Exception e) {
            System.err.println("[!] Error indexing " + root + ": " + e.getMessage());
        }
    }

    public void indexAllDrives() {
        for (Path root : FileSystems.getDefault().getRootDirectories()) {
            indexRoot(root);
        }
        index.save(); // Persist after full initial scan
    }
}
```

---

### 2.4 `FileWatcher`

A very simple, but effective, change‑monitoring layer using `WatchService`.  
Because `WatchService` does **not** recurse automatically, we register every directory we visit.

```java
package com.example.fileindexer;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;

public class FileWatcher implements Runnable {
    private final FileIndex index;
    private final WatchService ws;
    private final Map<WatchKey, Path> keys = new HashMap<>();

    public FileWatcher(FileIndex index) throws IOException {
        this.index = index;
        this.ws = FileSystems.getDefault().newWatchService();
        registerAll(FileSystems.getDefault().getRootDirectories());   // initial registration
    }

    /* ------------- Registration ------------- */

    private void register(Path dir) throws IOException {
        WatchKey key = dir.register(ws,
                StandardWatchEventKinds.ENTRY_CREATE,
                StandardWatchEventKinds.ENTRY_DELETE,
                StandardWatchEventKinds.ENTRY_MODIFY);
        keys.put(key, dir);
    }

    private void registerAll(Collection<Path> roots) throws IOException {
        for (Path root : roots) {
            Files.walkFileTree(root, new SimpleFileVisitor<>() {
                @Override
                public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
                    register(dir);
                    return FileVisitResult.CONTINUE;
                }
            });
        }
    }

    /* ------------- Event loop ------------- */

    @Override
    public void run() {
        while (true) {
            WatchKey key;
            try { key = ws.take(); }   // blocks
            catch (InterruptedException ex) {
                Thread.currentThread().interrupt();
                return;
            }

            Path dir = keys.get(key);
            if (dir == null) { key.reset(); continue; }

            for (WatchEvent<?> event : key.pollEvents()) {
                WatchEvent.Kind<?> kind = event.kind();
                Path name = (Path) event.context();
                Path full = dir.resolve(name);

                try {
                    if (kind == StandardWatchEventKinds.ENTRY_CREATE) {
                        if (Files.isDirectory(full)) {
                            registerAll(Collections.singleton(full));
                        }
                        if (Files.isRegularFile(full)) {
                            BasicFileAttributes attrs = Files.readAttributes(full, BasicFileAttributes.class);
                            index.add(new FileInfo(
                                    full.toAbsolutePath().toString(),
                                    attrs.size(),
                                    attrs.lastModifiedTime().toMillis(),
                                    FileIndex.sha256(full)));
                        }
                    } else if (kind == StandardWatchEventKinds.ENTRY_MODIFY) {
                        if (Files.isRegularFile(full)) {
                            BasicFileAttributes attrs = Files.readAttributes(full, BasicFileAttributes.class);
                            index.add(new FileInfo(
                                    full.toAbsolutePath().toString(),
                                    attrs.size(),
                                    attrs.lastModifiedTime().toMillis(),
                                    FileIndex.sha256(full)));
                        }
                    } else if (kind == StandardWatchEventKinds.ENTRY_DELETE) {
                        index.remove(full.toAbsolutePath().toString());
                    }
                } catch (IOException e) {
                    System.err.println("[!] Watch error on " + full + ": " + e.getMessage());
                }
            }

            boolean valid = key.reset();
            if (!valid) keys.remove(key);
        }
    }
}
```

