## 4. 客户端代码（`Client.java`）

```java
import javax.net.ssl.*;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.logging.*;

public class Client {

    private static final Logger log = Logger.getLogger(Client.class.getName());

    private String serverHost = "localhost";
    private int serverPort = 8443;
    private String userId = "user_123";
    private String password = "secret";

    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;

    private String sessionToken;

    // UI
    private JFrame frame;
    private JTextPane chatArea;
    private JTextField inputField;
    private JButton sendBtn;
    private JButton sendImgBtn;
    private JButton sendFileBtn;
    private JLabel statusLabel;

    public static void main(String[] args) {
        new Client().start();
    }

    void start() {
        buildUI();
        connectToServer();
    }

    /* ---------- UI ---------- */

    private void buildUI() {
        frame = new JFrame("E‑Commerce Chat");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLayout(new BorderLayout());

        chatArea = new JTextPane();
        chatArea.setEditable(false);
        JScrollPane scroll = new JScrollPane(chatArea);
        frame.add(scroll, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        inputField = new JTextField();
        sendBtn = new JButton("Send");
        sendImgBtn = new JButton("Img");
        sendFileBtn = new JButton("File");
        statusLabel = new JLabel("Disconnected");

        JPanel buttons = new JPanel();
        buttons.add(sendImgBtn);
        buttons.add(sendFileBtn);
        buttons.add(sendBtn);

        bottom.add(inputField, BorderLayout.CENTER);
        bottom.add(buttons, BorderLayout.EAST);
        bottom.add(statusLabel, BorderLayout.WEST);

        frame.add(bottom, BorderLayout.SOUTH);

        // Listeners
        sendBtn.addActionListener(e -> sendText());
        sendImgBtn.addActionListener(e -> sendImage());
        sendFileBtn.addActionListener(e -> sendFile());

        frame.setSize(600, 400);
        frame.setVisible(true);
    }

    /* ---------- 网络 ---------- */

    private void connectToServer() {
        new Thread(() -> {
            try {
                SSLContext ctx = SSLContext.getDefault(); // 默认 truststore
                SSLSocketFactory sf = ctx.getSocketFactory();
                socket = (SSLSocket) sf.createSocket(serverHost, serverPort);
                in = new DataInputStream(socket.getInputStream());
                out = new DataOutputStream(socket.getOutputStream());

                // 登录
                out.writeUTF("LOGIN|" + userId + "|" + password + "\n");
                out.flush();

                String resp = readLine();
                if (!resp.startsWith("AUTH_OK|")) {
                    throw new IOException("Auth failed");
                }
                sessionToken = resp.split("\\|")[1];
                setStatus("Connected");

                // 开始监听
                new Thread(this::listenLoop).start();
            } catch (Exception e) {
                log.warning("Connection error: " + e.getMessage());
                setStatus("Error");
            }
        }).start();
    }

    private void listenLoop() {
        try {
            while (true) {
                int type = in.read();
                int len = in.readInt();
                byte[] data = new byte[len];
                in.readFully(data);
                byte chksum = in.read();
                if ((byte) (type + len + chksum) != 0) {
                    throw new IOException("Bad checksum");
                }

                // UI 线程更新
                SwingUtilities.invokeLater(() -> handleMessage(type, data));
            }
        } catch (IOException e) {
            log.info("Disconnected: " + e.getMessage());
            setStatus("Disconnected");
        }
    }

    /* ---------- 消息发送 ---------- */

    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            byte[] payload = ("TEXT|" + sessionToken + "|" + txt).getBytes(StandardCharsets.UTF_8);
            out.writeByte(0x01); // TEXT
            out.writeInt(payload.length);
            out.write(payload);
            out.writeByte((byte) ((0x01 + payload.length) & 0xFF));
            out.flush();
            appendToChat("Me: " + txt);
            inputField.setText("");
        } catch (IOException e) {
            log.warning("Send error: " + e.getMessage());
        }
    }

    private void sendImage() {
        JFileChooser chooser = new JFileChooser();
        if (chooser.showOpenDialog(frame) != JFileChooser.APPROVE_OPTION) return;
        File imgFile = chooser.getSelectedFile();

        // 限制大小（10MB）
        if (imgFile.length() > 10 * 1024 * 1024) {
            JOptionPane.showMessageDialog(frame, "Image too large");
            return;
        }
        try (FileInputStream fis = new FileInputStream(imgFile)) {
            byte[] data = fis.readAllBytes();
            byte[] payload = ("IMAGE|" + sessionToken + "|" + Base64.getEncoder().encodeToString(data)).getBytes();
            out.writeByte(0x02); // IMAGE
            out.writeInt(payload.length);
            out.write(payload);
            out.writeByte((byte) ((0x02 + payload.length) & 0xFF));
            out.flush();
            appendToChat("Me: [image sent]");
        } catch (IOException e) {
            log.warning("Send image error: " + e.getMessage());
        }
    }

    private void sendFile() {
        JFileChooser chooser = new JFileChooser();
        if (chooser.showOpenDialog(frame) != JFileChooser.APPROVE_OPTION) return;
        File file = chooser.getSelectedFile();

        if (file.length() > 50 * 1024 * 1024) { // 50MB limit
            JOptionPane.showMessageDialog(frame, "File too large");
            return;
        }
        try (FileInputStream fis = new FileInputStream(file)) {
            byte[] data = fis.readAllBytes();
            String base64 = Base64.getEncoder().encodeToString(data);
            byte[] payload = ("FILE|" + sessionToken + "|" + file.getName() + "|" + base64).getBytes();
            out.writeByte(0x03); // FILE
            out.writeInt(payload.length);
            out.write(payload);
            out.writeByte((byte) ((0x03 + payload.length) & 0xFF));
            out.flush();
            appendToChat("Me: [file sent: " + file.getName() + "]");
        } catch (IOException e) {
            log.warning("Send file error: " + e.getMessage());
        }
    }

    /* ---------- UI 更新 ---------- */

    private void handleMessage(int type, byte[] data) {
        try {
            String msg = new String(data, StandardCharsets.UTF_8);
            if (msg.startsWith("TEXT|")) {
                String[] parts = msg.split("\\|", 3);
                if (parts.length == 3) appendToChat(parts[1] + ": " + parts[2]);
            } else if (msg.startsWith("IMAGE|")) {
                // 简单：在聊天框显示占位符
                appendToChat("[image received]");
            } else if (msg.startsWith("FILE|")) {
                String[] parts = msg.split("\\|", 4);
                if (parts.length >= 4) {
                    String fileName = parts[2];
                    byte[] fileData = Base64.getDecoder().decode(parts[3]);
                    // 下载到 tmp 目录
                    File outFile = new File("downloads", fileName);
                    outFile.getParentFile().mkdirs();
                    try (FileOutputStream fos = new FileOutputStream(outFile)) {
                        fos.write(fileData);
                    }
                    appendToChat("[file received: " + fileName + "]");
                }
            } else {
                appendToChat("[unknown] " + msg);
            }
        } catch (Exception e) {
            log.warning("Message parse error: " + e.getMessage());
        }
    }

    private void appendToChat(String txt) {
        chatArea.setText(chatArea.getText() + txt + "\n");
    }

    private void setStatus(String txt) {
        SwingUtilities.invokeLater(() -> statusLabel.setText(txt));
    }

    private String readLine() throws IOException {
        StringBuilder sb = new StringBuilder();
        int b;
        while ((b = in.read()) != -1) {
            if (b == '\n') break;
            sb.append((char) b);
        }
        return sb.toString();
    }
}
```

### 关键安全点

| 功能 | 防护措施 |
|------|----------|
| 传输 | `SSLSocket` 自动加密。 |
| 认证 | `sessionToken` 检查。 |
| 文件大小 | UI 层检查上传文件大小。 |
| 目录遍历 | 下载时只写入 `downloads/`，不解析路径。 |
| UI 更新 | `SwingUtilities.invokeLater` 避免 EDT 死锁。 |
| 异常处理 | 所有 `try` 块使用 `catch` 打印日志；连接异常后状态更新。 |

