## 2. 代码实现

```java
package com.example.imagedownloader;

import com.sun.net.httpserver.Headers;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpServer;

import java.io.*;
import java.net.InetSocketAddress;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.SecureRandom;
import java.util.*;

public class SimpleImageUploadServer {

    // ---------- 配置 ----------
    private static final int PORT = 8080;
    private static final String UPLOAD_PATH = "uploads";
    private static final long MAX_FILE_SIZE = 5 * 1024 * 1024; // 5 MB
    private static final long MAX_REQUEST_SIZE = 10 * 1024 * 1024; // 10 MB
    private static final Set<String> ACCEPTED_MIME_TYPES = Set.of(
            "image/jpeg",
            "image/png",
            "image/gif",
            "image/webp"
    );
    private static final Map<String, byte[]> MAGIC_NUMBERS = Map.of(
            "image/jpeg", new byte[]{(byte)0xFF, (byte)0xD8, (byte)0xFF},
            "image/png",  new byte[]{0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A},
            "image/gif", new byte[]{0x47, 0x49, 0x46, 0x38},
            "image/webp",new byte[]{0x57, 0x45, 0x42, 0x50}
    );
    private static final SecureRandom RANDOM = new SecureRandom();

    // ---------- 主入口 ----------
    public static void main(String[] args) throws IOException {
        // 创建上传目录
        Files.createDirectories(Paths.get(UPLOAD_PATH));

        HttpServer server = HttpServer.create(new InetSocketAddress(PORT), 0);
        server.createContext("/upload", new UploadHandler());
        server.setExecutor(null); // 默认线程池
        System.out.println("Server started at http://localhost:" + PORT + "/upload");
        server.start();
    }

    // ---------- 处理器 ----------
    static class UploadHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equalsIgnoreCase(exchange.getRequestMethod())) {
                sendResponse(exchange, 405, "Method Not Allowed");
                return;
            }

            Headers reqHeaders = exchange.getRequestHeaders();
            String contentType = reqHeaders.getFirst("Content-Type");
            if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                sendResponse(exchange, 400, "Content-Type must be multipart/form-data");
                return;
            }

            // 解析 boundary
            String boundary = extractBoundary(contentType);
            if (boundary == null) {
                sendResponse(exchange, 400, "Boundary not found");
                return;
            }

            // 读取请求体（可选：限制总大小）
            InputStream is = exchange.getRequestBody();
            ByteArrayOutputStream bodyBuf = new ByteArrayOutputStream();
            byte[] temp = new byte[8192];
            int read;
            long totalRead = 0;
            while ((read = is.read(temp)) != -1) {
                totalRead += read;
                if (totalRead > MAX_REQUEST_SIZE) {
                    sendResponse(exchange, 413, "Request too large");
                    return;
                }
                bodyBuf.write(temp, 0, read);
            }
            byte[] bodyBytes = bodyBuf.toByteArray();

            // 解析 multipart
            List<Part> parts = parseMultipart(bodyBytes, boundary);
            if (parts.isEmpty()) {
                sendResponse(exchange, 400, "No file part found");
                return;
            }

            // 只接受第一个文件部分
            Part filePart = parts.get(0);
            if (filePart.filename == null || filePart.filename.isEmpty()) {
                sendResponse(exchange, 400, "File part missing filename");
                return;
            }

            // 1️⃣ 校验文件大小
            if (filePart.content.length > MAX_FILE_SIZE) {
                sendResponse(exchange, 413, "File too large");
                return;
            }

            // 2️⃣ 校验 MIME 类型
            String contentTypeHeader = filePart.headers.get("Content-Type");
            if (contentTypeHeader == null || !ACCEPTED_MIME_TYPES.contains(contentTypeHeader)) {
                sendResponse(exchange, 415, "Unsupported Media Type");
                return;
            }

            // 3️⃣ 校验魔数（文件头）
            if (!validateMagicNumber(filePart.content, contentTypeHeader)) {
                sendResponse(exchange, 415, "File magic number mismatch");
                return;
            }

            // 4️⃣ 生成安全文件名
            String ext = mimeToExtension(contentTypeHeader);
            String safeFilename = generateSafeFileName(ext);

            // 5️⃣ 写文件
            File outFile = new File(UPLOAD_PATH, safeFilename);
            try (FileOutputStream fos = new FileOutputStream(outFile)) {
                fos.write(filePart.content);
            }

            sendResponse(exchange, 200, "File uploaded successfully as " + safeFilename);
        }
    }

    // ---------- 工具方法 ----------
    private static String extractBoundary(String contentType) {
        // contentType 例如：multipart/form-data; boundary=----WebKitFormBoundaryePkpFF7tjBAqx29L
        String[] parts = contentType.split(";");
        for (String part : parts) {
            part = part.trim();
            if (part.startsWith("boundary=")) {
                return part.substring(9).trim();
            }
        }
        return null;
    }

    private static List<Part> parseMultipart(byte[] body, String boundary) {
        List<Part> parts = new ArrayList<>();
        byte[] boundaryBytes = ("--" + boundary).getBytes();
        int pos = 0;

        while (pos < body.length) {
            // 查找 boundary
            int start = indexOf(body, boundaryBytes, pos);
            if (start < 0) break;
            pos = start + boundaryBytes.length;

            // 跳过可能的 \r\n
            if (pos + 2 <= body.length && body[pos] == '\r' && body[pos + 1] == '\n') {
                pos += 2;
            } else if (pos + 1 <= body.length && body[pos] == '\n') {
                pos += 1;
            }

            // 读取头部
            int headerEnd = indexOf(body, "\r\n\r\n".getBytes(), pos);
            if (headerEnd < 0) break;
            String headersStr = new String(body, pos, headerEnd - pos);
            Map<String, String> headers = parseHeaders(headersStr);
            pos = headerEnd + 4; // 跳过 \r\n\r\n

            // 读取内容，直到下一个 boundary
            int nextBoundary = indexOf(body, ("--" + boundary).getBytes(), pos);
            if (nextBoundary < 0) nextBoundary = body.length;
            int contentLength = nextBoundary - pos - 2; // 去掉 \r\n
            byte[] content = Arrays.copyOfRange(body, pos, pos + contentLength);
            pos = nextBoundary;

            // 解析 Content-Disposition 取文件名
            String disposition = headers.get("Content-Disposition");
            String filename = null;
            if (disposition != null) {
                for (String part : disposition.split(";")) {
                    part = part.trim();
                    if (part.startsWith("filename=")) {
                        filename = stripQuotes(part.substring(9));
                    }
                }
            }

            parts.add(new Part(headers, filename, content));
        }

        return parts;
    }

    private static Map<String, String> parseHeaders(String headerStr) {
        Map<String, String> map = new HashMap<>();
        for (String line : headerStr.split("\r\n")) {
            int idx = line.indexOf(':');
            if (idx > 0) {
                String key = line.substring(0, idx).trim();
                String value = line.substring(idx + 1).trim();
                map.put(key, value);
            }
        }
        return map;
    }

    private static String stripQuotes(String s) {
        if (s.startsWith("\"") && s.endsWith("\"") && s.length() >= 2) {
            return s.substring(1, s.length() - 1);
        }
        return s;
    }

    private static int indexOf(byte[] data, byte[] pattern, int start) {
        outer:
        for (int i = start; i <= data.length - pattern.length; i++) {
            for (int j = 0; j < pattern.length; j++) {
                if (data[i + j] != pattern[j]) {
                    continue outer;
                }
            }
            return i;
        }
        return -1;
    }

    private static boolean validateMagicNumber(byte[] fileData, String mimeType) {
        byte[] magic = MAGIC_NUMBERS.get(mimeType);
        if (magic == null) return false;
        if (fileData.length < magic.length) return false;
        for (int i = 0; i < magic.length; i++) {
            if (fileData[i] != magic[i]) return false;
        }
        return true;
    }

    private static String mimeToExtension(String mime) {
        return switch (mime) {
            case "image/jpeg" -> ".jpg";
            case "image/png" -> ".png";
            case "image/gif" -> ".gif";
            case "image/webp" -> ".webp";
            default -> "";
        };
    }

    private static String generateSafeFileName(String ext) {
        long timestamp = System.currentTimeMillis();
        int rnd = RANDOM.nextInt(1_000_000);
        return "IMG_" + timestamp + "_" + rnd + ext;
    }

    private static void sendResponse(HttpExchange exchange, int status, String message) throws IOException {
        byte[] resp = message.getBytes();
        exchange.getResponseHeaders().set("Content-Type", "text/plain; charset=utf-8");
        exchange.sendResponseHeaders(status, resp.length);
        try (OutputStream os = exchange.getResponseBody()) {
            os.write(resp);
        }
    }

    // ---------- 内部类 ----------
    private static class Part {
        Map<String, String> headers;
        String filename;   // 可为 null
        byte[] content;

        Part(Map<String, String> headers, String filename, byte[] content) {
            this.headers = headers;
            this.filename = filename;
            this.content = content;
        }
    }
}
```

