```java
package com.security.demo;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import javax.swing.*;

import org.jcodec.api.FrameGrab;
import org.jcodec.common.NIOUtils;
import org.jcodec.common.io.NIODataSource;
import org.jcodec.common.model.Picture;
import org.jcodec.scale.AWTUtil;

public class H264StreamServer {

    // 服务器端口
    private static final int PORT = 5000;

    // 最大可接受帧尺寸（防止溢出）
    private static final int MAX_FRAME_SIZE = 10_000_000; // ~10 MB

    // 用于解码的线程池（单线程即可，保持解码顺序）
    private final ExecutorService decoder = Executors.newSingleThreadExecutor();

    // 窗口
    private final JFrame frame;
    private final JLabel imageLabel;

    public H264StreamServer() {
        frame = new JFrame("H264 Stream Demo");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        imageLabel = new JLabel();
        frame.add(imageLabel, BorderLayout.CENTER);
        frame.setSize(640, 480);
        frame.setVisible(true);
    }

    public void start() throws IOException {
        ServerSocket serverSocket = new ServerSocket(PORT);
        System.out.println("Listening on port " + PORT);

        while (true) {
            Socket client = serverSocket.accept();
            System.out.println("Accepted connection from " + client.getRemoteSocketAddress());

            // 对每个客户端开启独立处理
            new Thread(() -> handleClient(client)).start();
        }
    }

    private void handleClient(Socket client) {
        try (InputStream in = client.getInputStream()) {
            // 读取字节流并按 NAL 单元拆分
            byte[] buffer = new byte[4096];
            int read;

            // 简单的 NAL 单元边界检测（NAL起始码 00 00 01 或 00 00 00 01）
            ByteArrayOutputStream nalBuffer = new ByteArrayOutputStream();

            while ((read = in.read(buffer)) != -1) {
                for (int i = 0; i < read; i++) {
                    nalBuffer.write(buffer[i]);

                    // 检测起始码（只检测 3 字节起始码，便于演示）
                    if (isStartCode(nalBuffer.toByteArray())) {
                        // 完整 NAL 已到达，解码
                        byte[] nalBytes = nalBuffer.toByteArray();
                        nalBuffer.reset();

                        // 交给解码线程
                        decoder.submit(() -> decodeAndRender(nalBytes));
                    }
                }
            }

        } catch (IOException e) {
            System.err.println("Connection error: " + e.getMessage());
        } finally {
            try { client.close(); } catch (IOException ignored) {}
        }
    }

    // 简单的起始码检测（仅示例，实际可使用更完整的实现）
    private boolean isStartCode(byte[] data) {
        if (data.length < 4) return false;
        // 00 00 01
        return data[data.length - 3] == 0x00 &&
               data[data.length - 2] == 0x00 &&
               data[data.length - 1] == 0x01;
    }

    private void decodeAndRender(byte[] h264Bytes) {
        try {
            // JCodec 需要一个 NIOBufferSource
            NIODataSource dataSource = NIOUtils.readableFileChannel(
                    new ByteArrayInputStream(h264Bytes));

            // 只解一帧（简化）
            FrameGrab grab = FrameGrab.createFrameGrab(dataSource);
            Picture picture = grab.getNativeFrame();

            if (picture == null) {
                System.err.println("No frame decoded");
                return;
            }

            // 转成 BufferedImage
            BufferedImage img = AWTUtil.toBufferedImage(picture);

            // 渲染到 UI 线程
            SwingUtilities.invokeLater(() -> imageLabel.setIcon(new ImageIcon(img)));

        } catch (Exception e) {
            System.err.println("Decoding error: " + e.getMessage());
        }
    }

    public static void main(String[] args) throws IOException {
        H264StreamServer server = new H264StreamServer();
        server.start();
    }
}
```

