            while ((line = in.readLine()) != null) {
                Move move = mapper.readValue(line, Move.class);
                Platform.runLater(() -> updateBoard(move));
            }
        } catch (IOException e) {
            e.printStackTrace();
            Platform.runLater(() -> logMessage("Connection lost"));
        }
    }

    private void sendMove(int r, int c) {
        try {
            if (cells[r][c].getText().isEmpty()) {
                Move m = new Move(r, c, mySymbol);
