Main
├── VideoStreamer        // 视频读取、帧压缩
└── SocketSender         // Socket 发送，支持 TLS
```

### 2.3 `VideoStreamer.java`

```java
import org.bytedeco.javacv.*;
import org.bytedeco.javacv.Frame;
import org.bytedeco.javacv.FrameGrabber.Exception;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class VideoStreamer {
    private final FrameGrabber grabber;
    private final BlockingQueue<byte[]> frameQueue; // 线程安全
    private volatile boolean running = true;

    public VideoStreamer(String source, int queueSize) throws Exception {
        this.grabber = new FFmpegFrameGrabber(source);
        this.frameQueue = new LinkedBlockingQueue<>(queueSize);
    }

    public void start() throws Exception {
        grabber.start();
        Thread producer = new Thread(this::produceFrames);
        producer.setDaemon(true);
        producer.start();
    }

    private void produceFrames() {
        Java2DFrameConverter converter = new Java2DFrameConverter();
        try {
            while (running && (grabber.grabImage() != null)) {
                Frame frame = grabber.grabImage();
                if (frame == null) break; // EOF

                // 转成 BufferedImage
                BufferedImage img = converter.getBufferedImage(frame);
                if (img == null) continue;

                // JPEG 压缩，减小传输量
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                ImageIO.write(img, "jpg", baos);
                baos.flush();

                // 把字节数组放入队列，等待发送端取
                byte[] payload = baos.toByteArray();
                frameQueue.put(payload);
            }
        } catch (Throwable e) {
            e.printStackTrace();
        } finally {
            try { grabber.stop(); } catch (Exception ignored) {}
        }
    }

    public byte[] poll() throws InterruptedException {
        return frameQueue.take();
    }

    public void stop() {
        running = false;
    }
}
```

### 2.4 `SocketSender.java`

```java
import javax.net.ssl.*;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.security.KeyStore;
import java.util.concurrent.TimeUnit;

public class SocketSender {
    private final InetSocketAddress addr;
    private final boolean useTLS;
    private final int connectTimeoutMs;

    public SocketSender(String host, int port, boolean useTLS, int connectTimeoutMs) {
        this.addr = new InetSocketAddress(host, port);
        this.useTLS = useTLS;
        this.connectTimeoutMs = connectTimeoutMs;
    }

    public void send(byte[] payload) throws Exception {
        Socket socket = useTLS ? createSSLSocket() : new Socket();

        try {
            socket.connect(addr, connectTimeoutMs);
            OutputStream out = socket.getOutputStream();

            // 发送帧长度（4字节网络字节序）
            out.write(ByteBuffer.allocate(4).putInt(payload.length).array());
            out.write(payload);
            out.flush();
        } finally {
            socket.close();
        }
    }

    private Socket createSSLSocket() throws Exception {
        SSLContext ctx = SSLContext.getInstance("TLS");
        // 如果你有自签名证书或 CA，请在此配置 KeyManager / TrustManager
        ctx.init(null, new TrustManager[]{new X509TrustManager() {
            public java.security.cert.X509Certificate[] getAcceptedIssuers() { return null; }
            public void checkClientTrusted(java.security.cert.X509Certificate[] chain, String authType) {}
            public void checkServerTrusted(java.security.cert.X509Certificate[] chain, String authType) {}
        }}, new java.security.SecureRandom());
        return ctx.getSocketFactory().createSocket();
    }
}
```

> **Tip**：如果你想在本地测试可以先启动一个 **EchoServer**，然后改成 **SSLServerSocket** 监听同一端口。

