### 5.2 客户端（SSL + Swing）

> 下面给出最小可运行的客户端 skeleton，仅展示网络与 UI 交互的框架。

```java
package com.ecommerce.client;

import javax.net.ssl.*;
import javax.swing.*;
import java.awt.*;
import java.io.*;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.cert.CertificateException;

public class SecureChatClient extends JFrame {
    private final SSLSocket socket;
    private final DataInputStream in;
    private final DataOutputStream out;
    private final JTextArea chatArea = new JTextArea(20, 50);
    private final JTextField inputField = new JTextField(40);
    private final JButton sendBtn = new JButton("Send");

    public SecureChatClient(String host, int port, String username, String password)
            throws IOException, GeneralSecurityException {
        // 建立 SSL 连接
        SSLContext ctx = SSLContext.getInstance("TLSv1.2");
        ctx.init(null, new TrustManager[]{new TrustAllCerts()}, new SecureRandom());
        SSLSocketFactory sf = ctx.getSocketFactory();
        socket = (SSLSocket) sf.createSocket(host, port);
        socket.setSoTimeout(300_000);

        in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
        out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));

        // UI
        setTitle("Chat - " + username);
        setLayout(new BorderLayout());
        add(new JScrollPane(chatArea), BorderLayout.CENTER);
        JPanel p = new JPanel();
        p.add(inputField);
        p.add(sendBtn);
        add(p, BorderLayout.SOUTH);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        pack();
        setVisible(true);

        // 认证
        sendMessage(MessageType.AUTH, (username + ":" + password).getBytes());
        Message ack = readMessage();
        if (ack.type != MessageType.ACK) {
            throw new IOException("Auth failed");
        }

        // 启动接收线程
        new Thread(this::receiveLoop).start();

        // 发送按钮监听
        sendBtn.addActionListener(e -> sendText());
    }

    private void receiveLoop() {
        try {
            while (true) {
                Message msg = readMessage();
                switch (msg.type) {
                    case TEXT -> chatArea.append(new String(msg.payload, StandardCharsets.UTF_8) + "\n");
                    case IMAGE -> {
                        // 这里仅演示：把图片写到临时文件并显示
                        Path img = Paths.get("tmp_" + System.currentTimeMillis() + ".jpg");
                        Files.write(img, msg.payload);
                        ImageIcon icon = new ImageIcon(img.toString());
                        JLabel lbl = new JLabel(icon);
                        JOptionPane.showMessageDialog(this, lbl, "Image", JOptionPane.PLAIN_MESSAGE);
                    }
                    case ERROR -> JOptionPane.showMessageDialog(this,
                            new String(msg.payload, StandardCharsets.UTF_8), "Error", JOptionPane.ERROR_MESSAGE);
                }
            }
        } catch (SocketTimeoutException e) {
            SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(this,
                    "客服忙，请稍后再试", "Timeout", JOptionPane.WARNING_MESSAGE));
        } catch (IOException e) {
            SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(this,
                    "连接异常: " + e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE));
        }
    }

    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            sendMessage(MessageType.TEXT, txt.getBytes(StandardCharsets.UTF_8));
            inputField.setText("");
        } catch (IOException ex) {
            JOptionPane.showMessageDialog(this, "Send failed: " + ex.getMessage(),
                    "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    private void sendMessage(MessageType type, byte[] payload) throws IOException {
        out.writeByte(type.ordinal());
        out.writeInt(payload.length);
        out.write(payload);
        out.flush();
    }

    private Message readMessage() throws IOException {
        int type = in.readUnsignedByte();
        int len = in.readInt();
        byte[] payload = new byte[len];
        in.readFully(payload);
        return new Message((byte) type, payload);
    }

    public static void main(String[] args) throws Exception {
        SwingUtilities.invokeLater(() -> {
            try {
                new SecureChatClient("localhost", 8443, "alice", "pass123");
            } catch (Exception e) {
                e.printStackTrace();
            }
        });
    }

    /* ---------- 简易 TrustManager (仅用于示例) ---------- */
    private static class TrustAllCerts implements X509TrustManager {
        public void checkClientTrusted(java.security.cert.X509Certificate[] chain, String authType) {}
        public void checkServerTrusted(java.security.cert.X509Certificate[] chain, String authType) {}
        public java.security.cert.X509Certificate[] getAcceptedIssuers() { return new java.security.cert.X509Certificate[0]; }
    }

    /* ---------- 消息类型枚举 ---------- */
    private enum MessageType { AUTH, TEXT, IMAGE, FILE, ACK, ERROR }
    private static class Message {
        byte type;
        byte[] payload;
        Message(byte t, byte[] p) { type = t; payload = p; }
    }
}
```

**重点安全点**

1. **SSL**：客户端同样使用 TLS。示例中的 `TrustAllCerts` 是为了简化，实际请使用 CA 验证或自签证书的信任链。  
2. **认证**：在连接后立即发送用户名/密码，服务器返回 ACK。  
3. **文件/图片**：对收到的数据做基本类型检查，防止恶意二进制注入。  
4. **UI**：所有 Swing 操作在 EDT 上完成，避免线程安全问题。  
5. **异常**：对连接超时、错误消息进行友好提示，避免信息泄漏。  

