import java.security.MessageDigest;

public final class Utility {

    /** Returns the SHA‑256 hash of a string (hex‑encoded). */
    public static String getHash(String base) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(base.getBytes("UTF-8"));
            StringBuilder hexString = new StringBuilder(2 * hash.length);
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (Exception ex) {
            throw new RuntimeException(ex);
        }
    }

    /* ---------- convenience line printers ---------- */
    public static void printLine(int n)     { printLine(n,'-'); }
    public static void printDoubleLine(int n) { printLine(n,'='); }

    public static void printLine(int n, char pattern) {
        for (int i=0;i<n;i++) System.out.print(pattern);
        System.out.println();
    }
}
