```java
import java.io.*;
import java.util.*;

public final class PlayerRepository {
    private static final String FILE = "players.bin";

    /** Reads *all* players from the binary file. */
    public static List<Player> loadPlayers() {
        List<Player> players = new ArrayList<>();
        try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(FILE))) {
            while (true) {                       // loop until EOF
                try {
                    Player p = (Player) in.readObject();
                    players.add(p);
                } catch (EOFException eof) {
                    break;                      // normal end of file
                }
            }
        } catch (FileNotFoundException e) {
            // file may not exist the first time – that's OK
        } catch (Exception e) {
            System.err.println("Failed to load players: " + e.getMessage());
        }
        return players;
    }

    /** Persist *all* players back to the binary file. */
    public static void savePlayers(List<Player> players) {
        try (ObjectOutputStream out = new ObjectOutputStream(new FileOutputStream(FILE))) {
            for (Player p : players) out.writeObject(p);
        } catch (Exception e) {
            System.err.println("Failed to save players: " + e.getMessage());
        }
    }
}
