```java
@Controller
@RequestMapping("/customers")
@RequiredArgsConstructor
public class CustomerController {
    private final CustomerService custService;
    private final OrgUnitRepository orgRepo;

    // Render customer list
    @GetMapping
    @PreAuthorize("hasAnyRole('ROLE_EMPLOYEE','ROLE_ADMIN')")
    public String list(@RequestParam(required = false) String name,
                       @RequestParam(required = false) Long orgId,
                       Model model) {

        Specification<Customer> spec = Specification.where(null);
        if (name != null && !name.isBlank())
            spec = spec.and((root, query, cb) -> cb.like(cb.lower(root.get("name")), "%" + name.toLowerCase() + "%"));
        if (orgId != null)
            spec = spec.and((root, query, cb) -> cb.equal(root.get("orgUnit").get("id"), orgId));

        List<Customer> customers = custService.custRepo.findAll(spec);
        model.addAttribute("customers", customers);

        // For the cascading dropdown
        List<OrgUnit> level1 = orgRepo.findByParentId(null);
        model.addAttribute("level1", level1);
        return "customer/list";
    }

    // Render create form
    @GetMapping("/new")
    @PreAuthorize("hasRole('ROLE_EMPLOYEE')")
    public String newForm(Model model) {
        model.addAttribute("customer", new CustomerDTO());
        List<OrgUnit> level1 = orgRepo.findByParentId(null);
        model.addAttribute("level1", level1);
        return "customer/form";
    }

    // Handle create
    @PostMapping
    @PreAuthorize("hasRole('ROLE_EMPLOYEE')")
    public String save(@Valid @ModelAttribute CustomerDTO dto, BindingResult br, RedirectAttributes ra) {
        if (br.hasErrors()) return "customer/form";
        custService.save(dto);
        ra.addFlashAttribute("msg", "Customer saved successfully");
        return "redirect:/customers";
    }

    // Edit, delete, view, etc. – analogous
}
```

> **Security tip:** `@PreAuthorize` guards each endpoint; `@Valid` prevents malformed input; `BindingResult` returns user‑friendly errors.

