            AVCodec codec = avcodec.avcodec_find_encoder(avcodec.AV_CODEC_ID_H264);
            if (codec == null) throw new IOException("H264 encoder not found");

            AVCodecContext codecCtx = avcodec.avcodec_alloc_context3(codec);
            codecCtx.bit_rate(400_000);          // 400 kbps，适合单帧小图
            codecCtx.width(frame.imageWidth);
            codecCtx.height(frame.imageHeight);
            codecCtx.time_base().num(1).den(25); // 25 fps
            codecCtx.gop_size(10);
            codecCtx.max_b_frames(1);
            codecCtx.pix_fmt(avutil.AV_PIX_FMT_YUV420P);

            if ((codecCtx.flags() & avcodec.AV_CODEC_FLAG_GLOBAL_HEADER) != 0)
                codecCtx.flags(codecCtx.flags() | avcodec.AV_CODEC_FLAG_GLOBAL_HEADER);

            if (avcodec.avcodec_open2(codecCtx, codec, (AVDictionary) null) < 0)
                throw new IOException("Could not open H264 encoder");

            // 2. 将 Frame 转为 AVFrame
            AVFrame avFrame = avcodec.av_frame_alloc();
            avFrame.format(codecCtx.pix_fmt());
            avFrame.width(codecCtx.width());
            avFrame.height(codecCtx.height());
            avcodec.av_frame_get_buffer(avFrame, 32);

