### 3.1. Common utilities

```java
package com.ecommerce.chat.common;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import javax.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;

public class CryptoUtil {
    // HMAC‑SHA256 key (in production generate per‑session)
    private static final byte[] HMAC_KEY = "supersecretkey".getBytes(StandardCharsets.UTF_8);
    private static final String HMAC_ALGO = "HmacSHA256";

    public static String computeHmac(byte[] data) throws GeneralSecurityException {
        Mac mac = Mac.getInstance(HMAC_ALGO);
        mac.init(new SecretKeySpec(HMAC_KEY, HMAC_ALGO));
        return Base64.getEncoder().encodeToString(mac.doFinal(data));
    }

    // Sanitize filenames – keep only safe chars
    public static String sanitizeFileName(String input) {
        return input.replaceAll("[^A-Za-z0-9._-]", "_");
    }

    // Limit file size
    public static boolean checkFileSize(long size, long maxSize) {
        return size <= maxSize;
    }

    // Serialize JSON to bytes (UTF‑8)
    public static byte[] jsonToBytes(JsonObject obj) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        try (JsonWriter writer = Json.createWriter(out)) {
            writer.writeObject(obj);
        }
        return out.toByteArray();
    }

    // Deserialize
    public static JsonObject bytesToJson(byte[] bytes) {
        try (InputStream in = new ByteArrayInputStream(bytes);
             JsonReader reader = Json.createReader(in)) {
            return reader.readObject();
        }
    }
}
