### 3.2. Server – core logic

```java
package com.ecommerce.chat.server;

import com.ecommerce.chat.common.CryptoUtil;

import javax.net.ssl.*;
import javax.json.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;

public class ChatServer {
    // Config
    private static final int PORT = 8443;
    private static final int MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB

    // Map<agentId, AgentHandler>
    private final Map<String, AgentHandler> agents = new ConcurrentHashMap<>();
    private final ExecutorService threadPool = Executors.newFixedThreadPool(20);

    public void start() throws Exception {
        SSLServerSocketFactory ssf = createSslServerFactory();
        try (SSLServerSocket serverSocket = (SSLServerSocket) ssf.createServerSocket(PORT)) {
            System.out.println("Server listening on port " + PORT);
            while (true) {
                SSLSocket socket = (SSLSocket) serverSocket.accept();
                // Determine role: client or agent by inspecting first message
                threadPool.submit(new InitialHandler(socket));
            }
        }
    }

    private static SSLServerSocketFactory createSslServerFactory() throws Exception {
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream("keystore.jks"), "keystorepass".toCharArray());

        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        kmf.init(ks, "keypass".toCharArray());

        KeyStore ts = KeyStore.getInstance("JKS");
        ts.load(new FileInputStream("truststore.jks"), "truststorepass".toCharArray());

        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(ts);

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), new SecureRandom());
        return ctx.getServerSocketFactory();
    }

    // ---- inner classes ---------------------------------------------------------

    /** First message decides if this is a customer or an agent */
    private class InitialHandler implements Runnable {
        private final SSLSocket socket;

        InitialHandler(SSLSocket socket) { this.socket = socket; }

        @Override
        public void run() {
            try (socket;
                 BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                 BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()))) {

                String line = reader.readLine();
                if (line == null) return;

                JsonObject init = CryptoUtil.bytesToJson(line.getBytes(StandardCharsets.UTF_8));
                String role = init.getString("role"); // "customer" or "agent"
                if ("customer".equalsIgnoreCase(role)) {
                    handleCustomer(socket, init);
                } else if ("agent".equalsIgnoreCase(role)) {
                    handleAgent(socket, init);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    private void handleCustomer(SSLSocket socket, JsonObject init) {
        String userId = init.getString("userId");
        System.out.println("Customer connected: " + userId);
        CustomerHandler handler = new CustomerHandler(socket, userId);
        threadPool.submit(handler);
    }

    private void handleAgent(SSLSocket socket, JsonObject init) {
        String agentId = init.getString("agentId");
        System.out.println("Agent connected: " + agentId);
        AgentHandler handler = new AgentHandler(socket, agentId);
        agents.put(agentId, handler);
        threadPool.submit(handler);
    }

    // -------------------------------------------------------------------------

    /** Handles one customer conversation (single thread per customer) */
    private class CustomerHandler implements Runnable {
        private final SSLSocket socket;
        private final String userId;
        private final Map<String, Integer> sessionSeq = new ConcurrentHashMap<>();
        private final ExecutorService filePool = Executors.newSingleThreadExecutor();

        CustomerHandler(SSLSocket socket, String userId) {
            this.socket = socket;
            this.userId = userId;
        }

        @Override
        public void run() {
            try (socket;
                 BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                 BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()))) {

                // Step 1: Wait for the first request
                String line = reader.readLine();
                JsonObject request = CryptoUtil.bytesToJson(line.getBytes(StandardCharsets.UTF_8));
                if (!"request".equals(request.getString("type"))) {
                    writer.write("error: first message must be a request\n");
                    writer.flush();
                    return;
                }

                // Find a free agent
                AgentHandler freeAgent = null;
                for (AgentHandler a : agents.values()) {
                    if (a.tryReserve(userId)) {
                        freeAgent = a;
                        break;
                    }
                }

                JsonObject response;
                if (freeAgent == null) {
                    // busy
                    response = Json.createObjectBuilder()
                            .add("type", "control")
                            .add("command", "busy")
                            .build();
                } else {
                    String sessionId = UUID.randomUUID().toString();
                    response = Json.createObjectBuilder()
                            .add("type", "control")
                            .add("command", "accept")
                            .add("sessionId", sessionId)
                            .build();
                    // tell agent about the new session
                    freeAgent.notifyNewSession(userId, sessionId);
                }
                writer.write(response.toString() + "\n");
                writer.flush();

                // Main loop
                while ((line = reader.readLine()) != null) {
                    JsonObject msg = CryptoUtil.bytesToJson(line.getBytes(StandardCharsets.UTF_8));
                    String type = msg.getString("type");
                    String sessionId = msg.getString("sessionId");
                    int seq = msg.getInt("seq");

                    // HMAC verification
                    String hmac = msg.getString("hmac");
                    JsonObject withoutHmac = Json.createObjectBuilder(msg)
                            .remove("hmac")
                            .build();
                    String calc = CryptoUtil.computeHmac(CryptoUtil.jsonToBytes(withoutHmac));
                    if (!MessageDigest.isEqual(hmac.getBytes(), calc.getBytes())) {
                        System.out.println("HMAC mismatch – discarding");
                        continue;
                    }

                    // Simple seq check
                    sessionSeq.merge(sessionId, seq, (old, newv) -> Math.max(old, newv));

                    // Persist
                    persistMessage(userId, sessionId, msg);

                    // Forward to agent
                    AgentHandler agent = freeAgent; // already reserved
                    if (agent != null) agent.forwardMessage(msg);
                }
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                // Cleanup reservations
                for (AgentHandler a : agents.values()) {
                    a.release(userId);
                }
            }
        }

        private void persistMessage(String userId, String sessionId, JsonObject msg) {
            Path logFile = Paths.get("logs", userId + "_" + sessionId + ".json");
            try {
                Files.createDirectories(logFile.getParent());
                // Append line (one JSON per line)
                Files.writeString(logFile, msg.toString() + System.lineSeparator(),
                        StandardOpenOption.CREATE, StandardOpenOption.APPEND);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    /** Handles one agent (one thread) – can serve many users */
    private class AgentHandler implements Runnable {
        private final SSLSocket socket;
        private final String agentId;
        private final BlockingQueue<JsonObject> inbox = new LinkedBlockingQueue<>();
        private final Set<String> activeUsers = ConcurrentHashMap.newKeySet();

        AgentHandler(SSLSocket socket, String agentId) {
            this.socket = socket;
            this.agentId = agentId;
        }

        @Override
        public void run() {
            try (socket;
                 BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                 BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()))) {

                // Listen for messages from agent
                String line;
                while ((line = reader.readLine()) != null) {
                    JsonObject msg = CryptoUtil.bytesToJson(line.getBytes(StandardCharsets.UTF_8));
                    handleAgentMessage(msg);
                }
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                // Clean up reservations
                for (String userId : activeUsers) {
                    agents.values().forEach(a -> a.release(userId));
                }
            }
        }

        private void handleAgentMessage(JsonObject msg) {
            String type = msg.getString("type");
            if ("control".equals(type)) {
                String command = msg.getString("command");
                if ("accept".equalsIgnoreCase(command)) {
                    String sessionId = msg.getString("sessionId");
                    // Nothing to do here – already accepted
                } else if ("reject".equalsIgnoreCase(command)) {
                    String sessionId = msg.getString("sessionId");
                    // Notify customer
                }
            } else {
                // Forward to customer
                String userId = msg.getString("userId");
                // find the socket for this user (omitted: we could keep a map in the server)
                // For illustration:
                // socketToUser.get(userId).write(msg.toString());
            }
        }

        /** Called by server when a new session is created */
        void notifyNewSession(String userId, String sessionId) {
            activeUsers.add(userId);
            JsonObject msg = Json.createObjectBuilder()
                    .add("type", "control")
                    .add("command", "new_session")
                    .add("userId", userId)
                    .add("sessionId", sessionId)
                    .build();
            // send to agent
            try (BufferedWriter writer = new BufferedWriter(
                    new OutputStreamWriter(socket.getOutputStream()))) {
                writer.write(msg.toString() + "\n");
                writer.flush();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        /** Reserve this agent for a specific user; return true if free */
        boolean tryReserve(String userId) {
            return activeUsers.add(userId);
        }

        void release(String userId) { activeUsers.remove(userId); }

        /** Forward a customer message to the agent */
        void forwardMessage(JsonObject msg) {
            try (BufferedWriter writer = new BufferedWriter(
                    new OutputStreamWriter(socket.getOutputStream()))) {
                writer.write(msg.toString() + "\n");
                writer.flush();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    // -------------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        new ChatServer().start();
    }
}
```

> **What the server does**  
> * Accepts TLS connections.  
> * Distinguishes *customer* vs *agent* by the first JSON message (`{"role":"customer", "userId":"1234"}` or `{"role":"agent","agentId":"A1"}`).  
> * Keeps a map of agents.  
> * On a new customer request, reserves an available agent (simple set logic).  
> * Forwards all messages (with HMAC validation) from customer to the agent and vice‑versa.  
> * Persists each message to a per‑session log file (`logs/<userId>_<sessionId>.json`).  

### 3.3. Client (Swing UI)

```java
package com.ecommerce.chat.client;

import com.ecommerce.chat.common.CryptoUtil;
import com.ecommerce.chat.common.FileUtil; // Utility for file selection / validation
import com.ecommerce.chat.common.MessageBuilder;

import javax.swing.*;
