import java.awt.event.ActionEvent;
import java.io.*;
import java.security.*;
import java.util.concurrent.*;

public class CustomerClient extends JFrame {
    private final JTextArea chatArea = new JTextArea(20, 50);
    private final JTextField inputField = new JTextField(40);
    private final JButton sendBtn = new JButton("Send");
    private final JButton imgBtn = new JButton("Send Image");
    private final JButton fileBtn = new JButton("Send File");

    private SSLSocket socket;
    private BufferedWriter writer;
    private BufferedReader reader;
    private final String userId;
    private String sessionId; // assigned by server
    private int seq = 0;
    private final ExecutorService recvPool = Executors.newSingleThreadExecutor();

    public CustomerClient(String userId) {
        this.userId = userId;
        initUI();
        connect();
    }

    private void initUI() {
        setTitle("Customer Chat – User: " + userId);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        chatArea.setEditable(false);
        JPanel panel = new JPanel(new BorderLayout());
        panel.add(chatArea, BorderLayout.CENTER);

        JPanel south = new JPanel();
        south.add(inputField);
        south.add(sendBtn);
        south.add(imgBtn);
        south.add(fileBtn);
        panel.add(south, BorderLayout.SOUTH);

        add(panel);
        pack();
        setLocationRelativeTo(null);
        setVisible(true);

        // Action listeners
        sendBtn.addActionListener(e -> sendText());
        inputField.addActionListener(e -> sendText());
        imgBtn.addActionListener(e -> sendImage());
        fileBtn.addActionListener(e -> sendFile());
    }

    private void connect() {
        try {
            SSLContext ctx = SSLContext.getInstance("TLSv1.3");
            ctx.init(null, new TrustManager[]{new X509TrustManager() {
                public void checkClientTrusted(java.security.cert.X509Certificate[] x509Certificates, String s) {}
                public void checkServerTrusted(java.security.cert.X509Certificate[] x509Certificates, String s) {}
                public java.security.cert.X509Certificate[] getAcceptedIssuers() { return null; }
            }}, new SecureRandom()); // In prod, load proper truststore

            SSLSocketFactory sf = ctx.getSocketFactory();
            socket = (SSLSocket) sf.createSocket("localhost", 8443);
            socket.startHandshake();

            writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));
            reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));

            // Initial role announcement
            JsonObject init = MessageBuilder.roleAnnounce("customer", userId);
            writer.write(init.toString() + "\n");
            writer.flush();

            // Wait for server response to the initial request
            String line = reader.readLine();
            JsonObject resp = CryptoUtil.bytesToJson(line.getBytes());
            String command = resp.getString("command");
            if ("busy".equalsIgnoreCase(command)) {
                JOptionPane.showMessageDialog(this, "All agents are busy. Try later.", "Busy", JOptionPane.WARNING_MESSAGE);
                System.exit(0);
            } else if ("accept".equalsIgnoreCase(command)) {
                sessionId = resp.getString("sessionId");
                // Start receiver thread
                recvPool.submit(this::receiveLoop);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void sendText() {
        String text = inputField.getText().trim();
        if (text.isEmpty() || sessionId == null) return;
        try {
            JsonObject msg = MessageBuilder.textMsg(sessionId, ++seq, text);
            writer.write(msg.toString() + "\n");
            writer.flush();
            chatArea.append("Me: " + text + "\n");
            inputField.setText("");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        int ret = fc.showOpenDialog(this);
        if (ret != JFileChooser.APPROVE_OPTION) return;
        File file = fc.getSelectedFile();
        try {
            byte[] data = Files.readAllBytes(file.toPath());
            if (!CryptoUtil.checkFileSize(data.length, 10 * 1024 * 1024)) {
                JOptionPane.showMessageDialog(this, "File too large", "Error", JOptionPane.ERROR_MESSAGE);
                return;
            }
            JsonObject msg = MessageBuilder.fileMsg(sessionId, ++seq, CryptoUtil.sanitizeFileName(file.getName()),
                    Base64.getEncoder().encodeToString(data), "image/png");
            writer.write(msg.toString() + "\n");
            writer.flush();
            chatArea.append("Me sent an image: " + file.getName() + "\n");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        int ret = fc.showOpenDialog(this);
        if (ret != JFileChooser.APPROVE_OPTION) return;
        File file = fc.getSelectedFile();
        try {
            byte[] data = Files.readAllBytes(file.toPath());
            if (!CryptoUtil.checkFileSize(data.length, 10 * 1024 * 1024)) {
                JOptionPane.showMessageDialog(this, "File too large", "Error", JOptionPane.ERROR_MESSAGE);
                return;
            }
            JsonObject msg = MessageBuilder.fileMsg(sessionId, ++seq, CryptoUtil.sanitizeFileName(file.getName()),
                    Base64.getEncoder().encodeToString(data), Files.probeContentType(file.toPath()));
            writer.write(msg.toString() + "\n");
            writer.flush();
            chatArea.append("Me sent a file: " + file.getName() + "\n");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void receiveLoop() {
        String line;
        try {
            while ((line = reader.readLine()) != null) {
                JsonObject msg = CryptoUtil.bytesToJson(line.getBytes());
                String type = msg.getString("type");
                if ("text".equals(type)) {
                    String text = msg.getString("text");
                    chatArea.append("Agent: " + text + "\n");
                } else if ("file".equals(type)) {
                    String fname = msg.getString("fileName");
                    String mime = msg.getString("mime");
                    byte[] data = Base64.getDecoder().decode(msg.getString("data"));
                    // Save to temporary dir
                    Path tmp = Paths.get("tmp", fname);
                    Files.createDirectories(tmp.getParent());
                    Files.write(tmp, data);
                    chatArea.append("Agent sent a file: " + fname + " (" + mime + ")\n");
                } else if ("control".equals(type)) {
                    // handle other control messages (busy, etc.)
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new CustomerClient("user1234"));
    }
}
