```java
import com.itextpdf.forms.PdfAcroForm;
import com.itextpdf.forms.fields.PdfFormField;
import com.itextpdf.kernel.pdf.PdfDocument;
import com.itextpdf.kernel.pdf.PdfReader;

public class NumPagesFromPdf {
    public static void main(String[] args) throws Exception {
        String pdfPath = "input.pdf";
        PdfDocument pdfDoc = new PdfDocument(new PdfReader(pdfPath));

        // 1. Получаем AcroForm
        PdfAcroForm acroForm = PdfAcroForm.getAcroForm(pdfDoc, false);
        if (acroForm == null) {
            System.out.println("В PDF нет AcroForm");
            pdfDoc.close();
            return;
        }

        // 2. Берём поле NUMPAGES
        PdfFormField numPagesField = acroForm.getField("NUMPAGES");
        if (numPagesField == null) {
            System.out.println("Поле NUMPAGES не найдено");
            pdfDoc.close();
            return;
        }

        // 3. Вычисляем значение поля (если оно расчётное)
        //    В iText 7 поле «расчётное» будет автоматически обновлено при вызове
        //    acroForm.getFormFields() после загрузки документа.
        //    Если скрипт явно не выполняется, можно вызвать:
        acroForm.getFormFields().forEach((k, v) -> v.calculate());

        String value = numPagesField.getValueAsString();
        System.out.println("NUMPAGES = " + value);

        pdfDoc.close();
    }
}
```

