## 4. Как «поправить» XML, добавив точное число страниц

Если вам нужно, чтобы XML уже содержал точное число страниц, можно
сформировать его программно, не парсить исходный файл.

```java
import org.w3c.dom.*;
import javax.xml.parsers.*;
import javax.xml.transform.*;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;
import java.io.*;

public class GenerateXmlWithPages {
    public static void main(String[] args) throws Exception {
        // Считаем страницы в PDF
        int nPages = 0;
        try (PDDocument doc = PDDocument.load(new File("input.pdf"))) {
            nPages = doc.getNumberOfPages();
        }

        // Создаём DOM‑дерево
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        DocumentBuilder db = dbf.newDocumentBuilder();
        Document xmlDoc = db.newDocument();

        Element root = xmlDoc.createElement("document");
        root.setAttribute("numPages", String.valueOf(nPages));
        xmlDoc.appendChild(root);

        // Добавляем, например, заголовок
        Element title = xmlDoc.createElement("title");
        title.setTextContent("Пример");
        root.appendChild(title);

        // Сохраняем в файл
        Transformer tf = TransformerFactory.newInstance().newTransformer();
        tf.setOutputProperty(OutputKeys.INDENT, "yes");
        tf.transform(new DOMSource(xmlDoc), new StreamResult(new File("output.xml")));

        System.out.println("XML с числом страниц успешно создан: output.xml");
    }
}
```

