## 1. ChatServer.java

```java
package com.example.chat;

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

// A simple multithreaded chat server
public class ChatServer {
    private final int port;
    private final Set<PrintWriter> clientWriters = ConcurrentHashMap.newKeySet();

    public ChatServer(int port) {
        this.port = port;
    }

    public void start() throws IOException {
        ServerSocket serverSocket = new ServerSocket(port);
        System.out.println("Chat server started on port " + port);

        while (true) {
            Socket clientSocket = serverSocket.accept();
            System.out.println("New client: " + clientSocket.getRemoteSocketAddress());
            handleClient(clientSocket);
        }
    }

    private void handleClient(Socket socket) {
        // Each client runs in its own thread
        new Thread(() -> {
            try (
                BufferedReader in = new BufferedReader(
                    new InputStreamReader(socket.getInputStream()));
                PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
            ) {
                clientWriters.add(out);
                // Send a welcome message
                out.println("Welcome to the chat! Type your messages below.");

                String line;
                while ((line = in.readLine()) != null) {
                    broadcast(line, out);
                }
            } catch (IOException e) {
                System.err.println("Client error: " + e.getMessage());
            } finally {
                // Clean up
                clientWriters.remove(out);
                try { socket.close(); } catch (IOException ignored) {}
                System.out.println("Client disconnected: " + socket.getRemoteSocketAddress());
            }
        }).start();
    }

    private void broadcast(String message, PrintWriter sender) {
        for (PrintWriter writer : clientWriters) {
            if (writer != sender) { // Don't echo back to the sender
                writer.println(message);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        int port = 12345; // default port
        if (args.length > 0) {
            port = Integer.parseInt(args[0]);
        }
        new ChatServer(port).start();
    }
}
```

