## 1. The core logic

```java
import jakarta.mail.*;
import jakarta.mail.search.FlagTerm;
import jakarta.mail.internet.MimeMessage;
import jakarta.mail.internet.MimeMultipart;
import jakarta.mail.internet.MimeBodyPart;

import java.util.Hashtable;
import java.util.Properties;

/**
 * Simple IMAP client that pulls all unseen messages and puts
 * (subject → plain‑text body) into a Hashtable.
 *
 * @author YourName
 */
public class ImapMailCollector {

    /**
     * Connects to the IMAP server, fetches all unseen messages, and
     * returns a Hashtable mapping each message’s subject to its body text.
     *
     * @param imapHost   The IMAP host (e.g., "imap.gmail.com")
     * @param username   IMAP username
     * @param password   IMAP password (or app‑specific password)
     * @return Hashtable with subject as key and body text as value
     * @throws MessagingException if anything goes wrong
     */
    public static Hashtable<String, String> collectUnseen(String imapHost,
                                                          String username,
                                                          String password) throws MessagingException {

        // 1. Set up the properties for an IMAP + TLS connection
        Properties props = new Properties();
        props.put("mail.store.protocol", "imaps"); // use IMAP over TLS
        props.put("mail.imaps.host", imapHost);
        props.put("mail.imaps.port", "993"); // default IMAPS port
        props.put("mail.imaps.ssl.enable", "true");
        props.put("mail.imaps.auth", "true");

        // 2. Create a Session (no debug to keep logs clean)
        Session session = Session.getInstance(props);

        // 3. Connect to the store
        Store store = session.getStore("imaps");
        store.connect(imapHost, username, password);

        // 4. Open the INBOX folder in read‑only mode
        Folder inbox = store.getFolder("INBOX");
        inbox.open(Folder.READ_ONLY);

        // 5. Search for messages that are NOT SEEN yet
        Message[] messages = inbox.search(new FlagTerm(new Flags(Flags.Flag.SEEN), false));

        // 6. Prepare the hashtable
        Hashtable<String, String> result = new Hashtable<>(messages.length);

        // 7. Loop over each message
        for (Message msg : messages) {
            String subject = msg.getSubject();          // may be null
            String body = getTextFromMessage(msg);      // plain‑text body

            if (subject != null && body != null) {
                result.put(subject, body);
            }
        }

        // 8. Clean up
        inbox.close(false);
        store.close();

        return result;
    }

    /**
     * Extracts the first plain‑text part of a MimeMessage.
     * Handles simple text, text/html, and multipart messages.
     *
     * @param message The message to parse
     * @return The body as a String, or null if no suitable part is found
     * @throws MessagingException
     */
    private static String getTextFromMessage(Message message) throws MessagingException {
        try {
            Object content = message.getContent();

            if (content instanceof String) {          // simple text
                return (String) content;
            }

            if (content instanceof MimeMultipart) {   // multipart
                return getTextFromMimeMultipart((MimeMultipart) content);
            }

            // Other types (e.g., application/pdf) are ignored
        } catch (Exception e) {
            // Wrap any exception as MessagingException
            throw new MessagingException("Failed to extract body", e);
        }
        return null;
    }

    /**
     * Recursively extracts text from a multipart object.
     *
     * @param multipart The multipart container
     * @return The first plain‑text body found, or null
     * @throws Exception
     */
    private static String getTextFromMimeMultipart(MimeMultipart multipart) throws Exception {
        for (int i = 0; i < multipart.getCount(); i++) {
            BodyPart part = multipart.getBodyPart(i);
            Object partContent = part.getContent();

            if (partContent instanceof String) {
                // Prefer text/plain over text/html
                if (part.isMimeType("text/plain")) {
                    return (String) partContent;
                }
            } else if (partContent instanceof MimeMultipart) {
                // Recursive descent for nested multiparts
                String nested = getTextFromMimeMultipart((MimeMultipart) partContent);
                if (nested != null) return nested;
            }
        }
        return null; // none found
    }

    // ------------------------------------------------------------------
    // Example main method – replace credentials with your own
    // ------------------------------------------------------------------
    public static void main(String[] args) {
        try {
            String imapHost = "imap.example.com";
            String username = "your.email@example.com";
            String password = "yourPassword";

            Hashtable<String, String> mailMap = collectUnseen(imapHost, username, password);

            // Demo: print all subject–body pairs
            for (String subj : mailMap.keySet()) {
                System.out.println("Subject: " + subj);
                System.out.println("Body:   " + mailMap.get(subj));
                System.out.println("-----------");
            }
        } catch (MessagingException e) {
            e.printStackTrace();
        }
    }
}
```

### How it works

| Step | What happens | Why it matters |
|------|--------------|----------------|
| **Properties** | `mail.store.protocol=imaps`, `mail.imaps.ssl.enable=true` | Connects to IMAP over TLS (port 993). |
| **Session** | `Session.getInstance(props)` | Holds the configuration for the connection. |
| **Store** | `store.connect(...)` | Authenticates against the IMAP server. |
| **Folder** | `inbox = store.getFolder("INBOX")` | Targets the inbox. |
| **Message search** | `FlagTerm(FIND UNSEEN)` | Avoids re‑processing messages. |
| **Body extraction** | `getTextFromMessage()` + recursive `getTextFromMimeMultipart()` | Handles plain text, HTML, and multipart formats. |
| **Hashtable** | `new Hashtable<>(messages.length)` | Stores the results in a key/value map. |
| **Clean‑up** | `folder.close()`, `store.close()` | Releases network resources. |

