```java
import java.io.*;
import java.nio.file.Files;

public class FFmpegEncoder implements AutoCloseable {

    private Process ffmpegProcess;
    private OutputStream ffmpegStdin;   // 给 ffmpeg 送图片
    private InputStream ffmpegStdout;   // 从 ffmpeg 取 H264 bitstream

    /**
     * 启动 ffmpeg 进程，输入是 image2pipe（stdin），输出是 H264 bitstream
     */
    public FFmpegEncoder(int width, int height, int fps, int bitrate) throws IOException {
        // 你可以在这里调整 ffmpeg 参数
        String cmd = String.format(
                "ffmpeg -y -f image2pipe -vcodec png -r %d -i - -c:v libx264 -preset veryfast " +
                "-tune zerolatency -x264opts keyint=%d:min-keyint=%d " +
                "-b:v %dk -maxrate %dk -bufsize %dk -pix_fmt yuv420p -f h264 -",
                fps, fps, fps, bitrate, bitrate, bitrate);

        ProcessBuilder pb = new ProcessBuilder(cmd.split(" "));
        pb.redirectErrorStream(true); // 把 stderr 也合并进 stdout（方便调试）
        ffmpegProcess = pb.start();

        ffmpegStdin = ffmpegProcess.getOutputStream();
        ffmpegStdout = ffmpegProcess.getInputStream();

        // 可选：监控 ffmpeg 的 stderr
        new Thread(() -> {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(ffmpegProcess.getErrorStream()))) {
                String line;
                while ((line = br.readLine()) != null) {
                    System.err.println("[ffmpeg] " + line);
                }
            } catch (IOException ignored) {}
        }).start();
    }

    /**
     * 把一帧 BufferedImage 编码成 PNG 并写入 ffmpeg 的 stdin
     */
    public void encodeFrame(java.awt.image.BufferedImage img) throws IOException {
        // 这里直接使用 ImageIO 生成 PNG（PNG 比 JPEG 对齐更简单）
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ImageIO.write(img, "png", baos);
        byte[] pngData = baos.toByteArray();

        ffmpegStdin.write(pngData);
        ffmpegStdin.flush();  // 让 ffmpeg 立刻处理
    }

    /**
     * 读取 ffmpeg 输出的 H264 bitstream，返回单个完整 frame（NALU）
     * 注意：这里的实现非常粗糙，真实项目需要更精准的帧分隔
     */
    public byte[] readH264Frame() throws IOException {
        // 简单实现：一次性读全部（适合低帧率/小分辨率）
        return ffmpegStdout.readAllBytes(); // 在生产环境请使用缓冲 + frame boundary
    }

    @Override
    public void close() throws IOException {
        ffmpegStdin.close();
        ffmpegStdout.close();
        ffmpegProcess.destroy();
    }
}
```

> **为什么要用 PNG？**  
> `ffmpeg -f image2pipe` 能直接接收 PNG/JPEG/PGM 等。PNG 维持无损、无色差，且与 JPEG 的压缩差异对 H.264 编码影响更小。

