package com.example.dynamicds;

import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.jdbc.DataSourceBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.datasource.lookup.AbstractRoutingDataSource;

import javax.sql.DataSource;
import java.util.HashMap;
import java.util.Map;

@Configuration
public class DataSourceConfig {

    // ① 主库
    @Bean(name = "dsPrimary")
    @Qualifier("dsPrimary")
    public DataSource primaryDataSource() {
        return DataSourceBuilder.create()
                .url("jdbc:mysql://localhost:3306/primary_db")
                .username("root")
                .password("root")
                .driverClassName("com.mysql.cj.jdbc.Driver")
                .build();
    }

    // ② 从库A
    @Bean(name = "dsA")
    @Qualifier("dsA")
    public DataSource dsA() {
        return DataSourceBuilder.create()
                .url("jdbc:mysql://localhost:3306/a_db")
                .username("root")
                .password("root")
                .driverClassName("com.mysql.cj.jdbc.Driver")
                .build();
    }

    // ③ 从库B
    @Bean(name = "dsB")
    @Qualifier("dsB")
    public DataSource dsB() {
        return DataSourceBuilder.create()
                .url("jdbc:mysql://localhost:3306/b_db")
                .username("root")
                .password("root")
                .driverClassName("com.mysql.cj.jdbc.Driver")
                .build();
    }

    // ④ 统一路由数据源
    @Bean
    public AbstractRoutingDataSource routingDataSource(
            @Qualifier("dsPrimary") DataSource primary,
            @Qualifier("dsA") DataSource dsA,
            @Qualifier("dsB") DataSource dsB) {

        RoutingDataSource routingDataSource = new RoutingDataSource();

        Map<Object, Object> targetDataSources = new HashMap<>();
        targetDataSources.put("primary", primary);  // 默认
        targetDataSources.put("dsA", dsA);
        targetDataSources.put("dsB", dsB);

        routingDataSource.setTargetDataSources(targetDataSources);
        routingDataSource.setDefaultTargetDataSource(primary); // 默认数据源
        return routingDataSource;
    }
}
