package com.example.security.controller;

import com.example.security.config.JwtUtil;
import com.example.security.entity.User;
import com.example.security.service.UserService;
import lombok.Data;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
@Validated
public class AuthController {

    private final UserService userService;
    private final JwtUtil jwtUtil;

    /* =================== 1. 注册 =================== */
    @PostMapping("/register")
    public ResponseEntity<?> register(@Valid @RequestBody RegisterRequest req) {
        User newUser = userService.register(req.getUsername(), req.getPassword(), req.getEmail());
        return ResponseEntity.ok("User registered: " + newUser.getUsername());
    }

    /* =================== 2. 登录 =================== */
    @PostMapping("/login")
    public ResponseEntity<?> login(@Valid @RequestBody LoginRequest req) {
        // 这里用 Spring Security 的 AuthenticationManager 进行身份校验
        try {
            var auth = authenticationManager
                    .authenticate(new UsernamePasswordAuthenticationToken(req.getUsername(), req.getPassword()));

            // 生成 token
            String token = jwtUtil.generateToken(req.getUsername());
            return ResponseEntity.ok(new JwtResponse(token));
        } catch (Exception e) {
            return ResponseEntity.status(401).body("Invalid username/password");
        }
    }

    /* =================== 3. 注销 =================== */
    @PostMapping("/logout")
    public ResponseEntity<?> logout(HttpServletRequest request) {
        // 简单实现：客户端直接删除存储的 token。服务器可维护黑名单
        String authHeader = request.getHeader("Authorization");
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            String token = authHeader.substring(7);
            blacklistService.addToken(token); // 假设有 BlacklistService
        }
        return ResponseEntity.ok("Logged out");
    }

    /* =================== DTOs =================== */
    @Data
    public static class RegisterRequest {
        @NotBlank @Size(min = 3, max = 20)
        private String username;
        @NotBlank @Size(min = 6, max = 32)
        private String password;
        @Email @NotBlank
        private String email;
    }

    @Data
    public static class LoginRequest {
        @NotBlank
        private String username;
        @NotBlank
        private String password;
    }

    @Data
    public static class JwtResponse {
        private final String token;
    }
}
```

> **实现细节**  
> - `authenticationManager.authenticate(...)` 会触发 `UserDetailsService` + `PasswordEncoder` 进行校验。  
> - `login` 仅返回 JWT，前端需自行把它放在 `Authorization: Bearer <token>` 中请求受保护接口。  
> - `logout` 通过一个 **blacklist**（内存 Map / Redis）记录已登出的 token，防止短时间内再次使用。生产环境可使用 Redis TTL 自动过期。

