```ts
import { Request, Response } from 'express';
import { loginUser } from '../services/auth.service';
import logger from '../utils/logger';

export const login = async (req: Request, res: Response) => {
  try {
    const { email, password, deviceId } = req.body;
    // 基础校验（可使用 joi 或 class-validator）
    if (!email || !password) {
      return res.status(400).json({ error: 'Missing credentials' });
    }

    const token = await loginUser(email, password, deviceId);
    // 登录成功
    res.status(200).json({ token });
  } catch (err: any) {
    // 统一错误处理
    logger.warn(`Login error: ${err.message}`, err);
    if (err.name === 'UnauthorizedError') {
      return res.status(401).json({ error: 'Invalid credentials' });
    }
    res.status(500).json({ error: 'Internal server error' });
  }
};
```

> **提示**  
> - 错误信息必须保持通用，避免泄露“用户不存在”或“密码错误”。  
> - 记录失败次数时，使用 Redis `INCR`/`EXPIRE` 机制。

### 3.3 业务逻辑层（`services/auth.service.ts`）

```ts
import { PrismaClient } from '@prisma/client';
import { config } from '../config';
import { comparePassword, signToken } from '../utils';
import { createClient } from 'redis';
import logger from '../utils/logger';

const prisma = new PrismaClient();
const redis = createClient({ url: config.redisUrl });

/**
 * 登录核心逻辑
 * @param email
 * @param plainPassword
 * @param deviceId 设备标识，若为空则使用 IP
 */
export const loginUser = async (email: string, plainPassword: string, deviceId?: string) => {
  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) {
    await handleFailedLogin(email);
    throw new Error('UnauthorizedError');
  }

  // 失败计数检查
  const lockKey = `lock:${user.id}`;
  const locked = await redis.get(lockKey);
  if (locked) {
    throw new Error('Account locked due to multiple failures');
  }

  const match = await comparePassword(plainPassword, user.passwordHash);
  if (!match) {
    await handleFailedLogin(email);
    throw new Error('UnauthorizedError');
  }

  // 复位失败计数
  await resetFailedLogin(email);

  // 可在此处进行多因素校验，若需要可返回 401 + 验证码
  // 生成 JWT
  const payload = { sub: user.id, email: user.email };
  const token = signToken(payload);

  // 可记录登录事件到数据库
  logger.info(`User ${user.id} logged in from ${deviceId ?? 'unknown device'}`);
  return token;
};

async function handleFailedLogin(email: string) {
  const key = `fail:${email}`;
  const count = await redis.incr(key);
  if (count === 1) {
    await redis.expire(key, config.lockoutMinutes * 60);
  }
  if (count >= config.maxLoginAttempts) {
    // 锁定账号
    const user = await prisma.user.findUnique({ where: { email } });
    if (user) {
      await redis.set(`lock:${user.id}`, '1', 'EX', config.lockoutMinutes * 60);
    }
  }
}

async function resetFailedLogin(email: string) {
  await redis.del(`fail:${email}`);
}
```

> **重要**  
> 1. **锁定策略**：把锁定键与 `user.id` 关联，避免同一邮箱多次失败导致无限锁定。  
> 2. **计数器**：使用 Redis 的原子操作 `INCR`，高并发下也能保证准确计数。  
> 3. **加密**：`passwordHash` 必须使用 bcrypt（或 argon2）进行单向加密。  
> 4. **Token**：`sub` 代表用户 ID，JWT 过期时间可根据业务需求自行调整。  

