            System.err.println("Failed to read admin password");
            e.printStackTrace();
        }
    }

    private void saveAdminPassword(String hash) {
        try (BufferedWriter bw = new BufferedWriter(new FileWriter(ADMIN_FILENAME))) {
            bw.write(hash);
        } catch (IOException e) {
            System.err.println("Failed to write admin password");
            e.printStackTrace();
        }
    }

    /* ------------------------------------------------------------------ */
