    /* ------------------------------------------------------------------ */
    public void login() {
        System.out.println("=== Administrator Login ===");
        while (true) {
            String pw = Keyboard.readString("Enter password: ");
            if (Utility.getHash(pw).equals(adminHash)) {
                System.out.println("Login successful.");
                break;
            }
            System.out.println("Incorrect password! Try again.");
        }
    }

    /* ------------------------------------------------------------------ */
    /*  Load / save players                                               */
    /* ------------------------------------------------------------------ */
    private void loadPlayers() {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(PLAYERS_FILENAME))) {
            while (true) {
                try {
                    Player p = (Player) ois.readObject();
                    players.add(p);
                } catch (EOFException eof) {
                    break;
                }
            }
        } catch (FileNotFoundException e) {
            System.out.println("players.bin not found – starting with empty list");
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        System.out.println("Players information loaded");
    }

    private void savePlayersToBin() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(PLAYERS_FILENAME))) {
            for (Player p : players) {
                oos.writeObject(p);
            }
        } catch (IOException e) {
            System.err.println("Failed to save players");
        }
    }

