        String name = Keyboard.readString("Enter new player name: ");
        if (getPlayerByName(name) != null) {
            System.out.println("Error: a player with that name already exists");
            return;
        }
        String pwd     = Keyboard.readString("Enter new password: ");
        String pwdHash = Utility.getHash(pwd);
        Player p = new Player(name, pwdHash, 100);   // default chips
        players.add(p);
        System.out.println("Player created");
        savePlayersToBin();
    }

    private void deletePlayer() {
        String name = Keyboard.readString("Enter player name to delete: ");
        Player p = getPlayerByName(name);
        if (p == null) {
            System.out.println("Error: no player with that name exists");
            return;
        }
        players.remove(p);
        System.out.println("Player deleted");
        savePlayersToBin();
