    /*  Chip operations                                                */
    /* --------------------------------------------------------------- */
    public int getChips() { return chips; }

    public void addChips(int amount) { chips += amount; }

    public void deductChips(int amount) {
        if (amount <= chips) chips -= amount;
    }

    /* --------------------------------------------------------------- */
    /*  Card value calculation                                         */
    /* --------------------------------------------------------------- */
    public int getTotalCardsValue() {
        int total = 0;
        for (Card c : cardsOnHand) total += c.getValue();
        return total;
    }

    public int getNumberOfCards() { return cardsOnHand.size(); }

    public void clearCardsOnHand() { cardsOnHand.clear(); }
}
