    private void loadPlayersFromFile() {
        try (ObjectInputStream ois =
                     new ObjectInputStream(new FileInputStream("players.bin"))) {

            while (true) {
                try {
                    Player p = (Player) ois.readObject();
                    players.put(p.getLoginName(), p);
                } catch (EOFException eof) {
                    break;
                }
            }

