    private Player login() {
        System.out.println("HighSum GAME");
        System.out.println("================================================================================");

        while (true) {
            String name = Keyboard.readString("Enter Login name > ");
            Player p = players.get(name);
            if (p == null) {
                System.out.println("User not found. Try again.");
                continue;
            }

            String pw = Keyboard.readString("Enter Password > ");
            if (p.checkPassword(pw)) {                     // check against stored hash
                System.out.println("Login successful.");
                return p;
