                                if (playerBet > 100 || playerBet <= 0) {
                                    System.out.println(playerBet > 100 ?
                                            "Insufficient chips" : "Invalid bet");
                                    valid = false;
                                } else {
                                    betOnTable += playerBet;
                                    player.deductChips(playerBet);
                                    System.out.println("Player call, state bet: " + playerBet);
                                    System.out.println(player.getLoginName() + ", You are left with " +
                                            player.getChips() + " chips");
                                    System.out.println("Bet on table: " + betOnTable);
                                    round++;
                                }
                            } else if ("q".equals(choice) || "n".equals(choice)) {
                                valid = true;
                                nextGame = false;
                                round = NUM_ROUNDS + 1;
                                playerQuit = true;

                                System.out.println("Since the player has quit, all the current chips bet goes to the dealer.");
                                System.out.println("Dealer Wins");
