                if ("y".equals(input)) {
                    nextGame = true;
                    valid = true;
                } else if ("n".equals(input)) {
                    nextGame = false;
                    valid = true;
                } else {
                    System.out.println("*** Please enter Y or N ***");
                }
            }
        }

        System.out.println("Logging out…Goodbye");
    }

    public static void main(String[] args) {
        new GameModule().run();
    }
