package protocol;

import java.nio.charset.StandardCharsets;
import java.util.Base64;

// ---------------------------------------------------------------------------
//  MessageType – enum for all operations
// ---------------------------------------------------------------------------

public enum MessageType {
    // Text message
    TEXT,

    // Image transfer – base64 encoded string in the payload
    IMAGE,

    // Binary file transfer – payload is Base64 of the bytes
    FILE,

    // Client → Server: request service
    SERVICE_REQUEST,

    // Server → Client: service granted
    SERVICE_ACCEPT,

    // Server → Client: service denied
    SERVICE_DENY,

    // Server → Client: heartbeat
    PING,

    // Client → Server: heartbeat acknowledgment
    PONG,

    // Server → Client: busy indicator (timeout)
    BUSY,

    // Reserved / future extensions
    UNKNOWN
}
