```java
package protocol;

import java.io.*;
import java.nio.charset.StandardCharsets;

// ---------------------------------------------------------------------------
//  Protocol – framing helpers
// ---------------------------------------------------------------------------

public final class Protocol {

    // 4‑byte length header + UTF‑8 string (Java ObjectInputStream/OutputStream not used)
    public static void sendMessage(OutputStream out, Message msg) throws IOException {
        byte[] body = MessageCodec.encode(msg);
        ByteBuffer bb = ByteBuffer.allocate(4 + body.length);
        bb.putInt(body.length);
        bb.put(body);
        out.write(bb.array());
        out.flush();
    }

    public static Message receiveMessage(InputStream in) throws IOException, ClassNotFoundException {
        // 1. Read 4‑byte length
        byte[] lenBuf = new byte[4];
        if (in.read(lenBuf) != 4) throw new EOFException("Stream closed");
        int len = ByteBuffer.wrap(lenBuf).getInt();

        // 2. Read the body
        byte[] body = new byte[len];
        int read = 0;
        while (read < len) {
            int r = in.read(body, read, len - read);
            if (r == -1) throw new EOFException("Stream closed while reading body");
            read += r;
        }
        return MessageCodec.decode(body);
    }
}
```

```java
package protocol;

import java.util.Base64;

// ---------------------------------------------------------------------------
//  MessageCodec – turn Message <-> byte[]
// ---------------------------------------------------------------------------

public final class MessageCodec {

    // Simple JSON‑like encoding (no external libs)
    public static byte[] encode(Message msg) {
        // {"type":"TEXT","payload":"Hello"}   (UTF‑8)
        String json = String.format(
                "{\"id\":\"%s\",\"type\":\"%s\",\"payload\":\"%s\"}",
                msg.getMessageId(),
                msg.getType(),
                escape(msg.getPayload())
        );
        return json.getBytes(StandardCharsets.UTF_8);
    }

    public static Message decode(byte[] data) {
        String json = new String(data, StandardCharsets.UTF_8);

        // Very naïve parsing – for demo only
        String type = extract(json, "\"type\":\"", "\"");
        String payload = extract(json, "\"payload\":\"", "\"");
        return new Message(MessageType.valueOf(type), unescape(payload));
    }

    // ---------- helpers ----------
    private static String escape(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    private static String unescape(String s) {
        return s.replace("\\\"", "\"").replace("\\\\", "\\");
    }

    private static String extract(String src, String start, String end) {
        int a = src.indexOf(start);
        if (a < 0) return "";
        int b = src.indexOf(end, a + start.length());
        if (b < 0) return "";
        return src.substring(a + start.length(), b);
    }
}
```

> **Security** – All user‑supplied data is escaped before JSON‑encoding to avoid injection attacks.  
> The payload for files/images is Base64‑encoded, so no binary data corrupts the framing.

