## 2.  Server (Multiple Users, Thread‑Pool)

```java
package server;

import protocol.Message;
import protocol.MessageType;
import protocol.Protocol;

import javax.swing.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class Server {

    private final int port;
    private final ExecutorService pool;
    private final Map<Socket, ClientConnection> connections = new ConcurrentHashMap<>();
    private final ServiceAgentUI ui;          // Swing UI for the agent

    public Server(int port, ServiceAgentUI ui) {
        this.port = port;
        this.ui    = ui;
        this.pool  = Executors.newCachedThreadPool();
    }

    public void start() throws IOException {
        ServerSocket ss = new ServerSocket(port);
        ui.log("Server started on port " + port);

        // Main acceptor loop
        new Thread(() -> {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    Socket client = ss.accept();
                    ClientConnection cc = new ClientConnection(client);
                    connections.put(client, cc);
                    pool.submit(cc::handle);
                } catch (IOException e) {
                    ui.log("Accept failed: " + e.getMessage());
                }
            }
            ui.log("Server shutting down");
        }).start();
    }

    public void shutdown() {
        pool.shutdownNow();
    }

    // ---------------------------------------------------------------
    //  ClientConnection – per‑user handler
    // ---------------------------------------------------------------
    private class ClientConnection {
        private final Socket socket;
        private final InputStream  in;
        private final OutputStream out;
        private final ChatHistory  history;
        private final String       userId;   // derived from IP or handshake

        // Timeout: 30 s without response
        private final TimeoutHandler timeoutHandler;

        ClientConnection(Socket socket) throws IOException {
            this.socket = socket;
            this.in     = socket.getInputStream();
            this.out    = socket.getOutputStream();
            this.userId = socket.getInetAddress().toString() + ":" + socket.getPort();
            this.history = new ChatHistory(userId);

            this.timeoutHandler = new TimeoutHandler();
            timeoutHandler.start();
        }

        void handle() {
            try {
                // 1. Send service‑request to UI
                SwingUtilities.invokeLater(() ->
                        ui.onNewConnection(userId, this::accept, this::decline));

                // 2. Wait until UI accepts or declines
                synchronized (this) {
                    this.wait();        // UI will notify when accepted or declined
                }

                // 3. Process loop
                while (!socket.isClosed()) {
                    Message msg = Protocol.receiveMessage(in);

                    // Reset heartbeat timer
                    timeoutHandler.reset();

                    switch (msg.getType()) {
                        case TEXT, IMAGE, FILE -> {
                            // Store locally
                            history.append(msg);
                            // Forward to the chosen agent (here we simply echo back)
                            sendMessage(msg);
                        }
                        case PONG -> {
                            // heartbeat ack – nothing else
                        }
                        default -> {
                            // Unexpected – ignore or log
                            ui.log("Unexpected message type from " + userId);
                        }
                    }
                }
            } catch (Exception e) {
                ui.log("Connection error with " + userId + ": " + e.getMessage());
                cleanup();
            }
        }

        void sendMessage(Message msg) {
            try {
                Protocol.sendMessage(out, msg);
            } catch (IOException e) {
                ui.log("Send failed to " + userId + ": " + e.getMessage());
            }
        }

        // UI callbacks
        void accept() {
            synchronized (this) {
                // Load chat history into UI
                ui.openChat(userId, history.getAll(), this::sendMessage);
                notify();
            }
        }

        void decline() {
            try {
                // Notify client and close
                sendMessage(new Message(MessageType.SERVICE_DENY, "Service declined"));
                socket.close();
            } catch (IOException ignored) {
            }
            cleanup();
        }

        void cleanup() {
            connections.remove(socket);
            try {
                socket.close();
            } catch (IOException ignored) {
            }
            ui.log("Closed connection with " + userId);
        }

        // ---------------------------------------------------------
        //  TimeoutHandler – watches for 30‑s inactivity
        // ---------------------------------------------------------
        private class TimeoutHandler {
            private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
            private ScheduledFuture<?> future;

            void start() {
                schedule();
            }

            void reset() {
                future.cancel(false);
                schedule();
            }

            void schedule() {
                future = scheduler.schedule(() -> {
                    // No message in 30s – send BUSY
                    sendMessage(new Message(MessageType.BUSY, "Server busy. Please wait."));
                }, 30, TimeUnit.SECONDS);
            }

            void stop() {
                scheduler.shutdownNow();
            }
        }
    }
}
