    private OutputStream out;
    private final String userId;           // local identifier
    private final ChatHistory history;     // local persistence

    public UserClient(String host, int port, String userId) {
        this.serverHost = host;
        this.serverPort = port;
        this.userId     = userId;
        this.history    = new ChatHistory(userId);
    }

    public void connect() throws IOException {
        socket = new Socket(serverHost, serverPort);
        in     = socket.getInputStream();
        out    = socket.getOutputStream();

        // Tell server we want service
        send(new Message(MessageType.SERVICE_REQUEST, userId));

        // Start listening thread
        new Thread(this::listen).start();

        // Start heartbeat timer
        new Timer(10000, e -> send(new Message(MessageType.PING, "ping"))).start();
