                    case BUSY  -> JOptionPane.showMessageDialog(null, msg.getPayload());
                    case SERVICE_ACCEPT -> JOptionPane.showMessageDialog(null, "Agent accepted your request");
                    case SERVICE_DENY   -> JOptionPane.showMessageDialog(null, "Agent declined your request");
                    case PONG            -> { /* heartbeat ack */ }
                    default -> System.out.println("Unhandled: " + msg.getType());
                }
                // Persist
                history.append(msg);
            }
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "Connection lost: " + e.getMessage());
            disconnect();
        }
    }

    // ---------- User actions ----------
    public void sendText(String txt) {
        send(new Message(MessageType.TEXT, txt));
