            String base64 = java.util.Base64.getEncoder().encodeToString(bytes);
            send(new Message(MessageType.FILE, f.getName() + "\0" + base64));
        } catch (IOException e) {
            JOptionPane.showMessageDialog(null, "Failed to read file: " + e.getMessage());
        }
    }

    private void send(Message msg) {
        try {
