        String filename = payload.substring(0, sep);
        byte[] data     = java.util.Base64.getDecoder().decode(payload.substring(sep + 1));

        // Save to user home /Downloads
        Path out = Paths.get(System.getProperty("user.home"), "Downloads", filename);
        try {
