```java
package server;

import protocol.Message;

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class ChatHistory {
    private final String userId;
    private final Path   file;

    public ChatHistory(String userId) {
        this.userId = userId;
        String safe = userId.replaceAll("[^a-zA-Z0-9.-]", "_");
        this.file   = Paths.get("chat_histories", safe + ".log");
        try {
            Files.createDirectories(file.getParent());
        } catch (IOException ignored) {}
    }

    public synchronized void append(Message msg) {
        try (Writer w = Files.newBufferedWriter(file,
                StandardOpenOption.CREATE, StandardOpenOption.APPEND)) {
            w.write(msg.getMessageId() + "|" + msg.getType() + "|" + msg.getPayload() + System.lineSeparator());
        } catch (IOException e) {
            // Log but continue
        }
    }

    public synchronized List<Message> getAll() {
        List<Message> list = new ArrayList<>();
        if (!Files.exists(file)) return list;
        try (BufferedReader r = Files.newBufferedReader(file)) {
            r.lines().map(this::parseLine).forEach(list::add);
        } catch (IOException ignored) {}
        return list;
    }

    private Message parseLine(String line) {
        String[] parts = line.split("\\|", 3);
        if (parts.length < 3) return new Message(MessageType.UNKNOWN, line);
        return new Message(MessageType.valueOf(parts[1]), parts[2]);
    }
}
