## 三、核心代码（Java + JavaCV）

> 这里演示一个最小可跑的示例，使用 **JavaCV**（基于 FFmpeg）进行编码。  
> 你可以把这个模块封装成一个类 `ImageToH264Stream`，然后在业务层调用 `send()`。

```java
import org.bytedeco.ffmpeg.avcodec.*;
import org.bytedeco.ffmpeg.avutil.*;
import org.bytedeco.ffmpeg.avformat.*;
import org.bytedeco.ffmpeg.global.avcodec;
import org.bytedeco.ffmpeg.global.avutil;
import org.bytedeco.ffmpeg.global.avformat;
import org.bytedeco.ffmpeg.global.avdevice;
import org.bytedeco.javacv.*;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.*;
import java.net.Socket;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;

public class ImageToH264Stream {

    private Socket socket;
    private OutputStream out;

    public ImageToH264Stream(String host, int port) throws IOException {
        socket = new Socket(host, port);
        out = socket.getOutputStream();
    }

    // 读取图像并返回 BufferedImage
    private BufferedImage readImage(InputStream in) throws IOException {
        return ImageIO.read(in);
    }

    // 直接把 BufferedImage 转成 YUV420P（byte[]）
    private byte[] rgbToYuv420P(BufferedImage img) {
        int width = img.getWidth();
        int height = img.getHeight();

        byte[] yuv = new byte[width * height * 3 / 2]; // YUV420

        int indexY = 0;
        int indexU = width * height;
        int indexV = indexU + (width * height) / 4;

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int rgb = img.getRGB(x, y);
                int r = (rgb >> 16) & 0xff;
                int g = (rgb >> 8) & 0xff;
                int b = rgb & 0xff;

                // BT.601 conversion
                int yVal = (int)(0.257 * r + 0.504 * g + 0.098 * b + 16);
                int uVal = (int)(-0.148 * r - 0.291 * g + 0.439 * b + 128);
                int vVal = (int)(0.439 * r - 0.368 * g - 0.071 * b + 128);

                yuv[indexY++] = (byte) yVal;

                // For U and V we subsample (every 2x2 block)
                if (y % 2 == 0 && x % 2 == 0) {
                    yuv[indexU++] = (byte) uVal;
                    yuv[indexV++] = (byte) vVal;
                }
            }
        }
        return yuv;
    }

    // 编码单帧 YUV420P 并返回 NALU 数据
    private List<byte[]> encodeFrame(byte[] yuv, int width, int height, AVCodecContext ctx,
                                      AVFrame inputFrame, AVPacket pkt) throws IOException {
        // 填充 AVFrame
        inputFrame.data(0).put(yuv, 0, yuv.length);
        inputFrame.width(width);
        inputFrame.height(height);
        inputFrame.format(avutil.AV_PIX_FMT_YUV420P);
        inputFrame.pts(0); // pts 仅示例

        avcodec.avcodec_send_frame(ctx, inputFrame);

        List<byte[]> nalus = new ArrayList<>();
        while (avcodec.avcodec_receive_packet(ctx, pkt) == 0) {
            // 这里 pkt.data 包含完整的 NALU
            BytePointer data = pkt.data();
            int size = pkt.size();
            byte[] out = new byte[size];
            data.get(out, 0, size);

            // 先加 4-byte length 头（Netty 等常用做法）
            ByteBuffer buf = ByteBuffer.allocate(4 + size);
            buf.putInt(size);
            buf.put(out);
            nalus.add(buf.array());

            avcodec.av_packet_unref(pkt);
        }
        return nalus;
    }

    public void send(InputStream imgStream) throws IOException {
        BufferedImage img = readImage(imgStream);
        int width = img.getWidth();
        int height = img.getHeight();

        // 初始化 FFmpeg 编码器
        avcodec.avcodec_register_all();
        AVCodec codec = avcodec.avcodec_find_encoder(avcodec.AV_CODEC_ID_H264);
        AVCodecContext ctx = avcodec.avcodec_alloc_context3(codec);
        ctx.width(width);
        ctx.height(height);
        ctx.time_base().num(1);
        ctx.time_base().den(25);
        ctx.gop_size(12);
        ctx.max_b_frames(2);
        ctx.pix_fmt(avutil.AV_PIX_FMT_YUV420P);
        ctx.rc_max_rate(5000000); // 5Mbps
        ctx.rc_min_rate(500000); // 0.5Mbps

        // 选项
        AVDictionary options = new AVDictionary(null);
        av_opt_set_int_dict(options, "preset", avcodec.AV_CODEC_FLAG_LOW_DELAY, 0);
        av_opt_set(options, "profile", "main", 0);

        if (avcodec.avcodec_open2(ctx, codec, options) < 0) {
            throw new IOException("Could not open codec");
        }

        AVFrame inputFrame = avutil.av_frame_alloc();
        inputFrame.format(avutil.AV_PIX_FMT_YUV420P);
        inputFrame.width(width);
        inputFrame.height(height);
        avutil.av_frame_get_buffer(inputFrame, 32);

        AVPacket pkt = avcodec.av_packet_alloc();

        // 1. 转 YUV
        byte[] yuv = rgbToYuv420P(img);

        // 2. 编码
        List<byte[]> nalus = encodeFrame(yuv, width, height, ctx, inputFrame, pkt);

        // 3. 发送
        for (byte[] frame : nalus) {
            out.write(frame);
            out.flush();  // 视情况可延迟 flush，避免频繁系统调用
        }

        // 4. 清理
        avcodec.av_packet_free(pkt);
        avutil.av_frame_free(inputFrame);
        avcodec.avcodec_free_context(ctx);
    }

    public void close() throws IOException {
        out.close();
        socket.close();
    }
}
