```java
package com.example.game;      // <-- adjust package as needed

import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Objects;

/**
 * Represents an item in the game.  
 * <p>
 * The class now supports a discount value (percentage) that can be applied to
 * the base {@code price}. The discount is stored in {@code discount} and is
 * applied only when {@code getDiscountedPrice()} is called, keeping the
 * original price unchanged. A {@code maxModification} field is also added
 * to mirror the client‑side logic.
 */
public class Item implements Dumper {

    /* --------------------------------------------------------------------- */
    /*  Basic item properties                                               */
    /* --------------------------------------------------------------------- */

    public String id;                         // Unique item identifier
    public LocalizedString description;       // Item description
    public boolean isInventory;               // Is item part of the inventory
    public int index;                         // Position in the list
    public PropertyItem[] propetys;           // Item properties
    public ItemType itemType;                 // Weapon type
    public int modificationIndex;             // Current modification index
    public LocalizedString name;              // Item name
    public PropertyItem[] nextProperty;       // Next level properties
    public int nextPrice;                     // Price of next level
    public int nextRankId;                    // Rank of next level
    public int price;                         // Base price (before discount)
    public boolean multicounted;              // Can be counted multiple times
    public int rankId;                        // Current rank id
    public ModificationInfo[] modifications;  // Available modifications
    public boolean specialItem;               // Special item flag
    public int count;                         // Quantity in inventory
    public boolean addable;                   // Is it addable to inventory
    public long time = 0L;                    // Expiry timestamp (ms)

    /* --------------------------------------------------------------------- */
    /*  New discount related properties                                     */
    /* --------------------------------------------------------------------- */

    /**
     * Discount percentage (0–100). 0 means no discount.
     */
    public int discount = 0;

    /**
     * Maximum number of modifications that can be applied to this item.
     * Mirrors the client‑side {@code maxModification} parameter.
     */
    public int maxModification = 0;

    /* --------------------------------------------------------------------- */
    /*  Constructor                                                         */
    /* --------------------------------------------------------------------- */

    /**
     * Full constructor including discount and maxModification.
     *
     * @param id              Unique identifier
     * @param description     Description of the item
     * @param isInventory     Is the item part of the inventory
     * @param index           List index
     * @param propetys        Item properties
     * @param weapon          Weapon type
     * @param modificationIndex Current modification index
     * @param name            Item name
     * @param nextProperty    Next level properties
     * @param nextPrice       Price of the next level
     * @param nextRankId      Next rank id
     * @param price           Base price
     * @param rankId          Current rank id
     * @param modifications   Available modifications
     * @param specialItem     Special item flag
     * @param count           Quantity
     * @param addable         Can be added
     * @param multicounted    Can be multicounted
     * @param discount        Discount percent (0–100)
     * @param maxModification Maximum modifications allowed
     */
    public Item(String id,
                LocalizedString description,
                boolean isInventory,
                int index,
                PropertyItem[] propetys,
                ItemType weapon,
                int modificationIndex,
                LocalizedString name,
                PropertyItem[] nextProperty,
                int nextPrice,
                int nextRankId,
                int price,
                int rankId,
                ModificationInfo[] modifications,
                boolean specialItem,
                int count,
                boolean addable,
                boolean multicounted,
                int discount,
                int maxModification) {

        this.id = id;
        this.description = description;
        this.isInventory = isInventory;
        this.index = index;
        this.propetys = propetys;
        this.itemType = weapon;
        this.modificationIndex = modificationIndex;
        this.name = name;
        this.nextProperty = nextProperty;
        this.nextPrice = nextPrice;
        this.nextRankId = nextRankId;
        this.price = price;
        this.rankId = rankId;
        this.modifications = modifications;
        this.specialItem = specialItem;
        this.count = count;
        this.addable = addable;
        this.multicounted = multicounted;

        /* Discount & maxModification – store as-is (no validation here). */
        this.discount = Math.max(0, Math.min(100, discount));
        this.maxModification = Math.max(0, maxModification);

        /* Expiry handling for special items. */
        long now = System.currentTimeMillis();
        if ("no_supplies".equals(id)) {
            this.time = now + ((3600000L * 24) * 31);
        } else if ("up_score_small".equals(id)) {
            this.time = now + ((3600000L * 24) * 7);
        } else if ("up_score_start".equals(id)
                || "up_score".equals(id)) {
            this.time = now + ((3600000L * 24) * 31);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Convenience constructors for legacy code (discount = 0)              */
    /* --------------------------------------------------------------------- */

    public Item(String id,
                LocalizedString description,
                boolean isInventory,
                int index,
                PropertyItem[] propetys,
                ItemType weapon,
                int modificationIndex,
                LocalizedString name,
                PropertyItem[] nextProperty,
                int nextPrice,
                int nextRankId,
                int price,
                int rankId,
                ModificationInfo[] modifications,
                boolean specialItem,
                int count,
                boolean addable,
                boolean multicounted) {
        this(id, description, isInventory, index, propetys, weapon,
                modificationIndex, name, nextProperty, nextPrice,
                nextRankId, price, rankId, modifications, specialItem,
                count, addable, multicounted, 0, 0);
    }

    /* --------------------------------------------------------------------- */
    /*  Getters & helpers                                                   */
    /* --------------------------------------------------------------------- */

    /**
     * Returns the original id combined with modification index
     * (unchanged from original logic).
     */
    public String getId() {
        return StringUtils.concatStrings(this.id,
                "_m",
                String.valueOf(this.modificationIndex));
    }

    /**
     * Returns the price after applying the discount.
     *
     * @return discounted price (rounded down to integer)
     */
    public int getDiscountedPrice() {
        if (discount <= 0) {
            return price;
        }
        double discounted = price * (1 - (discount / 100.0));
        return (int) Math.floor(discounted);
    }

    /**
     * Creates a deep copy of this item.
     * All fields are copied except {@code time} which is re‑calculated
     * according to the original constructor logic.
     */
    @Override
    public Item clone() {
        Item cloned = new Item(
                this.id,
                this.description,
                this.isInventory,
                this.index,
                this.propetys,
                this.itemType,
                this.modificationIndex,
                this.name,
                this.nextProperty,
                this.nextPrice,
                this.nextRankId,
                this.price,
                this.rankId,
                this.modifications,
                this.specialItem,
                this.count,
                this.addable,
                this.multicounted,
                this.discount,
                this.maxModification);
        // Preserve the same expiry timestamp
        cloned.time = this.time;
        return cloned;
    }

    /* --------------------------------------------------------------------- */
    /*  Dump representation (useful for debugging)                          */
    /* --------------------------------------------------------------------- */

    @Override
    public String dump() {
        return StringUtils.concatStrings(
                "-------DUMP GARAGE ITEM------\n",
                "\tid: ", this.id, "\n",
                "\tinventoryItem: ", this.isInventory, "\n",
                "\tindex: ", this.index, "\n",
                "\tname: ", this.name.localizatedString(Localization.RU), "\n",
                "\tprice: ", this.price, "\n",
                "\tdiscount: ", this.discount, "%\n",
                "\tdiscounted price: ", getDiscountedPrice(), "\n",
                "\trandId: ", this.rankId, "\n",
                "\tspecialItem: ", this.specialItem, "\n",
                "\tmulticounted: ", this.multicounted, "\n",
                "\tmaxModification: ", this.maxModification, "\n",
                "-------------------------------\n");
    }

    /* --------------------------------------------------------------------- */
    /*  Override equals & hashCode for completeness                         */
    /* --------------------------------------------------------------------- */

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Item)) return false;
        Item other = (Item) obj;
        return Objects.equals(id, other.id)
                && Objects.equals(description, other.description)
                && Objects.equals(name, other.name)
                && modificationIndex == other.modificationIndex
                && discount == other.discount
                && maxModification == other.maxModification;
    }

    @Override
    public int hashCode() {
        return Objects.hash(id, description, name, modificationIndex, discount, maxModification);
    }
}
```

### How the new fields work

| Field | Purpose | Notes |
|-------|---------|-------|
| `discount` | Discount percentage to apply to `price`. | 0–100; applied in `getDiscountedPrice()`. |
| `maxModification` | Maximum number of modifications allowed (mirrors client parameter). | Stored but not enforced internally; can be used by higher‑level logic. |

### Using the discounted price

```java
Item item = ...;
int priceForPurchase = item.getDiscountedPrice(); // uses discount logic
```

The `dump()` method now prints both the base price and the discounted price, which helps in debugging and verifying that the discount is applied correctly. The `clone()` method includes the new fields so that a deep copy preserves the discount and modification limits.

