package com.ecomm.chat;

import java.nio.file.*;
import java.security.MessageDigest;

public class Utils {
    public static Path getUserLog(String userId) {
        return Paths.get("logs", userId + ".txt").normalize();
    }

    public static String sha256(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        return bytesToHex(md.digest(data));
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    public static boolean isSafeFilename(String name) {
        Path p = Paths.get(name);
        return !p.isAbsolute() && !name.contains("..") && !name.contains("/") && !name.contains("\\");
    }
}
