### 2‑4. `ClientHandler.java`

```java
package com.ecomm.chat;

import javax.net.ssl.SSLSocket;
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.ConcurrentLinkedQueue;

public class ClientHandler implements Runnable {
    private final SSLSocket socket;
    private String userId; // 登录后确定
    private final ConcurrentLinkedQueue<Message> outQueue = new ConcurrentLinkedQueue<>();

    public ClientHandler(SSLSocket socket) {
        this.socket = socket;
    }

    @Override
    public void run() {
        try (DataInputStream in = new DataInputStream(socket.getInputStream());
             DataOutputStream out = new DataOutputStream(socket.getOutputStream())) {

            // 1. 先处理 LOGIN
            Message loginMsg = Message.readFrom(in);
            if (loginMsg.type != MessageType.COMMAND || !loginMsg.header.startsWith("LOGIN:")) {
                sendCommand(out, "FAIL:NOT_LOGGED_IN");
                close();
                return;
            }
            String[] parts = loginMsg.header.split(":");
            if (parts.length != 3) {
                sendCommand(out, "FAIL:INVALID_FORMAT");
                close();
                return;
            }
            String username = parts[1];
            String pwdHash = parts[2];
            if (!Auth.verify(username, pwdHash)) { // Auth 是单独实现的身份验证类
                sendCommand(out, "FAIL:BAD_CREDENTIAL");
                close();
                return;
            }
            userId = username;
            sendCommand(out, "OK");

            // 2. 开启读/写线程
            Thread writer = new Thread(() -> {
                try {
                    while (!socket.isClosed()) {
                        Message m = outQueue.poll();
                        if (m != null) m.writeTo(out);
                        else Thread.sleep(50);
                    }
                } catch (Exception e) {
                    // 记录日志
                }
            });
            writer.start();

            // 3. 主循环：读取客户端消息
            while (!socket.isClosed()) {
                Message m = Message.readFrom(in);
                if (m.type == MessageType.END) break;

                // 写入本地日志
                Path logPath = Utils.getUserLog(userId);
                Files.createDirectories(logPath.getParent());
                Files.write(logPath, (new Date() + " - " + m.type + " - " + m.header + "\n").getBytes(),
                           StandardOpenOption.CREATE, StandardOpenOption.APPEND);

                // 业务分发
                switch (m.type) {
                    case TEXT:
                        // 直接转发给客服 UI 或保存到文件
                        break;
                    case IMAGE:
                    case FILE:
                        // 保存文件，随后转发给客服
                        Path filePath = Utils.getUserLog(userId).getParent().resolve(userId + "_" + m.header);
                        Files.write(filePath, m.body, StandardOpenOption.CREATE);
                        break;
                    default:
                        // 其它业务
                }
            }

        } catch (Exception e) {
            // 统一异常处理，记录日志
        } finally {
            close();
        }
    }

    public void sendMessage(Message m) {
        outQueue.offer(m);
    }

    private void sendCommand(DataOutputStream out, String cmd) throws IOException {
        Message m = new Message();
        m.type = MessageType.COMMAND;
        m.header = cmd;
        m.body = new byte[0];
        m.writeTo(out);
    }

    private void close() {
        try { socket.close(); } catch (IOException ignored) {}
    }
}
```

