package com.ecomm.chat;

import javax.net.ssl.*;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.util.concurrent.*;

public class ChatServer {
    private static final int PORT = 8443;
    private static final int MAX_CLIENTS = 100;
    private final ExecutorService pool = Executors.newFixedThreadPool(MAX_CLIENTS);

    public void start() throws Exception {
        SSLServerSocketFactory ssf = (SSLServerSocketFactory) SSLServerSocketFactory.getDefault();
        SSLServerSocket server = (SSLServerSocket) ssf.createServerSocket();
        server.setReuseAddress(true);
        server.bind(new InetSocketAddress(PORT));
        System.out.println("Server listening on " + PORT);

        while (true) {
            SSLSocket client = (SSLSocket) server.accept();
            System.out.println("New client from " + client.getInetAddress());
            ClientHandler handler = new ClientHandler(client);
            pool.execute(handler);
        }
    }

    public static void main(String[] args) {
        try {
            new ChatServer().start();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

