public class ChatFrame extends JFrame {
    private final SSLSocket socket;
    private final DataInputStream in;
    private final DataOutputStream out;
    private final ChatPanel chatPanel = new ChatPanel();
    private final ExecutorService readerPool = Executors.newSingleThreadExecutor();
    private final String userId;
    private final File logFile;

    public ChatFrame(String host, int port, String userId, String pwdHash) throws IOException {
        super("E‑Commerce – Chat (" + userId + ")");
        this.userId = userId;
        this.logFile = new File("chatlogs" + File.separator + userId + ".txt");
        // 1. 建立 TLS 连接
        SSLSocketFactory ssf = (SSLSocketFactory) SSLSocketFactory.getDefault();
        socket = (SSLSocket) ssf.createSocket(host, port);
        in = new DataInputStream(socket.getInputStream());
        out = new DataOutputStream(socket.getOutputStream());

        // 2. 发送 LOGIN
        sendCommand("LOGIN:" + userId + ":" + pwdHash);

        // 3. 等待服务器响应
        Message resp = Message.readFrom(in);
        if (!"OK".equals(resp.header)) {
            throw new IOException("Login failed: " + resp.header);
        }

        // 4. 加载聊天记录
        loadChatHistory();

        // 5. UI 组装
        setLayout(new BorderLayout());
        add(chatPanel, BorderLayout.CENTER);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(600, 500);
        setLocationRelativeTo(null);

        // 6. 开启读线程
        readerPool.execute(this::listenLoop);
    }

    private void loadChatHistory() {
        if (!logFile.exists()) return;
        try (BufferedReader br = new BufferedReader(new FileReader(logFile))) {
            String line;
            while ((line = br.readLine()) != null) chatPanel.append(line + "\n");
        } catch (IOException ignored) {}
    }

    private void listenLoop() {
        try {
            while (true) {
                Message m = Message.readFrom(in);
                switch (m.type) {
                    case TEXT:
                        SwingUtilities.invokeLater(() ->
                                chatPanel.append("<" + userId + ">: " + new String(m.body, StandardCharsets.UTF_8)));
                        break;
                    case IMAGE:
                        ImageIcon icon = Utils.byteToIcon(m.body);
                        if (icon != null)
                            SwingUtilities.invokeLater(() -> chatPanel.appendImage(icon));
                        break;
                    case FILE:
                        // 下载文件到本地
                        File dest = new File("downloads", m.header);
                        dest.getParentFile().mkdirs();
                        Utils.bytesToFile(m.body, dest);
                        SwingUtilities.invokeLater(() ->
                                chatPanel.append("<" + userId + "> sent a file: " + dest.getName()));
                        break;
                    default:
                        // 其它命令
                }
            }
        } catch (IOException e) {
            SwingUtilities.invokeLater(() -> chatPanel.append("Connection lost."));
        }
    }

    // -------- 发送消息 --------
    public void sendText(String txt) {
        try {
            Message m = new Message();
            m.type = MessageType.TEXT;
            m.header = "";
            m.body = txt.getBytes(StandardCharsets.UTF_8);
            m.writeTo(out);
            chatPanel.append("<Me>: " + txt);
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "Send failed: " + e.getMessage(),
                    "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    public void sendImage(File imgFile) {
        try {
            byte[] data = Utils.fileToBytes(imgFile);
            Message m = new Message();
            m.type = MessageType.IMAGE;
            m.header = imgFile.getName();
            m.body = data;
            m.writeTo(out);
            ImageIcon icon = Utils.byteToIcon(data);
            if (icon != null) chatPanel.appendImage(icon);
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "Send image failed: " + e.getMessage(),
                    "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    public void sendFile(File file) {
        try {
            byte[] data = Utils.fileToBytes(file);
            // 限制大小
            if (data.length > 10 * 1024 * 1024) throw new IOException("File too large");
            Message m = new Message();
            m.type = MessageType.FILE;
            m.header = file.getName();
            m.body = data;
            m.writeTo(out);
            chatPanel.append("<Me> sent a file: " + file.getName());
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "Send file failed: " + e.getMessage(),
                    "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    private void sendCommand(String cmd) throws IOException {
        Message m = new Message();
        m.type = MessageType.COMMAND;
        m.header = cmd;
        m.body = new byte[0];
        m.writeTo(out);
    }

    // --------- 关闭 ----------
    public void close() {
        try {
            Message m = new Message();
            m.type = MessageType.END;
            m.body = new byte[0];
            m.writeTo(out);
            socket.close();
        } catch (IOException ignored) {}
        readerPool.shutdownNow();
    }
}
