```java
package com.ecomm.chatclient;

import javax.swing.*;
import java.io.Console;
import java.security.MessageDigest;
import java.util.Scanner;

public class ChatClient {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            try {
                // 简化：在控制台输入
                Scanner sc = new Scanner(System.in);
                System.out.print("Host (default localhost): ");
                String host = sc.nextLine();
                if (host.isEmpty()) host = "localhost";
                System.out.print("Port (default 8443): ");
                int port = Integer.parseInt(sc.nextLine());
                if (port <= 0) port = 8443;
                System.out.print("Username: ");
                String user = sc.nextLine();
                String pwd;
                Console console = System.console();
                if (console != null) pwd = new String(console.readPassword("Password: "));
                else {
                    System.out.print("Password: ");
                    pwd = sc.nextLine();
                }
                String pwdHash = sha256(pwd.getBytes());
                ChatFrame frame = new ChatFrame(host, port, user, pwdHash);
                // 事件绑定
                frame.chatPanel.getSendButton().addActionListener(e ->
                        frame.sendText(frame.chatPanel.getInputField().getText()));
                frame.chatPanel.getInputField().addActionListener(e ->
                        frame.sendText(frame.chatPanel.getInputField().getText()));
                frame.chatPanel.getImageButton().addActionListener(e -> {
                    JFileChooser fc = new JFileChooser();
                    if (fc.showOpenDialog(frame) == JFileChooser.APPROVE_OPTION) {
                        frame.sendImage(fc.getSelectedFile());
                    }
                });
                frame.chatPanel.getFileButton().addActionListener(e -> {
                    JFileChooser fc = new JFileChooser();
                    if (fc.showOpenDialog(frame) == JFileChooser.APPROVE_OPTION) {
                        frame.sendFile(fc.getSelectedFile());
                    }
                });

                frame.setVisible(true);
                frame.addWindowListener(new java.awt.event.WindowAdapter() {
                    @Override
                    public void windowClosing(java.awt.event.WindowEvent e) {
                        frame.close();
                    }
                });
            } catch (Exception e) {
                JOptionPane.showMessageDialog(null, "Failed to start: " + e.getMessage(),
                        "Error", JOptionPane.ERROR_MESSAGE);
                System.exit(1);
            }
        });
    }

    private static String sha256(byte[] data) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        return Utils.bytesToHex(md.digest(data));
    }
}
