import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.*;

public class SecureImgServer {
    private static final int PORT = 9000;
    private static final String HMAC_ALG = "HmacSHA256";
    private static final byte[] HMAC_KEY = "superSecretKey1234".getBytes(StandardCharsets.UTF_8);
    private static final long MAX_IMG_SIZE = 5L * 1024 * 1024; // 5 MB
    private static final long MAX_TOTAL_SIZE = 20L * 1024 * 1024; // 20 MB

    public static void main(String[] args) throws Exception {
        // Load keystore
        KeyStore ks = KeyStore.getInstance("JKS");
        try (InputStream ksIs = new FileInputStream("server.keystore")) {
            ks.load(ksIs, "keystorePass".toCharArray());
        }
        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, "keyPass".toCharArray());
        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(kmf.getKeyManagers(), null, null);
        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        SSLServerSocket server = (SSLServerSocket) ssf.createServerSocket(PORT);
        server.setNeedClientAuth(false); // 如果要双向认证则改成 true

        ExecutorService pool = Executors.newFixedThreadPool(10);
        System.out.println("Secure server listening on port " + PORT);
        while (true) {
            SSLSocket client = (SSLSocket) server.accept();
            pool.submit(() -> handle(client));
        }
    }

    private static void handle(SSLSocket client) {
        try (DataInputStream dis = new DataInputStream(
                new BufferedInputStream(client.getInputStream()));
             DataOutputStream dos = new DataOutputStream(
                new BufferedOutputStream(client.getOutputStream()))) {

            int imgCount = dis.readInt();
            System.out.println("Receiving " + imgCount + " images");

            long total = 0;
            for (int i = 0; i < imgCount; i++) {
                // ---- HMAC ----
                int tagLen = dis.readInt();
                byte[] recvTag = new byte[tagLen];
                dis.readFully(recvTag);

                long len = dis.readLong();
                if (len > MAX_IMG_SIZE) throw new IOException("Image too large");
                total += len;
                if (total > MAX_TOTAL_SIZE) throw new IOException("Total size exceeded");
                byte[] data = new byte[(int) len];
                dis.readFully(data);

                byte[] calcTag = hmac(data);
                if (!MessageDigest.isEqual(recvTag, calcTag))
                    throw new SecurityException("HMAC mismatch for image " + i);

                // ---- Save ----
                try (ByteArrayInputStream bais = new ByteArrayInputStream(data)) {
                    BufferedImage img = ImageIO.read(bais);
                    ImageIO.write(img, "png", new File("recv_" + i + ".png"));
                    System.out.println("Saved: recv_" + i + ".png");
                }
            }
            dos.writeUTF("OK");
            dos.flush();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try { client.close(); } catch (Exception ignored) {}
        }
    }

    private static byte[] hmac(byte[] data) throws Exception {
        Mac mac = Mac.getInstance(HMAC_ALG);
        mac.init(new SecretKeySpec(HMAC_KEY, HMAC_ALG));
        return mac.doFinal(data);
    }
}
