    @GetMapping("/all")
    public ResponseEntity<String> all(HttpServletRequest request) {
        String param = request.getParameter("baz");
        if (param == null) {
            return ResponseEntity.ok("baz not present");
        }
        return ResponseEntity.ok("baz=" + param);
    }

    // 4️⃣ 通过 @RequestParam Map
    @GetMapping("/map")
    public ResponseEntity<String> map(@RequestParam Map<String, String> params) {
        if (params.containsKey("qux")) {
