// Packet.java  – just a DTO, no serialisation needed
public final class Packet {
    private final int serialNo;
    private final String data;

    public Packet(int serialNo, String data) {
        this.serialNo = serialNo;
        this.data    = data;
    }
    public int serialNo() { return serialNo; }
    public String data()  { return data;   }

    // simple text representation:  <serialNo>:<data>
    public String toText() { return serialNo + ":" + data; }

    public static Packet fromText(String txt) {
        int idx = txt.indexOf(':');
        if (idx < 0) throw new IllegalArgumentException("invalid packet: " + txt);
        int sn = Integer.parseInt(txt.substring(0, idx));
        String d = txt.substring(idx + 1);
        return new Packet(sn, d);
    }
}
```

