import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class TCPPacketServer {

    private static final int PORT = 1024;
    private static final ExecutorService pool = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        System.out.println("Opening port…");
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {

            while (true) {
                Socket client = serverSocket.accept();
                pool.execute(new ClientHandler(client));
            }

        } catch (IOException e) {
            e.printStackTrace(System.err);
        } finally {
            pool.shutdown();
        }
    }

    /** Handles one client connection. */
    private static class ClientHandler implements Runnable {
        private final Socket socket;

        ClientHandler(Socket s) {
            this.socket = s;
        }

        @Override
        public void run() {
            try (   // automatic resource closing
                    BufferedReader in  = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                    PrintWriter   out = new PrintWriter(socket.getOutputStream(), true) ) {

                String line;
                while ((line = in.readLine()) != null) {
                    if (line.equalsIgnoreCase("CLOSE")) break;

                    Packet pkt = Packet.fromText(line);

                    // ---- SERVER SIDE LOGGING ----
                    System.out.printf("Recieving From Clients Packet’s serialNo#%d%n", pkt.serialNo());
                    System.out.printf("and packet’s Data is %s%n", pkt.data());

                    // ---- ACK BACK TO CLIENT ----
                    // we simply echo the same packet (you could change the logic here)
                    out.println(pkt.toText());
                }

            } catch (IOException | IllegalArgumentException e) {
                System.err.println("Client handler error: " + e.getMessage());
            } finally {
                try { socket.close(); } catch (IOException ignored) {}
            }
        }
    }
}
```

*What changed?*

| Before | After |
|--------|-------|
| No start‑up message | `System.out.println("Opening port…");` |
| Reads raw bytes → `ObjectInputStream` | Reads lines with `BufferedReader` |
| Prints “FROM CLIENT …” | Prints the exact wording you requested |
| Sends back a `Packet` via object stream | Sends back the same text line (`serialNo:data`) |

---

## 3.  TCPPacketClient.java

```java
import java.io.*;
import java.net.*;

public class TCPPacketClient {
    public static void main(String[] args) {
        try (   Socket socket = new Socket("localhost", 1024);
                BufferedReader userInput = new BufferedReader(new InputStreamReader(System.in));
                BufferedReader in   = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                PrintWriter   out  = new PrintWriter(socket.getOutputStream(), true) ) {

            int serialNo = 1;
            String line;

            while (true) {
                System.out.print("Enter the data packet: ");
                line = userInput.readLine();
                if (line == null) break;          // EOF

                if (line.equalsIgnoreCase("CLOSE")) {
                    out.println(line);            // let server know we are done
                    break;
                }

                // ----- SEND -----
                Packet pkt = new Packet(serialNo++, line);
                out.println(pkt.toText());        // <serialNo>:<data>

                // ----- RECEIVE ACK -----
                String response = in.readLine();
                if (response == null) break;      // server closed
                Packet ack = Packet.fromText(response);

                System.out.printf("FROM SERVER:Packet SerialNo#%d is received%n", ack.serialNo());
            }

        } catch (IOException e) {
            e.printStackTrace(System.err);
        }
    }
}
```

*What changed?*

| Before | After |
|--------|-------|
| Uses `PrintStream` + `ObjectOutputStream` | Uses `PrintWriter` + plain text |
| Reads the raw bytes back | Reads a single line and prints a simple acknowledgement |
| Prints “FROM SERVER: Packet SerialNo#x, Data: …” | Prints the required “FROM SERVER:Packet SerialNo#x is received” |

---

## 4.  How to run

1. **Compile**

   ```bash
   javac *.java
   ```

2. **Start the server**

   ```bash
   java TCPPacketServer
   ```

   You should see:

   ```
