```java
package com.example.socket.util;

import javax.net.ssl.*;
import java.io.FileInputStream;
import java.security.KeyStore;

public final class SslUtils {

    /**
     * 创建 SSLContext，基于 PKCS12 keystore
     */
    public static SSLContext createSSLContext(String keystorePath,
                                              String keystorePassword,
                                              String keyAlias) throws Exception {

        KeyStore ks = KeyStore.getInstance("PKCS12");
        try (FileInputStream fis = new FileInputStream(keystorePath)) {
            ks.load(fis, keystorePassword.toCharArray());
        }

        // 只使用指定 alias 的 key
        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, keystorePassword.toCharArray());
        // TrustManager 可以使用默认的
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(ks);

        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);
        return sslContext;
    }
}
```

> **使用说明**  
> `keystorePath` 需要是绝对路径，或者 `classpath:` 前缀。若使用 `classpath:ssl/server-keystore.p12`，可在 `SslUtils` 内部通过 `ResourceUtils.getFile()` 读取。

