```java
package com.example.socket.server;

import com.example.socket.config.SocketConfig;
import com.example.socket.util.SslUtils;
import jakarta.annotation.PreDestroy;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import javax.net.ServerSocketFactory;
import javax.net.ssl.SSLServerSocketFactory;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@Slf4j
@Component
public class SocketServer {

    private final SocketConfig config;
    private final ExecutorService pool;
    private ServerSocket serverSocket;

    public SocketServer(SocketConfig config) throws Exception {
        this.config = config;
        this.pool = Executors.newFixedThreadPool(config.getThreadPoolSize());
        initServerSocket();
    }

    private void initServerSocket() throws Exception {
        ServerSocketFactory factory = config.isSslEnabled()
                ? SSLServerSocketFactory.getDefault()
                : ServerSocketFactory.getDefault();

        // 如果使用自定义 keystore
        if (config.isSslEnabled()) {
            SSLContext ctx = SslUtils.createSSLContext(
                    config.getSsl().getKeystore(),
                    config.getSsl().getKeystorePassword(),
                    config.getSsl().getKeyAlias()
            );
            factory = ctx.getServerSocketFactory();
        }

        serverSocket = factory.createServerSocket(config.getPort());
        log.info("Socket Server started on port {}", config.getPort());
        // 线程启动：不断接受新连接
        Thread acceptThread = new Thread(this::acceptLoop);
        acceptThread.setDaemon(true);
        acceptThread.start();
    }

    private void acceptLoop() {
        while (!Thread.currentThread().isInterrupted()) {
            try {
                Socket client = serverSocket.accept();
                client.setSoTimeout(config.getReadTimeoutMs());
                pool.execute(new SocketHandler(client, config));
            } catch (Exception e) {
                if (serverSocket.isClosed()) {
                    log.warn("Server socket closed, stopping accept loop");
                    break;
                }
                log.error("Error accepting connection", e);
            }
        }
    }

    @PreDestroy
    public void shutdown() {
        try {
            serverSocket.close();
        } catch (Exception e) {
            log.warn("Error closing server socket", e);
        }
        pool.shutdownNow();
        log.info("Socket Server shut down");
    }
}
```

### 4.5 单连接处理器

```java
package com.example.socket.server;

import com.example.socket.config.SocketConfig;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.io.*;
import java.nio.charset.StandardCharsets;

@Slf4j
public class SocketHandler implements Runnable {

    private final Socket socket;
    private final SocketConfig config;

    public SocketHandler(Socket socket, SocketConfig config) {
        this.socket = socket;
        this.config = config;
    }

    @Override
    public void run() {
        String clientInfo = socket.getRemoteSocketAddress().toString();
        try (InputStream in = socket.getInputStream();
             BufferedInputStream bis = new BufferedInputStream(in);
             OutputStream out = socket.getOutputStream();
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(out, StandardCharsets.UTF_8))) {

            log.info("Connection accepted from {}", clientInfo);

            // 读取单条消息（这里以 \n 为分隔符）
            byte[] buffer = new byte[config.getMaxMessageLength()];
            int readBytes = bis.read(buffer);
            if (readBytes < 0) {
                log.warn("Client closed connection immediately: {}", clientInfo);
                return;
            }

            if (readBytes > config.getMaxMessageLength()) {
                log.warn("Message too long from {}: {} bytes", clientInfo, readBytes);
                // 可以根据业务决定是否拒绝
                return;
            }

            String payload = new String(buffer, 0, readBytes, StandardCharsets.UTF_8).trim();
            log.info("Received from {}: {}", clientInfo, payload);

            // 简单业务处理：这里只回 echo
            String response = "ACK: " + payload + "\n";
            writer.write(response);
            writer.flush();
        } catch (IOException e) {
            log.warn("I/O error with {}: {}", clientInfo, e.getMessage());
        } finally {
            try {
                socket.close();
                log.info("Connection closed: {}", clientInfo);
            } catch (IOException e) {
                log.warn("Failed to close socket {}", clientInfo);
            }
        }
    }
}
```

> **业务层可自行替换**  
> - 如果你想处理 JSON、XML 或自定义二进制协议，只需在 `SocketHandler` 中做相应的解析即可。  
> - 为了防止业务代码注入，请务必在业务层验证数据格式、长度、编码等。

