            out.println("</html>");
        } catch (Exception e) {
            // 4. Fail gracefully – do NOT leak stack traces or internal data.
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR,
                           "An unexpected error occurred. Please try again later.");
