import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.stream.Collectors;

public final class StudentManager {
    private final ConcurrentMap<Integer, Student> store = new ConcurrentHashMap<>();

    // ---------------- Add -----------------
    public Student addStudent(String name, String email, double gpa) {
        int id = SecurityUtils.secureRandomId();
        Student s = new Student(id, name, email, gpa);
        // Put-if-absent protects against accidental duplicate IDs
        if (store.putIfAbsent(id, s) != null) {
            // In the rare event of ID collision, retry
            return addStudent(name, email, gpa);
        }
        SecurityUtils.auditLog("Added student: " + s);
        return s;
    }

    // ---------------- Remove -----------------
    public boolean removeStudentById(int id) {
        Student removed = store.remove(id);
        if (removed != null) {
            SecurityUtils.auditLog("Removed student: " + removed);
            return true;
        }
        return false;
    }

    // ---------------- Update -----------------
    public boolean updateStudent(int id, String name, String email, double gpa) {
        return store.computeIfPresent(id, (key, oldStudent) -> {
            oldStudent.setName(name);
            oldStudent.setEmail(email);
            oldStudent.setGpa(gpa);
            SecurityUtils.auditLog("Updated student: " + oldStudent);
            return oldStudent;
        }) != null;
    }

    // ---------------- Search -----------------
    public Optional<Student> searchById(int id) {
        return Optional.ofNullable(store.get(id));
    }

    public List<Student> searchByName(String nameFragment) {
        String lower = nameFragment.toLowerCase();
        return store.values().stream()
                .filter(s -> s.getName().toLowerCase().contains(lower))
                .collect(Collectors.toList());
    }

    // ---------------- Report -----------------
    public String generateReport() {
        // Simple CSV report: id,name,email,gpa
        StringBuilder sb = new StringBuilder();
        sb.append("id,name,email,gpa\n");
        store.values().stream()
                .sorted(Comparator.comparingInt(Student::getId))
                .forEach(s -> sb.append(s.getId()).append(",")
                        .append(s.getName()).append(",")
                        .append(s.getEmail()).append(",")
                        .append(String.format("%.2f", s.getGpa())).append("\n"));
        SecurityUtils.auditLog("Generated report with " + store.size() + " students");
        return sb.toString();
    }
}
