// Message.java
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class Message implements Serializable {
    private static final long serialVersionUID = 1L;
    public MsgType type;
    public byte[] payload;   // 纯字节流，长度取决于 type

    public Message(MsgType type, byte[] payload) {
        this.type = type;
        this.payload = payload;
    }

    // 发送方法
    public static void send(Message msg, DataOutputStream out) throws IOException {
        byte[] payload = msg.payload;
        int len = 1 + payload.length; // 1 byte type + payload
        out.writeInt(len);
        out.writeByte(msg.type.ordinal());
        out.write(payload);
        out.flush();
    }

    // 接收方法
    public static Message receive(DataInputStream in) throws IOException {
        int len = in.readInt();           // read total length
        byte typeByte = in.readByte();
        MsgType type = MsgType.values()[typeByte];
        int payloadLen = len - 1;
        byte[] payload = new byte[payloadLen];
        in.readFully(payload);
        return new Message(type, payload);
    }
}

// MsgType.java
public enum MsgType { TEXT, IMAGE, FILE, COMMAND }
