    private ExecutorService pool = Executors.newFixedThreadPool(20);
    private final Set<ClientHandler> pending = ConcurrentHashMap.newKeySet(); // waiting list

    // 加载自签证书（或从受信任 CA）
    private SSLServerSocketFactory sslFactory() throws Exception {
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream("keystore.jks"), "changeit".toCharArray());

        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, "changeit".toCharArray());

        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(kmf.getKeyManagers(), null, null);
        return ctx.getServerSocketFactory();
    }

    public void start() throws Exception {
        SSLServerSocket ss = (SSLServerSocket) sslFactory().createServerSocket(PORT);
        System.out.println("Agent Server started on port " + PORT);

        while (true) {
            SSLSocket socket = (SSLSocket) ss.accept();
            ClientHandler handler = new ClientHandler(socket);
            pending.add(handler);
            pool.execute(handler);
        }
    }

    public static void main(String[] args) throws Exception {
        new AgentServer().start();
    }
}
