// ClientHandler.java
class ClientHandler implements Runnable {
    private SSLSocket socket;
    private DataInputStream in;
    private DataOutputStream out;
    private String userId;           // 通过 AUTH 消息获取
    private boolean busy = false;    // 当前客服是否 busy

    ClientHandler(SSLSocket socket) throws IOException {
        this.socket = socket;
        this.in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
        this.out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()));
    }

    @Override
    public void run() {
        try {
            // 第一步：身份验证
            Message authMsg = Message.receive(in);
            if (authMsg.type != MsgType.COMMAND) {
                throw new IOException("Expected AUTH command");
            }
            Map<String, String> cred = parseAuth(authMsg.payload);
            if (!checkCredential(cred)) {
                sendError("Authentication failed");
                return;
            }
            this.userId = cred.get("userId");
            System.out.println("User connected: " + userId);

            // 通知客服端 UI（伪代码）
            AgentUI.getInstance().addPendingUser(this);

            // 等待客服接手
            while (!busy) {
                Thread.sleep(500);
            }

            // 主循环
            while (!socket.isClosed() && !Thread.currentThread().isInterrupted()) {
                Message msg = Message.receive(in);
                handleMessage(msg);
            }
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        } finally {
            cleanup();
        }
    }

    private void handleMessage(Message msg) throws IOException {
        switch (msg.type) {
            case TEXT:
                String txt = new String(msg.payload, StandardCharsets.UTF_8);
                System.out.println("From " + userId + ": " + txt);
                // 记录日志
                ChatLog.save(userId, txt, false);
                // 反向发送给客服端 UI
                AgentUI.getInstance().displayMessage(userId, txt);
                break;
            case IMAGE:
            case FILE:
                // 处理文件/图片（保存在 temp 目录）
                String filename = UUID.randomUUID() + ".dat";
                Path path = Paths.get("temp", filename);
                Files.write(path, msg.payload);
                ChatLog.saveFile(userId, filename, msg.type);
                // 反馈客服端 UI
                AgentUI.getInstance().displayFile(userId, filename, msg.type);
                break;
            default:
                // 其它类型...
                break;
        }
    }

    public void sendMessage(Message msg) {
        try {
            Message.send(msg, out);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 关闭连接
    private void cleanup() {
        try { socket.close(); } catch (IOException ignored) {}
        AgentUI.getInstance().removePendingUser(this);
    }

