        String authJson = "{\"userId\":\""+userId+"\", \"token\":\""+token+"\"}";
        Message authMsg = new Message(MsgType.COMMAND, authJson.getBytes(StandardCharsets.UTF_8));
        Message.send(authMsg, out);

        // 监听后台线程
        new Thread(this::listen).start();
    }

    private void listen() {
        try {
            while (!socket.isClosed()) {
                Message msg = Message.receive(in);
                switch (msg.type) {
                    case TEXT:
                        String txt = new String(msg.payload, StandardCharsets.UTF_8);
