// ChatLog.java
import java.nio.file.*;
import java.util.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.concurrent.ConcurrentHashMap;

public class ChatLog {
    private static final Path LOG_DIR = Paths.get("chat_logs");
    private static final ObjectMapper mapper = new ObjectMapper();

    static {
        try {
            Files.createDirectories(LOG_DIR);
        } catch (IOException ignored) {}
    }

    // 记录文字
    public static synchronized void save(String userId, String txt, boolean isAgent) {
        Path file = LOG_DIR.resolve(userId + ".json");
        List<Msg> msgs = readMsgs(file);
        msgs.add(new Msg(isAgent ? "Agent" : "User", txt, System.currentTimeMillis()));
        writeMsgs(file, msgs);
    }

    // 记录文件
    public static synchronized void saveFile(String userId, String filename, MsgType type) {
        // 这里简单记录文件名与类型
    }

    private static List<Msg> readMsgs(Path file) {
        try {
            if (!Files.exists(file)) return new ArrayList<>();
            return Arrays.asList(mapper.readValue(file.toFile(), Msg[].class));
        } catch (IOException e) {
            return new ArrayList<>();
        }
    }

    private static void writeMsgs(Path file, List<Msg> msgs) throws IOException {
        mapper.writeValue(file.toFile(), msgs);
    }

    private static class Msg {
        public String sender;
        public String content;
        public long ts;
        public Msg() {}
        public Msg(String s, String c, long t) {sender=s;content=c;ts=t;}
    }
}
