## 4. Secure SessionFactory creation

```java
package com.example.util;

import org.hibernate.SessionFactory;
import org.hibernate.boot.MetadataSources;
import org.hibernate.boot.registry.StandardServiceRegistryBuilder;
import org.hibernate.cfg.Environment;

import java.util.Map;
import java.util.Properties;

public final class HibernateUtil {

    private static final SessionFactory sessionFactory = buildSessionFactory();

    private static SessionFactory buildSessionFactory() {
        try {
            // Load properties from hibernate.cfg.xml
            Properties settings = new Properties();
            settings.putAll(Environment.getProperties());

            /* 
             * 1️⃣ Read the password from an environment variable.
             *     In production you would use a secrets manager instead.
             */
            String h2Password = System.getenv("H2_PASSWORD");
            if (h2Password == null || h2Password.isBlank()) {
                throw new IllegalStateException(
                        "Environment variable H2_PASSWORD not set. " +
                        "Set it to a secure random string for production use."
                );
            }
            settings.put("hibernate.connection.password", h2Password);

            // Build the registry
            var registry = new StandardServiceRegistryBuilder()
                    .applySettings(settings)
                    .build();

            // Create MetadataSources from configuration
            var sources = new MetadataSources(registry);

            // Add annotated classes – can also be done via scanning
            sources.addAnnotatedClass(com.example.entity.Employee.class);

            // Build the SessionFactory
            return sources.buildMetadata().buildSessionFactory();
        } catch (Exception e) {
            System.err.println("SessionFactory creation failed: " + e.getMessage());
            throw new ExceptionInInitializerError(e);
        }
    }

    public static SessionFactory getSessionFactory() {
        return sessionFactory;
    }

    public static void shutdown() {
        getSessionFactory().close();
    }
}
```

> **Why not use `SessionFactoryBuilder` from config file?**  
> We override the password at runtime, ensuring the source code never contains the secret.

