## 4.  Swing Client – Non‑Threaded vs Multi‑Threaded

```java
// File: Client.java
import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
import java.util.concurrent.*;
import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;

public class Client extends JFrame {

    private static final long serialVersionUID = 1L;

    private DataService remote;
    private JTextArea output;
    private JButton nonThreadBtn, multiThreadBtn;

    public Client() {
        super("RMI Encyclopedia Demo");
        initUI();
        connectToServer();
    }

    private void initUI() {
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(700, 500);
        setLocationRelativeTo(null);

        output = new JTextArea();
        output.setEditable(false);
        output.setFont(new Font("Monospaced", Font.PLAIN, 12));
        JScrollPane scroll = new JScrollPane(output);

        nonThreadBtn = new JButton("Run Non‑Threaded");
        multiThreadBtn = new JButton("Run Multi‑Threaded");

        JPanel btnPanel = new JPanel();
        btnPanel.add(nonThreadBtn);
        btnPanel.add(multiThreadBtn);

        add(scroll, BorderLayout.CENTER);
        add(btnPanel, BorderLayout.SOUTH);

        nonThreadBtn.addActionListener(e -> runNonThreaded());
        multiThreadBtn.addActionListener(e -> runMultiThreaded());
    }

    private void connectToServer() {
        try {
            Registry reg = LocateRegistry.getRegistry("localhost", 1099);
            remote = (DataService) reg.lookup("DataService");
            output.append("Connected to RMI server.\n");
        } catch (Exception ex) {
            ex.printStackTrace();
            output.append("Could not connect to server.\n");
        }
    }

    // ---------- 1. Non‑threaded ----------
    private void runNonThreaded() {
        try {
            output.append("\n--- Non‑Threaded Execution ---\n");
            long start = System.nanoTime();

            int count = remote.Count();
            String repeated = remote.repeatedwords();
            String longest = remote.longest();
            String shortest = remote.shortest();
            String repeatMap = remote.Repeat();

            long elapsed = System.nanoTime() - start;
            long millis = elapsed / 1_000_000;

            output.append(String.format("Total letters (incl. spaces): %d\n", count));
            output.append(String.format("Repeated words: %s\n", repeated.isEmpty() ? "(none)" : repeated));
            output.append(String.format("Longest word: %s\n", longest));
            output.append(String.format("Shortest word: %s\n", shortest));
            output.append(String.format("Repeat map: %s\n", repeatMap));
            output.append(String.format("Non‑threaded time: %d ms\n", millis));
        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

    // ---------- 2. Multi‑threaded ----------
    private void runMultiThreaded() {
        try {
            output.append("\n--- Multi‑Threaded Execution ---\n");
            long start = System.nanoTime();

            ExecutorService executor = Executors.newFixedThreadPool(5);

            Future<Integer> fCount = executor.submit(() -> remote.Count());
            Future<String> fRepeated = executor.submit(() -> remote.repeatedwords());
            Future<String> fLongest = executor.submit(() -> remote.longest());
            Future<String> fShortest = executor.submit(() -> remote.shortest());
            Future<String> fRepeatMap = executor.submit(() -> remote.Repeat());

            // Wait for all to finish
            int count = fCount.get();
            String repeated = fRepeated.get();
            String longest = fLongest.get();
            String shortest = fShortest.get();
            String repeatMap = fRepeatMap.get();

            executor.shutdownNow();

            long elapsed = System.nanoTime() - start;
            long millis = elapsed / 1_000_000;

            output.append(String.format("Total letters (incl. spaces): %d\n", count));
            output.append(String.format("Repeated words: %s\n", repeated.isEmpty() ? "(none)" : repeated));
            output.append(String.format("Longest word: %s\n", longest));
            output.append(String.format("Shortest word: %s\n", shortest));
            output.append(String.format("Repeat map: %s\n", repeatMap));
            output.append(String.format("Multi‑threaded time: %d ms\n", millis));
        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

    // ---------- Main ----------
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            Client c = new Client();
            c.setVisible(true);
        });
    }
}
```

### Running the client

