using System;
using System.Net;
using System.Net.Sockets;
using System.Threading;

class VpnServer
{
    const int ControlPort = 12345;      // TCP control connection
    const int BufferSize = 1500;        // Ethernet MTU

    static void Main()
    {
        Console.WriteLine("VPN Server starting...");

        // 1. Listen for incoming VPN client connections
        TcpListener listener = new TcpListener(IPAddress.Any, ControlPort);
        listener.Start();
        Console.WriteLine($"Listening on port {ControlPort} ...");

        while (true)
        {
            TcpClient vpnClient = listener.AcceptTcpClient();
            Console.WriteLine("VPN client connected.");

            // Handle each client in its own thread
            ThreadPool.QueueUserWorkItem(_ => HandleClient(vpnClient));
        }
    }

    static void HandleClient(TcpClient client)
    {
        NetworkStream ns = client.GetStream();

        byte[] buffer = new byte[BufferSize];
        while (true)
        {
            // 2. Read a packet from the client (prefixed with length)
            int read = ns.Read(buffer, 0, 2);   // first 2 bytes = length
            if (read == 0) break; // connection closed
            int pktLen = BitConverter.ToUInt16(buffer, 0);

            // read the whole packet
            int offset = 2;
            while (pktLen > 0 && offset < BufferSize)
            {
                int r = ns.Read(buffer, offset, pktLen);
                offset += r;
                pktLen -= r;
            }

            // 3. Parse IP header to get destination
            if (!TryParseIpHeader(buffer, offset - pktLen, out IPAddress destIP,
                                  out byte protocol))
            {
                Console.WriteLine("Bad packet – skipping");
                continue;
            }

            // 4. Forward the packet to the real destination
            SendRawPacket(destIP, protocol, buffer, offset - pktLen);
        }

        client.Close();
    }

    // Very small IP header parser – only IPv4
    static bool TryParseIpHeader(byte[] data, int offset, out IPAddress destIP, out byte protocol)
    {
        destIP = null;
        protocol = 0;
        if (data.Length < offset + 20) return false;

        destIP = new IPAddress(BitConverter.ToUInt32(data, offset + 16));
        protocol = data[offset + 9];
        return true;
    }

    // Send a packet using a raw socket (requires admin)
    static void SendRawPacket(IPAddress destIP, byte protocol, byte[] data, int len)
    {
        try
        {
            Socket raw = new Socket(AddressFamily.InterNetwork, SocketType.Raw, protocol);
            raw.Connect(destIP); // connect to destination (IP only)
            raw.Send(data, len, SocketFlags.None);
            raw.Close();
            Console.WriteLine($"Forwarded packet to {destIP}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to forward to {destIP}: {ex.Message}");
        }
    }
}
```

### What’s happening?

1. **Control connection** – the client establishes a TCP connection to the server (`ControlPort`).  
2. **Packet framing** – the client sends each captured packet preceded by a 2‑byte length field.  
3. **IP parsing** – the server extracts the destination IP and protocol.  
4. **Raw send** – a raw socket is created and the packet is injected into the local IP stack (OS does the routing to the real destination).  

> ⚠️  Windows will drop raw IP packets sent from user mode unless `IP_HDRINCL` is set and the socket is opened with `ProtocolType.Any`.  
> In this simplified example we use the protocol number directly to create the raw socket (e.g. `ProtocolType.Tcp`).  
> For IPv6 or other protocols you’ll need to extend the parser.  

---

## 3. Client – Capture & Forward

```csharp
// ------------------------------------------------------------
// Client.cs
// ------------------------------------------------------------
using System;
using System.Net;
using System.Net.Sockets;
using System.Threading;

class VpnClient
{
    const string ServerIP = "192.0.2.1"; // replace with your server
    const int ServerPort = 12345;        // same as server
    const int BufferSize = 1500;         // Ethernet MTU

    static void Main()
    {
        Console.WriteLine("VPN Client starting...");

        // 1. Connect to the VPN server
        TcpClient vpn = new TcpClient(ServerIP, ServerPort);
        NetworkStream ns = vpn.GetStream();

        // 2. Set up raw socket to capture all outgoing IP traffic
        Socket raw = new Socket(AddressFamily.InterNetwork,
                                SocketType.Raw,
                                ProtocolType.IP);

        // Bind to the local interface (0.0.0.0 means all)
        raw.Bind(new IPEndPoint(IPAddress.Any, 0));

        // Enable IP_HDRINCL (so we send raw IP headers)
        raw.SetSocketOption(SocketOptionLevel.IP, SocketOptionName.HeaderIncluded, true);

        Console.WriteLine("Raw socket opened. Capturing traffic...");

        byte[] recvBuf = new byte[BufferSize];

        // 3. Start a background thread that forwards captured packets
        Thread forwardThread = new Thread(() =>
        {
            while (true)
            {
                int bytesRead = raw.Receive(recvBuf);
                if (bytesRead == 0) continue;

                // Send the packet to the server
                byte[] lengthPrefix = BitConverter.GetBytes((ushort)bytesRead);
                ns.Write(lengthPrefix, 0, lengthPrefix.Length);
                ns.Write(recvBuf, 0, bytesRead);
            }
        });
        forwardThread.IsBackground = true;
        forwardThread.Start();

        // 4. Listen for incoming packets from the server
        while (true)
        {
            // read length prefix
            int read = ns.Read(recvBuf, 0, 2);
            if (read == 0) break; // server closed

            int pktLen = BitConverter.ToUInt16(recvBuf, 0);
            int offset = 0;
            while (pktLen > 0)
            {
                int r = ns.Read(recvBuf, offset, pktLen);
                offset += r;
                pktLen -= r;
            }

            // Inject back into the local stack
            raw.Send(recvBuf, offset, SocketFlags.None);
            Console.WriteLine($"Injected packet back into local stack ({offset} bytes)");
        }

        vpn.Close();
    }
}
```

### How it works

1. **Raw socket capture** – The client opens a raw IP socket (`ProtocolType.IP`) and listens on all local IP addresses.  
2. **Packet forwarding** – In a background thread, any packet the OS sends out is read from the raw socket and forwarded over the TCP control connection to the server.  
3. **Reply injection** – The client also receives packets from the server and writes them back to the raw socket. The OS then delivers them to the application layer.

> **Important:** The raw socket receives *all* outbound IP traffic, not just traffic you want to route through the VPN.  
> For a real VPN you’d want to install a virtual adapter (TUN/TAP) and route only traffic to that adapter.  
> Windows’ built‑in “TAP‑Windows” driver is the easiest route, but it requires a driver installation and isn’t pure C#.

---

## 4. Making the Client the Default Gateway (Optional)

If you want **all** traffic to go through the client (without installing a tun interface), you can add a default route that points to the client’s **loopback** interface or a dedicated IP you control.  

```csharp
using System;
using System.Runtime.InteropServices;

class RouteManager
{
    [DllImport("iphlpapi.dll", CharSet = CharSet.Unicode)]
    private static extern uint CreateIpForwardEntry(ref MIB_IPFORWARDROW pRoute);

    [StructLayout(LayoutKind.Sequential)]
    struct MIB_IPFORWARDROW
    {
        public uint dwForwardDest;
        public uint dwForwardMask;
        public uint dwForwardPolicy;
        public uint dwForwardNextHop;
        public uint dwForwardIfIndex;
        public uint dwForwardType;
        public uint dwForwardProto;
        public uint dwForwardAge;
        public uint dwForwardMetric1;
        public uint dwForwardMetric2;
        public uint dwForwardMetric3;
        public uint dwForwardMetric4;
        public uint dwForwardMetric5;
    }

    public static void AddDefaultRoute(string gatewayIp, uint interfaceIndex)
    {
        var route = new MIB_IPFORWARDROW
        {
            dwForwardDest = 0,                 // 0.0.0.0
            dwForwardMask = 0,                 // 0.0.0.0
            dwForwardPolicy = 0,
            dwForwardNextHop = BitConverter.ToUInt32(
                IPAddress.Parse(gatewayIp).GetAddressBytes(), 0),
            dwForwardIfIndex = interfaceIndex,
            dwForwardType = 4,                 // Static
            dwForwardProto = 3,                // Manual
            dwForwardAge = 0,
            dwForwardMetric1 = 1
        };

        uint result = CreateIpForwardEntry(ref route);
        if (result != 0)
            throw new Exception($"CreateIpForwardEntry failed with {result}");
    }
}
```

*Call `AddDefaultRoute` with the client’s IP and the interface index you want to use.*  

> You can obtain the interface index via `NetworkInterface.GetAllNetworkInterfaces()` or `GetIfEntry` from IP Helper.

---

## 5. Security Enhancements (What You Should Add)

| Feature | Why it matters | Where to add it |
|---------|----------------|-----------------|
| **TLS/DTLS** | Encrypts the tunnel itself. | Wrap the `TcpClient`/`TcpListener` streams in `SslStream`. |
| **Mutual authentication** | Prevents rogue servers/clients. | Use certificates or pre‑shared keys. |
| **Integrity protection** | Detect packet tampering. | HMAC over each packet or use authenticated encryption (AES‑GCM). |
| **Packet filtering** | Prevent leaking of sensitive data. | Drop packets that do not meet your policy before forwarding. |
| **Rate limiting** | Thwart DoS by overloading the tunnel. | Queue packets and enforce bandwidth caps. |
| **Logging** | For diagnostics / audit. | Log connections, packet counts, errors. |

---

## 6. Testing the Sample

1. **Build the server** (`VpnServer.exe`) on a machine reachable by the client.  
2. **Build the client** (`VpnClient.exe`) and run as **Administrator**.  
3. **Route traffic**:  
   * Option 1 – Set your browser or `curl` to use a local HTTP proxy (`127.0.0.1:3128`).  
   * Option 2 – Add a default route pointing to the client’s IP (see section 4).  
4. Open a browser or run `ping 8.8.8.8`.  
5. You should see the client’s console printing “Captured packet…” and the server’s console printing “Forwarded packet to …”.

> **Note:** Because the client’s raw socket receives **all** outbound traffic, you may see packets for local network traffic too. Filter them in the client if needed.

---

## 7. What This Is NOT

- A full‑blown VPN (OpenVPN / WireGuard) – no tun interface, no encryption.  
- A kernel‑mode driver – all logic lives in user space.  
- A secure product – no authentication, no encryption.  

Use this only as a **proof‑of‑concept** or for educational labs. Before deploying anything in production, you must:

* Add proper encryption & authentication.  
* Replace the raw‑socket capture with a **TUN/TAP** virtual adapter so you can control exactly what traffic goes through the tunnel.  
* Harden the server against DoS and malicious packets.

---

## 8. Wrap‑Up

You now have:

1. A minimal **server** that accepts raw packets over a TCP control channel and forwards them.  
2. A **client** that captures raw IP traffic, sends it to the server, and injects replies back.  
3. A simple route‑injection helper.  

With this skeleton, you can start experimenting:

* Add TLS (`SslStream`) to secure the control channel.  
* Replace the raw socket with a proper **TUN** interface using the Windows TUN/TAP driver (or a cross‑platform equivalent).  
* Implement per‑packet encryption (AES‑GCM) for confidentiality.

Happy hacking – and remember: *any VPN implementation that handles arbitrary traffic on a shared network is a serious security vector; always review, test, and audit!*

