 * 2. Starts the Node bridge (a TCP server listening on port 5000).
 * 3. Provides a console command to load a JS module at runtime.
 */
@Mod(modid = "forgejs", name = "Forge JS Loader", version = "1.0.0",
     acceptableRemoteVersions = "*")
class ForgeJSMod {

    private val nodeBridge = NodeBridge(port = 5000)

    @Mod.EventHandler
    fun preInit(event: FMLPreInitializationEvent) {
        // nothing needed yet
    }

    @Mod.EventHandler
    fun onServerStarting(event: FMLServerStartingEvent) {
        // start the bridge
        nodeBridge.start()
        // register command /jsload <path>
        event.registerServerCommand(JSLoadCommand(nodeBridge))
    }

    @Mod.EventHandler
    fun postInit(event: net.minecraftforge.fml.common.event.FMLPostInitializationEvent) {
        // register a simple tick listener so we can see that the mod is alive
        MinecraftForge.EVENT_BUS.register(this)
    }

    @SubscribeEvent
    fun onTick(event: TickEvent.ServerTickEvent) {
        if (event.phase == TickEvent.Phase.END) {
            // nothing special – just keeps the mod alive
        }
    }
}
