> **What `JSLoadCommand` does** – it reads the file, hands the text to `JSModuleLoader.load`, then prints a confirmation in the Node terminal.  
>   The command is defined in the same file for brevity:

```kotlin
import net.minecraft.command.CommandBase
import net.minecraft.command.ICommandSender
import net.minecraft.server.MinecraftServer
import net.minecraft.util.text.TextComponentString
import java.io.File

class JSLoadCommand(private val bridge: NodeBridge) : CommandBase() {
    override fun getName() = "jsload"
    override fun getUsage(sender: ICommandSender) = "/jsload <path to .js>"

    override fun execute(
        server: MinecraftServer,
        sender: ICommandSender,
        args: Array<String>
    ) {
        if (args.isEmpty()) {
            sender.sendMessage(TextComponentString("Usage: $usage"))
            return
        }

        val file = File(args[0])
        if (!file.exists()) {
            sender.sendMessage(TextComponentString("File not found: $file"))
            return
        }

        try {
            val loader = JSModuleLoader(bridge)
            loader.load(file.readText(), file.name)
            sender.sendMessage(TextComponentString("Loaded ${file.name} successfully."))
        } catch (e: Exception) {
            sender.sendMessage(TextComponentString("Error loading JS: ${e.message}"))
            e.printStackTrace()
        }
    }
}
```

