### 3.2 `JSModuleLoader.kt`

```kotlin
package com.example.forgejs

import javax.script.Invocable
import javax.script.ScriptEngine
import javax.script.ScriptEngineManager
import javax.script.SimpleBindings
import java.util.concurrent.ConcurrentHashMap

/**
 * 1. Instantiates a Nashorn engine (JS 2015‑style).
 * 2. Exposes a very small Node‑like API:
 *      - console.log(...)
 *      - process.env
 *      - require(modulePath) – loads from the mod’s classpath/resources
 *
 * 3. Keeps a map of loaded modules so `require` can reuse them.
 */
class JSModuleLoader(private val bridge: NodeBridge) {

    private val engine: ScriptEngine = ScriptEngineManager().getEngineByName("nashorn")
    private val moduleCache = ConcurrentHashMap<String, Any?>()

    init {
        // Expose a "console" object that forwards to NodeBridge
        val console = object {
            @Suppress("unused")
            fun log(vararg args: Any?) {
                val message = args.joinToString(" ") { it?.toString() ?: "null" }
                bridge.sendLog("[JS] $message")
            }

            @Suppress("unused")
            fun error(vararg args: Any?) {
                val message = args.joinToString(" ") { it?.toString() ?: "null" }
                bridge.sendLog("[JS-ERROR] $message")
            }
        }
        engine.put("console", console)

        // process.env – expose a minimal env map
        engine.put("process", object {
            @Suppress("unused")
            val env = mapOf(
                "MODID" to "forgejs",
                "MC_VERSION" to "1.8.9"
            )
        })

        // Simple require implementation
        engine.put("require", object {
            @Suppress("unused")
            fun require(path: String): Any? {
                val normalized = path.trim('/').replace("\\", "/")
                return if (moduleCache.containsKey(normalized)) {
                    moduleCache[normalized]
                } else {
                    val js = loadModuleFile(normalized)
                    val module = engine.eval(js) // evaluate in same context
                    moduleCache[normalized] = module
                    module
                }
            }
        })
    }

    /**
     * Load a module from a string. The first argument is the JS source,
     * the second is a “module name” (used for caching and debugging).
     */
    fun load(source: String, moduleName: String = "module") {
        // Wrap the module code to emulate Node.js module scope
        val wrapped =
            """
            (function(exports, require, module, __filename, __dirname) {
                $source
            })({}, require, {exports: {}}, "$moduleName", "${moduleName.substringBeforeLast('/')}"); 
            """
        engine.eval(wrapped)
    }

    /** Reads a JS file from resources or the file system */
    private fun loadModuleFile(path: String): String {
        // First try classpath (resources folder)
        val stream = this::class.java.classLoader.getResourceAsStream(path)
        if (stream != null) {
            return stream.bufferedReader().use { it.readText() }
        }
        // Fall back to absolute file system path
        val file = java.io.File(path)
        if (file.exists()) return file.readText()
        throw IllegalArgumentException("Module not found: $path")
    }
}
```

> **Why wrap the module** – Node.js gives each file its own scope (`exports`, `module`, `require`).  
>  The wrapper keeps the API consistent while still running inside Nashorn.

