### 3.3 `NodeBridge.kt`

```kotlin
package com.example.forgejs

import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.net.ServerSocket
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * 1. Starts a **TCP** server on a chosen port (default 5000).  
 * 2. Accepts a single client (Node.js process).  
 * 3. Provides `sendLog(msg: String)` that forwards logs to that client.  
 *
 * **Node side**: a tiny script that connects to this port and prints everything it receives.
 */
class NodeBridge(private val port: Int) {

    private val server = ServerSocket(port)
    private val isRunning = AtomicBoolean(false)
    private val threadPool = Executors.newCachedThreadPool()

    private var out: PrintWriter? = null

    /**
     * Start listening for a Node client. Runs in its own thread.
     */
    fun start() {
        if (isRunning.getAndSet(true)) return
        threadPool.execute {
            println("[ForgeJS] NodeBridge listening on port $port")
            val socket = server.accept()
            println("[ForgeJS] Node client connected: ${socket.remoteSocketAddress}")
            out = PrintWriter(socket.getOutputStream(), true)
            // Optionally read back from Node if needed
            threadPool.execute { readFromNode(socket) }
        }
    }

    private fun readFromNode(socket: java.net.Socket) {
        val reader = BufferedReader(InputStreamReader(socket.getInputStream()))
        try {
            var line: String?
            while (reader.readLine().also { line = it } != null) {
                // Echo back to the server console, optional
                println("[Node→Forge] $line")
            }
        } catch (e: Exception) {
            println("[ForgeJS] NodeBridge read error: ${e.message}")
        }
    }

    /** Send a log line to the Node client. */
    fun sendLog(msg: String) {
        out?.println(msg)
    }

    /** Graceful shutdown – not used in this demo but good practice. */
    fun stop() {
        if (!isRunning.getAndSet(false)) return
        server.close()
        threadPool.shutdownNow()
    }
}
```

