import com.example.demo.security.AuthResult;
import com.example.demo.security.NcsAuthenticationProvider;     // the class that contains getAuthToken()
import com.example.demo.security.AuthServiceImpl;                // the class that contains auth()
import com.example.demo.repository.UserRepository;
import com.example.demo.service.EmployeeService;                 // service to load Employee by userId
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import javax.servlet.http.HttpServletRequest;
import java.util.stream.Collectors;

@Service
public class AuthFacade {

    @Autowired private AuthServiceImpl authService;          // inject the original service
    @Autowired private NcsAuthenticationProvider authProvider; // inject the provider that has getAuthToken()
    @Autowired private EmployeeService employeeService;       // service that loads Employee entity
    @Autowired private UserRepository userRepository;         // to resolve login->userId (if needed)
    @Autowired private TokenCache tokenCache;                // cache that stores Token objects

    public AuthResponse login(AuthRequest req, HttpServletRequest http) {
        String ip = http.getRemoteAddr();

        // 1️⃣  AuthServiceImpl.auth(...)
        AuthResult authResult = authService.auth(req.getLogin(), req.getPassword(), ip);
        if (!authResult.isValid()) {
            throw new IllegalArgumentException(authResult.getMessage()); // let the controller map to 401
        }

        // 2️⃣  Load the corresponding Employee (you may need to adapt this to your domain)
        Employee employee = employeeService.findByUserId(authResult.getUserId());
        if (employee == null) {
            throw new IllegalStateException("No employee found for userId=" + authResult.getUserId());
        }

        // 3️⃣  Run the partner/company checks that the original provider does
        UsernamePasswordAuthenticationToken authToken =
                authProvider.getAuthToken(req.getLogin(), authResult.getToken(), employee);

        // 4️⃣  Put the authentication in the SecurityContext (so that Spring Security sees it)
        SecurityContextHolder.getContext().setAuthentication(authToken);

        // 5️⃣  Build a response that the front‑end can consume
        AuthResponse resp = new AuthResponse();
        resp.setToken(authResult.getToken());
        resp.setUserId(authResult.getUserId());
        resp.setLogin(employee.getEmail());
        resp.setPhone(employee.getPhone());
        resp.setCompanyCssDir(authToken.getDetails() != null
                && ((UserInfo)authToken.getDetails()).getCompanyCssDir());

        // Convert partners
        resp.setPartners(authToken.getDetails() != null
                ? ((UserInfo)authToken.getDetails()).getPartners()
                    .stream()
                    .map(p -> new PartnerDto(p.getId(), p.getName()))
                    .collect(Collectors.toList())
                : null);

        return resp;
    }
}
```

> **Why the extra service (`AuthFacade`)?**  
> 1. Keeps the controller thin (the classic “fat controller” anti‑pattern).  
> 2. Allows you to mock or replace the *real* auth logic easily in unit tests.  
> 3. Lets you keep a single place where you can add further security‑related plumbing (e.g., audit logging, IP‑rate‑limiting, etc.).

