```java
// DivideServlet.java
package com.example.calc;

import java.io.IOException;
import java.io.PrintWriter;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;

import org.apache.commons.text.StringEscapeUtils;

@WebServlet(name = "DivideServlet", urlPatterns = {"/DivideServlet"})
public class DivideServlet extends HttpServlet {

    @Override
    protected void doPost(HttpServletRequest request,
                          HttpServletResponse response)
            throws ServletException, IOException {

        // 统一使用 UTF-8 编码
        request.setCharacterEncoding("UTF-8");
        response.setContentType("text/plain;charset=UTF-8");
        PrintWriter out = response.getWriter();

        try {
            // 1. 取参数
            String dividendStr = request.getParameter("dividend");
            String divisorStr  = request.getParameter("divisor");

            // 2. 基本校验：不能为空
            if (dividendStr == null || divisorStr == null
                    || dividendStr.trim().isEmpty()
                    || divisorStr.trim().isEmpty()) {
                out.println("错误：请填写完整的被除数与除数。");
                return;
            }

            // 3. 转换为数值类型（double 以支持小数）
            double dividend, divisor;
            try {
                dividend = Double.parseDouble(dividendStr.trim());
                divisor  = Double.parseDouble(divisorStr.trim());
            } catch (NumberFormatException e) {
                out.println("错误：输入必须是合法的数字。");
                return;
            }

            // 4. 除数不能为 0（浮点数时使用绝对值阈值）
            if (Math.abs(divisor) < 1e-12) {
                out.println("错误：除数不能为 0。");
                return;
            }

            // 5. 计算并返回结果
            double result = dividend / divisor;
            // 为防止 XSS，使用 HTML 转义（虽然此处为纯文本，演示安全姿态）
            out.println("计算结果：" + StringEscapeUtils.escapeHtml4(String.valueOf(result)));

        } finally {
            out.flush();
            out.close();
        }
    }

    // 为了安全，禁止 GET 请求
    @Override
    protected void doGet(HttpServletRequest request,
                         HttpServletResponse response)
            throws ServletException, IOException {
        response.sendError(HttpServletResponse.SC_METHOD_NOT_ALLOWED,
                "GET 方法不支持，请使用 POST。");
    }
}
```

### 关键安全点说明

| 位置 | 安全要点 | 说明 |
|------|----------|------|
| `request.setCharacterEncoding("UTF-8")` | 编码 | 防止字符编码被篡改导致信息泄露或解析错误 |
| `response.setContentType("text/plain;charset=UTF-8")` | 输出 MIME | 明确返回文本，避免浏览器误判导致 XSS |
| `StringEscapeUtils.escapeHtml4` | 输出转义 | 预防如果后期改成返回 HTML 时仍能转义，防止 XSS |
| `NumberFormatException` 捕获 | 输入校验 | 仅允许合法数字，阻止恶意字符串 |
| `Math.abs(divisor) < 1e-12` | 除零检查 | 兼顾浮点误差，避免 `Infinity`、`NaN` |
| `doGet` 直接 405 | 方法限制 | 只允许 POST，防止信息在 URL 中泄露 |
| `try‑finally` 关闭 PrintWriter | 资源管理 | 保证响应及时发送并释放资源 |

> **扩展**  
> * 如果将来把结果写入数据库，务必使用 **PreparedStatement** 防止 SQL 注入。  
> * 若想支持多语言或更复杂的前端 UI，可考虑使用 `JSP` 或前后端分离的框架（React/Vue），并通过 HTTPS 传输敏感数据。  

