public class HOTELIERServer {

    private final Path jsonPath;
    private final List<Hotel> hotels;          // in‑memory cache

    /* ---------- CONSTRUCTOR ---------- */
    public HOTELIERServer(Path jsonPath) {
        this.jsonPath = jsonPath;
        this.hotels   = loadHotelsFromJson(jsonPath);
    }

    /* ---------- LOAD / SAVE ---------- */
    private List<Hotel> loadHotelsFromJson(Path path) {
        try (Reader reader = Files.newBufferedReader(path, StandardCharsets.UTF_8)) {
            Type listType = new TypeToken<List<Hotel>>() {}.getType();
            return new Gson().fromJson(reader, listType);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private void saveHotelsToJson() {
        try (Writer writer = Files.newBufferedWriter(jsonPath, StandardCharsets.UTF_8)) {
            new GsonBuilder().setPrettyPrinting().create()
                .toJson(hotels, writer);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /* ---------- SEARCH ---------- */
    public List<Hotel> findByCity(String city) {
        return hotels.stream()
            .filter(h -> h.city.equalsIgnoreCase(city))
            .collect(Collectors.toList());
    }

    public List<Hotel> findByServices(List<String> services) {
        return hotels.stream()
            .filter(h -> h.services != null &&
                         h.services.containsAll(services))
            .collect(Collectors.toList());
    }

    /* ---------- UPDATE ---------- */
    public boolean updateRatings(int hotelId, Hotel.Ratings newRatings) {
        Optional<Hotel> opt = hotels.stream()
                                    .filter(h -> h.id == hotelId)
                                    .findFirst();
        if (opt.isEmpty()) return false;
        opt.get().ratings = newRatings;
        saveHotelsToJson();
        return true;
    }

    /* ---------- ADD / REMOVE ---------- */
    public boolean addHotel(Hotel newHotel) {
        if (hotels.stream().anyMatch(h -> h.id == newHotel.id)) return false;
        hotels.add(newHotel);
        saveHotelsToJson();
        return true;
    }

    public boolean removeHotel(int hotelId) {
        boolean removed = hotels.removeIf(h -> h.id == hotelId);
        if (removed) saveHotelsToJson();
        return removed;
    }

    /* ---------- ORDINA / PAGINA ---------- */
    public List<Hotel> getSorted(int page, int size, Comparator<Hotel> cmp) {
        return hotels.stream()
                .sorted(cmp)
                .skip((long) page * size)
                .limit(size)
                .collect(Collectors.toList());
    }

