import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class BankSimulator {

    /* ---------- 业务对象 ---------- */
    static class Account {
        // 账户余额
        private double total = 0.0;

        // 不做同步，容易产生数据竞争
        public void deposit(double amount) {
            // 读
            double old = total;
            // 业务处理（模拟延迟）
            try {
                Thread.sleep(new Random().nextInt(5));   // 随机 0~4 ms
            } catch (InterruptedException e) { /* ignore */ }
            // 写
            total = old + amount;
        }

        public double getTotal() {
            return total;
        }
    }

    /* ---------- 顾客线程 ---------- */
    static class Customer implements Runnable {
        private final Account account;
        private final int id;
        private final int deposits;   // 每位顾客的汇款次数
        private final Random rnd = new Random();

        public Customer(Account account, int id, int deposits) {
            this.account = account;
            this.id = id;
            this.deposits = deposits;
        }

        @Override
        public void run() {
            for (int i = 0; i < deposits; i++) {
                double amt = rnd.nextInt(500) + 1;          // 1~500 元
                account.deposit(amt);
                // 可选：打印每一步，便于观察
                // System.out.printf("Customer %d deposited %.2f, total=%.2f%n",
                //        id, amt, account.getTotal());
            }
        }
    }

    /* ---------- 主程序 ---------- */
    public static void main(String[] args) throws InterruptedException {
        final int RUNS = 5;                 // 运行次数
        final int CUSTOMERS = 10;           // 顾客数
        final int DEPOSITS_PER_CUSTOMER = 50; // 每人汇款次数

        for (int run = 1; run <= RUNS; run++) {
            Account acct = new Account();

            // 用固定大小线程池，保证所有线程同时开始
            ExecutorService pool = Executors.newFixedThreadPool(CUSTOMERS);

            for (int i = 0; i < CUSTOMERS; i++) {
                pool.submit(new Customer(acct, i, DEPOSITS_PER_CUSTOMER));
            }

            // 关闭线程池，等待全部线程结束
            pool.shutdown();
            pool.awaitTermination(1, TimeUnit.MINUTES);

            System.out.printf("Run %d: Expected total = %.2f, Actual total = %.2f%n",
                    run,
