</div>

<script>
/* ------------------------------------------------------------------
 * 3D Wireframe Constructor (VMC)
 * ------------------------------------------------------------------ */

const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

function resizeCanvas(){
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    draw(); // redraw on resize
}

const UI = {
    modeSpan: document.getElementById('mode'),
    toggleBtn: document.getElementById('toggleSnap'),
    resetBtn: document.getElementById('reset')
};

const menu = document.getElementById('menu');
const addLineBtn = document.getElementById('addLineBtn');

let snapMode = true;
UI.modeSpan.innerHTML = 'Mode: <strong>Snap</strong>';

UI.toggleBtn.addEventListener('click', ()=>{
    snapMode = !snapMode;
    UI.modeSpan.innerHTML = `Mode: <strong>${snapMode?'Snap':'Free'}</strong>`;
});
UI.resetBtn.addEventListener('click', ()=>{ reset(); });

/* ------------------------------------------------------------------
 * 3D Math helpers
 * ------------------------------------------------------------------ */
function vec3(x,y,z){return {x,y,z}}
function vec3Add(a,b){return vec3(a.x+b.x,a.y+b.y,a.z+b.z);}
function vec3Sub(a,b){return vec3(a.x-b.x,a.y-b.y,a.z-b.z);}
function vec3Scale(v,s){return vec3(v.x*s,v.y*s,v.z*s);}
function vec3Dot(a,b){return a.x*b.x + a.y*b.y + a.z*b.z;}
function vec3Cross(a,b){
    return vec3(a.y*b.z-a.z*b.y,
                a.z*b.x-a.x*b.z,
                a.x*b.y-a.y*b.x);
}
function vec3Length(v){return Math.hypot(v.x,v.y,v.z);}
function vec3Normalize(v){
    const l=vec3Length(v); return l===0?v:vec3Scale(v,1/l);
}

/* Simple perspective projection (camera at origin, looking along +Z) */
const camera = {dist:400}; // distance from origin to projection plane
function project(v){
    const f = camera.dist / (camera.dist + v.z);
    return {
        x: v.x * f + canvas.width/2,
        y: -v.y * f + canvas.height/2
    };
}

/* ------------------------------------------------------------------
 * Data Structures
 * ------------------------------------------------------------------ */
// 3D grid snapping points
const gridPoints = []; // array of vec3

// Model vertices (the actual wireframe model)
const modelVertices = []; // array of vec3

// Lines: {start: idx, end: idx}
const lines = [];

/* ------------------------------------------------------------------
 * Grid generation (size 200, step 40)
 * ------------------------------------------------------------------ */
function initGrid(){
    gridPoints.length = 0;
    const size = 200;
    const step = 40;
    for(let x=-size;x<=size;x+=step){
        for(let y=-size;y<=size;y+=step){
            for(let z=-size;z<=size;z+=step){
                gridPoints.push(vec3(x,y,z));
            }
        }
    }
}
initGrid();

/* ------------------------------------------------------------------
 * Rotation handling
 * ------------------------------------------------------------------ */
let rotX = 0, rotY = 0;
let isDragging=false, lastMouse={x:0,y:0};

canvas.addEventListener('mousedown', e=>{
    if(e.button===0){
        isDragging=true;
        lastMouse={x:e.clientX,y:e.clientY};
    }
});
canvas.addEventListener('mouseup', e=>{
    if(e.button===0) isDragging=false;
});
canvas.addEventListener('mousemove', e=>{
    if(isDragging){
        const dx = e.clientX - lastMouse.x;
        const dy = e.clientY - lastMouse.y;
        rotY += dx*0.01;
        rotX += dy*0.01;
        lastMouse={x:e.clientX,y:e.clientY};
        draw();
    }
});

/* ------------------------------------------------------------------
 * Mouse interaction (snapping, adding lines, free mode)
 * ------------------------------------------------------------------ */
let hoverIdx = null; // index of grid point under mouse
let selectedIdx = null; // first point selected for line
let freeDragIdx = null; // index in modelVertices being dragged in free mode

canvas.addEventListener('mousemove', onMouseMove);
canvas.addEventListener('click', onClick);
function onMouseMove(e){
    const mouse = {x:e.clientX,y:e.clientY};
    // Find nearest grid point (within threshold) in 3D space
    let best=null, bestDist=Infinity;
    if(snapMode){
        for(let i=0;i<gridPoints.length;i++){
            const g = rotatePoint(gridPoints[i], rotX, rotY);
            const p = project(g);
            const d = Math.hypot(p.x-mouse.x, p.y-mouse.y);
            if(d<20 && d<bestDist){
                best=i; bestDist=d;
            }
        }
    } else if(selectedIdx!==null){
        // In free mode, show menu only when hovering over an existing vertex
        for(let i=0;i<modelVertices.length;i++){
            const p = project(rotatePoint(modelVertices[i],rotX,rotY));
            const d = Math.hypot(p.x-mouse.x, p.y-mouse.y);
            if(d<15 && d<bestDist){
                best=i; bestDist=d;
            }
        }
    }
    if(best!==null && best!==hoverIdx){
        hoverIdx=best;
        if(hoverIdx!==null){
            // Position the menu near the mouse
            menu.style.left = (e.clientX+10)+'px';
            menu.style.top = (e.clientY+10)+'px';
            menu.style.display = 'block';
        } else {
            menu.style.display = 'none';
        }
    }
    if(hoverIdx===null) menu.style.display='none';
}
function onClick(e){
    if(hoverIdx!==null){
        if(selectedIdx===null){
            // First point selected
            selectedIdx = hoverIdx;
        } else {
            // Second point – create a line
            addLine(selectedIdx, hoverIdx);
            selectedIdx = null;
        }
    } else if(!snapMode){
        // In free mode: click to add a new vertex
        const p = screenTo3D(e.clientX, e.clientY);
        const idx = modelVertices.length;
        modelVertices.push(p);
        draw();
    }
}

/* ------------------------------------------------------------------
 * Helper: rotate a point around X and Y
 * ------------------------------------------------------------------ */
function rotatePoint(p,xRad,yRad){
    // Rotation around X
    let y = p.y * Math.cos(xRad) - p.z * Math.sin(xRad);
    let z = p.y * Math.sin(xRad) + p.z * Math.cos(xRad);
    // Rotation around Y
    let x = p.x * Math.cos(yRad) + z * Math.sin(yRad);
    z = -p.x * Math.sin(yRad) + z * Math.cos(yRad);
    return vec3(x,y,z);
}

/* ------------------------------------------------------------------
 * Helper: add line between two grid points (by index)
 * ------------------------------------------------------------------ */
function addLine(idxA, idxB){
    // Ensure both vertices exist in modelVertices
    const map = new Map(); // gridIdx -> modelIdx
    for(let i=0;i<modelVertices.length;i++){
        const gIdx = gridPoints.indexOf(modelVertices[i]);
        if(gIdx!==-1) map.set(gIdx,i);
    }
    let a = map.get(idxA);
    let b = map.get(idxB);
    if(a===undefined){
        a = modelVertices.push(gridPoints[idxA]) - 1;
    }
    if(b===undefined){
        b = modelVertices.push(gridPoints[idxB]) - 1;
    }
    lines.push({start:a,end:b});
    draw();
}

/* ------------------------------------------------------------------
 * Convert screen coordinates to 3D (approximate)
 * ------------------------------------------------------------------ */
function screenTo3D(x,y){
    // This is a simplistic inverse projection assuming z=0
    const ndcX = (x - canvas.width/2) / (canvas.width/2);
    const ndcY = -(y - canvas.height/2) / (canvas.height/2);
    const z = 0; // we assume the plane z=0
    const f = camera.dist / (camera.dist - z);
    return vec3(ndcX * (canvas.width/2)/f,
                ndcY * (canvas.height/2)/f,
                z);
}

/* ------------------------------------------------------------------
 * Menu interaction
 * ------------------------------------------------------------------ */
addLineBtn.addEventListener('click', ()=>{
    if(selectedIdx===null && hoverIdx!==null){
        // start a new line with this point
        selectedIdx = hoverIdx;
    } else if(selectedIdx!==null && hoverIdx!==null){
        // finish line
        addLine(selectedIdx, hoverIdx);
        selectedIdx = null;
    }
    menu.style.display='none';
});

/* ------------------------------------------------------------------
 * Reset function
 * ------------------------------------------------------------------ */
function reset(){
    modelVertices.length = 0;
    lines.length = 0;
    selectedIdx = null;
    draw();
}

/* ------------------------------------------------------------------
 * Rendering
 * ------------------------------------------------------------------ */
function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);

    // 1. Draw grid (small circles)
    ctx.fillStyle='#555';
    for(const gp of gridPoints){
        const rp = rotatePoint(gp, rotX, rotY);
        const pp = project(rp);
        if(pp.x<-20||pp.x>canvas.width+20||pp.y<-20||pp.y>canvas.height+20) continue;
        ctx.beginPath();
        ctx.arc(pp.x,pp.y,4,0,Math.PI*2);
        ctx.fill();
    }

    // 2. Draw existing vertices (model)
    ctx.fillStyle='#0f0';
    for(const v of modelVertices){
        const rv = rotatePoint(v, rotX, rotY);
        const pv = project(rv);
        if(pv.x<-10||pv.x>canvas.width+10||pv.y<-10||pv.y>canvas.height+10) continue;
        ctx.beginPath();
        ctx.arc(pv.x,pv.y,6,0,Math.PI*2);
        ctx.fill();
    }

    // 3. Draw lines
    ctx.strokeStyle='#fff';
    ctx.lineWidth=2;
    for(const ln of lines){
        const a = rotatePoint(modelVertices[ln.start], rotX, rotY);
        const b = rotatePoint(modelVertices[ln.end], rotX, rotY);
        const pa = project(a);
        const pb = project(b);
        ctx.beginPath();
        ctx.moveTo(pa.x,pa.y);
        ctx.lineTo(pb.x,pb.y);
        ctx.stroke();
    }

    // 4. Highlight selected point
    if(selectedIdx!==null){
        const vp = selectedIdx < gridPoints.length
                 ? gridPoints[selectedIdx]
                 : modelVertices[selectedIdx];
        const rv = rotatePoint(vp, rotX, rotY);
        const pv = project(rv);
        ctx.strokeStyle='#ff0';
        ctx.lineWidth=3;
        ctx.beginPath();
        ctx.arc(pv.x,pv.y,10,0,Math.PI*2);
        ctx.stroke();
    }

    // 5. Request next frame
    requestAnimationFrame(draw);
}
draw();
