## 2. Secure Axios wrapper (`src/api/httpClient.ts`)

```ts
/**
 * Secure Axios instance for a React application.
 *
 * Security Features:
 *  • Base URL from env
 *  • Request timeout (10s)
 *  • Request/response interceptors for auth, CSRF, error handling
 *  • Automatic CSRF token header
 *  • Retry for idempotent requests
 *  • Uses HttpOnly cookies for credentials (withCredentials:true)
 */

import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse, AxiosError } from 'axios';
import qs from 'qs';

// ------------------------------------------------------------------
// 1️⃣  Configuration
// ------------------------------------------------------------------

// 1.1 Base URL – never hard‑code in code.  Use .env file (create-react-app style)
const BASE_URL = process.env.REACT_APP_API_BASE_URL; // e.g. https://api.example.com

if (!BASE_URL) {
  console.warn('⚠️  REACT_APP_API_BASE_URL is not defined.  Axios instance will not work.');
}

// 1.2 Timeout (ms) – adjust as needed
const REQUEST_TIMEOUT = 10_000;

// 1.3 Max content length (bytes) – to guard against huge payloads
const MAX_CONTENT_LENGTH = 5 * 1024 * 1024; // 5 MiB

// ------------------------------------------------------------------
// 2️⃣  Helper: Get CSRF token from cookie
// ------------------------------------------------------------------

/**
 * Reads a cookie value by name.
 * @param name - cookie name
 */
const getCookie = (name: string): string | null => {
  const match = document.cookie.match(new RegExp(`(^|;\\s*)${name}=([^;]+)`));
  return match ? decodeURIComponent(match[2]) : null;
};

// ------------------------------------------------------------------
// 3️⃣  Create Axios instance
// ------------------------------------------------------------------
export const apiClient: AxiosInstance = axios.create({
  baseURL: BASE_URL,
  timeout: REQUEST_TIMEOUT,
  withCredentials: true,      // Send HttpOnly cookie
  maxContentLength: MAX_CONTENT_LENGTH,
  // Optional: transform request body for GET params
  paramsSerializer: (params) => qs.stringify(params, { arrayFormat: 'repeat' }),
});

// ------------------------------------------------------------------
// 4️⃣  Request interceptor – add auth & CSRF headers
// ------------------------------------------------------------------
apiClient.interceptors.request.use(
  (config: AxiosRequestConfig): AxiosRequestConfig => {
    // 4.1 Add CSRF token if present
    const csrfToken = getCookie('XSRF-TOKEN');
    if (csrfToken && config.headers) {
      config.headers['X-CSRF-Token'] = csrfToken;
    }

    // 4.2 Ensure we always send content type header for non‑GET
    if (config.method && !['get', 'head', 'options'].includes(config.method.toLowerCase())) {
      config.headers = config.headers ?? {};
      if (!config.headers['Content-Type']) {
        config.headers['Content-Type'] = 'application/json';
      }
    }

    return config;
  },
  (error) => Promise.reject(error),
);

// ------------------------------------------------------------------
// 5️⃣  Response interceptor – error handling & token refresh
// ------------------------------------------------------------------
apiClient.interceptors.response.use(
  (response: AxiosResponse): AxiosResponse => response,

  async (error: AxiosError): Promise<any> => {
    const { config, response } = error;

    // 5.1 If the request was canceled, just reject
    if (axios.isCancel(error)) {
      return Promise.reject(error);
    }

    // 5.2 401 Unauthorized – token expired or missing
    if (response?.status === 401) {
      // Option: Dispatch logout, redirect to login, or try token refresh
      // For demo: we simply log out via an event emitter or context
      const logoutEvent = new CustomEvent('logout', { detail: { reason: 'unauthorized' } });
      window.dispatchEvent(logoutEvent);
      return Promise.reject(error);
    }

    // 5.3 403 Forbidden – maybe user is not allowed to perform action
    if (response?.status === 403) {
      // Show generic forbidden message or redirect
      console.warn('Access forbidden – you do not have permission to perform this action.');
      return Promise.reject(error);
    }

    // 5.4 Network or server errors – optional retry for idempotent requests
    if (!response && !error.message?.includes('timeout')) {
      // Simple exponential back‑off retry up to 3 attempts
      const maxRetries = 3;
      config['__retryCount'] = config['__retryCount'] ?? 0;

      if (config['__retryCount'] < maxRetries) {
        config['__retryCount'] += 1;
        const delay = Math.pow(2, config['__retryCount']) * 200; // 200ms, 400ms, 800ms
        await new Promise((r) => setTimeout(r, delay));
        return apiClient(config);
      }
    }

    // 5.5 All other errors – propagate
    return Promise.reject(error);
  },
);

// ------------------------------------------------------------------
// 6️⃣  Export a typed wrapper (optional)
// ------------------------------------------------------------------
/**
 * Generic helper to perform API calls with type safety.
 *
 * @param config - AxiosRequestConfig
 * @returns Promise<AxiosResponse<T>>
 */
export const request = async <T = unknown>(config: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return apiClient.request<T>(config);
};

// ------------------------------------------------------------------
// 7️⃣  Convenience shortcuts
// ------------------------------------------------------------------
export const get = <T = unknown>(url: string, config?: AxiosRequestConfig) =>
  request<T>({ ...config, method: 'get', url });

export const post = <T = unknown>(url: string, data?: any, config?: AxiosRequestConfig) =>
