### 5️⃣  `src/auth.js` – Very small JWT guard

```js
import jwt from 'jsonwebtoken';
import dotenv from 'dotenv';

dotenv.config();

export const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader) return res.status(401).json({error: 'No token provided'});

  const token = authHeader.split(' ')[1];
  if (!token) return res.status(401).json({error: 'Malformed token'});

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;                // payload should contain userID at least
    next();
  } catch (err) {
    return res.status(401).json({error: 'Invalid or expired token'});
  }
};
```

> **Tip** – In production you might want to use a proper auth provider, refresh tokens, etc.

---

### 6️⃣  `src/routes/skills.js` – The endpoint

```js
import express from 'express';
import pool from '../db.js';
import { authenticate } from '../auth.js';

const router = express.Router();

/**
 * GET /skills
 * @query optional `user` (userID) – only if you want to fetch a specific user’s skills
 *
 * Response:
 * 200: { skills: [ { skill: 'JavaScript', count: 3 }, … ] }
 * 401: { error: '…' }
 * 500: { error: 'Internal Server Error' }
 */
router.get('/', authenticate, async (req, res) => {
  try {
    const { user } = req.query;   // optional; if omitted we return all skills
    const params = [];
    let sql = `
      SELECT skill
      FROM ExpertSkills
    `;
    if (user) {
      sql += ' WHERE userID = ?';
      params.push(user);
    }
    const [rows] = await pool.execute(sql, params);

    // Optional: aggregate counts (unique per user) or just return raw list
    const result = rows.map(r => ({skill: r.skill}));

    res.json({skills: result});
  } catch (err) {
    console.error('[GET /skills] ERROR:', err);
    res.status(500).json({error: 'Internal Server Error'});
  }
});

export default router;
```

> **Why `authenticate`?**  
> Even a read‑only list is often user‑specific.  
> Without auth you’d expose every user’s skill set; that’s a privacy breach.

