// 2. Funkcja „pobierająca” wszystkie wywołania
function findAllTwoArgHexCalls(code) {
  const ast = acorn.parse(code, { ecmaVersion: 2020, sourceType: 'module' });

  const matches = [];

  // Prosty DFS po drzewie
  function walk(node) {
    if (!node) return;

    // Czy to CallExpression (wywołanie funkcji)?
    if (node.type === 'CallExpression') {
      const args = node.arguments;

      // Sprawdźmy, że mamy dwa argumenty
      if (args.length === 2) {
        const first = args[0];

        // Czy pierwszy argument to literal szesnastkowy?
        if (
          first.type === 'Literal' &&
          typeof first.value === 'number' &&
          first.raw.startsWith('0x')
        ) {
          // Dodajemy wynik
          matches.push({
            callee: node.callee,        // np. Identifier {name: 'f'}
            firstArg: first.value,      // 0x1df jako liczba
            secondArg: args[1],         // cały drugi argument (może być literal, Identifier, CallExpression, itp.)
            raw: code.substring(node.start, node.end) // sam fragment kodu
          });
        }
      }
    }

    // Rekurencyjnie przeglądamy dzieci
    for (const key in node) {
      const child = node[key];
      if (Array.isArray(child)) {
        child.forEach(walk);
      } else if (child && typeof child.type === 'string') {
        walk(child);
      }
    }
  }

  walk(ast);

  return matches;
}

