```

### `public/client.js`

```js
/*  chat-ws/public/client.js  */

const wsUrl = window.location.protocol === 'https:' 
  ? `wss://${window.location.host}/ws`
  : `ws://${window.location.host}/ws`;

const ws = new WebSocket(wsUrl);

const chat = document.getElementById('chat');
const msgInput = document.getElementById('msg');
const sendBtn = document.getElementById('send');

function appendMessage({ user, text, time }) {
  const div = document.createElement('div');
  const ts = new Date(time).toLocaleTimeString();
  div.innerHTML = `<strong>[${ts}] ${user}:</strong> ${text}`;
  chat.appendChild(div);
  chat.scrollTop = chat.scrollHeight; // auto‑scroll
}

ws.addEventListener('open', () => {
  console.log('WS connection opened');
});

ws.addEventListener('message', (ev) => {
  try {
    const msg = JSON.parse(ev.data);
    if (msg.error) return alert(msg.error);
    appendMessage(msg);
  } catch (e) {
    console.error('Bad WS payload', e);
  }
});

ws.addEventListener('close', () => console.log('WS connection closed'));

sendBtn.addEventListener('click', () => {
  const text = msgInput.value.trim();
  if (!text) return;
  const payload = { user: 'demoUser', text };
  ws.send(JSON.stringify(payload));
  msgInput.value = '';
});
```

> **Note** – The demo uses a hard‑coded user `"demoUser"`.  
> In a real app, you’d fetch the authenticated username from a cookie or token.

