const express = require('express');
const jwt = require('jsonwebtoken');
const User = require('../models/user');

const router = express.Router();

// Registration
router.post('/register', async (req, res) => {
  const { username, password } = req.body;
  try {
    const existing = await User.findOne({ username });
    if (existing) return res.status(400).json({ error: 'Username taken' });

    const user = new User({ username, password });
    await user.save();

    res.json({ message: 'Registered' });
  } catch (e) {
    res.status(500).json({ error: 'Server error' });
  }
});

// Login
router.post('/login', async (req, res) => {
  const { username, password } = req.body;
  try {
    const user = await User.findOne({ username });
    if (!user) return res.status(400).json({ error: 'Invalid credentials' });

    const isMatch = await user.comparePassword(password);
    if (!isMatch) return res.status(400).json({ error: 'Invalid credentials' });

    const token = jwt.sign({ id: user._id }, process.env.JWT_SECRET, {
      expiresIn: '7d'
    });

    res.json({ token, username: user.username, position: user.position });
  } catch (e) {
    res.status(500).json({ error: 'Server error' });
  }
});

module.exports = router;
```

### 3.6 `sockets/player.js`

```js
const User = require('../models/user');
const Item = require('../models/inventory');
const jwt = require('jsonwebtoken');

const activePlayers = {}; // {socketId: userId}

const handlePlayerSocket = (io, socket) => {

  // Helper: verify JWT from client
  const verifyToken = token => {
    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET);
      return decoded.id;
    } catch {
      return null;
    }
  };

  // 1️⃣ Authenticate once when client connects
  socket.on('authenticate', async ({ token }) => {
    const userId = verifyToken(token);
    if (!userId) {
      socket.emit('error', { msg: 'Authentication failed' });
      socket.disconnect();
      return;
    }

    const user = await User.findById(userId).populate('inventory');
    if (!user) {
      socket.emit('error', { msg: 'User not found' });
      socket.disconnect();
      return;
    }

    activePlayers[socket.id] = userId;

    // Send initial state
    socket.emit('playerData', {
      username: user.username,
      position: user.position,
      inventory: user.inventory
    });

    // Broadcast that a new player joined
    io.emit('playerJoined', { id: socket.id, username: user.username, position: user.position });
  });

  // 2️⃣ Player movement
  socket.on('move', async ({ direction }) => {
    const userId = activePlayers[socket.id];
    if (!userId) return;
    const user = await User.findById(userId);
    if (!user) return;

    const step = 1; // units per move

    switch (direction) {
      case 'up':    user.position.y -= step; break;
      case 'down':  user.position.y += step; break;
      case 'left':  user.position.x -= step; break;
      case 'right': user.position.x += step; break;
      default: break;
    }

    await user.save();
    socket.emit('positionUpdate', user.position);
    socket.broadcast.emit('playerMoved', { id: socket.id, position: user.position });
  });

  // 3️⃣ Skill usage (very basic example)
  socket.on('useSkill', async ({ skillName }) => {
    const userId = activePlayers[socket.id];
    if (!userId) return;
    const user = await User.findById(userId);

    // Dummy skill effect: heal 10 HP
    if (skillName === 'heal') {
      // You’d store HP in the DB – omitted for brevity
      socket.emit('skillResult', { msg: 'Healed 10 HP' });
    } else {
      socket.emit('skillResult', { msg: `Unknown skill: ${skillName}` });
    }
  });

  // 4️⃣ Inventory actions
  socket.on('addItem', async ({ itemId }) => {
    const userId = activePlayers[socket.id];
    if (!userId) return;
    const user = await User.findById(userId);
    const item = await Item.findById(itemId);

    if (!item) return socket.emit('error', { msg: 'Item not found' });

    user.inventory.push(item._id);
    await user.save();

    const populatedItem = await item.populate('inventory').execPopulate();
    socket.emit('inventoryUpdate', user.inventory);
    socket.broadcast.emit('playerUpdated', { id: socket.id });
  });

  socket.on('disconnect', () => {
    console.log(`Player disconnected: ${socket.id}`);
    delete activePlayers[socket.id];
    io.emit('playerLeft', { id: socket.id });
  });
};

module.exports = { handlePlayerSocket };
```

> **Security notes**  
> * Always validate and sanitize input from the client.  
> * Never trust the client for critical logic; enforce rules server‑side.  
> * Use HTTPS/TLS for the WebSocket connection in production.

