```js
/* -------------------------------------------------------
   1️⃣  Game Configuration
   ------------------------------------------------------- */
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Resize canvas to fit the window
const resizeCanvas = () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
};
window.addEventListener('resize', resizeCanvas);
resizeCanvas(); // initial sizing

// Game constants
const PLAYER_SPEED = 200;          // pixels per second
const BULLET_SPEED = 500;
const ENEMY_SPEED = 80;
const SPAWN_INTERVAL = 2000;      // ms between enemy spawns
const ENEMY_SIZE = 40;
const BULLET_SIZE = 5;

// Utility
const now = () => performance.now();

/* -------------------------------------------------------
   2️⃣  Input Handling
   ------------------------------------------------------- */
const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup',   e => keys[e.key] = false);

/* -------------------------------------------------------
   3️⃣  Game Objects
   ------------------------------------------------------- */
class Player {
  constructor() {
    this.w = 60; this.h = 60;
    this.x = canvas.width / 2 - this.w / 2;
    this.y = canvas.height - this.h - 30;
    this.angle = 0;          // radians
    this.shooting = false;
  }

  update(delta) {
    // Movement
    if (keys['ArrowUp']) this.y -= PLAYER_SPEED * delta;
    if (keys['ArrowDown']) this.y += PLAYER_SPEED * delta;
    if (keys['ArrowLeft']) this.x -= PLAYER_SPEED * delta;
    if (keys['ArrowRight']) this.x += PLAYER_SPEED * delta;

    // Clamp to canvas
    this.x = Math.max(0, Math.min(canvas.width - this.w, this.x));
    this.y = Math.max(0, Math.min(canvas.height - this.h, this.y));

    // Shooting
    if (keys[' ']) {
      this.shoot();
      keys[' '] = false; // single shot per press
    }
  }

  shoot() {
    const cx = this.x + this.w / 2;
    const cy = this.y + this.h / 2;
    bullets.push(new Bullet(cx, cy, this.angle));
  }

  draw() {
    // Simple tank body
    ctx.save();
    ctx.translate(this.x + this.w / 2, this.y + this.h / 2);
    ctx.rotate(this.angle);
    ctx.fillStyle = '#0A0';
    ctx.fillRect(-this.w/2, -this.h/2, this.w, this.h);
    // Barrel
    ctx.fillStyle = '#555';
    ctx.fillRect(0, -5, 20, 10);
    ctx.restore();
  }
}

class Bullet {
  constructor(x, y, angle) {
    this.x = x;
    this.y = y;
    this.angle = angle;
    this.vx = Math.cos(angle) * BULLET_SPEED;
    this.vy = Math.sin(angle) * BULLET_SPEED;
    this.size = BULLET_SIZE;
  }

  update(delta) {
    this.x += this.vx * delta;
    this.y += this.vy * delta;
  }

  draw() {
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    ctx.fill();
  }

  offscreen() {
    return (
      this.x < 0 || this.x > canvas.width ||
      this.y < 0 || this.y > canvas.height
    );
  }
}

class Enemy {
  constructor() {
    this.w = ENEMY_SIZE;
    this.h = ENEMY_SIZE;
    this.x = Math.random() * (canvas.width - this.w);
    this.y = -this.h; // start above canvas
    this.vy = ENEMY_SPEED;
  }

  update(delta) {
    this.y += this.vy * delta;
  }

  draw() {
    ctx.fillStyle = '#A00';
    ctx.fillRect(this.x, this.y, this.w, this.h);
  }

  offscreen() {
    return this.y > canvas.height;
  }
}

/* -------------------------------------------------------
   5️⃣  Game Loop
   ------------------------------------------------------- */
const player = new Player();
const bullets = [];
const enemies = [];

let lastSpawn = 0;
let lastTime = now();

function gameLoop() {
  const curTime = now();
  const delta = (curTime - lastTime) / 1000; // in seconds
  lastTime = curTime;

  // Update
  player.update(delta);

  bullets.forEach(b => b.update(delta));
  enemies.forEach(e => e.update(delta));

  // Collision detection
  bullets.forEach((b, bi) => {
    enemies.forEach((e, ei) => {
      if (b.x < e.x + e.w && b.x + b.size > e.x &&
          b.y < e.y + e.h && b.y + b.size > e.y) {
        // destroy bullet & enemy
        bullets.splice(bi, 1);
        enemies.splice(ei, 1);
      }
    });
  });

  // Remove offscreen objects
  for (let i = bullets.length - 1; i >= 0; i--)
    if (bullets[i].offscreen()) bullets.splice(i, 1);
  for (let i = enemies.length - 1; i >= 0; i--)
    if (enemies[i].offscreen()) enemies.splice(i, 1);

  // Spawn enemies
  if (curTime - lastSpawn > SPAWN_INTERVAL) {
    enemies.push(new Enemy());
    lastSpawn = curTime;
  }

  // Render
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  player.draw();
  bullets.forEach(b => b.draw());
  enemies.forEach(e => e.draw());

  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
```

