```javascript
/* --------------------------------------------------------------
   Кастомный селект с учётом placeholder == value
   -------------------------------------------------------------- */

$(function () {
  /* ---------- 1. Построение разметки  ---------- */
  $('.custom-select').each(function () {
    var $select      = $(this);
    var placeholder  = $select.attr('placeholder') || $select.data('placeholder') || '';
    var classes      = $select.attr('class') || '';
    var id           = $select.attr('id') || '';
    var name         = $select.attr('name') || '';

    /* Старт шаблона */
    var template = '<div class="' + classes + '">';
    template += '<span class="custom-select-trigger">' + placeholder + '</span>';
    template += '<div class="custom-options">';

    /* Перебираем option’ы */
    $select.find('option').each(function () {
      var $opt  = $(this);
      var val   = $opt.attr('value') || '';
      var txt   = $opt.html() || '';
      var sel   = (val === placeholder) ? ' selected' : '';   // <– проверяем совпадение

      template += '<span class="custom-option' + sel + ' ' + ($opt.attr('class') || '') + '" data-value="' + val + '">' + txt + '</span>';
    });

    /* Завершаем шаблон */
    template += '</div></div>';

    /* Вставляем и скрываем оригинальный <select> */
    $select.wrap('<div class="custom-select-wrapper"></div>');
    $select.hide();
    $select.after(template);

    /* ---------- 2. Устанавливаем начальный выбранный элемент ---------- */
    var $wrapper   = $select.parent('.custom-select-wrapper');
    var $trigger   = $wrapper.find('.custom-select-trigger');
    var $selected  = $wrapper.find('.custom-option.selected');

    if ($selected.length) {                     // если нашёлся совпадающий option
      $trigger.text($selected.text());           // отображаем его текст в триггере
      $select.val($selected.data('value')).trigger('change'); // и обновляем оригинал
    } else {
      // если совпадения нет – оставляем placeholder (или пустой текст)
      $trigger.text(placeholder);
    }
  });

  /* --------------------------------------------------------------
     Остальные обработчики (hover, открытие/закрытие, выбор)
     -------------------------------------------------------------- */

  /* Hover */
  $('.custom-option:first-of-type').hover(
    function () { $(this).parents('.custom-options').addClass('option-hover'); },
    function () { $(this).parents('.custom-options').removeClass('option-hover'); }
  );

  /* Открытие/закрытие селекта */
  $('.custom-select-trigger').on('click', function (e) {
    $('html').one('click', function () {
      $('.custom-select').removeClass('opened');
    });
    $(this).parents('.custom-select').toggleClass('opened');
    e.stopPropagation();            // важно, чтобы клик не закрылось сразу
  });

  /* Выбор опции */
  $('.custom-option').on('click', function () {
    var $this  = $(this);
    var $wrapper = $this.closest('.custom-select-wrapper');

    /* Обновляем оригинальный <select> */
    var $select = $wrapper.find('select');
    $select.val($this.data('value')).trigger('change');

    /* Обновляем UI */
    $wrapper.find('.custom-option').removeClass('selection');
    $this.addClass('selection');

    $this.parents('.custom-select').removeClass('opened');
    $this.parents('.custom-select').find('.custom-select-trigger').text($this.text());
  });

  /* Дублируем событие change для внешних обработчиков (если нужно) */
  $('.custom-select-wrapper .custom-options .custom-option').on('click', function () {
    var value = $(this).data('value');
    var $select = $(this).closest('.custom-select-wrapper').find('select');
    $select.val(value).trigger('change');
  });
});
```

