## 2. Revised code (with comments)

```js
/**
 * app.js – Public‑ready Express server
 *
 * 1️⃣  Bind to all interfaces (0.0.0.0) and respect PORT env var.
 * 2️⃣  Use Helmet to set secure HTTP headers.
 * 3️⃣  Validate & sanitize user input with express-validator.
 * 4️⃣  Hash passwords with bcryptjs.
 * 5️⃣  Add basic rate‑limiting (express-rate-limit).
 * 6️⃣  Use CSRF tokens (csurf) and secure cookies.
 * 7️⃣  Serve static assets through a CDN in production.
 */

require('dotenv').config(); // Loads .env – keep secrets out of source

const express   = require('express');
const bodyParser= require('body-parser');
const helmet    = require('helmet');
const rateLimit = require('express-rate-limit');
const csurf     = require('csurf');
const session   = require('express-session');
const bcrypt    = require('bcryptjs');
const { body, validationResult } = require('express-validator');
const fs        = require('fs');
const path      = require('path');
const app       = express();
const port      = process.env.PORT || 80;

// ------------------------------------------------------------------
// 1. Middlewares
// ------------------------------------------------------------------
app.use(helmet());                     // 2️⃣ Secure headers
app.use(bodyParser.urlencoded({ extended: true }));

// 3️⃣ Session – required for CSRF. Store session in a secure store in prod.
app.use(session({
  secret: process.env.SESSION_SECRET || 'change-me',
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production', // HTTPS only
    sameSite: 'strict',
  },
}));

// 4️⃣ CSRF protection
app.use(csurf());

// 5️⃣ Rate limiting (example: 100 req per 15min per IP)
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests, please try again later.',
}));

// 6️⃣ Serve static files (in prod you might proxy this to a CDN)
app.use(express.static(path.join(__dirname, 'public')));

// 7️⃣ Expose the CSRF token to the view
app.use((req, res, next) => {
  res.locals.csrfToken = req.csrfToken();
  next();
});

// ------------------------------------------------------------------
// 8. Routes
// ------------------------------------------------------------------
app.get('/registration', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'registration.html'));
});

app.post(
  '/register',
  // Validation & sanitization
  [
    body('username')
      .trim()
      .isLength({ min: 3, max: 20 })
      .withMessage('Username must be 3-20 characters.')
      .escape(),
    body('email')
      .isEmail()
      .withMessage('Invalid email.')
      .normalizeEmail(),
    body('password')
      .isStrongPassword({
        minLength: 8,
        minLowercase: 1,
        minUppercase: 1,
        minNumbers: 1,
        minSymbols: 1,
