      .withMessage(
        'Password must be at least 8 characters and contain a mix of cases, numbers, and symbols.'
      ),
  ],
  async (req, res) => {
    // 9️⃣ Handle validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, email, password } = req.body;

    // 10️⃣ Hash password
    const saltRounds = 12;
    const hashed = await bcrypt.hash(password, saltRounds);

    const userData = { username, email, password: hashed };

    // 11️⃣ Persist user data
    const usersPath = path.join(__dirname, 'users.json');
    let json = [];
    try {
      const data = fs.readFileSync(usersPath, 'utf8');
      if (data) json = JSON.parse(data);
    } catch (err) {
      if (err.code !== 'ENOENT') throw err; // ignore file-not-found
    }
    json.push(userData);
    fs.writeFileSync(usersPath, JSON.stringify(json, null, 2));

    // 12️⃣ Redirect / or send JSON
    res.redirect('/content');
  }
);

app.get('/content', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'content.html'));
});

// ------------------------------------------------------------------
// 13. Error handling
// ------------------------------------------------------------------
app.use((err, req, res, next) => {
  if (err.code === 'EBADCSRFTOKEN') {
    // CSRF token errors
    return res.status(403).send('Form tampered with.');
  }
  console.error(err);
  res.status(500).send('Internal Server Error');
});

// ------------------------------------------------------------------
// 14. Start server on 0.0.0.0 (public)
// ------------------------------------------------------------------
app.listen(port, '0.0.0.0', () => {
  console.log(`🚀 Server listening on http${process.env.NODE_ENV === 'production' ? 's' : ''}://0.0.0.0:${port}`);
});
```

> **What changed?**  
> * The server now listens on **0.0.0.0** – all interfaces.  
> * The port is taken from `process.env.PORT` (good for Heroku, Render, Fly.io, etc.).  
> * Added a full security stack (Helmet, rate‑limit, CSRF, session).  
> * Passwords are hashed with bcrypt before storage.  
> * Input is validated and sanitized with `express-validator`.  
> * Errors are handled cleanly.

---

## 3. Deploying publicly

Below are 3 popular ways to expose your app:

| Platform | Quick steps |
|----------|-------------|
| **Heroku** | `heroku create`, `git push heroku main`, set env vars via `heroku config:set SESSION_SECRET=… NODE_ENV=production` |
| **Render** | Create a new “Web Service”, push repo, set `PORT` and `SESSION_SECRET` in Render’s “Environment Variables”. Render automatically assigns HTTPS. |
| **Docker + Cloud VM** | Build Dockerfile (`FROM node:20-alpine`), expose port `80` or `443`. Deploy to DigitalOcean App Platform, AWS ECS, etc. |
| **ngrok (for local testing)** | `ngrok http 80` – gives you a public HTTPS URL pointing to your local `0.0.0.0:80` instance. |

