      // Grab an array of promises – one per tagger
      const fetchTagPromises = selectedTaggers.map(tagger =>
        fetchTagsForImage(image, tagger)  // <-- external helper
      );

      // Wait for all tagger requests for this image
      const taggerResults = await Promise.all(fetchTagPromises);

      // Append image header
      tagsText += `Image ${image.id}\n`;

      // Append each tagger's output
      for (const result of taggerResults) {
        if (result.error) continue;

        const formattedTags = result.tags
          .map(tagObj => {
            const tag = Object.keys(tagObj)[0];
            const score = Object.values(tagObj)[0];
            return `\t${tag}: ${score.toFixed(4)}`;
          })
          .join('\n');

        tagsText += `Tags by ${result.tagger}:\n{\n${formattedTags}\n}\n\n`;
      }
    }

    // Finally write the caption
    setCaptionText(tagsText);

  } catch (error) {
    // Global error handling
    console.error('Error tagging image(s):', error);
    if (error.response) {
      console.error(error.response.data);
      console.error(error.response.status);
      console.error(error.response.headers);
    } else if (error.request) {
      console.error(error.request);
    } else {
      console.error('Error', error.message);
    }
  }
};
```

