**A minimal ASCII‑based tower‑defense prototype (ES 2023)**  

Below is a single‑file example that you can drop into an empty `index.html`.  
It uses a `<pre>` element for the grid, vanilla ES 2023 syntax, and a small
modular class structure.  
Feel free to copy‑paste and run it locally.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>ASCII Tower Defense</title>
<style>
  body { background:#111; color:#0f0; font-family:monospace; }
  #game { white-space:pre; line-height:1.2; font-size:12px; user-select:none; }
  #info { margin:10px 0; }
  button { margin-right:5px; }
</style>
</head>
<body>

<div id="info">
  <button id="playBtn">Play</button>
  <span id="status">Day</span>
</div>
<pre id="game"></pre>

<script type="module">
/*** -------------------  Game Classes  ------------------- ***/
class Grid {
  constructor(w, h) {
    this.w = w; this.h = h;
    this.cells = Array.from({length:h}, ()=>Array(w).fill('.'));
  }
  set(x, y, v) { this.cells[y][x] = v; }
  get(x, y) { return this.cells[y][x]; }
  clearCell(x, y) { this.cells[y][x] = '.'; }
  render() { return this.cells.map(r=>r.join('')).join('\n'); }
}

class Entity {
  constructor(x, y, ch) { this.x = x; this.y = y; this.ch = ch; }
}

class Player extends Entity { constructor(x, y) { super(x, y, 'P'); } }
class Stash  extends Entity { constructor(x, y) { super(x, y, 'S'); } }
class Zombie extends Entity {
  constructor(x, y, target) { super(x, y, 'Z'); this.target = target; }
  move(grid, stashes) {
    // simple 1‑step towards nearest stash (Manhattan)
    if (!this.target) return;
    let dx = Math.sign(this.target.x - this.x);
    let dy = Math.sign(this.target.y - this.y);
    // if both directions possible pick the closer one
    const distX = Math.abs(this.target.x - this.x);
    const distY = Math.abs(this.target.y - this.y);
    if (distX > distY) this.x += dx;
    else this.y += dy;
    // clamp inside grid
    this.x = Math.max(0, Math.min(grid.w-1, this.x));
    this.y = Math.max(0, Math.min(grid.h-1, this.y));
  }
}

class Game {
  constructor() {
    this.gridW = 30; this.gridH = 20;
    this.grid = new Grid(this.gridW, this.gridH);
    this.player = null;
    this.stashes = [];
    this.zombies = [];
    this.isDay = true;
    this.tickMs = 200;
    this.dayMs = 5000;          // 5 s day/night cycle
    this.zombieSpawnPerNight = 3;
    this._bindUI();
  }

  _bindUI() {
    const playBtn = document.getElementById('playBtn');
    const gameEl  = document.getElementById('game');
    playBtn.onclick = () => this.start();
    gameEl.onclick = (e) => this._handleClick(e);
  }

  _handleClick(e) {
    // calculate grid coordinate from click
    const rect = e.currentTarget.getBoundingClientRect();
    const cellW = 1;   // width of one char
    const cellH = 1.2; // line‑height approx
    const x = Math.floor((e.clientX - rect.left)/cellW);
    const y = Math.floor((e.clientY - rect.top)/cellH);
    if (x < 0 || y < 0 || x >= this.grid.w || y >= this.grid.h) return;
    // place stash if empty
    if (this.grid.get(x, y) === '.') {
      const stash = new Stash(x, y);
      this.stashes.push(stash);
      this.grid.set(x, y, stash.ch);
      this.render();
    }
  }

  start() {
    // init entities
    this.grid = new Grid(this.gridW, this.gridH);
    this.stashes = [];
    this.zombies = [];
    this.isDay = true;
    this._placePlayer();
    this.render();
    this._clearIntervals();
    this._dayTimer = setInterval(()=>this._toggleDay(), this.dayMs);
    this._gameLoop = setInterval(()=>this._tick(), this.tickMs);
  }

  _clearIntervals() {
    clearInterval(this._dayTimer);
    clearInterval(this._gameLoop);
  }

  _placePlayer() {
    let x, y;
    do { x = Math.floor(Math.random()*this.gridW);
         y = Math.floor(Math.random()*this.gridH); }
    while (this.grid.get(x, y) !== '.');
    this.player = new Player(x, y);
    this.grid.set(x, y, this.player.ch);
  }

  _toggleDay() {
    this.isDay = !this.isDay;
    document.getElementById('status').textContent = this.isDay ? 'Day' : 'Night';
    if (!this.isDay) this._spawnZombies();
  }

  _spawnZombies() {
    for (let i=0; i<this.zombieSpawnPerNight; i++) {
      let x, y;
      // spawn on a random edge
      if (Math.random()<0.5) { // vertical edge
        x = Math.random()<0.5 ? 0 : this.gridW-1;
        y = Math.floor(Math.random()*this.gridH);
      } else { // horizontal edge
        x = Math.floor(Math.random()*this.gridW);
        y = Math.random()<0.5 ? 0 : this.gridH-1;
      }
      const target = this._nearestStash(x,y);
      if (!target) continue; // no stashes
      const z = new Zombie(x, y, target);
      this.zombies.push(z);
      this.grid.set(x, y, z.ch);
    }
  }

  _nearestStash(x, y) {
    if (this.stashes.length===0) return null;
    return this.stashes.reduce((best, s) => {
      const d1 = Math.abs(best.x - x)+Math.abs(best.y - y);
      const d2 = Math.abs(s.x - x)+Math.abs(s.y - y);
      return d2<d1 ? s : best;
    }, this.stashes[0]);
  }

  _tick() {
    // move zombies
    this.zombies.forEach(z => {
      // clear previous cell
      this.grid.clearCell(z.x, z.y);
      // find nearest stash again (in case stashes moved/removed)
      if (!z.target || !this.stashes.includes(z.target))
        z.target = this._nearestStash(z.x, z.y);
      z.move(this.grid, this.stashes);
      // collision with stash
      const hit = this.stashes.find(s=>s.x===z.x && s.y===z.y);
      if (hit) {
        // remove stash
        this.stashes = this.stashes.filter(s=>s!==hit);
        this.grid.clearCell(hit.x, hit.y);
      }
      // collision with player
      if (z.x===this.player.x && z.y===this.player.y) {
        alert('You were eaten! Game over.');
        this._clearIntervals();
        return;
      }
      // place zombie
      this.grid.set(z.x, z.y, z.ch);
    });
    this.render();
  }

  render() {
    document.getElementById('game').textContent = this.grid.render();
  }
}

/*** -------------------  Entry Point  ------------------- ***/
const game = new Game();
</script>
</body>
</html>
```

### How it works

| Feature | Implementation |
|---------|----------------|
| **Grid world** | 30 × 20 ASCII grid in a `<pre>` element. |
| **Player** | Randomly spawned on start, shown as `P`. |
| **Gold Stash** | Click a grid cell to place a stash (`S`). |
| **Day/Night cycle** | Toggles every 5 s; shows `Day`/`Night` in the status. |
| **Zombies** | Spawn at random edge each night (`Z`). Move one tile per tick towards nearest stash. |
| **Destruction** | If a zombie reaches a stash, the stash disappears. |
| **Game loop** | `setInterval` tick every 200 ms updates positions and re‑renders. |

> **Tip**  
> The code is intentionally short and uses modern ES features (class syntax,
> `Array.from`, arrow functions, `let/const`).  
> You can expand the logic (path‑finding, more tower types, score, etc.) by
> adding methods to the `Game` class.  
> To keep the demo fast, the grid size and tick rate are modest; feel free to
> tweak `gridW`, `gridH`, `tickMs`, or `dayMs` to suit your taste.

Happy hacking!

