Below is a **drop‑in replacement** for the original parser that removes all regex
look‑behind constructs (the only ones that caused problems on iOS).  
The new implementation keeps the public API identical – you still call

```js
const parser = getParser(/* … */);
const json  = parser.getParsedText(bbcode);
```

but now the parser works on any JavaScript engine that does **not** support
look‑behind.

> **Why it works**  
> * `getBreakLineBeforeTag` and `getBreakLineAfterTag` no longer use
>   `(?<= … )`.  
> * Instead we capture the tag that precedes the newline (or the tag that
>   precedes the newline to be removed) and decide in the replacement callback
>   whether we keep or drop the newline.  
> * All other regexes remain unchanged – they already work on iOS.

---

```js
/* ==========================================================
   BBcode parser – look‑behind free version
   ========================================================== */
function getParser(
  fontsDictionary,
  addImageIntoDictionary,
  errorHandler = () => {},
  codeLayout = { fillColor: () => '#23241f', vLineWidth: () => 0, hLineWidth: () => 0 },
  quoteLayout = { vLineWidth: () => 5, vLineColor: () => '#ccc', hLineWidth: () => 0, paddingLeft: () => 20 }
) {

  /* ==========================================================
     String helpers
     ========================================================== */
  String.prototype.findClosingTag = function (tagType) {
    const tags = new Tags();

    const openingTagPattern = tags.isANotParameterizedTag(tagType)
      ? Patterns.getNotParameterizedOpeningTag([tagType], 'g')
      : Patterns.getOpeningTag([tagType], 'g');

    const closingTagPattern = Patterns.getClosingTag([tagType], 'g');

    const openingTagPositions = [...this.matchAll(openingTagPattern)].map(m => m.index);
    const closingTagPositions = [...this.matchAll(closingTagPattern)].map(m => m.index);

    if (closingTagPositions.length === 0 || openingTagPositions.length === 0) {
      return -1;
    }
    if (closingTagPositions.length === 1 || openingTagPositions.length === 1) {
      return closingTagPositions[0];
    }

    for (let i = 0; i < closingTagPositions.length; i++) {
      if (openingTagPositions[i + 1] > closingTagPositions[i]) {
        return closingTagPositions[i];
      }
    }

    return closingTagPositions[closingTagPositions.length - 1];
  };

  String.prototype.chopString = function (openingTagsPattern, hasClosingTag = true) {
    let str = String(this);
    let hasStyles = str.match(openingTagsPattern);
    if (!hasStyles) return str;

    const chopped = [];
    while (hasStyles) {
      const [tag, tagType] = hasStyles;
      const openingTagPosition = hasStyles.index;

      if (openingTagPosition > 0) {
        chopped.push(str.slice(0, openingTagPosition));
      }

      const closingTagLength = hasClosingTag ? `[/${tagType}]`.length : 0;
      const closingTagPosition = hasClosingTag ? str.findClosingTag(tagType) : -1;

      if (hasClosingTag && closingTagPosition === -1) {
        return [...chopped, str];
      }

      const end = hasClosingTag ? closingTagPosition + closingTagLength : openingTagPosition + tag.length;
      chopped.push(str.slice(openingTagPosition, end));

      const rest = str.slice(end);
      if (!rest) break;
      str = rest;
      hasStyles = str.match(openingTagsPattern);
      if (!hasStyles) chopped.push(rest);
    }
    return chopped;
  };

  String.prototype.isOpenTagComeFirst = function (tag) {
    const tags = new Tags();
    const openTag  = tags.isANotParameterizedTag(tag) ? `[${tag}]` : `[${tag}`;
    const closeTag = `[/${tag}]`;
    return this.indexOf(openTag) <= this.indexOf(closeTag);
