  /* ==========================================================
     Tags & Patterns
     ========================================================== */
  class Tags {
    constructor() {
      this.tags = {
        styles:    ['b', 'i', 'u', 's', 'sup', 'sub', 'font', 'color', 'size', 'url', 'email', 'highlight'],
        media:     ['img'],
        list:      ['ul', 'ol', 'li'],
        title:     ['h1', 'h2', 'h3', 'h4'],
        extra:     ['code', 'quote'],
        alignment: ['left', 'center', 'right', 'justify'],
        withoutClosing: ['hr'],
