        case 'i':   line = { text: txt, ...opts, italics: true }; break;
        case 'u':   line = { text: txt, ...opts, decoration: 'underline' }; break;
        case 's':   line = { text: txt, ...opts, decoration: 'lineThrough' }; break;
        case 'sup': line = { text: txt, ...opts, sup: { offset: '15%' } }; break;
        case 'sub': line = { text: txt, ...opts, sub: { offset: '15%' } }; break;

