        case 'h1': line = { text: txt, ...opts, fontSize: 26 }; break;
        case 'h2': line = { text: txt, ...opts, fontSize: 20 }; break;
        case 'h3': line = { text: txt, ...opts, fontSize: 16 }; break;
        case 'h4': line = { text: txt, ...opts, fontSize: 13 }; break;

