      const target = text || ol || ul || line;
      const options = { ...prevOpts, ...opts };
      let type = 'text';
      if (ul) type = 'ul';
      if (ol) type = 'ol';

      if (typeof target !== 'string') return line;

      const has = target.match(pattern);
      if (!has) return { [type]: target, ...options };

      const [full, tagType, value, inner] = has;
      if (inner.isOpenTagComeFirst(tagType)) {
        const newLine = ParserHelper.getNewLineByTag(inner, tagType, value, options);
