      return { [type]: target, ...options };
    }

    static getInsiderLineStyles(line, openingTagPattern, outsiderPattern) {
      let { text, ul, ol, stack, ...opts } = line;
      if (typeof line === 'string') opts = {};

      const target = text || ol || ul || stack || line;
      let type = 'text';
      if (ul) type = 'ul';
      if (ol) type = 'ol';
      if (stack) type = 'stack';

      if (typeof target !== 'string') return line;

      const has = target.match(openingTagPattern);
      if (!has) return { [type]: target, ...opts };

      const [match, tag] = has;
      const closingTagPattern = Patterns.getClosingTag([tag]);

      const hasClosing = target.match(closingTagPattern);
      if (!hasClosing) return { [type]: target, ...opts };

      const listOpenPattern = Patterns.getOpeningTag(['ul', 'ol']);
      const parts = !stack
        ? target.chopString(openingTagPattern)
