      const newList = [];
      let test = true;
      while (test) {
        const idx = list.findIndex(l => l.ol);
        if (idx > 1) newList.push(...list.slice(0, idx - 1));
        const prev = list[idx - 1];
        const cur  = list[idx];
        newList.push({ stack: [prev, ParserHelper.fixOlListsHelper(cur)] });

        const rest = list.slice(idx + 1);
