        this.prepareContent,
        this.breakLineTagsHandler,
        this.horizontalRuleTagHandler,
        this.horizontalRuleTagParser,
        this.outsiderStylesParser,
        this.insiderStylesParser,
        this.fixOlLists,
      ].map(f => f.bind(this));

      this.tags = new Tags();
    }

    prepareContent(contents = '') {
      if (!contents || typeof contents !== 'string') return '';

      const breakTags = [...this.tags.getBreakLineTags(), 'li'];

      const beforePattern = Patterns.getBreakLineBeforeTag(['ul', 'ol', 'li'], 'g');
      const afterPattern  = Patterns.getBreakLineAfterTag(breakTags, 'g');

      // 1. misc replacements
      contents = contents.replace(/\[ml\]/g, '');
      contents = contents.replace(/\[\/ml\]/g, '\n');
