      const openingTagPattern = Patterns.getOpeningTag(['hr']);
      return contents.map(l => l.chopString(openingTagPattern, false)).flat();
    }

    horizontalRuleTagParser(contents) {
      return contents.map(l => l === '[hr]'
        ? { canvas: [{ type: 'line', x1: 0, y1: 0, x2: 515, y2: 0, lineWidth: 1 }] }
        : l
      );
    }

    outsiderStylesParser(contents) {
      const tags = this.tags.getAllTags('hr');
      const pattern = Patterns.getFullTag(tags, 's');
      return contents.map(l => ParserHelper.getOutsiderLineStyles(l, pattern));
    }

    insiderStylesParser(contents) {
      const tags = this.tags.getAllTags('hr');
      const openingTagPattern = Patterns.getOpeningTag(tags);
      const outsiderPattern = Patterns.getFullTag(tags, 's');
      return contents.map(l => ParserHelper.getInsiderLineStyles(l, openingTagPattern, outsiderPattern));
