### 10. Configuración de la app (`src/app.js`)

```js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const dotenv = require('dotenv');
const morgan = require('morgan');
const usersRoutes = require('./routes/users.routes');
const errorHandler = require('./middlewares/error.middleware');

dotenv.config();

const app = express();

/* ----------  Middlewares Globales ---------- */
app.use(helmet());                         // Cabeceras de seguridad
app.use(express.json());                   // Body parser JSON
app.use(morgan('dev'));                    // Logging de peticiones

/* ----------  CORS ---------- */
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || '*', // En prod: define tu dominio
    credentials: true
  })
);

/* ----------  Rate Limiting ---------- */
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10), // 15 min
  max: parseInt(process.env.RATE_LIMIT_MAX, 10),          // 100 reqs
  message: 'Demasiadas peticiones, intenta de nuevo más tarde'
});
app.use(limiter);

/* ----------  Rutas ---------- */
app.use('/api', usersRoutes);

/* ----------  404 Not Found ---------- */
app.use((req, res) => {
  res.status(404).json({ msg: 'Ruta no encontrada' });
});

/* ----------  Error Handler ---------- */
app.use(errorHandler);

module.exports = app;
```

---

### 11. Servidor (`src/server.js`)

```js
const http = require('http');
const app = require('./app');
const connectDB = require('./config/db.config');
const dotenv = require('dotenv');

dotenv.config();

const PORT = process.env.PORT || 3000;

(async () => {
  await connectDB(); // Conexión a MongoDB

  const server = http.createServer(app);

  server.listen(PORT, () => {
    console.log(`🚀 API escuchando en http://localhost:${PORT}`);
  });
})();
```

