$(".custom-select").each(function () {
    var $select   = $(this),
        classes   = $select.attr("class") || "",
        id        = $select.attr("id")   || "",
        name      = $select.attr("name") || "",
        placeholder = $select.attr("placeholder") || "";

    /* Если placeholder совпадает с value какого‑то <option>,
       помечаем этот <option> как выбранный */
    if (placeholder) {
        $select.find("option[value='" + placeholder + "']").prop("selected", true);
    }

    /* Создаём markup для кастомного селекта */
    var template = '<div class="' + classes + '">';
    template += '<span class="custom-select-trigger">';
    /* Текст триггера – либо выбранный вариант, либо placeholder */
    var $selectedOpt = $select.find("option:selected");
    template += $selectedOpt.length ? $selectedOpt.text() : placeholder;
    template += '</span>';
    template += '<div class="custom-options">';

    $select.find("option").each(function () {
        var $opt   = $(this),
            val    = $opt.attr("value"),
            text   = $opt.html(),
            optCls = $opt.attr("class") || "",
            selected = $opt.is(":selected") ? " selected" : "";

        template += '<span class="custom-option' + optCls + selected +
                    '" data-value="' + val + '">' + text + '</span>';
    });

    template += '</div></div>';

    /* Вставляем кастомный элемент после оригинального <select> */
    $select.wrap('<div class="custom-select-wrapper"></div>');
    $select.hide();
    $select.after(template);
