## 2️⃣ Implémentation fonctionnelle : cœur rempli vs cœur vide

### 2.1 `FavoriteManager` – plus qu’un simple add

```js
// services/FavoriteManager.js
export default class FavoriteManager {
  /** Retourne un Set avec les ids favoris (pour une recherche O(1)) */
  static _getFavoritesSet() {
    try {
      const data = localStorage.getItem('favorites');
      const arr  = data ? JSON.parse(data) : [];
      return new Set(arr);
    } catch (e) {
      console.warn('[FavoriteManager] localStorage parsing error', e);
      return new Set();
    }
  }

  /** Persiste un Set dans localStorage */
  static _persist(favSet) {
    localStorage.setItem('favorites', JSON.stringify([...favSet]));
  }

  /** Vérifie si l’id est déjà favori */
  static isFavorite(id) {
    return this._getFavoritesSet().has(id);
  }

  /** Ajoute (ou enlève) un id au favoris */
  static toggleFavorite(id) {
    const set = this._getFavoritesSet();
    if (set.has(id)) set.delete(id);
    else set.add(id);
    this._persist(set);
  }

  /** Nettoyage du storage (utile pour tests) */
  static clear() {
    localStorage.removeItem('favorites');
  }
}
```

> **Note** : l’utilisation d’un `Set` garantit des temps de recherche rapides ; la persistance reste toujours un tableau JSON pour garder la compatibilité `localStorage`.

