## 8️⃣ Server Setup – `server.js`

```js
require('dotenv').config(); // load .env early

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoose = require('mongoose');
const authRoutes = require('./routes/auth');
const profileRoutes = require('./routes/profile');

const app = express();
const PORT = process.env.PORT || 3000;

// 1️⃣ Middleware
app.use(helmet());

// CORS – only allow origins from CORS_WHITELIST
const corsWhitelist = (process.env.CORS_WHITELIST || '')
  .split(',')
  .map((url) => url.trim());
app.use(
  cors({
    origin: (origin, callback) => {
      // allow requests with no origin (e.g., mobile apps, curl)
      if (!origin) return callback(null, true);
      if (corsWhitelist.indexOf(origin) !== -1) {
        return callback(null, true);
      }
      callback(new Error('Not allowed by CORS'));
    },
  })
);

app.use(express.json());

// 2️⃣ Rate‑limiter – 100 req / 15 min per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { message: 'Too many requests, please try again later.' },
});
app.use(limiter);

// 3️⃣ Routes
app.use('/api/auth', authRoutes);
app.use('/api', profileRoutes); // protected routes start with /api

app.get('/', (req, res) => {
  res.send('Security Demo API. Use /api/auth for login/register.');
});

// 4️⃣ Connect to MongoDB Atlas
mongoose
  .connect(process.env.MONGO_URI, {
    useNewUrlParser: true,
    useUnifiedTopology: true,
    // useCreateIndex: true, // mongoose >=6 removed this
  })
  .then(() => console.log('🚀 Connected to MongoDB Atlas'))
  .catch((err) => {
    console.error('❌ MongoDB connection error:', err);
    process.exit(1);
  });

// 5️⃣ Start
app.listen(PORT, () => {
  console.log(`✅ Server listening on port ${PORT}`);
});
```

