function checkModernJSFeatures() {
  const features = [
    // Basic modern syntax & language features
    { name: 'OptionalChaining', test: () => !!(0?.toString) },
    { name: 'NullishCoalescing', test: () => (null ?? 1) === 1 },
    { name: 'BigInt', test: () => typeof 0n === 'bigint' },

