    { name: 'DynamicImport', test: () => typeof import === 'function' },

    // Weak references & finalizers
    { name: 'WeakRef', test: () => typeof WeakRef === 'function' },
    { name: 'FinalizationRegistry', test: () => typeof FinalizationRegistry === 'function' },

