    total: features.length,
    missing: [],
    details: {},
  };

  for (const f of features) {
    try {
      const ok = !!f.test();
      report.details[f.name] = ok;
      if (ok) report.supported += 1;
      else report.missing.push(f.name);
    } catch (_) {
      // Some tests might throw in very old engines; treat as missing.
      report.details[f.name] = false;
      report.missing.push(f.name);
    }
  }

  return report;
}

/* Example usage */
