   weather‑proxy – production‑ready backend
   --------------------------------------------------------------
   Features:
   • Input validation (Joi)
   • CORS whitelist + helmet
   • Express‑rate‑limit + p‑limit (concurrency)
   • Axios with timeout/retry, LRU cache
   • Structured logging (winston)
   • Graceful shutdown / env‑var validation
   ============================================================== */

const express   = require('express');
const cors      = require('cors');
const helmet    = require('helmet');
const rateLimit = require('express-rate-limit');
const axios     = require('axios');
const pLimit    = require('p-limit');
const winston   = require('winston');
const dotenv    = require('dotenv');
const Joi       = require('joi');
const LRU       = require('lru-cache');

dotenv.config({ path: '.env' });   // ← Load env vars once

/* ------------------------------------------------------------------
   1️⃣  ENVIRONMENT VALIDATION
   ------------------------------------------------------------------ */
const requiredEnv = ['APIKEY', 'PORT', 'ALLOWED_ORIGINS'];
requiredEnv.forEach((key) => {
  if (!process.env[key]) {
    console.error(`Missing required env variable: ${key}`);
    process.exit(1);
  }
});

const API_KEY   = process.env.APIKEY;
const PORT      = parseInt(process.env.PORT, 10) || 3000;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS.split(','); // e.g. https://example.com,https://app.example.com

/* ------------------------------------------------------------------
   2️⃣  LOGGING SETUP (winston)
   ------------------------------------------------------------------ */
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.Console({ format: winston.format.simple() })
  ]
});

/* ------------------------------------------------------------------
   3️⃣  EXPRESS APP INITIALIZATION
   ------------------------------------------------------------------ */
const app = express();
app.use(helmet());
app.use(express.json());

// CORS – only allow listed origins
app.use(cors({
  origin: (origin, callback) => {
    // Allow non-browser requests (e.g., Postman) by passing null origin
    if (!origin || ALLOWED_ORIGINS.includes(origin)) return callback(null, true);
    return callback(new Error('CORS policy violation'), false);
  },
  credentials: true
}));

/* ------------------------------------------------------------------
   4️⃣  RATE‑LIMITING
   ------------------------------------------------------------------ */
// 100 requests / 15 minutes per IP – tweak for your quota
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});
app.use('/weather', limiter);

/* ------------------------------------------------------------------
   5️⃣  INPUT VALIDATION (Joi)
   ------------------------------------------------------------------ */
const weatherBodySchema = Joi.object({
  cities: Joi.array().items(
    Joi.string().trim().min(1).max(50) // keep city names sane
  ).min(1).max(20) // limit to 20 cities per request
});

/* ------------------------------------------------------------------
   6️⃣  CACHE – LRU (configurable max size / ttl)
   ------------------------------------------------------------------ */
const cache = new LRU({
  max: 500,             // max 500 entries
  ttl: 5 * 60 * 1000    // 5 minutes TTL
});

/* ------------------------------------------------------------------
   7️⃣  AXIOS INSTANCE – timeout + retry logic
   ------------------------------------------------------------------ */
const http = axios.create({
  baseURL: 'https://open-weather13.p.rapidapi.com',
  timeout: 5_000,       // 5 seconds
  headers: {
    'X-RapidAPI-Key': API_KEY,
    'X-RapidAPI-Host': 'open-weather13.p.rapidapi.com'
  }
});

/* ------------------------------------------------------------------
   8️⃣  CONCURRENCY BOUND – limit to 5 simultaneous external requests
   ------------------------------------------------------------------ */
const limit = pLimit(5);

/* ------------------------------------------------------------------
   9️⃣  ROUTE HANDLER
   ------------------------------------------------------------------ */
app.post('/weather', async (req, res) => {
  // 1️⃣  Validate
  const { error, value } = weatherBodySchema.validate(req.body);
  if (error) {
    logger.warn('Bad request', { path: req.path, message: error.message });
    return res.status(400).json({ error: error.message });
  }

  const { cities } = value;

  // 2️⃣  Build promises with cache & concurrency control
  const promises = cities.map((city) => limit(() => getWeather(city)));

  try {
    const data = await Promise.all(promises);
    res.json(data);
  } catch (err) {
    logger.error('Internal server error', { err: err.stack });
    res.status(500).json({ error: 'Internal server error' });
  }
});

/* ------------------------------------------------------------------
   A.  GET WEATHER – with cache & retry
   ------------------------------------------------------------------ */
async function getWeather(city) {
  // Check cache first
  const cached = cache.get(city);
  if (cached) return cached;

  // Retry logic – 3 attempts, exponential back‑off
  const attempts = 3;
  for (let i = 0; i < attempts; i++) {
    try {
      const { data } = await http.get(`/city/${encodeURIComponent(city)}`);
      const result = {
        city,
        temperature: data?.main?.temp ?? 'N/A',
        fetchedAt: new Date().toISOString()
      };
      cache.set(city, result);      // Store in cache
      return result;
    } catch (e) {
      logger.warn(`Attempt ${i + 1} failed for ${city}`, {
        url: e.config?.url,
        method: e.config?.method,
        status: e.response?.status
      });
      if (i === attempts - 1) {
        // Final attempt – return graceful fallback
        return { city, temperature: 'N/A' };
      }
      // Back‑off 200‑300 ms before retry
      await new Promise(r => setTimeout(r, 200 * (i + 1)));
    }
  }
}

/* ------------------------------------------------------------------
   B.  START SERVER
   ------------------------------------------------------------------ */
app.listen(PORT, () => {
  logger.info(`Weather proxy listening on port ${PORT}`);
});

/* ------------------------------------------------------------------
   C.  Graceful shutdown (optional but recommended)
   ------------------------------------------------------------------ */
process.on('SIGINT', () => {
  logger.info('SIGINT received – shutting down');
  process.exit(0);
});
process.on('SIGTERM', () => {
  logger.info('SIGTERM received – shutting down');
  process.exit(0);
});
```

---

### Quick Checklist

| ✅ | What to verify in production |
|----|------------------------------|
| ✅ | `ALLOWED_ORIGINS` contains all your front‑ends |
| ✅ | `APIKEY` is kept in a secrets manager (e.g., Vault, KMS) |
| ✅ | Rate‑limit thresholds match your RapidAPI plan |
| ✅ | Cache TTL aligns with how often weather data changes |
| ✅ | HTTPS is enforced on your public endpoint (via reverse proxy) |
| ✅ | Logging level is appropriate for your environment |

Feel free to tweak the numbers (concurrency, cache size, rate‑limit) to fit your exact use‑case. Happy hacking!

