// 1. Import dependencies
const express = require('express');      // Web framework
const http = require('http');            // Underlying HTTP server
const path = require('path');            // Path helpers
const { Server } = require('socket.io'); // Socket.io server
const { Pool } = require('pg');          // PostgreSQL client pool

// 2. Environment variables (use dotenv or OS env in prod)
const PORT = process.env.PORT || 3000;
const DB_URL = process.env.DATABASE_URL || 'postgres://user:pass@localhost:5432/flights';
const SECURE_SOCKET = process.env.SECURE_SOCKET === 'true'; // WSS if true

// 3. Create Express app
const app = express();
app.set('view engine', 'ejs');              // Use EJS templates
app.set('views', path.join(__dirname, 'views'));
app.use(express.static(path.join(__dirname, 'public'))); // Serve static files

// 4. Create HTTP(S) server and attach Socket.io
const server = http.createServer(app);
const io = new Server(server, {
  // Enable secure websockets if SECURE_SOCKET is true
  cors: { origin: '*' }, // In production restrict origins
  transports: ['websocket', 'polling'], // Fallback
  secure: SECURE_SOCKET
});

// 5. PostgreSQL connection pool
const pool = new Pool({ connectionString: DB_URL });

// 6. Helper to fetch all flights (parameterised query)
async function getFlights() {
  // Use a simple SELECT – no user input, so safe
  const res = await pool.query('SELECT id, flight_number, origin, destination, departure_time, arrival_time, status FROM flights ORDER BY departure_time ASC');
  return res.rows;
}

// 7. Route: SSR the flight board
app.get('/', async (req, res) => {
  try {
    const flights = await getFlights();          // 7a. Get fresh data
    res.render('index', { flights });            // 7b. Render template
  } catch (err) {
    console.error('DB error', err);
    res.status(500).send('Internal Server Error');
  }
});

// 8. Socket.io connection
io.on('connection', async (socket) => {
  console.log('New client connected:', socket.id);

  // Send initial data when a new client connects
  const flights = await getFlights();
  socket.emit('flights', flights);

  // Optional: Handle client disconnect
  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.id);
  });
});

// 9. Listen to PostgreSQL NOTIFY messages
(async () => {
  // Create a dedicated client for LISTEN/NOTIFY
  const client = await pool.connect();
  await client.query('LISTEN flight_changes'); // We’ll create this trigger later

  client.on('notification', async (msg) => {
    if (msg.channel === 'flight_changes') {
      console.log('Database change detected, broadcasting to clients');
      const flights = await getFlights();          // Re‑query after change
      io.emit('flights', flights);                 // Broadcast to all sockets
    }
  });
