## 5. `public/js/client.js`

```js
// 1. Connect to Socket.io (same origin)
const socket = io(); // auto‑detects protocol/host

// 2. Utility: render flight list into the table
function renderFlights(flights) {
  const tbody = document.querySelector('#flight-table tbody');
  tbody.innerHTML = ''; // Clear existing rows

  flights.forEach(f => {
    const tr = document.createElement('tr');
    tr.dataset.id = f.id; // Keep the ID for potential future updates

    tr.innerHTML = `
      <td>${escapeHtml(f.flight_number)}</td>
      <td>${escapeHtml(f.origin)}</td>
      <td>${escapeHtml(f.destination)}</td>
      <td>${escapeHtml(f.departure_time)}</td>
      <td>${escapeHtml(f.arrival_time)}</td>
      <td class="status">${escapeHtml(f.status)}</td>
    `;
    tbody.appendChild(tr);
  });
}

// 3. Escape function to avoid XSS if data is ever injected client‑side
function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// 4. Listen for server emissions
socket.on('flights', (flights) => {
  console.log('Received flights update:', flights);
  renderFlights(flights); // Re‑render entire table on change
});
```

**Security notes**

* All data received over WebSocket is rendered into the DOM **after escaping**.  
* The server never sends raw HTML; the client never injects scripts.  

