## 2️⃣ 代码实现

```js
// analyze-tsx-imports.js
const fs = require('fs');
const path = require('path');
const { parse } = require('@babel/parser');
const traverse = require('@babel/traverse').default;
const resolve = require('resolve');
const { builtinModules } = require('module');

/**
 * Analyze all imports in a TSX file.
 *
 * @param {string} tsxFilePath - Absolute path to the .tsx file.
 * @returns {Promise<Array<Object>>} - Array of import objects:
 *   {
 *     type: 'static' | 'dynamic' | 'require',
 *     source: string,          // import source string
 *     loc: object,             // location info
 *     resolvedPath: string | null,
 *     packageName: string | null, // top‑level package name if third‑party
 *     isNodeCore: boolean,     // true if it's a Node builtin module
 *     hasVuln: boolean | null   // placeholder for vulnerability flag
 *   }
 */
async function analyzeTsxImports(tsxFilePath) {
  const code = fs.readFileSync(tsxFilePath, 'utf8');

  // 1️⃣ Parse TSX → AST
  const ast = parse(code, {
    sourceType: 'module',
    plugins: ['tsx', 'typescript', 'jsx', 'classProperties'],
  });

  // 2️⃣ Collect raw import nodes
  const rawImports = [];
  traverse(ast, {
    ImportDeclaration(path) {
      rawImports.push({
        type: 'static',
        source: path.node.source.value,
        loc: path.node.loc,
      });
    },
    Import(path) {
      // dynamic import(`module`)
      const node = path.node;
      const arg = node.arguments[0];
      if (arg && arg.type === 'StringLiteral') {
        rawImports.push({
          type: 'dynamic',
          source: arg.value,
          loc: node.loc,
        });
      }
    },
    CallExpression(path) {
      // CommonJS require()
      const node = path.node;
      if (
        node.callee.type === 'Identifier' &&
        node.callee.name === 'require' &&
        node.arguments.length === 1 &&
        node.arguments[0].type === 'StringLiteral'
      ) {
        rawImports.push({
          type: 'require',
          source: node.arguments[0].value,
          loc: node.loc,
        });
      }
    },
  });

  // 3️⃣ Resolve each import
  const results = await Promise.all(
    rawImports.map(async (imp) => {
      let resolvedPath = null;
      let packageName = null;
      let isNodeCore = false;

      // Check if it's a Node builtin
      if (builtinModules.includes(imp.source)) {
        isNodeCore = true;
      }

      // Resolve only if it's a third‑party module
      if (!imp.source.startsWith('.') && !imp.source.startsWith('/')) {
        try {
          resolvedPath = resolve.sync(imp.source, { basedir: path.dirname(tsxFilePath) });

          // Locate package.json of the resolved module
          const pkgDir = path.dirname(
            require.resolve(imp.source, { paths: [path.dirname(tsxFilePath)] })
          );
          const pkgJsonPath = path.join(pkgDir, 'package.json');
          const pkg = JSON.parse(fs.readFileSync(pkgJsonPath, 'utf8'));
          packageName = pkg.name || imp.source;
        } catch (err) {
          // Could not resolve (maybe a missing package)
          resolvedPath = null;
          packageName = imp.source;
        }
      } else {
        // For relative imports, just resolve the file path
        resolvedPath = path.resolve(path.dirname(tsxFilePath), imp.source);
      }

      // Placeholder for vulnerability check (e.g., via npm audit / Snyk)
      const hasVuln = null; // TODO: integrate with vulnerability API

      return {
        ...imp,
        resolvedPath,
        packageName,
        isNodeCore,
        hasVuln,
      };
    })
  );

  // 4️⃣ Quick safety audit (example)
  results.forEach((imp) => {
    if (imp.isNodeCore && !imp.source.startsWith('react-')) {
      console.warn(
        `⚠️  Potential misuse of Node core module "${imp.source}" in frontend TSX.`
      );
    }
  });

  return results;
}

/* ==================== Usage Demo ==================== */
// (uncomment below to test)
// (async () => {
//   const imports = await analyzeTsxImports('./src/App.tsx');
//   console.log(JSON.stringify(imports, null, 2));
// })();

module.exports = analyzeTsxImports;
```

---

## 3️⃣ 如何使用

```js
