## 1. Установка зависимостей

```bash
npm init -y
npm install express sqlite3
```

---

## 2. Создаём базу (если её ещё нет)

```bash
# В командной строке (или через скрипт)
sqlite3 data.db <<EOF
CREATE TABLE IF NOT EXISTS users (
    id   INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    age  INTEGER NOT NULL
);

INSERT INTO users (name, age) VALUES ('Alice', 28);
INSERT INTO users (name, age) VALUES ('Bob', 35);
INSERT INTO users (name, age) VALUES ('Eve', 22);
EOF
```

