## 3. Express‑сервер + wrapper для sqlite3

```js
// index.js
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const app = express();
const DB_PATH = path.resolve(__dirname, 'data.db');

// ----- 1️⃣ Открываем подключение
const db = new sqlite3.Database(DB_PATH, (err) => {
  if (err) console.error('❌ Ошибка подключения к БД:', err);
  else console.log('✅ Подключено к SQLite');
});

/**
 * Проброс sqlite3 функции в Promise.
 * Позволяет использовать async/await.
 */
function dbAll(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.all(sql, params, (err, rows) => {
      if (err) return reject(err);
      resolve(rows);
    });
  });
}

/**
 * Преобразуем массив объектов (rows) в массив массивов.
 * Выбираем нужные поля в нужном порядке.
 */
function to2DArray(rows, columns) {
  return rows.map(row => columns.map(col => row[col]));
}

/**
 * GET /users?minAge=20&maxAge=40
 * Возвращает двумерный массив: [[id, name, age], ...]
 */
app.get('/users', async (req, res) => {
  try {
    // 1️⃣ Параметризуем запрос, чтобы избежать инъекций
    const minAge = parseInt(req.query.minAge, 10) || 0;
    const maxAge = parseInt(req.query.maxAge, 10) || 100;

    const sql = `
      SELECT id, name, age
      FROM users
      WHERE age BETWEEN ? AND ?
      ORDER BY id ASC
    `;
    const rows = await dbAll(sql, [minAge, maxAge]);

    // 2️⃣ Преобразуем в двумерный массив
    const columns = ['id', 'name', 'age'];   // порядок колонок
    const array2D = to2DArray(rows, columns);

    res.json({
      columns,          // метаданные
      data: array2D     // сами данные
    });
  } catch (e) {
    console.error('❌ Ошибка запроса:', e);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

/**
 * Чистим ресурсы при завершении
 */
process.on('SIGINT', () => {
  console.log('\n🔒 Завершаем сервер...');
  db.close(() => {
    console.log('✔️ База закрыта');
    process.exit(0);
  });
});

app.listen(3000, () => {
  console.log('🚀 Сервер запущен на http://localhost:3000');
});
```

### Как это работает

| Шаг | Что делаем | Зачем |
|-----|-----------|-------|
| 1 | `dbAll(sql, params)` | Оборачиваем `db.all` в Promise → `await`‑конструкция |
| 2 | `to2DArray(rows, columns)` | Преобразуем массив объектов (как возвращает sqlite3) в массив массивов, чтобы API отдаёт «чистый» `Array<Array<...>>` |
| 3 | Параметризованный SQL (`?`) | Защита от SQL‑инъекций |
| 4 | Возвращаем JSON | API‑клиенты получают сразу массив `data` + `columns` (если нужно знать порядок) |

---

## 4. Тестируем

```bash
node index.js
```

Перейдите в браузере / Postman:

```
http://localhost:3000/users?minAge=20&maxAge=40
```

Ответ:

```json
{
  "columns": ["id", "name", "age"],
  "data": [
    [1, "Alice", 28],
    [2, "Bob", 35],
    [3, "Eve", 22]
  ]
}
```

---

## 5. Безопасность и лучшие практики

| Что улучшить | Как |
|--------------|-----|
| **Параметризованные запросы** | Уже реализовано через `?`. Не вставляйте строку запроса через конкатенацию. |
| **Обработка ошибок** | В примере – `try/catch` в роуте, но в продакшене можно вынести middleware `errorHandler`. |
| **Проверка входных данных** | `parseInt(req.query.minAge, 10) || 0` → гарантирует, что число либо 0, либо значение, иначе ошибка 400. |
| **Ограничение количества строк** | Добавьте `LIMIT` в SQL, чтобы не отдавать миллионы записей за один запрос. |
| **Логи** | В продакшене логируйте только общее состояние, не раскрывайте детали ошибок в ответе клиенту. |
| **SSL/TLS** | Если сервер в интернете, настройте HTTPS. |
| **Ограничение доступа** | Подумайте о аутентификации/авторизации (JWT, OAuth и пр.). |
| **Обновление зависимостей** | Периодически проверяйте `npm audit`. |

---

