## 3. Axios Wrapper (`src/api/auth.ts`)

```ts
// src/api/auth.ts
import axios from 'axios';

const api = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL, // e.g., https://api.example.com
  withCredentials: true, // Send cookies if your backend uses them
  timeout: 30_000,
});

/**
 * Interceptor to attach JWT token to every request
 */
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('authToken');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

/**
 * Global error handling
 */
api.interceptors.response.use(
  (resp) => resp,
  async (error) => {
    // 401 Unauthorized → clear token and redirect to login
    if (error.response?.status === 401) {
      localStorage.removeItem('authToken');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

/* ---------- API Endpoints ---------- */

export const register = (payload: {
  email: string;
  password: string;
  name: string;
}) =>
  api.post<{ token: string }>(`/auth/register`, payload);

export const login = (payload: { email: string; password: string }) =>
  api.post<{ token: string }>(`/auth/login`, payload);

export const logout = () => api.post(`/auth/logout`);

export const fetchMe = () => api.get<{ name: string; email: string }>(`/auth/me`);
```

