      count
    }
  `,
}).subscribe({
  next: data => console.log('🚀', data),
  error: err => console.error('❌', err),
});
```

**Пояснение**  
* `subscription { count }` – это валидный GraphQL‑оператор.  
* Библиотека `subscriptions-transport-ws` автоматически добавляет поле `data` с
  вашими значениями.

