```js
// server.js
const express = require('express');
const { graphqlHTTP } = require('express-graphql');
const { buildSchema } = require('graphql');
const { PubSub } = require('graphql-subscriptions');
const { SubscriptionServer } = require('subscriptions-transport-ws');
const { execute, subscribe } = require('graphql');

const pubsub = new PubSub();

const schema = buildSchema(`
  type Query {
    hello: String
  }
  type Subscription {
    count: Int
  }
`);

const root = {
  hello: () => 'Hello world!',
  count: () => pubsub.asyncIterator('count'),
};

const app = express();
app.use('/graphql', graphqlHTTP({ schema, rootValue: root, graphiql: true }));

const server = app.listen(4000, () => console.log('GraphQL API listening on http://localhost:4000/graphql'));

SubscriptionServer.create(
  {
    schema,
    execute,
    subscribe,
    rootValue: root,   // <-- добавили!
    onConnect: () => console.log('Client connected'),
    onDisconnect: () => console.log('Client disconnected'),
  },
  { server, path: '/subscriptions' }
);

setInterval(() => {
  pubsub.publish('count', { count: Math.floor(Math.random() * 10) });
}, 1000);
```

```js
// client.js
const { SubscriptionClient } = require('subscriptions-transport-ws');
const ws = require('ws');

const client = new SubscriptionClient('ws://localhost:4000/subscriptions', { reconnect: true }, ws);

client.request({
  query: `
    subscription {
      count
    }
  `
}).subscribe({
  next: data => console.log('📬', data),
  error: err => console.error('❌', err),
});
```

## 4️⃣ Что ещё важно знать (для исследователя безопасности)

| Что | Почему это важно |
|-----|-----------------|
| **Отсутствие аутентификации** | Любой клиент может подключиться к `/subscriptions` и получать данные. |
| **Отсутствие авторизации** | Публикация (`pubsub.publish`) доступна только на сервере, но подписчикам выдаётся любой `count`. |
| **Потенциал DoS** | `setInterval` без ограничений может генерировать слишком много сообщений. |
| **Надёжность WebSocket** | `subscriptions-transport-ws` объявлен устаревшим. Лучше перейти на `graphql-ws`. |
| **Валидация** | В вашем схеме нет входных параметров, но в реальном приложении нужно валидировать любые аргументы подписки, чтобы предотвратить злоупотребления. |

### Быстрый чек‑лист

1. **Аутентификация** – передайте токен в `onConnect` и сохраните в контексте (`context`).
2. **Авторизация** – проверьте права в резолвере подписки (`authorization`).
3. **Rate‑лимит** – ограничьте количество сообщений на пользователя (например, `setInterval` внутри `subscribe`).
4. **Переключение на `graphql-ws`** – он поддерживает `keepAlive`, `onConnect`, `onDisconnect` и более современный API.
5. **Тестирование** – напишите unit‑тесты, проверяющие, что подписка не возвращает `undefined` и что нет утечек памяти.

## 5️⃣ Итог

> **Ключ к решению** – добавить `rootValue` в конфигурацию `SubscriptionServer`.  
> После этого подписка работает без ошибок, а ваш сервер готов к дальнейшему развитию и усилению безопасности. 🚀

