### Quick‑Take

- **Why the snippet “doesn’t work”**  
  1. **Timing** – The wrapper is only applied **after** you create a `new WebSocketInterceptor(...)`.  
  2. **Scope** – Existing WebSocket objects created before you inject the interceptor are already bound to the original constructor and can’t be retro‑actively wrapped.  
  3. **Missing static members** – `WebSocket.CONNECTING`, `OPEN`, `CLOSING`, `CLOSED`, and the `protocol` property are not forwarded by the proxy, so code that relies on them may silently break.  
  4. **Prototype mismatch** – A proxy that returns a plain object is no longer an instance of `WebSocket`, so `instanceof WebSocket` checks fail.  

Below is a **robust, production‑ready** patch that:

* Replaces `window.WebSocket` globally (so **every** future connection goes through it).  
* Keeps the same prototype chain (`instanceof` works).  
* Forwards all properties (including static constants).  
* Lets you modify outgoing data **and** intercept incoming messages, even when handlers are added via `addEventListener` or the legacy `onmessage` property.  
* Adds minimal overhead and logs for debugging.

---

## 1. The “global monkey‑patch” implementation

```js
(() => {
  /* Grab the original constructor and its prototype */
  const OriginalWebSocket = window.WebSocket;
  const OriginalProto = OriginalWebSocket.prototype;

  /* ------------------------------------------------------------------
   * Helper:  Wrap a single WebSocket instance
   * ------------------------------------------------------------------ */
  function wrapSocket(ws) {
    /* --- Intercept send ------------------------------------------------- */
    const origSend = ws.send;
    ws.send = function (data) {
      try {
        console.debug('[WS‑Intercept] Outgoing', { data });

        // Example: modify binary or textual data
        // if (typeof data === 'string') data = data.toUpperCase();

        return origSend.call(this, data);
      } catch (e) {
        console.error('[WS‑Intercept] send failed', e);
        throw e;
      }
    };

    /* --- Intercept addEventListener ------------------------------------- */
    const origAddListener = ws.addEventListener;
    ws.addEventListener = function (type, listener, options) {
      if (type === 'message' && typeof listener === 'function') {
        const wrapped = function (e) {
          console.debug('[WS‑Intercept] Incoming', e.data);
          return listener.call(this, e);
        };
        return origAddListener.call(this, type, wrapped, options);
      }
      return origAddListener.call(this, type, listener, options);
    };

    /* --- Intercept onmessage property ----------------------------------- */
    Object.defineProperty(ws, 'onmessage', {
      set(fn) {
        if (typeof fn === 'function') {
          const wrapped = function (e) {
            console.debug('[WS‑Intercept] onmessage', e.data);
            return fn.call(this, e);
          };
          OriginalProto.addEventListener.call(ws, 'message', wrapped);
        } else {
          OriginalProto.removeEventListener.call(ws, 'message', fn);
        }
      },
      get() {
        // We don't keep a ref – this is a best‑effort proxy.
        return null;
      },
      configurable: true,
      enumerable: false,
    });

    /* --- Optionally expose the original socket for debugging --------- */
    ws._originalWebSocket = ws;
    return ws;
  }

  /* ------------------------------------------------------------------
   * The patched constructor
   * ------------------------------------------------------------------ */
  function PatchedWebSocket(url, protocols) {
    // The constructor can be called with no arguments in some libraries
    const ws = new OriginalWebSocket(url, protocols);
    return wrapSocket(ws);
  }

  /* Preserve the prototype chain:  PatchedWebSocket instanceof WebSocket */
  PatchedWebSocket.prototype = OriginalProto;

  /* Forward static members (CONNECTING, OPEN, …) */
  ['CONNECTING', 'OPEN', 'CLOSING', 'CLOSED'].forEach((k) => {
    Object.defineProperty(PatchedWebSocket, k, {
      get: () => OriginalWebSocket[k],
      enumerable: true,
      configurable: true,
    });
  });

  /* Finally replace the global constructor */
  window.WebSocket = PatchedWebSocket;

