  store.subscribe((mutation, state) => {
    if (mutation.type.startsWith('user/')) {
      // 只在用户模块变更时才广播
      const payload = {
        type: 'USER_INFO',
        data: state.user,
        version: state.user.version   // 可选
      };
      // 这里 * 代表允许跨域；如果知道子页面 origin，可以写成 origin
      window.parent.postMessage(payload, '*');
    }
  });
}
