It uses the built‑in `crypto` module, AES‑256‑GCM (which gives you confidentiality + integrity), and a PBKDF2‑derived key so you can use a simple pass‑phrase.

> **⚠️ Security note**  
> * Never hard‑code the password or key in source code that is checked‑in.  
> * Store the key/IV securely (e.g. in a vault, hardware security module, or a dedicated key‑management service).  
> * Use a *unique* random IV per encryption.  
> * The example below is for learning / testing purposes; adapt it to your production security requirements.

```bash
# 1. Install Node (>=12.0) – the script uses only core modules
# 2. Save this file as encrypt.js
# 3. Run: node encrypt.js --encrypt <path-to-input-file> <path-to-output-file>
#    or: node encrypt.js --decrypt <path-to-encrypted-file> <path-to-output-file>
```

```js
#!/usr/bin/env node
/**
 * encrypt.js
 *
 * Usage:
 *   node encrypt.js --encrypt  input.js  output.enc
 *   node encrypt.js --decrypt  output.enc  decrypted.js
 *
 * The script will prompt for a pass‑phrase on the command line.
 */

const fs = require('fs');
const crypto = require('crypto');
const path = require('path');
const readline = require('readline');

// ---- Configuration ----
const ALGORITHM = 'aes-256-gcm';
const KEY_LENGTH = 32;          // 256 bits
const SALT_LENGTH = 16;         // For PBKDF2
const IV_LENGTH = 12;           // Recommended for GCM (12 bytes)
const PBKDF2_ITERATIONS = 100000;
const DIGEST = 'sha256';

// ---- Helper: Prompt for password without echo ----
function promptPassword(promptText) {
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
    });

    // Hide typed characters
    const stdin = process.openStdin();
    stdin.on('data', (char) => {
      char = char + '';
      switch (char) {
        case '\n':
        case '\r':
        case '\u0004':
          stdin.pause();
          break;
        default:
          process.stdout.clearLine();
          readline.cursorTo(process.stdout, 0);
          process.stdout.write(promptText + Array(rl.line.length + 1).join('*'));
          break;
      }
    });

    rl.question(promptText, (value) => {
      rl.history = rl.history.slice(1);
      rl.close();
      resolve(value);
    });
  });
}

// ---- Key derivation ----
function deriveKey(password, salt) {
  return crypto.pbkdf2Sync(password, salt, PBKDF2_ITERATIONS, KEY_LENGTH, DIGEST);
}

// ---- Encryption ----
function encryptFile(inputPath, outputPath, password) {
  const salt = crypto.randomBytes(SALT_LENGTH);
  const key = deriveKey(password, salt);
  const iv = crypto.randomBytes(IV_LENGTH);

  const cipher = crypto.createCipheriv(ALGORITHM, key, iv);

  const input = fs.createReadStream(inputPath);
  const output = fs.createWriteStream(outputPath);

  // We will prepend the salt and iv to the output file.
  // Output format: | salt | iv | ciphertext | authTag |
  // (authTag is appended automatically by cipher.final())
  output.write(salt);
  output.write(iv);

  input.pipe(cipher).pipe(output);

  output.on('finish', () => {
    console.log(`✓ Encrypted "${inputPath}" → "${outputPath}"`);
  });

  output.on('error', (err) => {
    console.error('❌ Encryption failed:', err);
  });
}

// ---- Decryption ----
function decryptFile(inputPath, outputPath, password) {
  const input = fs.createReadStream(inputPath);
  // We'll read salt and iv first, then pipe the rest.
  const buffers = [];
  let bytesRead = 0;
  let headerRead = false;

  input.on('data', (chunk) => {
    if (!headerRead) {
      buffers.push(chunk);
      bytesRead += chunk.length;

      // We need at least SALT_LENGTH + IV_LENGTH bytes for header
      if (bytesRead >= SALT_LENGTH + IV_LENGTH) {
        const header = Buffer.concat(buffers, bytesRead);
        const salt = header.slice(0, SALT_LENGTH);
        const iv = header.slice(SALT_LENGTH, SALT_LENGTH + IV_LENGTH);

        const ciphertext = header.slice(SALT_LENGTH + IV_LENGTH);
        const remaining = Buffer.concat([ciphertext, chunk.slice(SALT_LENGTH + IV_LENGTH)]);

        const key = deriveKey(password, salt);
        const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);

        // We must provide the authTag, which is the last 16 bytes of the ciphertext
        const authTag = remaining.slice(remaining.length - 16);
        const ct = remaining.slice(0, remaining.length - 16);

        decipher.setAuthTag(authTag);

        const output = fs.createWriteStream(outputPath);
        output.write(ct);
        output.write(decipher.update(ct));
        output.end(decipher.final());

        console.log(`✓ Decrypted "${inputPath}" → "${outputPath}"`);
        headerRead = true; // Done
        input.destroy();   // Stop reading further
      }
    }
  });

  input.on('error', (err) => {
    console.error('❌ Decryption failed:', err);
  });
}

// ---- CLI handling ----
async function main() {
  const args = process.argv.slice(2);

  if (args.length !== 3) {
    console.error(`Usage:
  node encrypt.js --encrypt  <input>  <output>
  node encrypt.js --decrypt  <input>  <output>`);
    process.exit(1);
  }

  const [mode, inputPath, outputPath] = args;
  if (!['--encrypt', '--decrypt'].includes(mode)) {
    console.error('First argument must be --encrypt or --decrypt');
    process.exit(1);
  }

  const absInput = path.resolve(inputPath);
  const absOutput = path.resolve(outputPath);

  if (!fs.existsSync(absInput)) {
    console.error(`❌ Input file "${absInput}" does not exist`);
    process.exit(1);
  }

  const password = await promptPassword('Enter pass‑phrase: ');

  if (mode === '--encrypt') {
    encryptFile(absInput, absOutput, password);
  } else {
    decryptFile(absInput, absOutput, password);
  }
}

main().catch((err) => {
  console.error('❌ Unexpected error:', err);
  process.exit(1);
});
```

### How it works

1. **Password prompt** – The script asks you for a pass‑phrase without echoing it.
2. **Key derivation** – `pbkdf2Sync` turns the pass‑phrase into a 256‑bit key.  
   *A random 16‑byte salt* is generated per file to make the derived key unique.
3. **Encryption**  
   * A random 12‑byte IV is generated (required for GCM).  
   * The file is streamed, so you can encrypt large files without loading everything into RAM.  
   * The output file is written as: `| salt | iv | ciphertext | authTag |`.  
   * The authTag (16 bytes) is automatically appended by `Cipher.final()` and verified on decryption.
4. **Decryption** – The script reads the salt & IV, derives the key again, then decrypts and verifies integrity.

### Extending / Production‑grade considerations

| Issue | Recommendation |
|-------|----------------|
| **Key storage** | Store the pass‑phrase / key securely (e.g., AWS KMS, HashiCorp Vault). |
| **Salt persistence** | In many setups you store the salt & IV alongside the ciphertext (as we do). |
| **Integrity** | AES‑GCM provides this. |
| **Error handling** | Wrap in try/catch and handle authTag failures. |
| **File permissions** | Ensure encrypted files are protected from unauthorized users (chmod). |
| **Audit** | Log encryption/decryption events if needed. |

Feel free to tweak the algorithm, key length, or add a CLI for bulk processing. Happy encrypting!

