```

### Скрипт

```html
<script>
  // Функция, которая очищает localStorage и убирает отображаемый текст
  function clearSavedData() {
      // 1️⃣ Удаляем запись из localStorage
      localStorage.removeItem('savedData');

      // 2️⃣ Очищаем контейнер, где отображаются данные
      var savedDataDiv = document.getElementById('savedData');
