          savedDataDiv.innerHTML = '';
      }
  }

  // 3️⃣ Подписываемся на кнопку
  document.getElementById('clearButton').addEventListener('click', function (e) {
      e.preventDefault();
      clearSavedData();
      alert('Данные удалены');
  });

  // 4️⃣ Загружаем данные (если они остались в localStorage)
  (function () {
      var savedData = localStorage.getItem('savedData');
      if (savedData) {
          try {
              var dataObj = JSON.parse(savedData);
              var container = document.getElementById('savedData');
              for (var key in dataObj) {
                  container.innerHTML += "<p>" + key + ": " + decodeURIComponent(dataObj[key]) + "</p>";
              }
          } catch (err) {
              console.error('Ошибка парсинга сохранённых данных', err);
          }
      } else {
          // При отсутствии данных можно оставить сообщение или просто ничего не выводить
          console.log('Нет сохранённых данных');
      }
  })();
</script>
```

> **Почему так?**  
> - `localStorage.removeItem('savedData')` – полностью удаляет запись.  
> - `innerHTML = ''` – гарантирует, что даже если в DOM остался какой‑то «запас» текста, он будет удалён.  
> - Установка слушателя события на кнопку позволяет пользователю вручную очистить данные в любой момент.

---

## 2. Если вы хотите, чтобы данные автоматически исчезали после перехода со второй на первую страницу

Если ваша цель – **сразу** очищать `localStorage` при заходе на первую страницу, просто удалите строку, которая выводит данные, до того, как вы их парсите.  

