    res.render('author_settings', { settings });
  });
});

app.post('/author/settings', (req, res) => {
  const { blog_title, subtitle, author_name } = req.body;
  if (!blog_title || !subtitle || !author_name) {
    return res.status(400).send('All fields are required.');
  }
  db.run(
    `UPDATE settings SET blog_title = ?, subtitle = ?, author_name = ?
     WHERE id = 1`,
    [blog_title, subtitle, author_name],
    function (err) {
      if (err) return res.status(500).send('DB error');
      res.redirect('/author');
    }
  );
});

// --------------- Author Edit Article ----------------
app.get('/author/edit/:id', (req, res) => {
  const id = req.params.id;
  getSettings((err, settings) => {
    if (err) return res.status(500).send('DB error');
    getArticle(id, (err, article) => {
      if (err || !article) return res.status(404).send('Article not found');
      res.render('author_edit', { settings, article });
    });
  });
});

app.post('/author/edit/:id', (req, res) => {
  const id = req.params.id;
  const { title, subtitle, content } = req.body;
  const now = new Date().toISOString();
  db.run(
    `UPDATE articles SET title = ?, subtitle = ?, content = ?, updated_at = ?
     WHERE id = ?`,
    [title, subtitle, content, now, id],
    function (err) {
      if (err) return res.status(500).send('DB error');
      res.redirect('/author');
    }
  );
});

// --------------- Reader Home ----------------
app.get('/', (req, res) => {
  getSettings((err, settings) => {
    if (err) return res.status(500).send('DB error');
    db.all(
      `SELECT * FROM articles WHERE status = 'published'
       ORDER BY published_at DESC`,
      [],
      (err, articles) => {
        if (err) return res.status(500).send('DB error');
        res.render('reader_home', { settings, articles });
      }
    );
  });
});

// --------------- Reader Article ----------------
app.get('/article/:id', (req, res) => {
  const id = req.params.id;
  getSettings((err, settings) => {
    if (err) return res.status(500).send('DB error');
    getArticle(id, (err, article) => {
      if (err || !article) return res.status(404).send('Article not found');
      getComments(id, (err, comments) => {
        if (err) return res.status(500).send('DB error');
        res.render('reader_article', {
          settings,
          article,
          comments
        });
      });
    });
  });
});

app.post('/article/:id/like', (req, res) => {
  const id = req.params.id;
  db.run(
    `UPDATE articles SET likes = likes + 1 WHERE id = ?`,
    [id],
    function (err) {
      if (err) return res.status(500).send('DB error');
      res.redirect(`/article/${id}`);
    }
  );
});

app.post('/article/:id/comment', (req, res) => {
  const id = req.params.id;
  const { comment } = req.body;
  if (!comment) return res.status(400).send('Comment cannot be empty.');
  const now = new Date().toISOString();
  db.run(
    `INSERT INTO comments (article_id, comment, created_at)
     VALUES (?, ?, ?)`,
    [id, comment, now],
    function (err) {
      if (err) return res.status(500).send('DB error');
      res.redirect(`/article/${id}`);
    }
  );
});

// ---------- Start Server ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Blog app listening at http://localhost:${PORT}`);
});
