  // 4. Проходим по массиву, начиная со второго элемента
  for (let i = 1; i < arr.length; ++i) {
    const item = arr[i];

    if (typeof item === "string") {
      // Слово может быть либо ключом, либо операцией
      if (item === "Read" || item === "Write") {
        operation = item;
      } else {
        // Это обычный ключ, создаём объект‑контейнер
        pendingKey = item;
        if (!context[pendingKey]) {
          context[pendingKey] = {};
        }
      }
    } else if (Array.isArray(item)) {
      // У нас пришёл массив значений
      bufferArray = item;

      // Если мы уже знаем ключ и операцию – кладём данные в нужные места
      if (pendingKey && operation) {
        // 4.1. Записываем массив под ключом и операцией
        context[pendingKey][operation] = bufferArray;

        // 4.2. Если операция – Write, копируем массив в два разных места
        if (operation === "Write") {
          // В родительский уровень (Load Profile → General → Write)
          // и в объект Parameters → Positive → Write
          context.Write = bufferArray;
          context.Parameters = context.Parameters || {};
          context.Parameters.Positive = context.Parameters.Positive || {};

          // В примере «Positive» содержит только те элементы,
          // которые можно писать в режиме «Positive» – 2‑й и 3‑й из Write‑массива.
          // Это – простое правило‑примера; в реальном коде замените на своё.
          context.Parameters.Positive.Write =
            bufferArray
              .slice(1)          // удаляем первый элемент (Get Version)
              .reverse();        // меняем порядок как в примере
        }

        // 4.3. Если операция – Read, кладём массив в Parameters → Instantaneous → Read
        if (operation === "Read") {
          context.Parameters = context.Parameters || {};
          context.Parameters.Instantaneous = context.Parameters.Instantaneous || {};
          context.Parameters.Instantaneous.Read = bufferArray;
        }

        // Сбрасываем вспомогательные переменные
        pendingKey = null;
        operation  = null;
        bufferArray = null;
