/**
 * A thin wrapper around the browser WebSocket API that exposes a convenient
 * event emitter interface (`mitt`) for the rest of the application.
 *
 * The socket is connected to **ws://owbalancer.ddns.net:8765/site** when
 * {@link WebSocketManager#open} is called.
 *
 * @class
 * @see {@link https://github.com/developit/mitt | mitt} – event emitter library
 */
class WebSocketManager {
  /**
   * Create a new {@link WebSocketManager} instance.
   *
   * @constructor
   */
  constructor() {
    /** @type {import('mitt').Emitter} */
    this.emitter = mitt();
  }

  /**
   * Opens a WebSocket connection and registers a message listener.
   *
   * The listener parses JSON payloads and forwards specific actions to the
   * internal `mitt` emitter:
   *
   * | action               | emitted event         | payload |
   * |----------------------|-----------------------|---------|
   * | `update_station`     | `update_station`      | `{ uuid }` |
   * | `update_station_list`| `update_station_list` | `undefined` |
   * | `update_inventory`   | `update_inventory`    | `{ factory_uuid, inventory_name }` |
   *
   * @returns {void}
   *
   * @fires WebSocketManager#update_station
   * @fires WebSocketManager#update_station_list
   * @fires WebSocketManager#update_inventory
   *
   * @throws {Error} If the WebSocket fails to connect.
   */
  open() {
    this.socket = new WebSocket('ws://owbalancer.ddns.net:8765/site');

    const self = this; // `self` is used to capture `this` for the event callback

    /**
     * Handles incoming WebSocket messages.
     *
     * @param {MessageEvent<string>} msg - The event object.
     */
    this.socket.addEventListener('message', (msg) => {
      const json = JSON.parse(msg.data);
      const { action, uuid, factory, inventory } = json;

      if (action === 'update_station') {
        self.emitter.emit('update_station', { uuid });
      } else if (action === 'update_station_list') {
        self.emitter.emit('update_station_list');
      } else if (action === 'update_inventory') {
        self.emitter.emit('update_inventory', {
          factory_uuid: factory,
          inventory_name: inventory,
        });
      }
    });
  }

  /**
   * Sends a JSON‑encoded message through the open WebSocket.
   *
   * @param {Object} data - The payload to send.
   * @returns {void}
   *
   * @throws {TypeError} If `data` cannot be serialized to JSON.
   * @throws {DOMException} If the socket is not open.
   */
  sendMessage(data) {
    this.socket.send(JSON.stringify(data));
  }
}

/**
 * The default export that can be used throughout the application.
 *
 * @type {WebSocketManager}
 */
export const websocketApi = new WebSocketManager();
```

### Quick notes on the security aspects

* **Transport** – The socket is opened over plain **ws://**. If the server supports TLS, change to **wss://** to protect payload integrity and confidentiality.
* **JSON validation** – The code blindly parses every incoming payload (`JSON.parse`). If you control the server, ensure it never sends malformed data. In a hostile environment, wrap the `JSON.parse` call in a `try/catch`.
* **Event filtering** – The emitter is internal; only the specified actions are forwarded. Additional actions are silently ignored, which helps limit attack surface.

