下面给出一个 **完整可直接运行** 的示例项目。  
它使用 **Node.js + Express** 做后端，**vanilla‑JS + CSS** 做前端，满足你列出的全部需求：

| 需求 | 解决方案 |
|------|----------|
| 1. 分类（单选） | 前端用 `<input type="radio">`，后端把分类信息写进 JSON |
| 2. 分页（20 个/页，4 列） | 前端 JS 负责计算页数、渲染页面；分页按钮切换页面 |
| 3. 自动扫描文件夹 | 后端每次请求都扫描一次 `assets/` 目录；放新文件直接刷新即可 |
| 5. 点击预览图片下载 | 预览图链接指向 `assets/.../preview.png`，点击时创建一个隐藏 `<a>` 并触发下载 |

> **注意**  
> - 这里的 **模型文件** 仅用作示例（`.obj` / `.fbx` / `.glb` 等），实际部署时请根据需要调整。  
> - 代码没有做权限校验，部署到公网请自行加认证或防火墙。  
> - 若有大量模型建议做缓存或数据库存储，当前实现仅演示文件系统读取。

---

## 1️⃣ 项目目录结构

```
3d‑viewer/
├─ assets/          # 存放模型文件夹（project、docs、hrdp 等）
│   ├─ project/
│   │   ├─ model1.obj
│   │   ├─ preview1.png
│   │   └─ ...
│   ├─ docs/
│   └─ hrdp/
├─ public/
│   ├─ index.html
│   ├─ script.js
│   └─ styles.css
├─ server.js
├─ package.json
└─ .gitignore
```

> **assets/** 目录里每个子目录即为 **模型用途分类**，且每个模型都必须有同名的预览图（后缀可自行改）。  
> 例如：`assets/project/model1.obj` 与 `assets/project/preview1.png`（或者 `model1.png`）同名。

---

## 2️⃣ 后端（server.js）

```js
/* server.js */
const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3000;

// 静态资源（预览图、模型文件）
app.use('/assets', express.static(path.join(__dirname, 'assets')));
app.use('/public', express.static(path.join(__dirname, 'public')));

// 统一入口：返回分类与模型列表
app.get('/api/models', (req, res) => {
  const baseDir = path.join(__dirname, 'assets');
  const categories = fs.readdirSync(baseDir, { withFileTypes: true })
    .filter(d => d.isDirectory())
    .map(d => d.name);

  const data = categories.map(cat => {
    const dirPath = path.join(baseDir, cat);
    const files = fs.readdirSync(dirPath);
    const models = [];

    // 只列出 *.obj / *.fbx / *.glb 等模型文件
    const modelExts = ['.obj', '.fbx', '.glb', '.gltf', '.dae'];
    files.forEach(file => {
      const ext = path.extname(file).toLowerCase();
      if (!modelExts.includes(ext)) return;

      const nameWithoutExt = path.basename(file, ext);
      const preview = files.find(f => {
        const pf = path.basename(f);
        return pf.toLowerCase().startsWith(nameWithoutExt.toLowerCase()) &&
               (path.extname(pf).toLowerCase() === '.png' ||
                path.extname(pf).toLowerCase() === '.jpg' ||
                path.extname(pf).toLowerCase() === '.jpeg');
      });

      const previewFile = preview ? `/assets/${cat}/${preview}` : null;
      const modelFile = `/assets/${cat}/${file}`;

      models.push({
        name: nameWithoutExt,
        preview: previewFile,
        file: modelFile
      });
    });

    return { category: cat, models };
  });

  res.json({ categories, data });
});

app.listen(PORT, () => {
  console.log(`3D viewer running at http://localhost:${PORT}`);
});
```

> 说明  
> - `/api/models` **每次请求都会重新扫描文件夹**，所以你只要把新模型放进 `assets/` 目录并刷新页面即可看到。  
> - 只会返回支持的模型后缀，预览图默认是同名 PNG/JPG。

---

## 3️⃣ 前端

### 3.1 `public/index.html`

```html
<!DOCTYPE html>
<html lang="zh">
<head>
  <meta charset="UTF-8">
  <title>3D 模型预览</title>
  <link rel="stylesheet" href="/public/styles.css">
</head>
<body>
  <h1>3D 模型预览</h1>

  <section id="category-filter">
    <label>分类：</label>
    <div id="radio-group"></div>
  </section>

  <section id="preview-area">
    <div id="models-grid"></div>
    <div id="pagination"></div>
  </section>

  <script src="/public/script.js"></script>
</body>
</html>
```

### 3.2 `public/styles.css`

```css
/* styles.css */
body {font-family: Arial, sans-serif; margin: 20px;}
h1 {text-align: center;}
#category-filter {margin-bottom: 20px;}
#radio-group input {margin-right: 5px;}
#models-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 15px;
}
.model-card {
  border: 1px solid #ccc;
  padding: 10px;
  text-align: center;
}
.model-card img {width: 100%; cursor: pointer;}
#pagination {text-align: center; margin-top: 20px;}
.page-btn {margin: 0 5px; cursor: pointer;}
.page-btn.active {font-weight: bold;}
```

### 3.3 `public/script.js`

```js
/* script.js */
const API_URL = '/api/models';
const ITEMS_PER_PAGE = 20;

let categories = [];
let currentCategory = null;
let currentPage = 1;
let currentModels = [];

// ---------- 初始化 ----------
fetch(API_URL).then(r => r.json()).then(initApp);

function initApp({ categories: cats, data }) {
  categories = cats;
  currentCategory = cats[0];
  createRadioButtons(categories);
  loadModelsForCategory(currentCategory, data);
}

function createRadioButtons(cats) {
  const container = document.getElementById('radio-group');
  container.innerHTML = '';
  cats.forEach(cat => {
    const id = `cat-${cat}`;
    const radio = document.createElement('input');
    radio.type = 'radio';
    radio.id = id;
    radio.name = 'category';
    radio.value = cat;
    radio.checked = cat === currentCategory;
    radio.addEventListener('change', () => {
      currentCategory = cat;
      currentPage = 1;
      loadModelsForCategory(cat, data);
    });

    const label = document.createElement('label');
    label.htmlFor = id;
    label.textContent = cat;

    container.appendChild(radio);
    container.appendChild(label);
  });
}

// ---------- 模型加载 ----------
function loadModelsForCategory(cat, data) {
  const catData = data.find(d => d.category === cat);
  if (!catData) return;
  currentModels = catData.models;
  renderPage();
}

function renderPage() {
  const grid = document.getElementById('models-grid');
  grid.innerHTML = '';

  const start = (currentPage - 1) * ITEMS_PER_PAGE;
  const pageItems = currentModels.slice(start, start + ITEMS_PER_PAGE);

  pageItems.forEach(item => {
    const card = document.createElement('div');
    card.className = 'model-card';

    const img = document.createElement('img');
    img.src = item.preview || 'placeholder.png'; // placeholder.png 可放在 public/
    img.alt = item.name;
    img.title = item.name;
    img.onclick = () => downloadFile(item.file);

    const title = document.createElement('div');
    title.textContent = item.name;

    card.appendChild(img);
    card.appendChild(title);
    grid.appendChild(card);
  });

  renderPagination();
}

// ---------- 分页 ----------
function renderPagination() {
  const container = document.getElementById('pagination');
  container.innerHTML = '';
  const totalPages = Math.ceil(currentModels.length / ITEMS_PER_PAGE);

  for (let i = 1; i <= totalPages; i++) {
    const btn = document.createElement('span');
    btn.className = 'page-btn' + (i === currentPage ? ' active' : '');
    btn.textContent = i;
    btn.onclick = () => { currentPage = i; renderPage(); };
    container.appendChild(btn);
  }
}

// ---------- 下载 ----------
function downloadFile(url) {
  const a = document.createElement('a');
  a.href = url;
  a.download = url.split('/').pop(); // 使用文件名
  document.body.appendChild(a);
  a.click();
  a.remove();
}
```

> **说明**  
> - **单选框** 通过 `radio-group` 生成，点击后立即切换分类。  
> - **分页** 计算当前页的模型切片，20 个/页。  
> - **下载** 直接在前端使用 `<a>` 元素触发文件下载。  
> - 如果某个模型没有预览图，页面会显示 `placeholder.png`（请自行放到 `public/`）。  

---

## 4️⃣ 运行步骤

1. **安装依赖**  
   ```bash
   cd 3d-viewer
   npm install express
   ```

2. **放模型**  
   在 `assets/` 里按分类建文件夹，例如：

   ```
   assets/
   ├─ project/
   │   ├─ car.obj
   │   └─ car.png
   ├─ docs/
   │   ├─ book.fbx
   │   └─ book.png
   └─ hrdp/
       ├─ tree.glb
       └─ tree.png
   ```

3. **启动服务器**  
   ```bash
   node server.js
   ```

4. **访问**  
   打开浏览器，访问 `http://localhost:3000`。  
   - 选中分类 → 页面实时更新。  
   - 分页按钮 → 换页。  
   - 点击预览图 → 下载对应模型。  

5. **自动刷新**  
   新建或删除文件后，只需刷新页面即可看到变更。

---

## 5️⃣ 进一步改进（可选）

| 方向 | 思路 |
|------|------|
| **性能** | 把扫描结果缓存到内存或数据库，定时刷新。 |
| **安全** | 对 `/api/models` 做权限校验，或限制可访问文件。 |
| **预览** | 用 **Three.js** 在每个卡片里直接渲染 3D 预览（需额外 JS）。 |
| **UI** | 使用 Bootstrap / Tailwind 让页面更美观。 |
| **多语言** | 把分类名存成键值，前端根据语言显示。 |

---

