  <title>Hover Preview Demo</title>
  <style>
    #preview-container {
      position: absolute; z-index:1000; width:300px; background:#fff;
      border:1px solid #ccc; box-shadow:0 4px 8px rgba(0,0,0,.2);
      padding:8px; display:none;
    }
    .preview-trigger { display:inline-block; margin:20px; cursor:pointer; }
  </style>
</head>
<body>
  <div class="preview-trigger" data-preview-url="/preview/1" tabindex="0">
    <img src="https://picsum.photos/50/50?random=1" alt="Thumb">
