## 3. Generator code – `generator.js`

```js
/**
 *  sql-to-express/generator.js
 *
 *  This script asks the user for a SQL CREATE TABLE statement,
 *  parses it, and writes a minimal Express app that exposes
 *  CRUD endpoints for that table.
 *
 *  Run it with:
 *     node generator.js
 *
 *  The generated files are written into the "generated" folder.
 */

'use strict';
const fs = require('fs-extra');
const path = require('path');
const readlineSync = require('readline-sync');
const { Parser } = require('node-sql-parser');
const ejs = require('ejs');

// ------------------------------------------------------------------
// 1. Ask user for SQL input
// ------------------------------------------------------------------
let sqlInput = '';

while (!sqlInput.trim()) {
  console.log('\nPlease paste your CREATE TABLE statement.\nYou can also provide a file path:');
  const userInput = readlineSync.question('> ');
  const trimmed = userInput.trim();

  if (!trimmed) continue;

  if (trimmed.endsWith('.sql') || trimmed.endsWith('.txt')) {
    // Treat as a file path
    const filePath = path.resolve(process.cwd(), trimmed);
    if (!fs.existsSync(filePath)) {
      console.log(`❌ File not found: ${filePath}`);
      continue;
    }
    sqlInput = fs.readFileSync(filePath, 'utf8');
  } else {
    // Direct SQL string
    sqlInput = trimmed;
  }
}

// ------------------------------------------------------------------
// 2. Parse the SQL statement
// ------------------------------------------------------------------
const parser = new Parser();
let ast;
try {
  ast = parser.astify(sqlInput);
} catch (err) {
  console.error('❌ Failed to parse SQL:', err.message);
  process.exit(1);
}

if (!Array.isArray(ast)) ast = [ast];
if (ast[0].type !== 'create') {
  console.error('❌ Only CREATE TABLE statements are supported.');
  process.exit(1);
}

const tableDef = ast[0];
const tableName = tableDef.table[0].table;

// Helper: convert SQL data types to Sequelize data types
const sqlToSequelize = type => {
  const t = type.toUpperCase();
  if (/^INT/.test(t)) return 'DataTypes.INTEGER';
  if (/^BIGINT/.test(t)) return 'DataTypes.BIGINT';
  if (/^VARCHAR/.test(t)) return 'DataTypes.STRING';
  if (/^TEXT/.test(t)) return 'DataTypes.TEXT';
  if (/^DATETIME/.test(t)) return 'DataTypes.DATE';
  if (/^TIMESTAMP/.test(t)) return 'DataTypes.DATE';
  if (/^DECIMAL/.test(t)) return 'DataTypes.DECIMAL';
  if (/^BOOLEAN/.test(t)) return 'DataTypes.BOOLEAN';
  if (/^FLOAT/.test(t)) return 'DataTypes.FLOAT';
  return 'DataTypes.STRING';
};

// Build column descriptors
const columns = tableDef.create_definitions.map(col => {
  const colName = col.column.column;
  const colType = sqlToSequelize(col.definition.dataType);

  // Constraints
  const allowNull = !col.definition.nullable || col.definition.nullable === false;
  const primaryKey = col.definition.primaryKey || false;
  const unique = col.definition.unique || false;
  const autoIncrement = col.definition.autoIncrement || false;

  return {
    name: colName,
    type: colType,
    allowNull,
    primaryKey,
    unique,
    autoIncrement,
  };
});

// ------------------------------------------------------------------
// 3. Prepare templates
// ------------------------------------------------------------------
const templateDir = path.join(__dirname, 'templates');

const filesToGenerate = [
  {
    // Sequelize model
    dest: path.join('generated', 'models', `${tableName}.js`),
    template: 'model.ejs',
  },
  {
    // CRUD controller
    dest: path.join('generated', 'controllers', `${tableName}.js`),
    template: 'controller.ejs',
  },
  {
    // Router
    dest: path.join('generated', 'routes', `${tableName}.js`),
    template: 'router.ejs',
  },
  {
    // Auth utilities
    dest: path.join('generated', 'auth', 'auth.js'),
    template: 'auth.ejs',
  },
  {
    // Entry point
    dest: path.join('generated', 'app.js'),
    template: 'app.ejs',
  },
  {
    // package.json
    dest: path.join('generated', 'package.json'),
    template: 'package.ejs',
  },
];

// ------------------------------------------------------------------
// 4. Render and write files
// ------------------------------------------------------------------
for (const file of filesToGenerate) {
  const destPath = path.join(__dirname, file.dest);
  const destDir = path.dirname(destPath);
  fs.ensureDirSync(destDir);

  const templatePath = path.join(templateDir, file.template);
  const templateContent = fs.readFileSync(templatePath, 'utf8');

  const rendered = ejs.render(templateContent, {
    tableName,
    columns,
  });

  fs.writeFileSync(destPath, rendered, 'utf8');
  console.log(`✔︎ Created ${file.dest}`);
}

// ------------------------------------------------------------------
// 5. Install dependencies inside generated/
// ------------------------------------------------------------------
const execSync = require('child_process').execSync;
console.log('\n🔧 Installing generated project dependencies…');
execSync('npm install', { cwd: path.join(__dirname, 'generated'), stdio: 'inherit' });

console.log('\n✅ Done! Your CRUD API for table "'.concat(tableName, '" is ready inside the "generated" folder.'));
console.log('📌 To start the app, run:');
console.log('   cd generated');
console.log('   node app.js');
console.log('\nGood luck! 🚀');
```

