'use strict';
const jwt = require('jsonwebtoken');
const cookieParser = require('cookie-parser');
const SECRET = process.env.JWT_SECRET || 'REPLACE_WITH_RANDOM_SECRET';
const TOKEN_COOKIE = 'auth_token';

module.exports = {
  signToken: (payload) => jwt.sign(payload, SECRET, { expiresIn: '1h' }),

  verifyToken: (req, res, next) => {
    const token = req.cookies[TOKEN_COOKIE];
    if (!token) return res.status(401).json({ error: 'Unauthorized' });

    try {
      const decoded = jwt.verify(token, SECRET);
      req.user = decoded;
      next();
    } catch (e) {
      return res.status(401).json({ error: 'Invalid token' });
    }
  },

  loginRoute: (router, UserModel) => {
    router.post('/login', async (req, res) => {
      const { email, password } = req.body;
      if (!email || !password) return res.status(400).json({ error: 'Missing credentials' });

      const user = await UserModel.findOne({ where: { email } });
      if (!user || user.password !== password) return res.status(401).json({ error: 'Invalid credentials' });

      const token = module.exports.signToken({ id: user.id, email: user.email });
      res
        .cookie(TOKEN_COOKIE, token, { httpOnly: true, secure: process.env.NODE_ENV === 'production' })
        .json({ message: 'Logged in' });
    });

    router.post('/logout', (req, res) => {
      res.clearCookie(TOKEN_COOKIE).json({ message: 'Logged out' });
    });
  },
};
