/* background.js – Service worker */

const QUOTE_API = 'https://api.quotable.io/quotes?author=Elon+Musk';

async function fetchElonQuotes() {
  try {
    const res = await fetch(QUOTE_API);
    if (!res.ok) throw new Error('Network error');
    const data = await res.json();
    return data.results; // Array of quote objects
  } catch (e) {
    console.error('Failed to load Elon quotes', e);
    return [];
  }
}

// Cache quotes in memory; refresh every 24h (configurable)
let cachedQuotes = [];
let lastFetched = 0;
const CACHE_DURATION_MS = 24 * 60 * 60 * 1000;

async function getElonQuotes() {
  const now = Date.now();
  if (now - lastFetched > CACHE_DURATION_MS || cachedQuotes.length === 0) {
    cachedQuotes = await fetchElonQuotes();
    lastFetched = now;
  }
  return cachedQuotes;
}

/**
 * Search for a quote that contains the term (case‑insensitive).
 * Returns the first matching quote, or null.
 */
function findQuoteByTerm(quotes, term) {
  const lcTerm = term.toLowerCase();
  return quotes.find(q => q.content.toLowerCase().includes(lcTerm));
}

/* Listener from content script */
chrome.runtime.onMessage.addListener(async (msg, sender) => {
  if (msg.type === 'GET_QUOTE') {
    const quotes = await getElonQuotes();
    const quote = findQuoteByTerm(quotes, msg.term);
    return { quote }; // The message sender will receive this as a Promise
  }
  // Optional: context menu handler
  if (msg.type === 'SHOW_CONTEXT_MENU') {
    const quotes = await getElonQuotes();
    const quote = findQuoteByTerm(quotes, msg.term);
    if (quote) {
      chrome.notifications.create({
        type: 'basic',
        iconUrl: 'icons/icon.png',
