```js
function search(query = '', role = '', city = '') {
  const data = fs.readFileSync('./db/musicians.json');
  const musicians = JSON.parse(data).musicians.map(musician => ({
    name: musician.name,
    genre: musician.genre,
    originalName: musician.name,
    profileLink: `/profile/${musician.id}`,
    thumbnail: musician.thumbnail,
    soundcloud: musician.soundcloud,
    role: musician.role,
    city: musician.city      // хранится в city
  }));

  let results = [];

  if (query || role || city) {
    const lowerQuery = query.toLowerCase();

    results = musicians.filter(musician => {
      const nameScore  = musician.name.toLowerCase().startsWith(lowerQuery) ? 2
                       : musician.name.toLowerCase().includes(lowerQuery) ? 1 : 0;
      const genreScore = musician.genre.toLowerCase().startsWith(lowerQuery) ? 2
                       : musician.genre.toLowerCase().includes(lowerQuery) ? 1 : 0;

      return (
        nameScore + genreScore > 0 &&
        (role === '' || musician.role === role) &&
        (city === '' || (musician.city && musician.city.toLowerCase().trim() === city.toLowerCase().trim()))
      );
    });

    // Сортировка по score + city (descending)
    results.sort((a, b) => {
      const aNameScore  = a.name.toLowerCase().startsWith(lowerQuery) ? 2
                       : a.name.toLowerCase().includes(lowerQuery) ? 1 : 0;
      const aGenreScore = a.genre.toLowerCase().startsWith(lowerQuery) ? 2
                       : a.genre.toLowerCase().includes(lowerQuery) ? 1 : 0;
      const bNameScore  = b.name.toLowerCase().startsWith(lowerQuery) ? 2
                       : b.name.toLowerCase().includes(lowerQuery) ? 1 : 0;
      const bGenreScore = b.genre.toLowerCase().startsWith(lowerQuery) ? 2
                       : b.genre.toLowerCase().includes(lowerQuery) ? 1 : 0;

      const aScore = aNameScore + aGenreScore + (a.city ? 1 : 0);
      const bScore = bNameScore + bGenreScore + (b.city ? 1 : 0);

      return bScore - aScore;   // descending
    });

    // Удаляем дубликаты
    results = results.filter((result, index, self) =>
      index === self.findIndex(r =>
        r.name === result.name && r.genre === result.genre && r.city === result.city
      )
    );
  }

  return results;
}
```

> **Важно** – замените `location` на `city` во всех местах, где вы выводите/сортируете данные.

