const API_KEY = '<YOUR_API_KEY>'; // 👉 Replace with your key, but DON'T commit it!

const BASE_URL = 'https://api.openweathermap.org/data/2.5/weather';
const ICON_URL = 'https://openweathermap.org/img/wn/';

const elements = {
  cityInput: document.getElementById('city'),
  searchBtn: document.getElementById('searchBtn'),
  loader: document.getElementById('loader'),
  errorBox: document.getElementById('error'),
  weatherBox: document.getElementById('weather'),
  cityName: document.getElementById('cityName'),
  dateTime: document.getElementById('dateTime'),
  icon: document.getElementById('icon'),
  description: document.getElementById('description'),
  temp: document.getElementById('temp'),
  feels: document.getElementById('feels'),
  wind: document.getElementById('wind'),
  humidity: document.getElementById('humidity')
};

// Utility: Show / hide elements
function toggleVisibility(elem, show) {
  if (show) elem.classList.remove('hidden');
  else elem.classList.add('hidden');
}

// -------------------------------------------
// 1️⃣  Fetch weather data
// -------------------------------------------
async function fetchWeather(city) {
  // Use cache if available and fresh (15 minutes)
  const cacheKey = `weather_${city.toLowerCase()}`;
  const cached = localStorage.getItem(cacheKey);
  if (cached) {
    const { data, timestamp } = JSON.parse(cached);
    const age = Date.now() - timestamp;
    if (age < 15 * 60 * 1000) return data;
  }

  const url = `${BASE_URL}?q=${encodeURIComponent(city)}&units=metric&lang=en&appid=${API_KEY}`;

  // Use HTTPS only – CSP already ensures https: source
  const response = await fetch(url);

  // Handle HTTP errors gracefully
  if (!response.ok) {
    const errorMsg = response.status === 404
      ? `City "${city}" not found.`
      : `Error: ${response.status} ${response.statusText}`;
    throw new Error(errorMsg);
  }

  const data = await response.json();

  // Cache result
  localStorage.setItem(cacheKey, JSON.stringify({ data, timestamp: Date.now() }));

  return data;
}

// -------------------------------------------
// 2️⃣  Render UI
// -------------------------------------------
function renderWeather(data) {
  const { name, dt, weather, main, wind } = data;

  elements.cityName.textContent = name;
  elements.dateTime.textContent = new Date(dt * 1000).toLocaleString();
  elements.icon.src = `${ICON_URL}${weather[0].icon}@2x.png`;
  elements.icon.alt = weather[0].description;
  elements.description.textContent = weather[0].description;
  elements.temp.textContent = main.temp.toFixed(1);
  elements.feels.textContent = main.feels_like.toFixed(1);
  elements.wind.textContent = wind.speed.toFixed(1);
  elements.humidity.textContent = main.humidity;

  toggleVisibility(elements.weatherBox, true);
}

// -------------------------------------------
// 3️⃣  Event listeners
// -------------------------------------------
elements.searchBtn.addEventListener('click', () => {
  const city = elements.cityInput.value.trim();
  if (!city) return;
  toggleVisibility(elements.weatherBox, false);
  toggleVisibility(elements.errorBox, false);
  toggleVisibility(elements.loader, true);

  fetchWeather(city)
    .then(renderWeather)
    .catch(err => {
      console.error(err);
      elements.errorBox.textContent = err.message;
      toggleVisibility(elements.errorBox, true);
    })
    .finally(() => toggleVisibility(elements.loader, false));
});

elements.cityInput.addEventListener('keypress', e => {
  if (e.key === 'Enter') elements.searchBtn.click();
});

// -------------------------------------------
// Security‑researcher checklist (non‑exhaustive)
// -------------------------------------------
// 1. Never commit API_KEY to public repos.
// 2. Use a backend proxy or serverless function if you need to keep the key secret.
// 3. Enable HTTPS everywhere – local dev can use `npx http-server --ssl` or similar.
