// Новая асинхронная версия search
function search(query = '', role = '', city = '', genre = '', callback) {
  let sql = 'SELECT * FROM users WHERE 1=1';
  const params = [];

  if (query) {
    sql += ' AND (LOWER(name) LIKE ? OR LOWER(genre) LIKE ?)';
    const like = `%${query.toLowerCase()}%`;
    params.push(like, like);
  }
  if (role) { sql += ' AND role = ?'; params.push(role); }
  if (city) { sql += ' AND LOWER(city) = ?'; params.push(city.toLowerCase()); }
  if (genre) { sql += ' AND LOWER(genre) = ?'; params.push(genre.toLowerCase()); }

  connection.query(sql, params, (err, rows) => {
    if (err) return callback(err);
    const musicians = rows.map(m => ({
      name: m.name,
      genre: m.genre,
      originalName: m.name,
      profileLink: `/profile/${m.id}`,
      thumbnail: m.thumbnail,
      soundcloud: m.soundcloud,
      role: m.role,
      city: m.city
    }));
    callback(null, musicians);
  });
}

// Route /search
