      const musicians = rows.map(m => ({
        name: m.name,
        genre: m.genre,
        originalName: m.name,
        profileLink: `/profile/${m.id}`,
        thumbnail: m.thumbnail,
        soundcloud: m.soundcloud,
        role: m.role,
        city: m.city
      }));
      res.render('search', { musicians, query, role, city, genre, citiesAndRegions });
    });
  }
});
