PORT=3000

MONGO_URI=mongodb://localhost:27017/newsletter
MONGO_DB_NAME=newsletter_db

RATE_LIMIT_WINDOW_MS=60000      # 1 minute
RATE_LIMIT_MAX=100              # max requests per window
```

---

## 4. Database connection (`config/db.js`)

```js
// config/db.js
const mongoose = require('mongoose');

const connectDB = async () => {
  const { MONGO_URI, MONGO_DB_NAME } = process.env;
  if (!MONGO_URI) throw new Error('MONGO_URI not defined');

  const uri = `${MONGO_URI}/${MONGO_DB_NAME}`;

  await mongoose.connect(uri, {
    useNewUrlParser: true,
    useUnifiedTopology: true,
  });

  console.log(`✅ MongoDB connected: ${MONGO_DB_NAME}`);
};

module.exports = connectDB;
```

---

## 5. Mongoose schema (`models/Subscriber.js`)

```js
// models/Subscriber.js
const mongoose = require('mongoose');

const SubscriberSchema = new mongoose.Schema({
  email: {
    type: String,
    required: true,
    unique: true,          // enforce unique emails at DB level
    trim: true,
    lowercase: true,
  },
  name: {
    type: String,
    default: null,
    trim: true,
  },
  createdAt: {
    type: Date,
    default: Date.now,
  },
});

// Index to accelerate queries by email
SubscriberSchema.index({ email: 1 }, { unique: true });

module.exports = mongoose.model('Subscriber', SubscriberSchema);
```

> **Why `unique`?**  
> Prevents duplicate subscriptions even if validation fails on the app layer. Mongoose will throw a `MongoError: E11000 duplicate key error` on duplicate attempts, which we catch later.

---

## 6. Validators (`utils/validators.js`)

```js
// utils/validators.js
const validator = require('validator');

const isValidEmail = (email) => {
  return validator.isEmail(email);
};

module.exports = { isValidEmail };
```

---

## 7. API route (`routes/subscribers.js`)

```js
// routes/subscribers.js
const express = require('express');
const Subscriber = require('../models/Subscriber');
const { isValidEmail } = require('../utils/validators');
const router = express.Router();

/**
 * POST /api/subscribe
 * Body: { email: string, name?: string }
 */
router.post('/', async (req, res) => {
  try {
    const { email, name } = req.body;

    // 1️⃣ Basic validation
    if (!email) {
      return res.status(400).json({ success: false, error: 'Email is required.' });
    }

    if (!isValidEmail(email)) {
      return res.status(400).json({ success: false, error: 'Invalid email format.' });
    }

    // 2️⃣ Persist
    const subscriber = new Subscriber({
      email,
      name: name || null,
    });

    await subscriber.save();

    // 3️⃣ Success response
    return res.status(201).json({ success: true });

  } catch (err) {
    console.error(err);

    // Duplicate key error (email already exists)
    if (err.code === 11000) {
      return res.status(409).json({
        success: false,
        error: 'Email already subscribed.',
      });
    }

    // Validation errors from Mongoose
    if (err.name === 'ValidationError') {
      return res.status(400).json({
        success: false,
        error: err.message,
      });
    }

    // Generic server error
    return res.status(500).json({
      success: false,
      error: 'Internal server error.',
    });
  }
});

module.exports = router;
```

---

## 8. Main application (`app.js`)

```js
// app.js
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const connectDB = require('./config/db');
const subscriberRoutes = require('./routes/subscribers');

const app = express();
const PORT = process.env.PORT || 3000;

// 1️⃣ Security middlewares
app.use(helmet());

// 2️⃣ Rate limiting (adjust according to environment)
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 60000,
  max: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { success: false, error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// 3️⃣ Enable CORS (restrict origins in production)
app.use(cors());

// 4️⃣ Body parsing
app.use(express.json());

// 5️⃣ API routes
app.use('/api/subscribe', subscriberRoutes);

// 6️⃣ Global error handler (optional)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ success: false, error: 'Unexpected error.' });
});

// 7️⃣ Connect DB & start server
connectDB()
  .then(() => {
    app.listen(PORT, () => console.log(`🚀 Server listening on http://localhost:${PORT}`));
  })
  .catch((err) => {
    console.error('Failed to connect DB:', err);
    process.exit(1);
  });
```

---

## 9. Running the API

```bash
# install deps
npm install

# start (dev with nodemon)
npm run dev

# production
npm start
```

Send a test request:

```bash
curl -X POST http://localhost:3000/api/subscribe \
  -H "Content-Type: application/json" \
  -d '{"email":"alice@example.com","name":"Alice"}'
```

Response on success:

```json
