app.use(cors()); // Only if you serve the HTML from a different port
app.use(bodyParser.json());
app.use(express.static('public'));   // serves index.html, css, etc.

// --- Utility: read and parse the toplist.txt --------------------
function readTopList() {
  const file = path.join(__dirname, 'toplist.txt');
  let lines = [];
  try {
    const data = fs.readFileSync(file, 'utf8');
    lines = data.split('\n').filter(Boolean);
  } catch (e) {
    // File may not exist yet – fine, we’ll create it on first write
  }

  // Convert each line “name,score” into an object
  return lines.map(line => {
    const [name, score] = line.split(',');
    return { name: name.trim(), score: parseInt(score, 10) };
  });
}

// --- Utility: write the whole list back to file ----------------
function writeTopList(list) {
  const file = path.join(__dirname, 'toplist.txt');
  const data = list
    .map(entry => `${entry.name},${entry.score}`)
    .join('\n') + '\n';
  fs.writeFileSync(file, data, 'utf8');
}

// --- POST /scores – receive a new score ------------------------
app.post('/scores', (req, res) => {
  const { name, score } = req.body;

  // Basic server‑side validation (you *must* do this!)
  if (
    typeof name !== 'string' ||
    typeof score !== 'number' ||
    !Number.isInteger(score) ||
    score < 0 ||
    name.length > 20 ||
    /[,\n]/.test(name)  // no commas or newlines in the name
  ) {
    return res.status(400).json({ error: 'Invalid input' });
  }

  // Sanitize the name: strip HTML tags, trim whitespace
  const safeName = name.replace(/<[^>]*>/g, '').trim();

  // Read the current list, append new entry, sort descending
  let list = readTopList();
  list.push({ name: safeName, score });

  // Keep only top 100 (or whatever you wish)
  list.sort((a, b) => b.score - a.score);
  list = list.slice(0, 100);

  // Write back to disk atomically (fs.writeFileSync is already atomic on POSIX)
  writeTopList(list);

  // Return the top‑10 (or top‑N) list to the client
  const top10 = list.slice(0, 10);
  res.json({ top: top10 });
});

// --- Optional: GET /toplist – return current list -------------
app.get('/toplist', (req, res) => {
  const list = readTopList();
  list.sort((a, b) => b.score - a.score);
  res.json({ top: list.slice(0, 10) });
});

app.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
```

> **Security notes**  
> * **Input sanitisation** – we strip newlines, commas (used as the file delimiter), and HTML tags.  
> * **Path traversal** – we never expose `toplist.txt` path to the user; the server hard‑codes it.  
> * **File corruption** – `writeFileSync` writes atomically on most modern OSes. If you expect a very high write rate you might use a queue or lock‑file mechanism.  
> * **Rate limiting** – you could add a simple in‑memory counter per IP or a library like `express-rate-limit` to avoid a DoS.  
> * **CORS** – the demo uses `cors()` to allow a frontend served from a different port. In production you would restrict the `origin` to your own domain.  
> * **HTTPS** – always serve over TLS; otherwise the POST request is exposed to MITM.  

Run the server:

```bash
node server.js
```

Your `index.html` (the game) should now be served by the same host (or a proxy).  
When a player finishes, the modal pops up, the backend writes to `toplist.txt`, and the updated top‑10 table is shown.

---

## 3.  What if you *don’t* want a backend?

If you’re only running a local demo or you *really* don’t want to expose a backend, you can:

| Goal | Approach | Caveats |
|------|----------|---------|
| **Persist locally on the client** | Use `localStorage` to store a JSON string. | Only one user per browser; data can be cleared by the user. |
| **Download a file for the user to keep** | Create a Blob and trigger a download. | User must manually upload it back later; no shared leaderboard. |
| **Use a cloud storage service** | e.g. Firebase Realtime DB or Firestore, or AWS S3 with a signed URL. | Requires SDK and authentication; still a backend of some sort. |

But for a *real* shared leaderboard, a server‑side component is required.

---

## 4.  Bonus – Rendering the leaderboard before the game ends

You can fetch the leaderboard when the page loads and show it in a sidebar or modal:

```js
fetch('/toplist')
  .then(r => r.json())
  .then(data => renderTopList(data.top));
```

Add a `<div id="leaderboard"></div>` somewhere in your page.

---

## 5.  Summary checklist

| Task | Done? | Comment |
|------|-------|---------|
| Prompt user for name after game ends | ✅ | Use `prompt()` or a custom form |
| Send name + score to the server | ✅ | `fetch('/scores', …)` |
| Server sanitises input | ✅ | strip commas, newlines, tags |
| Server appends record to a plain‑text file | ✅ | `fs.writeFileSync()` |
| Server reads the file, sorts, returns top‑N | ✅ | Return JSON |
| Client renders leaderboard | ✅ | Simple table or modal |
| Handle concurrent writes / file corruption | ❓ | `writeFileSync` is atomic; for high load consider a DB |
| Protect against XSS / CSRF | ❓ | If you expose an endpoint to other sites, add CSRF tokens |
| Use HTTPS in production | ❓ | Essential for any data transmission |
| Rate limit / bot protection | ❓ | Optional but recommended |

Once you plug the above into your project, you’ll have a functioning high‑score leaderboard that is **secure** (input validated, sanitized, and stored in a file you control) and **user‑friendly** (name prompt, modal feedback, live leaderboard). Feel free to extend it into a real database or a more elaborate UI as your game grows!

