      if (/\s/.test(ch)) { i++; continue; }
      if (ch === '(' || ch === ')') { tokens.push(ch); i++; continue; }

      // Multi‑char operators
      if (expr.substr(i,2) === '**' || expr.substr(i,2) === '//') {
        tokens.push(expr.substr(i,2));
        i += 2; continue;
      }
      if (['+','-','*','/','%'].includes(ch)) { tokens.push(ch); i++; continue; }

      // Numbers (integer or float)
      const numMatch = expr.slice(i).match(/^[0-9]+(?:\.[0-9]*)?|\.[0-9]+/);
      if (numMatch) {
        tokens.push(numMatch[0]);
        i += numMatch[0].length; continue;
      }

      throw new Error(`Unexpected character "${ch}" at position ${i+1}`);
    }
    return tokens;
  }

  function toRPN(tokens) {
    const output = [];
    const stack = [];
    tokens.forEach(tok => {
      if (tok === '(') {
        stack.push(tok);
      } else if (tok === ')') {
        while (stack.length && stack[stack.length-1] !== '(') {
          output.push(stack.pop());
        }
        if (!stack.length) throw new Error('Mismatched parentheses');
        stack.pop(); // pop '('
      } else if (OPERATORS[tok]) {
        while (stack.length && OPERATORS[stack[stack.length-1]]) {
          const o2 = stack[stack.length-1];
          if ((OPERATORS[tok].assoc === 'L' && OPERATORS[tok].prec <= OPERATORS[o2].prec) ||
              (OPERATORS[tok].assoc === 'R' && OPERATORS[tok].prec < OPERATORS[o2].prec)) {
            output.push(stack.pop());
          } else break;
        }
        stack.push(tok);
      } else { // number
        output.push(tok);
      }
    });
    while (stack.length) {
      const top = stack.pop();
      if (top === '(' || top === ')') throw new Error('Mismatched parentheses');
      output.push(top);
    }
    return output;
  }

  function evaluateRPN(rpn) {
    const stack = [];
    rpn.forEach(tok => {
      if (OPERATORS[tok]) {
        const b = stack.pop();
        const a = stack.pop();
        if (a === undefined || b === undefined) throw new Error('Invalid expression');
        if (tok === '/' && b === 0) throw new Error('Division by zero');
        if (tok === '%' && b === 0) throw new Error('Modulo by zero');
        stack.push(OPERATORS[tok].fn(a, b));
      } else {
        stack.push(parseFloat(tok));
      }
    });
    if (stack.length !== 1) throw new Error('Invalid expression');
    return stack[0];
  }

  function calculate(expr) {
    if (expr.length > MAX_LEN) throw new Error('Expression too long');
    const tokens = tokenize(expr);
    const rpn = toRPN(tokens);
    return evaluateRPN(rpn);
  }

  const exprInput = document.getElementById('expr');
  const resultDiv = document.getElementById('result');
  const calcBtn = document.getElementById('calcBtn');

  calcBtn.addEventListener('click', () => {
    const expr = exprInput.value.trim();
    resultDiv.textContent = ''; // clear previous
    resultDiv.classList.remove('error');
    if (!expr) return;

    try {
      const res = calculate(expr);
      resultDiv.textContent = `= ${res}`;
    } catch (e) {
      resultDiv.textContent = `Error: ${e.message}`;
      resultDiv.classList.add('error');
    }
  });

  // Allow pressing Enter to submit
  exprInput.addEventListener('keydown', e => {
    if (e.key === 'Enter') calcBtn.click();
  });
})();
</script>
</body>
</html>
```

### 3.3 How to Run

1. **Save** the code above as `calculator.html` in a folder on your machine.
2. **Open** the file in any modern browser (Chrome, Firefox, Edge, Safari).
3. **Type** an expression in the input box, e.g.:

```
(5 + 3) * 2
```

4. **Click** “Calculate” (or press **Enter**) – the result appears below.

### 3.4 Security Checklist

| Check | What to Verify |
|-------|----------------|
| **CSP** | Open dev‑tools → Network → Headers → `Content‑Security‑Policy` shows `default-src 'self'; script-src 'self';`. |
| **No `<script>` tags** | Inspect the source: only the inline `<script>` you see. |
| **No `eval` or `Function`** | Search the JS code: no `eval`, `new Function`, or `setTimeout` with string. |
| **Output via `textContent`** | In dev‑tools → Elements → inspect `#result` – text content only. |
| **Input Length** | Try a 201‑char expression → “Error: Expression too long”. |
| **Division by zero** | `10 / 0` → “Error: Division by zero”. |
| **Mismatched parentheses** | `(1+2` → “Error: Mismatched parentheses”. |

---

## 4.  Summary

| Language | Implementation | Security Strength |
|----------|----------------|-------------------|
| **Python** | Console calculator, AST‑based parsing, size limit, no `eval`. | *Very low attack surface* – safe for CLI use. |
| **JavaScript** | Web page, custom parser, CSP, XSS safe, size limit. | *Low to medium* – still browser‑dependent but no script injection or eval. |

> **Takeaway** – A calculator is a micro‑ecosystem of typical vulnerabilities. By building it “securely” (no `eval`, validate input, sanitise output, enforce CSP), you practice the very same patterns that protect real applications from injection, XSS, and denial‑of‑service attacks. Feel free to extend these examples, e.g., add a history feature, or expose a REST API—just keep the same safety rules in mind. Happy hacking!

