  // adapter: require('socket.io-redis')({ host: 'redis', port: 6379 })
});

io.use((socket, next) => {
  const token = socket.handshake.auth.token; // sent from client
  if (!token) {
    return next(new Error('Missing token'));
  }
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET!);
    // payload: { sub: userId, iat, exp }
    (socket as any).userId = payload.sub;
    return next();
  } catch (err) {
    console.warn('JWT error', err);
    return next(new Error('Invalid token'));
  }
});

io.on('connection', (socket) => {
  const userId = (socket as any).userId;
  console.log(`User ${userId} connected, socket id ${socket.id}`);

  // Join a room dedicated to this user (private channel)
  socket.join(`user:${userId}`);

  // 3.1.1   Sending message to another user
  socket.on('sendMessage', async (payload) => {
