      from: userId,
      to: payload.to,
      content: sanitized,
      sentAt: new Date(),
    });

    // Push to recipient if online
    if (targetSocketId) {
      io.to(`user:${payload.to}`).emit('receiveMessage', {
        from: userId,
        content: sanitized,
        sentAt: new Date(),
