      }
    }
  });

  socket.on('disconnect', () => {
    console.log(`User ${userId} disconnected`);
  });
});
```

> **Nota**: `socket.handshake.auth.token` è una proprietà introdotta in socket.io 4. Se usi una versione più vecchia, puoi passare il token come query string o header (`socket.handshake.headers['authorization']`).

