    const sum = sessionStorage.getItem('sum');

    // Выводим в DOM, используя textContent – защищаем от XSS
    document.getElementById('output').textContent =
      sum !== null ? `Сумма: ${sum}` : 'Нет данных';
  </script>
</body>
