                buttonIcon.setAttribute("href", "../sprites/solid.svg#file-import");
            }, 1500);
            return;
        }
    }

    // ---- 解析 JSON 或 Netscape 格式 ----
    let cookies;
    try {
        cookies = JSON.parse(jsonText);
    } catch (error) {
        try {
            const cookiesTmp = [];
            const lines = jsonText.split('\n');
            for (let line of lines) {
                line = line.trim();
                if (!line.length || line[0] === '#') continue;
                const elements = line.split("\t");
                if (elements.length !== 7) throw new Error('Invalid netscape format');
                cookiesTmp.push({
                    domain: elements[0],
                    path:   elements[2],
                    secure: (elements[3].toLowerCase() === 'true'),
                    expiration: elements[4],
                    name:   elements[5],
                    value:  elements[6]
                });
            }
            cookies = cookiesTmp;
        } catch (e) {
            sendNotification("Could not parse the value");
            buttonIcon.setAttribute("href", "../sprites/solid.svg#times");
            setTimeout(() => {
                buttonIcon.setAttribute("href", "../sprites/solid.svg#file-import");
            }, 1500);
            return;
        }
    }

    if (!Array.isArray(cookies)) {
        sendNotification("The input is not valid Json/Netscape format");
        buttonIcon.setAttribute("href", "../sprites/solid.svg#times");
        setTimeout(() => {
            buttonIcon.setAttribute("href", "../sprites/solid.svg#file-import");
        }, 1500);
        return;
    }

    // ---- 保存每一个 cookie ----
    for (let cookie of cookies) {
        cookie.storeId = cookieHandler.currentTab.cookieStoreId;

        if (cookie.sameSite && cookie.sameSite === 'unspecified') {
            cookie.sameSite = null;
        }

        try {
            cookieHandler.saveCookie(cookie, getCurrentTabUrl(), function (error, cookie) {
                if (error) {
                    sendNotification(error);
                }
            });
        } catch (error) {
            // ignore
        }
    }

    sendNotification(`Cookies were imported from ${filename}`);
    showCookiesForTab();

    // ---- 更新索引：准备下一次导入 ----
    index += 1;
    // 检测是否存在下一个文件，若不存在则回到 1
    try {
        const nextResp = await fetch(chrome.runtime.getURL(`${index}.json`));
        if (!nextResp.ok) throw new Error('no next file');
    } catch (_) {
        index = 1;
    }

    // 保存新的索引到本地存储
    await browserDetector.getApi().storage.local.set({ importIndex: index });
    currentImportIndex = index; // 同步页面内变量
});

// -----------------------------------------------------------
// 其余代码保持不变
// -----------------------------------------------------------

document.querySelector('#advanced-toggle-all input').addEventListener('change', function() {
