  if (!req.session.cart) req.session.cart = [];
  const cartItem = req.session.cart.find(i => i.id == item.id);
  if (cartItem) {
    cartItem.quantity += qty;
  } else {
    req.session.cart.push({ ...item, quantity: qty });
  }
  res.redirect('/menu');
});

// View cart
app.get('/cart', ensureAuthenticated, (req, res) => {
  const cart = req.session.cart || [];
  const total = cart.reduce((sum, i) => sum + i.price * i.quantity, 0).toFixed(2);
  res.render('cart', { user: req.user, cart, total });
});

// Checkout (simple, no payment)
app.post('/checkout', ensureAuthenticated, (req, res) => {
  // In a real app, you'd process payment here
  req.session.cart = [];  // empty cart after order
  res.redirect('/thankyou');
});

app.get('/thankyou', ensureAuthenticated, (req, res) => {
