// 3️⃣  A small utility that creates DOM nodes safely
function createNode(type, attributes = {}, ...children) {
  const node = document.createElement(type);
  for (const [attr, value] of Object.entries(attributes)) {
    // textContent is safe: it escapes HTML automatically
    if (attr === 'textContent') node.textContent = value;
    else if (attr === 'innerHTML') node.innerHTML = value; // <-- use with caution
    else node.setAttribute(attr, value);
  }
  for (const child of children) {
    node.appendChild(child);
  }
  return node;
}

// 4️⃣  Build a card element from a weather JSON object
function buildWeatherCard(data) {
  // Destructure the JSON response
  const { name, main, weather, wind } = data;
  const { temp, humidity, pressure } = main;
  const [weatherInfo] = weather; // array with 1 element

  // Create nodes
  const title = createNode('h2', { textContent: name });
  const tempEl = createNode('p', { textContent: `Temperature: ${kelvinToCelsius(temp)}°C` });
  const humEl  = createNode('p', { textContent: `Humidity: ${humidity}%` });
  const presEl = createNode('p', { textContent: `Pressure: ${pressure} hPa` });
  const windEl = createNode('p', { textContent: `Wind: ${wind.speed} m/s` });
  const icon   = createNode('img', { src: `https://openweathermap.org/img/wn/${weatherInfo.icon}@2x.png`, alt: weatherInfo.description });

  // Assemble the card
  return createNode('div', { class: 'card' }, icon, title, tempEl, humEl, presEl, windEl);
}

// 5️⃣  Convert Kelvin to Celsius
function kelvinToCelsius(k) {
  return (k - 273.15).toFixed(1);
}

// 6️⃣  Fetch data from the API
async function fetchWeather(city) {
  const url = `${BASE_URL}?q=${encodeURIComponent(city)}&appid=${API_KEY}`;
  try {
    const response = await fetch(url, { method: 'GET', credentials: 'omit' });

    // 7️⃣  Check for HTTP errors
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

    const data = await response.json();

    // 8️⃣  Render the card
    const card = buildWeatherCard(data);
    container.appendChild(card);

  } catch (err) {
    // 9️⃣  Show a user‑friendly error
    console.error(err);
    const errMsg = createNode('p', { textContent: 'Unable to fetch weather data. Try again later.' });
    container.appendChild(errMsg);
  }
}

// 10️⃣  Kick‑off
fetchWeather(CITY);
```

---

### 4. What Just Happened?

| Step | What we did | Why it matters for beginners |
|------|-------------|-----------------------------|
| 1️⃣ | Defined constants (API key, URL, city). | Keeps values in one place for easy change. |
| 2️⃣ | Grabbed the container element. | Allows us to inject content later. |
| 3️⃣ | Created a helper that safely builds DOM nodes. | Avoids `innerHTML` where possible—prevents XSS. |
| 4️⃣ | Built a card from the raw JSON. | Demonstrates object destructuring and DOM composition. |
| 5️⃣ | Converted temperatures. | Shows data manipulation. |
| 6️⃣ | Used `fetch` to hit the API. | Modern, promise‑based HTTP client. |
| 7️⃣ | Checked the response status. | Defensive programming. |
| 8️⃣ | Rendered the card. | Ties everything together. |
| 9️⃣ | Caught and logged errors. | Encourages error handling best practices. |
| 10️⃣ | Started the process. | Shows the entry point of the script. |

---

### 5. Security Best‑Practices

| Topic | Recommendation | How it appears in the example |
|-------|----------------|--------------------------------|
| **CORS** | Only make requests to APIs that set `Access-Control-Allow-Origin` to your domain or `*`. | The `fetch` call automatically obeys CORS; if the API denies it, the promise rejects. |
| **HTTPS** | Always use `https://` URLs. | `BASE_URL` uses HTTPS. |
| **API Keys** | Never commit your key to public repos. | In production, store it in a server‑side environment variable or a `.env` file not checked in. |
| **XSS** | Never insert user input directly into `innerHTML`. | We use `textContent` for all data except the icon URL (which is from a trusted source). |
| **Rate‑Limiting** | Respect the API’s rate limits; add a delay or cache responses. | Not covered in this simple example but noted for production. |
| **Content Security Policy (CSP)** | Set a CSP header that restricts `script-src` and `img-src`. | A `meta` tag or server header can block malicious content. |

> **Pro‑Tip:** In a real project you’d use a build system (Webpack, Vite) or a framework (React, Vue) to handle assets and environment variables, but the core ideas stay the same.

---

### 6. Extending the Example

| Feature | How to add it |
|---------|---------------|
| **Multiple cities** | Use a loop, or provide a dropdown that calls `fetchWeather` on change. |
| **Unit toggle** | Add a button that toggles between Celsius and Fahrenheit; recompute `tempEl.textContent`. |
| **Caching** | Store the JSON in `localStorage` and use it if the API call fails or is slow. |
| **Loading spinner** | Insert an element before the fetch, remove it on success/failure. |
| **Error UI** | Show a styled error card with retry button. |

---

### 7. Quick Quiz (for the reader)

1. Which DOM property would you use to **safely** insert text that could contain `<script>` tags?  
   *Answer: `textContent`.*

2. What will happen if the API responds with a `404` status?  
   *Answer: The `if (!response.ok)` check throws an error, which is caught and a friendly message is displayed.*

3. Why do we use `encodeURIComponent(city)` in the request URL?  
   *Answer: To escape any characters that might break the query string (e.g., spaces, `&`).*

---

### 8. Summary

* We fetched JSON from a public API using `fetch`.  
* We parsed the JSON, extracted relevant fields, and built DOM elements safely.  
* We handled HTTP errors and displayed a user‑friendly message.  
* We incorporated a few security‑centric best practices that any beginner should learn early.

> **Take‑away for the reader:**  
> “Fetching and rendering API data is as straightforward as grabbing data, turning it into a DOM tree, and appending it to the document—provided you respect HTTP status codes, handle errors, and never let raw data slip into the page as executable code.”

