> **Why `dummyRecId`?**  
> `lightning-file-upload` normally requires a `record-id`. We pass a dummy Id because the file is not attached to a single record until we run our Apex logic.

### b. Component JS – `bulkAttachModal.js`

```js
import { LightningElement, api, wire } from 'lwc';
import attachToRecords from '@salesforce/apex/AttachmentBulkUploader.attachToRecords';
import { getRecord } from 'lightning/uiRecordApi';

export default class BulkAttachModal extends LightningElement {
    @api recordIds = [];      // List Action will supply this
    isModalOpen = false;
    selectedFileId = null;
    selectedFileName = '';
    isAttachDisabled = true;
    acceptedFormats = '.pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg';

    // We need a dummy record Id for the lightning-file-upload component
    dummyRecId = '001000000000000AAA';

    openModal() {
        this.isModalOpen = true;
    }
    closeModal() {
        this.isModalOpen = false;
        this.resetForm();
    }

    handleUploadFinished(event) {
        const uploadedFiles = event.detail.files; // array of uploaded files
        if (uploadedFiles && uploadedFiles.length > 0) {
            const file = uploadedFiles[0];
            this.selectedFileId = file.id;
            this.selectedFileName = file.name;
            this.isAttachDisabled = false;
        }
    }

    async handleAttach() {
        try {
            const result = await attachToRecords({
                recordIds: this.recordIds,
                contentVersionId: this.selectedFileId
            });
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Success',
                    message: result,
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Error',
                    message: error.body.message,
                    variant: 'error'
                })
            );
        } finally {
            this.closeModal();
        }
    }

    resetForm() {
        this.selectedFileId = null;
        this.selectedFileName = '';
        this.isAttachDisabled = true;
    }
}
```

