    button { margin-right: 1rem; padding: 0.5rem 1rem; }
  </style>
</head>
<body>
  <h1>RxJS Demo – JSON Viewer</h1>
  <button id="showBtn">Показать данные</button>
  <button id="delBtn" disabled>Удалить</button>
  <div id="tableContainer"></div>

