> **Why do we enable `'unsafe-inline'`?**  
> In this demo we use inline `<script>` for convenience, but in production you should inline the JS in a separate file and remove `'unsafe-inline'` from the CSP.

### src/index.js

```js
/* -------------  Imports (RxJS 7 UMD bundle) ------------- */
const { fromEvent, ajax } = rxjs;
const { map, tap, switchMap, take, filter, finalize } = rxjs.operators;

/* -------------  DOM helpers ------------- */
const showBtn   = document.getElementById('showBtn');
const delBtn    = document.getElementById('delBtn');
const container = document.getElementById('tableContainer');

/* -------------  State ------------- */
const dataRows = []; // keeps an array of objects from the JSON
let tableEl = null;  // reference to the <table> element

/* -------------  Utility – safe rendering ------------- */
/**
 * Create a table row from an object.
 * All values are inserted via textContent (no innerHTML).
 */
function createRow(obj, idx) {
  const tr = document.createElement('tr');
  tr.setAttribute('data-index', idx);

  Object.entries(obj).forEach(([key, val]) => {
    const td = document.createElement('td');
    td.textContent = String(val);
    tr.appendChild(td);
  });

  return tr;
}

/**
 * Render the whole table.
 */
function renderTable(rows) {
  const tbl = document.createElement('table');
  const thead = document.createElement('thead');
  const tbody = document.createElement('tbody');

  if (rows.length === 0) return; // nothing to render

  /* Header row – first object keys */
  const headerRow = document.createElement('tr');
  Object.keys(rows[0]).forEach(key => {
    const th = document.createElement('th');
    th.textContent = key;
    headerRow.appendChild(th);
  });
  thead.appendChild(headerRow);

  /* Data rows */
  rows.forEach((row, idx) => {
    tbody.appendChild(createRow(row, idx));
  });

  tbl.appendChild(thead);
  tbl.appendChild(tbody);

  /* Replace old table if any */
  container.innerHTML = '';
  container.appendChild(tbl);
  tableEl = tbl;
}

/* -------------  Event – Show data ------------- */
const show$ = fromEvent(showBtn, 'click').pipe(
  /* Disable the button so we don't spam requests */
  tap(() => {
    showBtn.disabled = true;
    delBtn.disabled = true; // we cannot delete before any data
  }),
  /* Switch to an Ajax Observable that completes after the JSON arrives */
  switchMap(() => ajax.getJSON('https://example.com/data.json')),
  /* Expect an array in JSON. If it isn't, we throw an error. */
  map(json => {
    if (!Array.isArray(json)) {
      throw new Error('JSON response is not an array');
    }
    return json;
  }),
  /* Merge each row into our state array */
  map(rows => {
    rows.forEach(row => dataRows.push(row));
    return dataRows;
  })
);

show$.subscribe({
  next: (rows) => {
    renderTable(rows);
    delBtn.disabled = rows.length === 0;
  },
  error: (err) => {
    console.error('Failed to load JSON:', err);
    alert('Ошибка при загрузке данных. Пожалуйста, проверьте консоль.');
  },
  complete: () => {
    // Re‑enable the button for subsequent loads if you want
    showBtn.disabled = false;
  }
});

/* -------------  Event – Delete last row ------------- */
const del$ = fromEvent(delBtn, 'click').pipe(
  filter(() => dataRows.length > 0),          // guard
  tap(() => {
    // Remove last element from our state array
    dataRows.pop();
  })
);

del$.subscribe({
  next: () => {
    renderTable(dataRows);
    delBtn.disabled = dataRows.length === 0;
  }
});
```

### How it works

| Step | What happens | RxJS operators used |
|------|--------------|---------------------|
| 1 | User clicks **Показать данные** | `fromEvent` → `tap` (disable buttons) → `switchMap` (ajax) |
| 2 | `ajax.getJSON` emits the parsed JSON | `map` (check array) |
| 3 | Merge rows into `dataRows` array | `map` |
| 4 | Render table with `renderTable()` | `next` handler |
| 5 | User clicks **Удалить** | `fromEvent` → `filter` → `tap` (remove last) |
| 6 | Re‑render table | `next` handler |

