Below is a **Vue 3 Composition‑API “module”** that behaves exactly like the original ES‑class but uses the modern idioms of Vue 3.

> **Key points**  
> • The queue is a *reactive* object (`state`) that can be used from any component.  
> • All state‑mutating methods are wrapped in `useQueue()` – it’s a “composable”.  
> • `inject()` is used to grab the globally‑provided `eventBus` and the global `config` (you must provide those in your app).  
> • The module is exported as a *singleton* so you only ever get one queue instance (just like `new Queue()` in the original).  
> • All console‑debug statements from the original class are kept so you can compare logs easily.  

```ts
// src/composables/useQueue.ts
import { reactive, inject, onUnmounted } from 'vue';

/**
 * Queue composable – a thin, Composition‑API wrapper around the legacy
 * Queue class implementation.
 *
 * @example
 * // In a component
 * import { useQueue } from '@/composables/useQueue';
 * const { addToQueue, state } = useQueue();
 */
export function useQueue() {
  /* ------------------------------------------------------------------
   *  Dependencies – the app must provide these in its root component
   *  (usually via `provide()` in App.vue or in a top‑level layout).
   * ------------------------------------------------------------------ */
  const eventBus = inject('eventBus');
  const config = inject('config');

  if (!eventBus || !config) {
    throw new Error(
      'useQueue() – “eventBus” and “config” must be provided via Vue\'s inject.'
    );
  }

  /* ------------------------------------------------------------------
   *  Reactive state – this is the single source of truth.
   * ------------------------------------------------------------------ */
  const state = reactive({
    items: [] as Array<any>,   // array of queued items
    queueRunning: false,       // true while an item is being played
  });

  /* ------------------------------------------------------------------
   *  Helper: check if the queue is empty.
   * ------------------------------------------------------------------ */
  const isEmpty = () => state.items.length === 0;

  /* ------------------------------------------------------------------
   *  Public API – add a new item to the queue.
   * ------------------------------------------------------------------ */
  const addToQueue = (item: any) => {
    /*  The legacy implementation mutates the incoming object – keep that
        behaviour so that downstream code that relies on `fromQueue`
        and `step` continues to work. */
    item.fromQueue = true;
    item.step = 3;
    state.items.push(item);

    console.log(
      'Queue: adding item to queue:',
      state.items.length,
      'queueRunning:',
      state.queueRunning,
      state.items
    );

    // if nothing is running yet – start immediately
    if (!state.queueRunning) {
      console.log(
        'Queue: added To Queue, start play because queue was idle.',
        'queueRunning:',
        state.queueRunning
      );
      playQueued();
    }
  };

  /* ------------------------------------------------------------------
   *  Private helper – called internally to start the next item.
   * ------------------------------------------------------------------ */
  const playQueued = () => {
    state.queueRunning = true;
    console.log('Queue: playQueued, queue length is:', state.items.length);

    // FIFO – pop the first element
    const item = state.items.shift();

    // Guard: if the queue was emptied concurrently
    if (!item) {
      state.queueRunning = false;
      return;
    }

    item.step = 4;
    console.log('Queue: playQueued trigger eventBus', item.type, item);

    /* The legacy code emits an event – the component that actually
       plays the audio/video should listen for this event and add the
       `ended` listener. */
    eventBus.emit(item.type, item);
  };

  /* ------------------------------------------------------------------
   *  Public API – called by the component that actually plays the media
   *  (e.g. a <audio> element) when it ends.
   * ------------------------------------------------------------------ */
  const playQueuedEnded = (event: Event) => {
    // remove the listener so we don't leak
    event.target?.removeEventListener('ended', playQueuedEnded, true);

    if (isEmpty()) {
      state.queueRunning = false;
      console.log(
        'Queue: playQueuedEnded – no more entries in queue:',
        state.items.length,
        state.queueRunning
      );
    } else {
      console.log(
        'Queue: playQueuedEnded – item ended, remaining items:',
        state.items.length,
        state.queueRunning
      );

      console.log(
        'Queue: setting timer for next run:',
        config.settings.alerts.queueTimeDistance
      );

      // start the next item after the configured delay
      window.setTimeout(
        playQueued,
        config.settings.alerts.queueTimeDistance
      );
    }
  };

  /* ------------------------------------------------------------------
   *  Cleanup – if you ever need to cancel pending timeouts or detach
   *  listeners when the component using this composable unmounts.
   * ------------------------------------------------------------------ */
  onUnmounted(() => {
    // You could keep a reference to the timeout ID and clear it here.
  });

  /* ------------------------------------------------------------------
   *  Return all public members – the consumer can destructure what it
   *  needs.  The whole `state` object is also exposed for reactivity.
   * ------------------------------------------------------------------ */
  return {
    state,
    isEmpty,
    addToQueue,
    playQueued,
    playQueuedEnded,
  };
}

/* ----------------------------------------------------------------------
 *  Export a *singleton* instance so that all modules that import it
 *  share the same queue – mimicking `new Queue()` from the legacy code.
 * ---------------------------------------------------------------------- */
export const queue = useQueue();

/* ----------------------------------------------------------------------
 *  Default export – if you prefer the classic `import Queue from ...`
 * ---------------------------------------------------------------------- */
export default queue;
```

---

### How to use it in a component

```vue
