Below is a **full‑stack refactor** that addresses the most common security & performance issues in the snippet you posted.  
I’ll walk through the changes in the order they appear:

1. **Replace `nodejs-websocket` → `ws`** (more actively maintained, better error handling)  
2. **Add TLS (wss://) – never expose a raw WebSocket on port 80/443 to the public Internet**  
3. **Enforce a simple authentication scheme** (token + rate‑limit)  
4. **Sanitize all user‑generated content** to stop XSS / injection attacks  
5. **Binary support – properly flag messages and store / forward only allowed file types**  
6. **Graceful shutdown & cleanup**  
7. **Client‑side improvements** – ES6 modules, typed events, better UI state handling

---

## 1. Backend –  `server.js`

```js
/* ----------------------------------------------------
 *  WebSocket Chat Server – secure, scalable, minimal
 * ---------------------------------------------------- */

const fs   = require('fs');
const http = require('http');
const https= require('https');
const { WebSocketServer } = require('ws');
const crypto  = require('crypto');
const rateLimit = require('express-rate-limit');
const helmet   = require('helmet');
const express  = require('express');

const app = express();
app.use(helmet());                    // HTTP headers hardening

// ---- Rate limit: 10 requests / 15 seconds per IP  ----
const limiter = rateLimit({
  windowMs: 15 * 1000,
  max: 10,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---- HTTPS Server (replace key.pem / cert.pem with your own --------
const httpsServer = https.createServer({
  key  : fs.readFileSync('key.pem'),   // <-- generate with `openssl req -newkey rsa:2048 -nodes -keyout key.pem -x509 -days 365 -out cert.pem`
  cert : fs.readFileSync('cert.pem')
}, app);

// ---- WebSocket server attached to HTTPS -------------
const wss = new WebSocketServer({ server: httpsServer });

// ------------------------------------------------------------------
const ALLOWED_ORIGINS = ['https://yourdomain.com']; // <-- adjust

// ------------------------------------------------------------------
// Utility – generate random token (simple auth, no DB for demo)
function generateToken() {
  return crypto.randomBytes(24).toString('hex');
}

// In‑memory store: token -> {username, ip, ws, lastMsgTime}
const clients = new Map();

// ------------------------------------------------------------------
// Message format we use:
// { type: 'text' | 'binary', payload: string | ArrayBuffer, meta: {from, timestamp} }
function sendJSON(ws, obj) {
  ws.send(JSON.stringify(obj));
}

// ------------------------------------------------------------------
// Broadcast helper – filter by type
function broadcast(obj) {
  const msg = JSON.stringify(obj);
  for (const [_, cl] of clients) {
    if (cl.ws.readyState === cl.ws.OPEN) cl.ws.send(msg);
  }
}

// ------------------------------------------------------------------
// Validation helpers
function isTextSafe(str) {
  // Very light sanitization – for demo only, replace < & > etc.
  return str.replace(/[<>]/g, (c) => ({'<':'&lt;','>':'&gt;'}[c]));
}

function isAllowedMime(mime) {
  const allowed = [
    'image/png',
    'image/jpeg',
    'image/gif',
    'application/pdf',
    'text/plain'
  ];
  return allowed.includes(mime);
}

// ------------------------------------------------------------------
// WebSocket upgrade & handshake
wss.on('connection', (ws, request) => {
  const ip = request.socket.remoteAddress;

  // --- Origin check ------------------------------------------------
  const origin = request.headers.origin;
  if (!ALLOWED_ORIGINS.includes(origin)) {
    ws.close(4003, 'Origin not allowed');
    return;
  }

  // --- Auth – client must send a token as first message ----------
  let authenticated = false;
  let token, username;

  const authTimer = setTimeout(() => {
    if (!authenticated) ws.close(4001, 'Authentication timeout');
  }, 10_000); // 10s to authenticate

  ws.on('message', (data, isBinary) => {
    if (!authenticated) {
      // Expect the first message to be JSON with { token, username }
      try {
        const { token: t, username: u } = JSON.parse(data.toString());
        // Validate token (for demo, any token that exists in our store)
        const existing = clients.get(t);
        if (existing) {
          // Same token from another connection – kill old one
          existing.ws.close(4005, 'Token already in use');
          clients.delete(t);
        }
        token    = t || generateToken();   // if no token supplied, we’ll give one
        username = isTextSafe(u || 'anon');
        clients.set(token, { ws, username, ip, lastMsgTime: 0 });

        authenticated = true;
        clearTimeout(authTimer);
        // Send back the token so the client can store it
        sendJSON(ws, { type: 'auth', token, username });

        console.log(`Client ${username} (${ip}) authenticated with token ${token}`);
      } catch (e) {
        ws.close(4002, 'Invalid auth payload');
      }
      return;
    }

    // ----------------------------------------------------------------
    // After authentication we accept two kinds of data:
    //   1. Text: normal chat message
    //   2. Binary: file upload
    // ----------------------------------------------------------------
    const client = clients.get(token);
    if (!client) return; // Should not happen

    // Rate‑limit: 5 messages per 5s
    const now = Date.now();
    if (now - client.lastMsgTime < 1000) {
      ws.send(JSON.stringify({ type: 'error', msg: 'Rate limit: 1 msg per sec' }));
      return;
    }
    client.lastMsgTime = now;

    if (isBinary) {
      // Binary message – we expect the first 8 bytes to be a 64‑bit
      // number that encodes the MIME type string length, followed by
      // the MIME string.  This is a simple protocol; in production
      // you might use something like multipart/form-data or a JSON
      // header + binary payload.
      try {
        const buffer = Buffer.from(data);
        const mimeLen = buffer.readUInt32BE(0);
        const mime    = buffer.slice(4, 4 + mimeLen).toString('utf8');

        if (!isAllowedMime(mime)) {
          ws.send(JSON.stringify({ type: 'error', msg: 'Disallowed MIME type' }));
          return;
        }

        // Forward to others
        broadcast({
          type: 'binary',
          payload: buffer.slice(4 + mimeLen).toString('base64'), // base64 in JSON
          meta: {
            from: username,
            timestamp: new Date().toISOString(),
            mime
          }
        });

      } catch (e) {
        console.warn('Binary parse error', e);
        ws.send(JSON.stringify({ type: 'error', msg: 'Malformed binary upload' }));
      }
    } else {
      // Text message
      const text = isTextSafe(data.toString());
      broadcast({
        type: 'text',
        payload: text,
        meta: {
          from: username,
          timestamp: new Date().toISOString()
        }
      });
    }
  });

  ws.on('close', () => {
    if (token && clients.has(token)) {
      clients.delete(token);
      console.log(`Client ${username} disconnected`);
    }
    clearTimeout(authTimer);
  });

  ws.on('error', err => {
    console.warn('WS error', err);
  });
});

// ------------------------------------------------------------------
// Graceful shutdown
process.on('SIGINT', () => {
  console.log('Shutting down...');
  wss.clients.forEach(ws => ws.close(1000, 'Server shutting down'));
  httpsServer.close(() => process.exit(0));
});

httpsServer.listen(8443, () => console.log('Secure WebSocket server listening on port 8443'));
```

### Key take‑aways

| Problem | Fix |
|---------|-----|
| **No authentication** | First message is JSON `{ token?, username }`. Generates a token if not supplied. |
| **Unrestricted origins** | `Origin` header checked. |
| **No TLS** | Runs over HTTPS/WSS (`8443`). |
| **Rate limiting** | Both HTTP (Express) & WebSocket per client. |
| **XSS** | `isTextSafe` escapes `<` & `>`. |
| **Binary handling** | Simple protocol: MIME length + MIME + payload. Only a whitelist of MIME types is accepted. |
| **Resource leak** | On `close` we clean up the `clients` map. |
| **Graceful shutdown** | Sends `1000` closing frames to all sockets. |

> **Tip** – In a real system you’d store tokens in a DB or use JWT, support TLS via a reverse proxy (NGINX/Traefik), and maybe use a message queue (Kafka, Redis Pub/Sub) for horizontal scaling.

