    errors.push('numberOfQuestions');
  }
  if (!customText || typeof customText !== 'string' || customText.length > 500) {
    errors.push('customText');
  }

  return errors;
}

// ------- API endpoint -------
app.post('/api/generate-quiz', async (req, res) => {
  const payload = req.body;

  const errors = validatePayload(payload);
  if (errors.length) {
    return res.status(400).json({
      error: 'Invalid input',
      fields: errors
    });
  }

  const {
    board,
    questionType,
    difficulty,
    numberOfQuestions,
    customText
  } = payload;

  // Build the prompt
  const prompt = `
Create ${numberOfQuestions} ${questionType} quiz questions for a ${board} board exam at a ${difficulty} difficulty level. 
The questions should test a resident’s knowledge of radiology fundamentals and be written in a concise, professional tone.
Incorporate the following additional information from the user:
"${customText}"
Provide each question followed by four answer choices (A–D) and label the correct answer.
Return the output as plain text.`;

  try {
    // OpenAI request
    const completion = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      messages: [{ role: 'user', content: prompt }],
      temperature: 0.7,
      max_tokens: 1500
    });

    const quizText = completion.choices[0].message.content.trim();

    res.json({ quiz: quizText });
  } catch (err) {
    console.error('OpenAI error:', err);
    res.status(500).json({ error: 'Failed to generate quiz. Try again later.' });
  }
});

// ------- Start server -------
app.listen(PORT, () => {
  console.log(`⚡️ Radiology Quiz API listening on http://localhost:${PORT}`);
});
```

> **Why GPT‑4o-mini?**  
> It offers a balance of quality, cost, and speed. Replace `gpt-4o-mini` with `gpt-3.5-turbo` or any other model you have access to.

