/* script.js */
document.getElementById('quizForm').addEventListener('submit', async e => {
  e.preventDefault();

  const spinner = document.getElementById('spinner');
  const output = document.getElementById('quizContent');
  spinner.classList.remove('hidden');
  output.textContent = '';

  const payload = {
    board: document.getElementById('board').value,
    questionType: document.getElementById('questionType').value,
    difficulty: document.getElementById('difficulty').value,
    numberOfQuestions: parseInt(document.getElementById('numberOfQuestions').value, 10),
    customText: document.getElementById('customText').value.trim()
  };

  try {
    const res = await fetch('/api/generate-quiz', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.error || 'Unknown error');
    }

    const data = await res.json();
    output.textContent = data.quiz;
  } catch (err) {
    console.error(err);
    output.textContent = `⚠️ ${err.message}`;
  } finally {
    spinner.classList.add('hidden');
  }
});
