    header("Location: $url");
    exit;
}

function is_logged_in() {
    return isset($_SESSION['user_id']);
}

function current_user() {
    return $_SESSION['user'] ?? null; // array with id, username, role
}

function require_login() {
    if (!is_logged_in()) {
        redirect('login.php');
    }
}

function is_admin() {
