## 6. Registration (`register.php`)

```php
<?php
require_once 'functions.php';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = trim($_POST['username'] ?? '');
    $email    = trim($_POST['email'] ?? '');
    $pass     = $_POST['password'] ?? '';
    $err      = [];

    if (!$username) $err[] = 'Username required.';
    if (!$email || !filter_var($email, FILTER_VALIDATE_EMAIL)) $err[] = 'Valid email required.';
    if (strlen($pass) < 6) $err[] = 'Password must be at least 6 characters.';

    if (empty($err)) {
        // Check uniqueness
        $stmt = $pdo->prepare('SELECT id FROM users WHERE username = ? OR email = ?');
        $stmt->execute([$username, $email]);
        if ($stmt->fetch()) {
            $err[] = 'Username or email already taken.';
        } else {
            $hash = password_hash($pass, PASSWORD_DEFAULT);
            $stmt = $pdo->prepare('INSERT INTO users (username, email, password) VALUES (?, ?, ?)');
            $stmt->execute([$username, $email, $hash]);

            // Auto‑login after registration
            $_SESSION['user_id'] = $pdo->lastInsertId();
            $_SESSION['user'] = ['id' => $_SESSION['user_id'], 'username' => $username, 'role' => 'user'];
            redirect('index.php');
        }
    }
}
?>
