```php
<?php
/**
 * Обработчик формы, который записывает все целые числа
 * от n до m включительно в текстовый файл.
 *
 * Принимает POST‑запросы с полями `n` и `m`.
 * Использует оператор `for` для перебора диапазона.
 * Валидация и очистка входных данных гарантируют, что
 * в файл попадут только целые числа, а не произвольный PHP‑код.
 */

session_start();

/* 1. Проверяем, пришёл ли запрос методом POST и есть ли нужные поля */
if ($_SERVER['REQUEST_METHOD'] !== 'POST' || !isset($_POST['n'], $_POST['m'])) {
    http_response_code(400);
    exit('Неверный запрос. Пожалуйста, используйте форму.');
}

/* 2. Сохраняем и очищаем ввод пользователя */
$n_raw = $_POST['n'];
$m_raw = $_POST['m'];

/* 3. Приведение к целочисленному типу */
$n = filter_var($n_raw, FILTER_VALIDATE_INT);
$m = filter_var($m_raw, FILTER_VALIDATE_INT);

if ($n === false || $m === false) {
    http_response_code(400);
    exit('Пожалуйста, введите корректные целые числа.');
}

/* 4. При необходимости меняем порядок, чтобы цикл всегда работал от меньшего к большему */
if ($n > $m) {
    [$n, $m] = [$m, $n];
}

/* 5. Путь к файлу (не забудьте выставить нужные права на запись) */
$filepath = __DIR__ . '/output.txt';

/* 6. Открываем файл для дозаписи */
$fh = fopen($filepath, 'a');
if ($fh === false) {
    http_response_code(500);
    exit('Не удалось открыть файл для записи.');
}

/* 7. Записываем числа в файл, используя оператор `for` */
for ($i = $n; $i <= $m; $i++) {
    fwrite($fh, $i . PHP_EOL);  // Каждый номер в отдельной строке
}

/* 8. Закрываем дескриптор */
fclose($fh);

/* 9. Информируем пользователя */
echo "<h2>Успешно! В файле <code>$filepath</code> записаны числа от $n до $m.</h2>";
echo '<a href="form.php">Вернуться к форме</a>';
```

