    // CSRF check
    if (!validateCsrfToken($_POST['csrf_token'] ?? '')) {
        die('Invalid CSRF token.');
    }

    if (!$email || strlen($password) < 8) {
        $error = 'Please provide a valid email and a password of at least 8 characters.';
    } else {
        // Check if email already exists
        $stmt = $pdo->prepare('SELECT id FROM users WHERE email = ?');
        $stmt->execute([$email]);

        if ($stmt->fetch()) {
            $error = 'Email already registered.';
        } else {
            // Hash the password (Argon2id by default in PHP 8.1+)
            $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

            // Insert user
            $stmt = $pdo->prepare('INSERT INTO users (email, password) VALUES (?, ?)');
            $stmt->execute([$email, $hashedPassword]);

            // Optionally: automatically log in the new user
            $_SESSION['user_id'] = $pdo->lastInsertId();
            header('Location: dashboard.php');
            exit;
        }
    }
}

// Render form
?>
<!doctype html>
<html lang="en">
<head><meta charset="UTF-8"><title>Sign Up</title></head>
<body>
