    public function addQuestion(Question $q): void
    {
        $this->questions[] = $q;
    }

    /**
     * Affiche l’ensemble du quiz dans un formulaire POST
     */
    public function afficheQuiz(): void
    {
        echo '<form method="post" action="Action/submit.php">';
        foreach ($this->questions as $q) {
            $q->afficheQuestion();
            echo '<hr>';
        }
        echo '<input type="submit" name="submit" value="Envoyer">';
        echo '</form>';
    }

    /**
     * Calcule le score à partir des données POST
     *
     * @param array $postData $_POST
     * @return int Score (nombre de bonnes réponses)
     */
    public function checkReponse(array $postData): int
    {
        $score = 0;
        foreach ($this->questions as $q) {
            $uuid    = $q->uuid;
            $answer  = $postData[$uuid] ?? null;
            if ($q->checkReponse($answer)) {
                $score++;
            }
        }
        return $score;
    }
