## 1. config.php

```php
<?php
// ---------------------------------------------------------------
// Configuration & common helpers
// ---------------------------------------------------------------

session_start();  // for the admin login

// Database connection (SQLite)
$pdo = new PDO('sqlite:' . __DIR__ . '/database.sqlite');
$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

// Create tables if they do not exist
$pdo->exec("
    CREATE TABLE IF NOT EXISTS files (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        original_name TEXT NOT NULL,
        stored_name   TEXT NOT NULL,
        upload_time   INTEGER NOT NULL,
        expiry_time   INTEGER NOT NULL,
        size          INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS settings (
        key   TEXT PRIMARY KEY,
        value TEXT NOT NULL
    );
");

// Default settings – will be inserted only once
$defaultSettings = [
    'allowed_extensions' => 'jpg,jpeg,png,gif,txt,doc,docx,pdf,zip',
    'max_file_size'      => '10485760',     // 10 MB in bytes
    'default_expiry'     => '30',           // days
    'admin_user'         => 'admin',        // plain‑text for demo (hash in prod)
    'admin_pass'         => password_hash('admin', PASSWORD_DEFAULT), // hashed
];
foreach ($defaultSettings as $k => $v) {
    $stmt = $pdo->prepare("INSERT OR IGNORE INTO settings (key, value) VALUES (:k, :v)");
    $stmt->execute([':k' => $k, ':v' => $v]);
}

// Helpers -------------------------------------------------------

// Get a setting value (returns string or null)
function get_setting($key) {
    global $pdo;
    $stmt = $pdo->prepare("SELECT value FROM settings WHERE key = :k");
    $stmt->execute([':k' => $key]);
    return $stmt->fetchColumn();
}

// Update a setting (creates or updates)
function set_setting($key, $value) {
    global $pdo;
    $stmt = $pdo->prepare("REPLACE INTO settings (key, value) VALUES (:k, :v)");
    $stmt->execute([':k' => $key, ':v' => $value]);
}

// Generate a safe random filename
function generate_filename($extension) {
    return bin2hex(random_bytes(16)) . '.' . $extension;
}

// ---------------------------------------------------------------
?>
```

