            $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
            $allowed = array_map('trim', explode(',', get_setting('allowed_extensions')));
            if (!in_array($ext, $allowed)) {
                $response['msg'] = 'Расширение файла недопустимо';
            } else {
                // 2. Store the file
                $storedName = generate_filename($ext);
                $dest = __DIR__ . '/uploads/' . $storedName;

                if (move_uploaded_file($file['tmp_name'], $dest)) {
                    // 3. Store metadata
                    $expiryDays = (int) ($_POST['expiry_days'] ?? 0);
                    $expiryTime = $expiryDays > 0 ? time() + ($expiryDays * 86400) : 0;

                    $stmt = $pdo->prepare("
                        INSERT INTO files (original_name, stored_name, upload_time, expiry_time, size)
                        VALUES (:orig, :stored, :up, :exp, :size)
                    ");
                    $stmt->execute([
                        ':orig'  => $file['name'],
                        ':stored'=> $storedName,
                        ':up'    => time(),
                        ':exp'   => $expiryTime,
                        ':size'  => $file['size'],
                    ]);

                    $response['msg'] = 'Файл успешно загружен!';
