    // Retrieve the stored filename
    $stmt = $pdo->prepare("SELECT stored_name FROM files WHERE id = :id");
    $stmt->execute([':id' => $id]);
    $row = $stmt->fetch(PDO::FETCH_ASSOC);

    if ($row) {
        // Delete file from disk
        $filePath = __DIR__ . '/uploads/' . $row['stored_name'];
        if (file_exists($filePath)) {
            @unlink($filePath);
        }

        // Delete DB record
        $stmt = $pdo->prepare("DELETE FROM files WHERE id = :id");
        $stmt->execute([':id' => $id]);

        $response['msg'] = 'Файл удалён';
        $response['success'] = true;
    } else {
        $response['msg'] = 'Файл не найден';
    }
}

header('Content-Type: application/json');
echo json_encode($response);
