> **为什么选这些？**  
> *`helmet`* 为常用安全 HTTP 头；  
> *`csurf`* 提供 CSRF 令牌；  
> *`jsonwebtoken`* 用于无状态身份认证；  
> *`dotenv`* 让机密信息不写在代码里。

#### 2.1.2 `server.js`

```js
require('dotenv').config();
const express = require('express');
const helmet = require('./middleware/helmet');
const csrf = require('./middleware/csrf');
const auth = require('./middleware/auth');
const todoRoute = require('./routes/todo');
const path = require('path');
const cors = require('cors');
const session = require('express-session');

const app = express();

/* 1. 安全头 */
app.use(helmet());

// 2. Session 用来存 CSRF token (只要是无状态也可改成 cookie + httpOnly)
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: true,
  cookie: { httpOnly: true, secure: process.env.NODE_ENV === 'production' }
}));

/* 3. body 解析 */
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

/* 4. CORS（若前后端分离） */
app.use(cors({
  origin: process.env.FRONTEND_ORIGIN,
  credentials: true
}));

/* 5. CSRF 保护（POST/PUT/DELETE） */
app.use(csrf);

/* 6. 静态文件 */
app.use(express.static(path.join(__dirname, 'public')));

/* 7. 路由前置：JWT 校验 */
app.use('/api', auth, todoRoute);

/* 8. 错误处理 */
app.use((err, req, res, next) => {
  if (err.code === 'EBADCSRFTOKEN') {
    return res.status(403).json({ error: 'Invalid CSRF token' });
  }
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

/* 9. 启动 */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server listening on ${PORT}`));
```

> **重点**  
> * `helmet`：默认加上了 `Content-Security-Policy: default-src 'self'` 等头。  
> * `csrf`：`csurf` 自动在 session 中存放令牌，并在每次请求里验证。  
> * `auth`：只对 `/api/**` 做 JWT 校验，避免未登录用户访问。  

#### 2.1.3 `middleware/auth.js`

```js
const jwt = require('jsonwebtoken');

module.exports = (req, res, next) => {
  // 取 Authorization: Bearer <token>
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing token' });

  const [scheme, token] = authHeader.split(' ');
  if (scheme !== 'Bearer' || !token)
    return res.status(401).json({ error: 'Invalid token format' });

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET, { algorithms: ['HS256'] });
    req.user = payload; // { id, username, ... }
    next();
  } catch (e) {
    console.warn('JWT verification failed:', e.message);
    res.status(401).json({ error: 'Invalid token' });
  }
};
```

> **为什么用 JWT？**  
> 1. 无状态，后端不需要存 session。  
> 2. 可以在 token 里携带角色、权限，方便后端做细粒度权限控制。  

#### 2.1.4 `middleware/csrf.js`

```js
const csurf = require('csurf');
const cookieParser = require('cookie-parser');

module.exports = csurf({
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict'
  }
});
```

> 该中间件会把 CSRF token 写进 httpOnly cookie，前端通过 `fetch` 的 `credentials: 'include'` 读取 cookie，随后再放到自定义 header（如 `X-CSRF-Token`）里提交。

