```js
const express = require('express');
const router = express.Router();
const db = require('../db'); // 简化: 用 mysql2/promise

/**
 * GET /api/todos
 * 取得所有待办事项（分页）
 */
router.get('/todos', async (req, res, next) => {
  try {
    const [rows] = await db.query('SELECT id, title, completed, created_at FROM todos WHERE user_id = ?', [req.user.id]);
    res.json(rows);
  } catch (e) {
    next(e);
  }
});

/**
 * POST /api/todos
 * 新增一条待办事项
 */
router.post('/todos', async (req, res, next) => {
  const { title } = req.body;
  if (!title || title.length > 255) {
    return res.status(400).json({ error: 'Invalid title' });
  }
  try {
    const [result] = await db.execute('INSERT INTO todos (user_id, title) VALUES (?, ?)', [req.user.id, title]);
    res.status(201).json({ id: result.insertId, title, completed: false });
  } catch (e) {
    next(e);
  }
});

/**
 * PATCH /api/todos/:id
 * 更新已完成状态
 */
router.patch('/todos/:id', async (req, res, next) => {
  const { completed } = req.body;
  if (typeof completed !== 'boolean') {
    return res.status(400).json({ error: 'Invalid completed flag' });
  }
  const todoId = req.params.id;
  try {
    const [result] = await db.execute(
      'UPDATE todos SET completed = ? WHERE id = ? AND user_id = ?',
      [completed, todoId, req.user.id]
    );
    if (result.affectedRows === 0) return res.status(404).json({ error: 'Not found' });
    res.json({ id: todoId, completed });
  } catch (e) {
    next(e);
  }
});

/**
 * DELETE /api/todos/:id
 * 删除待办事项
 */
router.delete('/todos/:id', async (req, res, next) => {
  const todoId = req.params.id;
  try {
    const [result] = await db.execute(
      'DELETE FROM todos WHERE id = ? AND user_id = ?',
      [todoId, req.user.id]
    );
    if (result.affectedRows === 0) return res.status(404).json({ error: 'Not found' });
    res.status(204).end();
  } catch (e) {
    next(e);
  }
});

module.exports = router;
```

> **安全点**  
> * **参数化查询**：防止 SQL 注入。  
> * **用户归属校验**：在每个更新、删除都检查 `user_id`，避免跨用户操作。  
> * **输入验证**：对 `title` 长度、`completed` 类型做校验。  

