### 3.2 `public/main.js`

```js
/* 1. 全局配置：使用 HTTPS、带凭证 */
const API_BASE = '/api';
const CSRF_HEADER = 'X-CSRF-Token';

/**
 * 读取 CSRF 令牌
 * csurf 写入 httpOnly cookie，前端通过 fetch 获取 cookie
 * 这里我们用一个轻量的 `getCookie` 方案
 */
function getCSRFToken() {
  // 读取 document.cookie (httpOnly cookie 只能在服务器端读，若想在前端读需要改成普通 cookie)
  // 方案: 在服务器返回一个 `/csrf-token` endpoint，前端 GET 该 endpoint 并把 token 放进 header
  return fetch('/csrf-token', { credentials: 'include' })
    .then(r => r.json())
    .then(d => d.token);
}

/**
 * 通用 fetch 封装，自动添加 CSRF、JWT
 */
async function api(url, options = {}) {
  const token = await getCSRFToken(); // 每次请求都获取最新的 CSRF token
  const authHeader = `Bearer ${localStorage.getItem('jwt')}`;

  const defaultHeaders = {
    'Content-Type': 'application/json',
    [CSRF_HEADER]: token,
    Authorization: authHeader
  };
  options.headers = { ...defaultHeaders, ...(options.headers || {}) };
  options.credentials = 'include'; // 发送 cookie

  const resp = await fetch(API_BASE + url, options);
  if (!resp.ok) {
    const err = await resp.json();
    throw new Error(err.error || 'Unknown error');
  }
  if (resp.status !== 204) return resp.json();
}

/**
 * 渲染待办列表
 */
async function renderTodos() {
  try {
    const todos = await api('/todos');
    const container = document.getElementById('todos');
    container.innerHTML = '';
    todos.forEach(todo => {
      const div = document.createElement('div');
      div.className = 'todo';
      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.checked = todo.completed;
      cb.addEventListener('change', () => toggleCompleted(todo.id, cb.checked));
      const span = document.createElement('span');
      span.textContent = todo.title;
      span.style.textDecoration = todo.completed ? 'line-through' : 'none';
      const del = document.createElement('button');
      del.textContent = '删除';
      del.style.marginLeft = '10px';
      del.addEventListener('click', () => deleteTodo(todo.id));
      div.appendChild(cb);
      div.appendChild(span);
      div.appendChild(del);
      container.appendChild(div);
    });
  } catch (e) {
    console.error('加载失败:', e);
    alert('获取待办列表失败: ' + e.message);
  }
}

/**
 * 添加待办
 */
document.getElementById('add-form').addEventListener('submit', async e => {
  e.preventDefault();
  const input = document.getElementById('new-title');
  try {
    await api('/todos', { method: 'POST', body: JSON.stringify({ title: input.value }) });
    input.value = '';
    renderTodos();
  } catch (e) {
    alert('添加失败: ' + e.message);
  }
});

/**
 * 更新完成状态
 */
async function toggleCompleted(id, completed) {
  try {
    await api(`/todos/${id}`, { method: 'PATCH', body: JSON.stringify({ completed }) });
    renderTodos();
  } catch (e) {
    alert('更新失败: ' + e.message);
  }
}

/**
 * 删除
 */
async function deleteTodo(id) {
  if (!confirm('确定删除？')) return;
  try {
    await api(`/todos/${id}`, { method: 'DELETE' });
    renderTodos();
  } catch (e) {
    alert('删除失败: ' + e.message);
  }
}

/* 4. 页面首次加载刷新 */
renderTodos();

/* 5. 定期轮询刷新（可选） */
setInterval(renderTodos, 30000); // 30 秒刷新一次
```

> **安全点**  
> * CSRF token 每次请求前都从 `/csrf-token` 拉取，确保 token 最新。  
> * 使用 `credentials: 'include'` 让 cookie（如果有）跟随请求，配合 `SameSite=strict` 防止 CSRF。  
> * 所有 API 响应都通过 `api()` 统一捕获错误并给出友好提示。  

### 3.3 `/csrf-token` endpoint（后端新增）

```js
// server.js 里新增一条路由
app.get('/csrf-token', (req, res) => {
  res.json({ token: req.csrfToken() });
});
```

> `req.csrfToken()` 是 `csurf` 提供的，用来生成或获取当前 session 的 CSRF token。  

---

## 4. 细节补充：安全最佳实践

| 场景 | 需要注意 | 代码或配置 |
|---|---|---|
| **HTTPS** | 防止中间人窃听、伪造请求 | `process.env.NODE_ENV === 'production'` → `app.use(helmet.hsts({ maxAge: 31536000 }))` |
| **CSP** | 防止 XSS | `helmet.contentSecurityPolicy({ directives: { ... } })` |
| **Rate Limiting** | 防止暴力破解、DoS | `express-rate-limit` 中间件 |
| **Input Validation** | 防止注入、错误数据 | `express-validator` 或自定义校验 |
| **Logging & Monitoring** | 追踪异常 | `morgan` + `winston` |
| **Error Suppression** | 生产环境不泄露堆栈 | `app.set('env', 'production')` 后 `res.status(500).json({ error: 'Internal Server Error' })` |
| **Session Cookie** | 防止 session 劫持 | `httpOnly`, `secure`, `sameSite=strict` |
| **JWT** | 防止重放、暴力破解 | `expiresIn: '1h'` + `refresh token` |
| **Content-Type & Accept** | 防止 MIME type confusion | `app.use(helmet.contentTypeOptions())` |
| **CSRF** | 防止跨站请求伪造 | `csurf` + `SameSite=Strict` + `X-CSRF-Token` header |

---

## 5. 演练一波

> **假设**：用户已经登录并拿到了 JWT，放在 `localStorage`。  
> **步骤**  
> 1. 打开页面 → `main.js` 调用 `renderTodos()` → Ajax 请求 `/api/todos`，服务器返回 `200 + JSON`。  
> 2. 用户点击 `完成` → `PATCH /api/todos/:id`，请求中带 `X-CSRF-Token`。  
> 3. 若攻击者试图 CSRF（伪造请求） → CSRF token 在 cookie 里，攻击页面无法读取并发送相同 token → `csurf` 拒绝请求。  
> 4. 若攻击者试图 XSS 注入 → 服务器返回 JSON，前端使用 `JSON.parse` 解析，后端对输入做长度/字符校验，`CSP` 阻止了任何外部脚本执行。  
> 5. 若攻击者想注入 SQL → 服务器使用参数化查询，防止 `; DROP TABLE todos;` 之类的注入。

---

## 6. 小结

- **Ajax 让前端与后端分离**，但也打开了新的安全门。  
- **安全研究者的任务**：  
  1. **识别攻击面**（CSRF、XSS、注入）。  
  2. **评估现有防御**（CSRF token、JWT、CSP）。  
  3. **演练攻击**：利用工具 `OWASP ZAP` / `Burp Suite` 做自动化扫描。  
  4. **验证防御有效**：尝试 CSRF、XSS、SQL 注入等，确认已被拦截。  
- **代码示例**：本例通过 `fetch` + `csurf` + JWT + CSP + Helmet 等，构成了一个“安全可验证”的 Ajax 数据刷新完整方案。  

> 你可以将以上代码直接跑起来（记得先 `npm i`、`.env` 配置好），随后用 `curl` / `Postman` / `Burp Suite` 进行手工攻击，验证安全防御是否到位。祝你玩得开心，也能更好地理解 Ajax 与安全的交互！

